        \STATE Receive $\boldsymbol{w}_g$ \quad \rev{// Obtains the fresh global model} \label{alg:wait}
    \ENDIF
    \IF{$\boldsymbol{w}_g \neq \boldsymbol{w}_o$} \label{alg:receiveFresh}
        \STATE $\beta^i_{t_i-1} \leftarrow$ Calculation based on Equation \eqref{eq:betaUpdate} \quad \rev{// Computes aggregation weight for model merging} \label{alg:betaUpdate}
        \STATE Update $\boldsymbol{w}_{o,l-1}$ with Equation \eqref{eq:deviceAggregation} \quad \rev{// Aggregates local and fresh global models} \label{alg:deviceAggregation}
        \STATE Update $\gamma^i_{t_i}$ and $\upsilon^i_{t_i}$ with Equation \eqref{eq:controlDevice} \quad \rev{// Updates device-side control parameters} \label{alg:controlDeviceUpdate}
        \STATE $\mathcal{R} \leftarrow loss_{o,l}^{b,i} - loss_{o,l}^{a,i}$ \quad \rev{// Calculates reward based on loss difference} \label{alg:rewardUpdate}
        \STATE $b_{t_i} \leftarrow (1-\rho)b_{t_i-1} + \rho \mathcal{R}$ \quad \rev{// Updates bias term for reinforcement learning} \label{alg:btUpdate}
        \STATE Update $\theta_{t}$ or $\mathcal{H}_{t_i}^i$ with $\mathcal{R}$ \quad \rev{// Updates meta model or history with reward} \label{alg:rlupdate}
    \ENDIF
    \STATE Update $\boldsymbol{w}_{o,l}$ based on Equation \eqref{eq:localSGD} \quad \rev{// Performs local stochastic gradient descent update} \label{alg:SGDUpdate}
\ENDFOR
\rev{
\STATE \textbf{Return} $\boldsymbol{w}^i_{o,\mathcal{L}}$ \quad // Returns the trained local model
}
\end{algorithmic}
\end{algorithm}
\end{figure}

For local training, the reward $\mathcal{R}$ is defined as the change in loss value before and after model merging on a device. Specifically, we denote $loss_{o,l^*}^{b,i}$ as the loss value of $\mathcal{F}_{i}(\boldsymbol{w}_{o,l^*}, \zeta_{l^*})$ before merging the new global model according to the request after $l^*$ local epochs, and denote $loss_{o,l^*}^{a,i}$ as that after merging. Then we have $\mathcal{R} = loss_{o,l^*}^{b,i} - loss_{o,l^*}^{a,i}$. The LSTM model is updated using Equation \eqref{eq:rlupdate} after the initial aggregation \cite{Zoph2017Neural},
\begin{equation}\label{eq:rlupdate}\small
    \theta_t = \theta_{t - 1} + \eta_{RL} \sum_{l = 1}^{ \mathcal{L}} \nabla_{\theta_{t - 1}} \log P(\mathcal{s}_l|\mathcal{s}_{(l-1):1}; \theta_{t - 1})(\mathcal{R} - b_t),
\end{equation}
where $\theta_t$ is the meta model after its $t$-th update, $\eta_{RL}$ is the learning rate of RL training, $\mathcal{L}$ is the maximum number of local epochs, $\mathcal{s}_l$ denotes the requesting decision after the $l$-th local epoch, and $b_t$ is used to control the bias of the model. The model undergoes pre-training using historical data and is subsequently updated in real time during the training process of \AName{} on each device. The $\mathcal{Q}$-learning method establishes a mapping \(\mathcal{H}^i\) between decisions and rewards for Device \(i\). This mapping is revised based on a weighted average that incorporates both historical values and the current reward \cite{dietterich2000hierarchical}, as demonstrated in Equation \eqref{eq:qupdate},
\begin{align}
\label{eq:qupdate}
    &\mathcal{H}^i_{t_i}  (l^*_{t_i - 1}, a_{t_i - 1})  = \mathcal{H}^i_{t_i-1}(l^*_{t_i - 1}, a_{t_i - 1})  \nonumber \\
    & + \phi (\mathcal{R} + \psi \max_a{\mathcal{H}^i_{t_i-1}(l^*_{t_1}, a) - \mathcal{H}^i_{t_i-1}(l^*_{t_i - 1}, a_{t_i - 1})}),
\end{align}
where $a_{t_i - 1}$ denotes the action, $l^*_{t_i - 1}$ is the number of local epochs to send the request within the $(t_i - 1)$-th device-side model aggregation, $\phi$ and $\psi$ are hyper-parameters. The action space for $a_{t_i - 1}$ is $\{add, stay, minus\}$, where $add$ means adding 1 epoch to $l^*_{t_i - 1}$ ($l^*_{t_i} = l^*_{t_i - 1} + 1$), $stay$ means staying with the same epoch ($l^*_{t_i} = l^*_{t_i - 1} + 1$), and $minus$ means removing 1 epoch from $l^*_{t_i - 1}$ ($l^*_{t_i} = l^*_{t_i - 1} - 1$).

\subsubsection{Device-Side Model Aggregation}
\label{subsec:device_agg}

When receiving a fresh global model $\boldsymbol{w}_g$, Device $i$ merges the fresh global model with its current local model $\boldsymbol{w}_{o,l}^b$ with Equation \eqref{eq:deviceAggregation}.
\begin{equation}
\label{eq:deviceAggregation}
\boldsymbol{w}_{o,l}^a = (1-\beta^i_{t_i-1}) \boldsymbol{w}_{o,l}^b + \beta^i_{t_i-1} \boldsymbol{w}_g,
\end{equation}
where $\beta^i_{t_i - 1}$ is the weight of the fresh global model on Device $i$ at the $(t_i - 1)$-th device-side model aggregation. Equation \eqref{eq:deviceAggregation} differs from Equation \eqref{eq:serverAggregation} as the received fresh global model corresponds to a higher global version. $\beta^i_{t - 1}$ is calculated with Equation \eqref{eq:betaUpdate},
\begin{equation}\label{eq:betaUpdate}
\begin{split}
\phi^i_{t_i-1}(g, o) &= \frac{\gamma^i_{t_i-1}}{\sqrt{g}}(1-\frac{\upsilon^i_{t_i-1}}{\sqrt{g - o + 1}}),\\
\beta^i_{t_i-1}(g, o) &= \frac{\mu_{\beta} \phi^i_{t_i-1}(g, o)}{1 + \mu_{\beta} \phi^i_{t_i-1}(g, o)},
\end{split}    
\end{equation}
where $\mu_{\beta}$ is a hyper-parameter, $\gamma^i_{t_i-1}$ and $\upsilon^i_{t_i-1}$ are control parameters adjusted with Equation \eqref{eq:controlDevice},
\begin{align}
\label{eq:controlDevice}
\gamma^i_{t_i} &= \gamma^i_{t_i-1} - \eta_{\gamma^i}\nabla_{\gamma^i_{t_i-1}} \mathcal{F}_i(\boldsymbol{w}_{o,l}^b, \zeta_{l-1}), \nonumber\\
\upsilon^i_{t_i} &= \upsilon^i_{t_i-1} - \eta_{\upsilon^i}\nabla_{\upsilon^i_{t_i-1}} \mathcal{F}_i(\boldsymbol{w}_{o,l}^b, \zeta_{l-1}), \zeta_{l-1} \sim \mathcal{D}_i.
\end{align}
For Equation \eqref{eq:controlDevice}, $\eta_{\gamma^i}$ and $\eta_{\upsilon^i}$ are learning rates for $\gamma^i_{t_i}$ and $\upsilon^i_{t_i}$. Besides, we have the partial deviation of the loss function in terms of $\gamma^i_{t_i-1}$: 
\begin{equation*}
\begin{aligned}
\nabla_{\gamma^i_{t_i-1}} \mathcal{F}_i(\boldsymbol{w}_{o,l}^b, \zeta_{l-1}) &= \left(\frac{\partial \mathcal{F}_i(\boldsymbol{w}_{o,l}^b, \zeta_{l-1})}{\partial \boldsymbol{w}_{o,l}^b} \right)^\mathrm{T} \frac{\partial \boldsymbol{w}_{o,l}^b}{\partial \gamma_{t_i-1}^i} \\
&= g_{o,l}^\mathrm{T}(\boldsymbol{w}_{o,l}^b) \frac{\partial \boldsymbol{w}_{o,l}^b}{\partial \gamma_{t_i-1}^i},  \\
\end{aligned}
\end{equation*}
where $g_{o,l}^\mathrm{T}(\boldsymbol{w}_{o,l}^b)$ is the local gradient on Device $i$ with $\boldsymbol{w}_{o,l}^b$ and $\zeta_{l-1}$. Meanwhile, we have
\begin{equation*}
\begin{aligned}
\boldsymbol{w}_{o,l}^b &= (1-\beta^i_{t_i-1}) \boldsymbol{w}_{o,l}^a + \beta^i_{t_i-1} \boldsymbol{w}_g \\
&= \boldsymbol{w}_{o,l}^a + \beta^i_{t_i-1}(\boldsymbol{w}_g - \boldsymbol{w}_{o,l}^a),
\end{aligned}
\end{equation*}
where $\boldsymbol{w}_g$ and $\boldsymbol{w}_{o,l}^a$ are independent with $\gamma_{t_i-1}^i$. Then, we have:
\begin{equation*}
\begin{aligned}
\frac{\partial \boldsymbol{w}_{o,l}^b}{\partial \gamma_{t_i-1}^i} &= \frac{\partial(\boldsymbol{w}_{o,l}^a + \beta^i_{t_i-1}(\boldsymbol{w}_g - \boldsymbol{w}_{o,l}^a))}{\partial \gamma_{t_i-1}^i} \\
&= (\boldsymbol{w}_g - \boldsymbol{w}_{o,l}^a)\frac{\partial \beta^i_{t_i-1}}{\partial \gamma_{t_i-1}^i}.
\end{aligned}
\end{equation*}
After elaborating $\beta^i_{t_i-1}$, we have:
\begin{equation*}
\begin{aligned}
\frac{\partial \beta^i_{t_i-1}}{\partial \gamma_{t_i-1}^i} &= \frac{\partial(1-(1 + \mu_{\beta} \phi^i_{t_i-1})^{-1})}{\partial \gamma_{t_i-1}^i} \\
&= \frac{\mu_{\beta}}{(1 + \mu_{\beta} \phi^i_{t_i-1})^{2}}\frac{\partial \phi^i_{t_i-1}}{\partial \gamma_{t_i-1}^i} \\
&= \frac{\mu_{\beta}}{\sqrt{g}(1 + \mu_{\beta} \phi^i_{t_i-1})^{2}}(1-\frac{\upsilon^i_{t_i-1}}{\sqrt{g - o + 1}}),
\end{aligned}
\end{equation*}
where $\phi^i_{t_i-1}$ represents $\phi^i_{t_i-1}(g,o)$. Finally, we can calculate the partial deviation of the loss function in terms of $\gamma_{t_i-1}^i$:
\begin{equation*}
\begin{aligned}
&\nabla_{\gamma^i_{t_i-1}} \mathcal{F}_i(\boldsymbol{w}_{o,l}^b, \zeta_{l-1}) \\
= ~&(\boldsymbol{w}_g - \boldsymbol{w}_{o,l}^a)\frac{\mu_{\beta}g_{o,l}^\mathrm{T}(\boldsymbol{w}_{o,l}^b)}{\sqrt{g}(1 + \mu_{\beta} \phi^i_{t_i-1})^{2}}(1-\frac{\upsilon^i_{t_i-1}}{\sqrt{g - o + 1}}).
\end{aligned}
\end{equation*}
Similarly, we can derive the partial deviation of the loss function with respect to $\upsilon^i_{t_i-1}$:
\begin{equation*}
\begin{aligned}
\nabla_{\upsilon^i_{t_i-1}} \mathcal{F}_i(\boldsymbol{w}_{o,l}^b, \zeta_{l-1}) &= \frac{\mu_{\beta}\gamma^i_{t_i-1}g_{o,l}^\mathrm{T}(\boldsymbol{w}_{o,l}^b)(\boldsymbol{w}_{o,l}^a - \boldsymbol{w}_g)}{\sqrt{g}\sqrt{g - o + 1}(1 + \mu_{\beta} \phi^i_{t_i-1})^{2}}.
\end{aligned}
\end{equation*}

Algorithm \ref{alg:device_passive} shows the device-side model update algorithm of \AName{}. First, an epoch number $l^*$ (time slot) for  requesting a fresh global model is set based on $\theta_{t-1}$ when $t = 1$ or $\mathcal{H}_{t_i-1}^i$ when $t\neq 1$ (Line \ref{alg:select}). In the $l^*$-th local epoch, the device sends a request to the server (Line \ref{alg:send}), and it waits for the fresh global model (Line \ref{alg:wait}). After receiving the fresh global model (Line \ref{alg:receiveFresh}), we exploit Equation \eqref{eq:betaUpdate} to update $\beta^i_{t_i-1}$ (Line \ref{alg:betaUpdate}), Equation \eqref{eq:deviceAggregation} to update $\boldsymbol{w}_{o,l-1}$ (Line \ref{alg:deviceAggregation}), Equation \eqref{eq:controlDevice} to update $\gamma^i_{t-1}$ and $\upsilon^i_{t-1}$ (Line \ref{alg:controlDeviceUpdate}), the reward values (Line \ref{alg:rewardUpdate}), $b_{t-1}$ with $\rho$ being a hyper-parameter (Line \ref{alg:btUpdate}), $\theta_{t}$ when $t = 1$ or $\mathcal{H}_{t_i-1}^i$ when $t \neq 1$ (Line \ref{alg:rlupdate}). Finally, the local model is updated (Line \ref{alg:SGDUpdate}).


\subsection{Convergence Analysis}

In this subsection, we present the assumptions of \AName{}, followed by its convergence guarantees.
%(see details in Appendix). 
\begin{assumption} 
\label{ass:smooth}
($L$-smoothness) The loss function $\mathcal{F}_i$ is differentiable and $L$-smooth for each device $i \in \mathcal{M}$ and $\forall x, y$, 
$
\mathcal{F}_i(y) - \mathcal{F}_i(x) \leq \ip{\nabla \mathcal{F}_i(x)}{y-x} + \frac{L}{2} \|y-x\|^2
$
with $L > 0$.
\end{assumption}
\begin{assumption} 
\label{ass:convex}
($\mu$-strongly convex)
The loss function $\mathcal{F}_i$ is $\mu$-strongly convex for each device $i \in \mathcal{M}$: $ \langle \nabla \mathcal{F}_i(x) - \nabla \mathcal{F}_i(y), x - y \rangle  \geq  \mu \parallel x - y \parallel ^ 2$ with $\mu > 0$.
\end{assumption}
\begin{assumption} 
\label{ass:sampling}
(Unbiased sampling)
The local sampling is unbiased and the local gradients are unbiased stochastic gradients $\mathbb{E}_{\zeta_l \sim \mathcal{D}_i} [\nabla \mathcal{F}_i(\boldsymbol{w}_{o,l}; \zeta_l)] = \nabla \mathcal{F}_i(\boldsymbol{w}_{o,l})$.
\end{assumption}
\begin{assumption} 
\label{ass:gradient}
(Bounded local gradient)
The stochastic gradients are bounded on each device $i \in \mathcal{M}$: $\mathbb{E}_{\zeta_l \sim \mathcal{D}_i} \parallel \nabla \mathcal{F}_i(\boldsymbol{w}_{o,l}; \zeta_l) \parallel^2 \le{\mathcal{G}^2}$.
\end{assumption}
\begin{assumption} 
\label{ass:variance}
(Bounded local variance)
The variance of local stochastic gradients are bounded on each device $i \in \mathcal{M}$ is bounded: $\mathbb{E}_{\zeta_l \sim \mathcal{D}_i} \parallel \nabla \mathcal{F}_i(\boldsymbol{w}_{o,l}; \zeta_l) - \mathcal{F}(\boldsymbol{w}_{o,l}) \parallel^2 \le{\mathcal{V}^2}$.
\end{assumption}
\begin{theorem}
Let Assumptions \ref{ass:smooth} - \ref{ass:variance} hold, after $T$ global updates, \AName{} converges to a critical point:
\begin{align*}
&\min_{t=0}^{T} \E\parallel \nabla \mathcal{F}(\boldsymbol{w}_{o,l}) \parallel^2 \\
\leq~& \frac{2 \E\left[ \mathcal{F}(\boldsymbol{w}_{0}) - \mathcal{F}(\boldsymbol{w}_{T}) \right]}{\alpha_{min} \mathcal{L}_{min}^3} + \OM\left( \frac{L \mathcal{G}^2 \mathcal{L}_{max}}{\mathcal{L}_{min}^3} \right) \\
&\quad + \OM\left( \frac{\mathcal{L}^i \mathcal{V}^2}{ \mathcal{L}_{min}^7}\right) + \OM\left( \frac{\tau \mathcal{G}^2 \mathcal{L}_{max}}{ \mathcal{L}_{min}^7} \right) \\
&\quad + \OM\left( \frac{ \mathcal{G}^2 \mathcal{L}_{max} }{\mathcal{L}_{min}^3} \right) + \OM\left( \frac{ L \mathcal{G}^2 \mathcal{L}_{max} }{\mathcal{L}_{min}^3} \right)\\
&  + \OM\left(\frac{ L \tau^2 \mathcal{G}^2 \mathcal{L}_{max}^2}{\mathcal{L}_{min}^3} \right) + \OM\left( \frac{ L \tau^2 \mathcal{G}^2 \mathcal{L}_{max}^2 }{\mathcal{L}_{min}^3} \right),
\end{align*}
where $\alpha_{min} \leq \alpha_t^i$, $\mathcal{L}_{min} \leq \mathcal{L}_t \leq \mathcal{L}_{max}$, $\eta_i = \frac{1}{\sqrt{T}}$, $\forall i \in \mathcal{M}$, and $T = \mathcal{L}_{min}^6$.
\end{theorem}

\rev{
See Appendix \ref{sec:appendx} for the detailed proof of Theorem 1, which demonstrates how Assumptions \ref{ass:smooth} - \ref{ass:variance} ensure convergence.
}

