\begin{algorithm}[H]
\caption{\rev{\SName{} on the Server and Devices}}
\label{alg:FedSSMU}
\begin{algorithmic}[1]

\REQUIRE \quad \\
\textbf{Server Inputs:} \\
$T$: The maximum number of global rounds \\
$m'$: The number of devices to be triggered in each round \\
$\tau$: The predefined staleness limit \\
$\boldsymbol{w}_{1,0}$: The initial global model for round 1 \\
$\lambda_{0}^i, \sigma_{0}^i, \iota_{0}^i$: Initial control parameters for each device $i$ \\
$\eta_{\lambda^i}, \eta_{\sigma^i}, \eta_{\iota^i}$: Learning rates for server-side control parameter updates \\

\textbf{Device Inputs:} \\
$\mathcal{L}^i$: The maximum number of local epochs on Device $i$ \\
$\boldsymbol{w}_{g,0}$: The global model received from the server at round $g$ \\
$\gamma_{t_i}^i, \upsilon_{t_i}^i$: Initial control parameters for device-side aggregation \\
$\eta_{\gamma^i}, \eta_{\upsilon^i}$: Learning rates for device-side control parameter updates \\
$\eta_i$: Learning rate for local SGD \\
$\Theta_g$: Parameters of the RL model at round $g$ \\

\ENSURE \quad \\
$\boldsymbol{w}_{T+1,0}$: The final global model after round $T$ \\

\STATE \textbf{Server-Side Procedure:}
\FOR{$g = 1$ to $T$}
    \STATE Randomly select $m'$ devices and send $\boldsymbol{w}_{g,0}$ to them \quad // Trigger devices with global model
    \STATE Initialize $k = 0$ \quad // Counter for aggregated models in this round
    \WHILE{not all $m'$ devices have uploaded their models}
        \STATE Receive $\boldsymbol{w}_{g,0}^i$ from Device $i$ \quad // Collect local model from device
        \STATE Compute staleness $\tau_i = k + 1$ \quad // Staleness based on aggregation count
        \IF{$\tau_i > \tau$}
            \STATE Discard $\boldsymbol{w}_{g,0}^i$ \quad // Discard if staleness exceeds limit
        \ELSE
            \STATE Update $\lambda_g^i, \sigma_g^i, \iota_g^i$ using Equation \eqref{eq:control} \quad // Dynamic parameter adjustment
            \STATE Compute $\alpha_g^i$ using Equation \eqref{eq:alpha} \quad // Calculate aggregation weight
            \STATE Update $\boldsymbol{w}_{g,k+1} = (1 - \alpha_g^i) \boldsymbol{w}_{g,k} + \alpha_g^i \boldsymbol{w}_{g,0}^i$ \quad // Aggregate models
            \STATE Set $k = k + 1$ \quad // Increment aggregation counter
        \ENDIF
    \ENDWHILE
    \STATE Set $\boldsymbol{w}_{g+1,0} = \boldsymbol{w}_{g,k}$ \quad // Set global model for next round
\ENDFOR
\STATE \textbf{Return} $\boldsymbol{w}_{T+1,0}$

\STATE \textbf{Device-Side Procedure (for each Device $i$ at round $g$):}
\STATE Receive $\boldsymbol{w}_{g,0}$ from server and set $\boldsymbol{w}_{g,0}^i = \boldsymbol{w}_{g,0}$
\STATE Determine request time slot $l^*$ using RL model with parameters $\Theta_g$ \quad // See Section \ref{subsec:slot_selection}
\FOR{$l = 1$ to $\mathcal{L}^i$}
    \IF{$l = l^*$}
        \STATE Request fresh global model from server
        \STATE Receive $\boldsymbol{w}_{g,k}$ (if available, where $k > 0$)
    \ENDIF
    \IF{$\boldsymbol{w}_{g,k}$ received and $k > 0$}
        \STATE Compute $\beta_{t_i}^i$ using Equation \eqref{eq:betaUpdate} \quad // Weight for merging
        \STATE Update $\boldsymbol{w}_{g,l-1}^i = (1 - \beta_{t_i}^i) \boldsymbol{w}_{g,l-1}^i + \beta_{t_i}^i \boldsymbol{w}_{g,k}$ \quad // Merge with fresh global model
        \STATE Update $\gamma_{t_i}^i, \upsilon_{t_i}^i$ using Equation \eqref{eq:controlDevice} \quad // Adjust parameters
    \ENDIF
    \STATE Update $\boldsymbol{w}_{g,l}^i = \boldsymbol{w}_{g,l-1}^i - \eta_i \nabla \mathcal{F}_i(\boldsymbol{w}_{g,l-1}^i, \zeta_{l-1})$ \quad // Local SGD, $\zeta_{l-1} \sim \mathcal{D}_i$
\ENDFOR
\STATE Upload $\boldsymbol{w}_{g,\mathcal{L}^i}^i$ to server

\end{algorithmic}
\end{algorithm}
\end{figure}


In this section, we extend the above approach to the synchronous FL case. In the synchronous version named FedSSMU as shown in Algorithm \ref{alg:FedSSMU}, the server triggers local training on $m'$ devices at the beginning of each global round. The training is organized into multiple global rounds, starting with an initial global model version of 0. The global model version is incremented by 1 at the end of each global round. 

The training process of \SName{} includes the following steps:
\begin{itemize}
\item Step \textcircled{1}: At the beginning of each global round $g$, the server triggers $m' (m' \leq m)$ randomly selected devices and broadcasts the current global model $\boldsymbol{w}_{g,0}$ to them, where $g$ is the global round number, and $0$ indicates that no local models have been received yet by the server in this round.
\item Step \textcircled{2}: Each selected device performs local training using its local dataset. The training is conducted by applying the gradient descent method described in Equation \eqref{eq:localSGD}.
%Step \textcircled{2}: Each selected device performs local training using its local dataset.
\item %Step \textcircled{3}: During local training, Device $i$ requests the latest global model $\boldsymbol{w}_{g, k}$ from the server to minimize staleness, as the global model may have been updated concurrently.
Step \textcircled{3}: During local training, Device $i$ dynamically determines the slot for requesting the latest global model $\boldsymbol{w}_{g, k}$ from the server to minimize staleness, based on the RL-based method detailed in Section \ref{subsec:slot_selection}. This mechanism balances the trade-off between requesting the updated global model too early, which risks incorporating insufficient updates, and requesting too late, which may lead to underutilizing the updated model.
\item Step \textcircled{4}: When the server receives a request for an updated model, it checks the version of the global model. If the version $k > 0$, indicating that there is a newer global model, the server sends the updated global model $\boldsymbol{w}_{g,k}$ to the requesting device.
%Step \textcircled{5}: Upon receiving the updated global model, the device merges it with its latest local model to form a new model and continues local training with this updated model.
\item Step \textcircled{5}: Upon receiving the updated global model, the device merges it with its latest local model using the aggregation method outlined in Section \ref{subsec:device_agg}. This process is governed by Equation \eqref{eq:deviceAggregation} and includes parameter adjustments as specified in Equation \eqref{eq:controlDevice}. The device then continues local training with this updated model.
\item Step \textcircled{6}: Once local training is completed, Device $i$ uploads its locally trained model to the server.
%Step \textcircled{7}: Whenever the server receives a local model $\boldsymbol{w}^i_{g,0}$ from any device, it immediately aggregates this local model with the current global model $\boldsymbol{w}_{g,k}$. After each aggregation, the global model version is incremented from $\boldsymbol{w}_{g,k}$ to $\boldsymbol{w}_{g,k+1}$, where $k$ denotes the number of local models that have been aggregated so far in the current global round $g$. The staleness of the local model is calculated as $\tau_i = k + 1$. If $\tau_i$ exceeds a predefined threshold $\tau$, indicating excessive staleness, the local model is discarded to maintain convergence and avoid reverting the global model to a less accurate state.
\item Step \textcircled{7}: Whenever the server receives a local model $\boldsymbol{w}^i_{g,0}$ from any device, it immediately aggregates this local model with the current global model $\boldsymbol{w}_{g,k}$ using the server-side aggregation method described in Section \ref{subsec:MAServer}. This process adheres to Equation \eqref{eq:serverAggregation} and incorporates parameter adjustments as defined in Equation \eqref{eq:control}. After each aggregation, the global model version is incremented from $\boldsymbol{w}_{g,k}$ to $\boldsymbol{w}_{g,k+1}$, where $k$ denotes the number of local models that have been aggregated so far in the current global round $g$. The staleness of the local model is calculated as $\tau_i = k + 1$. If $\tau_i$ exceeds a predefined threshold $\tau$, indicating excessive staleness, the local model is discarded to maintain convergence and avoid reverting the global model to a less accurate state.
\end{itemize}

