\caption{\label{fig21} Schematic view of an experiment presenting the various dimensions of interest.}
\end{figure}

The simulation results are shown in Fig.~\ref{figlens0.1} and Fig.~\ref{figlens1} which correspond to scintillators of 0.1 mm and 1 mm respectively.

\begin{figure}[h]
\includegraphics[width=0.5\textwidth]{Figures/Fig-16.png}% Here is how to import EPS art
\caption{\label{figlens0.1}Optical simulations of p$^{+}$, He$^{1+}$ and He$^{2+}$ in the configuration where the photons emitted by a scintillator of 0.1 mm are collected with an optical system. The binning corresponds to the pitch of the camera (6.5 µm).}
