\section{Motivation}
The motivation for this work comes from few sources. The first originated from a problem posed by a close friend, who asked me to prove the identity
\begin{equation}
	\label{1.1}
	\sum_{n=0}^{\infty}\operatorname{Li}_3(-e^{-(2n+1)\pi})=-\frac{\pi^3}{720}.
\end{equation}
where $\operatorname{Li}_3(z)=\sum_{k=1}^{\infty}\frac{z^k}{k^3}$ for $|z|<1$, is the trilogarithm function.
While working through this problem, we uncovered an interesting generalization that led us to investigate related series more deeply. This line of inquiry eventually brought us to the papers of Vepštas and Plouffe \cite{Vepstas,pluffe}, which formed the second source of inspiration. In particular, Vepštas derived elegant results one of which is involving Bernoulli numbers $B_n$ and the Riemann Zeta function $\zeta(m)$ (See \cite[Section 24.2 and 25.2 ]{NIST}) is \cite[Corollary 2, p.9]{Vepstas}
\begin{align*}
2\sum_{p=1}^{\infty}\operatorname{Li}_{4m-1}(e^{-2\pi p})&=2\sum_{n=1}^{\infty}\frac{1}{n^{4m-1}(e^{2\pi n}-1)}\\
&=-\zeta(4m-1)+\frac{(2\pi)^{4m-1}}{(4m)!}\sum_{j=0}^{2m}\binom{4m}{2j}(-1)^jB_{2j}B_{4m-2j}.
\end{align*}
The above identity also appears in a paper written by Cerbo \cite{cerbo}
\newpage
\vspace{-5mm}
Also, Vepštas \cite[Theorem 9, p.12]{Vepstas} studied the series $S_s(x)=\sum_{m=1}^{\infty}\operatorname{Li}_s(e^{-xm})$ and showed that 
$$\zeta(3)=\frac{5\pi^3}{72}-\frac{1}{2}S_3(2\pi\sqrt{3})-\frac{3}{2}S_3\left(\frac{2\pi\sqrt{3}}{3}\right)$$
A substantial collection of related sums has been previously investigated; this part offers a review of several notable examples. One of the most striking instances is a series introduced by Ramanujan \cite[Eq.(1.41)]{sanham}, stating 
\begin{align*}
\frac{1^{13}}{e^{2\pi}-1}+\frac{2^{13}}{e^{4\pi}-1}+\frac{3^{13}}{e^{6\pi}-1}+\cdots &= \frac{1}{24}\\
\frac{1^{5}}{e^{1\pi}-1}+\frac{3^{5}}{e^{3\pi}-1}+\frac{5^{5}}{e^{5\pi}-1}+\cdots &= \frac{31}{504}
\end{align*}
More similar sums were discussed by Zucker \cite{zucker1,zucker2}. Some of these sums are
\begin{align*}
&\sum_{n=1}^{\infty} \frac{1}{n \left(e^{2\pi n x} + 1\right)} = \frac{1}{2} \sum_{m=1}^{\infty} \frac{1 - \tanh(\pi m x)}{m}\\
&\sum_{n=1}^{\infty} \frac{(-1)^n}{n \left(e^{2\pi n x} + 1\right)} = \frac{1}{2} \sum_{m=1}^{\infty} \frac{(-1)^m \left(1 - \tanh(\pi m x)\right)}{m}\\
&\sum_{n=1}^{\infty}(-1)^{n+1}\operatorname{cosech}(\pi n)\coth(\pi n)=\frac{1}{12}=2\sum_{n=0}^{\infty}\frac{2n+1}{e^{(2n+1)\pi}+1}\\
&\sum_{n=1}^{\infty}(-1)^{n+1}n\ \operatorname{cosech}(\pi n)=\frac{1}{4\pi}=\frac{1}{2}\sum_{n=1}^{\infty}\operatorname{sech}^2((2n-1)\pi/2)
\end{align*}
\par In this paper we present an addendum to Vepštas's paper by considering this class of sums 
\begin{align}
	\label{1.2}
	\Phi^{+}(q\ ;a):=\sum_{n=0}^{\infty}\operatorname{Li}_{2q+1}(-e^{-a\pi(2n+1)})
\end{align}
for $q\in \mathbb{N}\setminus\{1\}$ such that $q\equiv 1 \ (mod\ 2)$ and $a\in \mathbb{N}$ and $\operatorname{Li}_s(z)=\sum_{k=1}^{\infty}\frac{z^k}{k^s}$ for $|z|<1$ is defined to be the polylogarithm function, for more information see \cite[section 25.12]{NIST}. And a new proof for the sum
\begin{align}
	\label{raman}
\Phi(p):=	\sum_{k=0}^{\infty}\frac{\tanh\left(\frac{\pi(2k+1)}{2}\right)}{(2k+1)^{4p-1}} \quad \text{for}\  p\in \mathbb{N}
\end{align}
\par The technique used in this manuscript is both direct and elementary, relying exclusively on algebraic manipulations. This deliberate avoidance of complex analytic techniques highlights the strength and elegance of elementary methods in deriving meaningful results.

\section{The Evaluations of $\Phi^{+}(q; a)$}
Before we begin the evaluation of $\Phi^{+}(q;a)$, we present a proposition and the proof of the identity in \eqref{1.1}.
\begin{proposition}[Mittag-Leffler expansion for the cosecant function]
	Let $z\in \mathbb{C}\setminus\{0\}$, then
	\begin{equation}
		\label{mittag1}
		\csc(\pi z)=\frac{1}{\pi z}+\frac{2z}{\pi}\sum_{k=1}^{\infty}\frac{(-1)^k}{z^2-k^2}	
	\end{equation}
	the identity appears in \cite[Entry. 1.422.(4)]{inteseries}
\end{proposition}
\subsection{Proof of the identity in \eqref{1.1}}
Suppose we have  $\Omega_1=\sum_{n=0}^{\infty}\operatorname{Li}_3(-e^{-(2n+1)\pi})$, it's clear that 
\begin{align*}
	\Omega_1 &=\sum_{n=0}^{\infty}\sum_{k=1}^{\infty}\frac{(-1)^ke^{-(2n+1)\pi k}}{k^3}=\sum_{k=1}^{\infty}\frac{(-1)^k}{k^3}\sum_{n=0}^{\infty}e^{-(2n+1)\pi k}
	=\sum_{k=1}^{\infty}\frac{(-1)^ke^{-\pi k}}{k^3(1-e^{-2\pi k})}\\
	&=\frac{1}{2}\sum_{k=1}^{\infty}\frac{(-1)^k}{k^3}\operatorname{cosech}(\pi k)
\end{align*}
using \eqref{mittag1}, set $z=iz$ and thus,
\begin{align*}
	\Omega_1&=\frac{1}{2}\sum_{k=1}^{\infty}\frac{(-1)^k}{k^3}\left\{\frac{1}{\pi k}-\frac{2k}{\pi}\sum_{n=1}^{\infty}\frac{(-1)^{n+1}}{k^2+n^2}\right\}
	=\frac{1}{2}\sum_{k=1}^{\infty}\frac{(-1)^k}{\pi k^4}-\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k+1}}{\pi k^2(k^2+n^2)}\\
	&=\frac{-7\pi^3}{1440}-\frac{1}{\pi}\underbrace{\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k+1}}{k^2(k^2+n^2)}}_{\Omega_2}
\end{align*}
We notice $\Omega_2$ is symmetric over $k$ and $n$, that is;
$$ \sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k}}{k^2(k^2+n^2)}=\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k}}{n^2(k^2+n^2)} $$
Let's us define the function $f(n,k)=\frac{(-1)^{n+k}}{n^2(k^2+n^2)}$, we deduce immediately that
$$\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}f(k,n)=\frac{1}{2}\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}f(k,n)+\frac{1}{2}\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}f(n,k)$$
Then, we have;
\begin{align*}
	\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k}}{k^2(k^2+n^2)} &=\frac{1}{2}\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k}}{k^2(k^2+n^2)}+\frac{1}{2}\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k}}{n^2(k^2+n^2)}\\		&=\frac{1}{2}\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k}}{(k^2+n^2)}\left(\frac{1}{n^2}+\frac{1}{k^2}\right)
\end{align*}
Since the above double sum is absolutely convergent, we can switch the order of summation to get
\begin{align*}
	\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k}}{k^2(k^2+n^2)}&=\frac{1}{2}\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k}}{(k^2+n^2)}\left(\frac{1}{n^2}+\frac{1}{k^2}\right)	=\frac{1}{2}\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{k+n}}{n^2k^2}\\
	&=\frac{1}{2}\left(\sum_{k=1}^{\infty}\frac{(-1)^k}{k^2}\right)^2=\frac{\pi^4}{288}
\end{align*}
From this point, we have established that
$$\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{(-1)^{n+k+1}}{k^2(k^2+n^2)}=-\frac{\pi^4}{288}.$$
Finally, we conclude;
$$\Omega_1=-\frac{7\pi^3}{1440}-\frac{1}{\pi}\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{(-1)^{n+k+1}}{k^2(k^2+n^2)}=-\frac{\pi^3}{720}.$$

In the following, we present a series of lemmas that will play a crucial role in the subsequent evaluation of $\Phi^{+}(q;a)$. These foundational results provide the necessary tools and structure to carry out the analysis in a systematic manner.
\begin{lemma}[Partial fraction Decomposition]\label{lemma2.1} 
	For $q\in \mathbb{N}\setminus\{1\}$ and $n,k\in \mathbb{N}$, thus if 
	$$\wp(2q,n,k)=\frac{1}{n^{2q}(n^2+k^2)}$$
	then 
	$$\wp(2q,n,k)=\sum_{m=0}^{q-2}\frac{(-1)^m}{n^{2(q-m)}k^{2(m+1)}}+\frac{(-1)^{q+1}}{n^2k^{2(q-1)}(n^2+k^2)}$$
\end{lemma}
\begin{proof}
We shall show this via mathematical induction. For the base case, it's clear that 
$$\wp(4,n,k)=\frac{1}{n^4(n^2 + k^2)} = \frac{1}{n^4k^2} - \frac{1}{n^2k^2(n^2 + k^2)}$$
Now, assume that the identity holds for some $Q\geq 2$, that is;
\begin{equation}\label{partial}
	\wp(2Q,n,k)=\sum_{m=0}^{Q-2}\frac{(-1)^m}{n^{2(Q-m)}k^{2(m+1)}}+\frac{(-1)^{Q+1}}{n^2k^{2(Q-1)}(n^2+k^2)}
\end{equation}
next, we show $\wp(2Q+2,n,k)$ holds true. To this end, multiply both sides of the inductive hypothesis \eqref{partial} by $\frac{1}{n^2}$ to obtain 
\begin{equation}
	\label{2.2}
	\frac{1}{n^{2(Q+1)}(n^2 + k^2)} = \sum_{m=0}^{Q-2} \frac{(-1)^m}{n^{2(Q+1 - m)}k^{2(m+1)}} + \frac{(-1)^{Q+1}}{n^4 k^{2(Q-1)}(n^2 + k^2)}
\end{equation}
observe, from the last term in \eqref{2.2}, we have that
$$\frac{(-1)^{Q+1}}{n^4 k^{2(Q-1)}(n^2 + k^2)}=\frac{(-1)^{Q-1}}{n^{2(Q+1-(Q-1))}k^{2(Q-1+1)}}+\frac{(-1)^{Q+2}}{n^2k^{2Q}(n^2+k^2)}$$
Hence,
\vspace{-3mm} 
$$\wp(2Q+2,n,k)=\sum_{m=0}^{Q-1}\frac{(-1)^m}{n^{2(Q+1-m)}k^{2(m+1)}}+\frac{(-1)^{Q+2}}{n^2k^{2Q}(n^2+k^2)}$$
which completes the inductive step.
\end{proof}
\begin{lemma}\label{lemma2.2}
	For $q\in \mathbb{N}\setminus\{1\}$ such that $q\equiv 1 \ (mod\ 2)$ then
	$$\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^{2q}(n^2+k^2)}=\frac{1}{2}\sum_{m=0}^{q-2}(-1)^m\zeta(2q-2m)\zeta(2m+2)+(-1)^{q+1}\frac{\zeta(2q)\zeta(2)}{2}$$	
	$$\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{(-1)^{n+k}}{n^{2q}(n^2+k^2)}=\frac{1}{2}\sum_{m=0}^{q-2}(-1)^m\eta(2q-2m)\eta(2m+2)+(-1)^{q+1}\frac{\eta(2q)\eta(2)}{2}$$	
	where $\zeta(s)=\sum_{k=1}^{\infty}\frac{1}{k^s}$ and $\Re(s)>1$ with $\eta(s)=\sum_{k=1}^{\infty}\frac{(-1)^{k+1}}{k^s}$ and $\Re(s)>0$ 	is the Dirichlet eta function.
\end{lemma}
\begin{proof}
		Recall the partial fraction decomposition of $\wp(2q,n,k)$ in Lemma \ref{lemma2.1} and thus, 
\begin{align*}
\sum_{n,k=1}^{\infty}\wp(2q,n,k)&=\sum_{m=0}^{q-2}(-1)^m\zeta(2q-2m)\zeta(2m+2)+\sum_{n,k=1}^{\infty}\frac{(-1)^{q+1}}{n^2k^{2(q-1)}(n^2+k^2)}\\
&=\sum_{m=0}^{q-2}(-1)^m\zeta(2q-2m)\zeta(2m+2)+\sum_{n,k=1}^{\infty}\frac{(-1)^{q+1}}{k^{2q}n^2}-\sum_{n,k=1}^{\infty}\wp(2q,k,n)
\end{align*}
so, after rearrangement the result follows immediately. A similar approach would suffice for the second identity.
\end{proof}
\begin{lemma}\label{lemma2.3}
	For $q\in \mathbb{N}\setminus\{1\}$ such that $q\equiv 1 \ (mod\ 2)$ and $a\in \mathbb{N}$, we have that;
	\begin{align*}
&\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^{2q}(n^2+a^2k^2)}=\frac{a^{2q}}{a^{2q}+1}\left[\sum_{m=0}^{q-2}\frac{(-1)^m}{a^{2m+2}}\zeta(2q-2m)\zeta(2m+2)+\frac{(-1)^{q+1}}{a^{2q}}\zeta(2q)\zeta(2)\right]\\
&\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{(-1)^{n+k}}{n^{2q}(n^2+a^2k^2)}=\frac{a^{2q}}{a^{2q}+1}\left[\sum_{m=0}^{q-2}\frac{(-1)^m}{a^{2m+2}}\eta(2q-2m)\eta(2m+2)+\frac{(-1)^{q+1}}{a^{2q}}\eta(2q)\eta(2)\right]
\end{align*}

\end{lemma}
\begin{proof}
	By the partial fraction decomposition Lemma, we have that 
\begin{align*}
	&\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^{2q}(n^2+a^2k^2)}\\
	&=\sum_{m=0}^{q-2}\frac{(-1)^m}{a^{2m+2}}\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^{2q-2m}k^{2m+2}}+\frac{(-1)^{q+1}}{a^{2q-2}}\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^2k^{2q-2}(n^2+a^2k^2)}	
\end{align*}
Now, 
\begin{align*}
	\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^2k^{2q-2}(n^2+a^2k^2)}=\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{a^2k^{2q}n^2}-\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{a^2k^{2q}(n^2+a^2k^2)}
\end{align*}
But by symmetry, 
$$\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{k^{2q}(n^2+a^2k^2)}=\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^{2q}(n^2+a^2k^2)}$$
Hence, we deduce that
\begin{align*}
	&\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^{2q}(n^2+a^2k^2)}\\
	&=\sum_{m=0}^{q-2}\frac{(-1)^m}{a^{2m+2}}\zeta(2q-2m)\zeta(2m+2)+\frac{(-1)^{q+1}}{a^{2q}}\zeta(2q)\zeta(2)-\frac{(-1)^{q+1}}{a^{2q}}\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^{2q}(n^2+a^2k^2)}
\end{align*}
Thus, by rearranging gives the desired result. With similar arguments the second result holds true.
\end{proof}
\begin{rmk}
From Lemma \ref{lemma2.3}, if;
$$\nu_q(a)=\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{n^{2q}(n^2+a^2k^2)} \quad \text{and} \quad \nu^{*}_q(a)=\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{(-1)^{n+k}}{n^{2q}(n^2+a^2k^2)}$$
we immediately notice that,
\begin{align}\label{eqn2.3}
	\begin{split}
\nu_3(a)=\sum_{n=1}^{\infty}\frac{n\pi\coth\left(\frac{n\pi}{a}\right)-a}{2an^8}
=\frac{a^6}{1+a^6}\left[\frac{\zeta(6)\zeta(2)}{a^6}-\frac{\zeta^2(4)}{a^4}+\frac{\zeta(6)\zeta(2)}{a^2}\right]
\end{split}
\end{align}
\begin{align}\label{eqn2.4}
	\begin{split}
	\nu^{*}_3(a)=\sum_{n=1}^{\infty}\frac{(-1)^n\left(n\pi\operatorname{csch}\left(\frac{n\pi}{a}\right)-a\right)}{2an^8}
	=\frac{a^6}{1+a^6}\left[\frac{\eta(6)\eta(2)}{a^6}-\frac{\eta^2(4)}{a^4}+\frac{\eta(6)\eta(2)}{a^2}\right]
	\end{split}
\end{align}
\vspace{-5mm}
\begin{align}
\begin{split}
\hspace{-1.5mm}\nu_5(a)&=\sum_{n=1}^{\infty}\frac{n\pi\coth\left(\frac{n\pi}{a}\right)-a}{2an^{12}}\\
&=\frac{a^{10}}{1+a^{10}}\left[\frac{\zeta(2)\zeta(10)}{a^{10}}-\frac{\zeta(4)\zeta(8)}{a^{8}}+\frac{\zeta^2(6)}{a^{6}}-\frac{\zeta(8)\zeta(4)}{a^{4}}+\frac{\zeta(10)\zeta(2)}{a^{2}}\right]
\end{split}
\end{align}
\begin{align}
\begin{split}
\hspace{-2.5mm}\nu^{*}_5(a)&=\sum_{n=1}^{\infty}\frac{(-1)^n\left(n\pi\operatorname{csch}\left(\frac{n\pi}{a}\right)-a\right)}{2an^8}\\
&=\frac{a^{10}}{1+a^{10}}\left[\frac{\eta(2)\eta(10)}{a^{10}}-\frac{\eta(4)\eta(8)}{a^{8}}+\frac{\eta^2(6)}{a^{6}}-\frac{\eta(8)\eta(4)}{a^{4}}+\frac{\eta(10)\eta(2)}{a^{2}}\right]
\end{split}
\end{align}
From equation \eqref{eqn2.3} at $a=1$ in $\nu_3(a)$, we get a famous sum by Ramanujan (check \cite{glasser,sanham}) which is
$$\sum_{n=1}^{\infty}\frac{\coth(\pi n)}{n^7}=\frac{19\pi^7}{567000}.$$
\end{rmk}
\begin{theorem}
	For $q\in \mathbb{N}\setminus\{1\}$ such that $q\equiv 1 \ (mod\ 2)$ and $a\in \mathbb{N}$, we have that;
	\begin{align*}
		&\Phi^{+}(q;a)
		=\frac{-\eta(2q+2)}{2a\pi}+\frac{a^{2q+1}}{\pi(a^{2q}+1)}\left[\sum_{m=0}^{q-2}\frac{(-1)^m}{a^{2m+2}}\eta(2q-2m)\eta(2m+2)+\frac{(-1)^{q+1}}{a^{2q}}\eta(2q)\eta(2)\right]
	\end{align*}
\end{theorem}
\begin{proof}
	\begin{align*}
	\Phi^{+}(q;a)&=\sum_{n=0}^{\infty}\sum_{k=1}^{\infty}\frac{(-1)^ke^{-(2n+1)a\pi k}}{k^{2q+1}}=\sum_{k=1}^{\infty}\frac{(-1)^k}{k^{2q+1}}\sum_{n=0}^{\infty}e^{-(2n+1)a\pi k}=\sum_{k=1}^{\infty}\frac{(-1)^ke^{-a\pi k}}{k^{2q+1}(1-e^{-2a\pi k})}\\
	&=\frac{1}{2}\sum_{k=1}^{\infty}\frac{(-1)^k\operatorname{cosech}(a\pi k)}{k^{2q+1}}=\frac{1}{2}\sum_{k=1}^{\infty}\frac{(-1)^k}{k^{2q+1}}\left[\frac{1}{a\pi k}-\frac{2ak}{\pi}\sum_{n=1}^{\infty}\frac{(-1)^{n+1}}{a^2k^2+n^2}\right]\\
	&=\frac{1}{2}\sum_{k=1}^{\infty}\frac{(-1)^k}{a\pi k^{2q+2}}-\sum_{k=1}^{\infty}\sum_{n=1}^{\infty}\frac{a(-1)^{n+k+1}}{\pi k^{2q}(a^2k^2+n^2)}=-\frac{\eta(2q+2)}{2a\pi}+\frac{a}{\pi}\sum_{n=1}^{\infty}\sum_{k=1}^{\infty}\frac{(-1)^{n+k}}{k^{2q}(k^2+n^2)}.
\end{align*}
Thus, by Lemma \ref{lemma2.3} the result follows immediately.
\end{proof}
In particular, 
\begin{align}\label{eqn2.7}
\begin{split}
\Phi^{+}(3;a)&=\sum_{k=1}^{\infty}\frac{(-1)^k\operatorname{cosech}(a\pi k)}{2k^{7}}\\
&=\frac{a\pi^7}{1+a^6}\left[\frac{310a^4-343a^2+310}{3628800}\right]-\frac{127\pi^7}{2419200a}
\end{split}
\end{align}
Now, for $a=1,2$, we have the following;
\begin{align}
\sum_{k=1}^{\infty}\frac{(-1)^k\operatorname{cosech}(\pi k)}{k^{7}}&=-\frac{26\pi^7}{907200}\\
\sum_{k=1}^{\infty}\frac{(-1)^k\operatorname{cosech}(2\pi k)}{k^{7}}&=\frac{1834\pi^7}{134784000}
\end{align}
Similarly, 
\begin{align}\label{eqn2.10}
	\begin{split}
		\Phi^{+}(5;a)&=\sum_{k=1}^{\infty}\frac{(-1)^k\operatorname{cosech}(a\pi k)}{2k^{11}}\\
		&=\frac{a\pi^{11}}{1+a^{10}}\left[\frac{\theta(a)}{201180672000}\right]-\frac{1414477\pi^{11}}{2615348736000a}
	\end{split}
\end{align}
where $\theta(a)=178850a^8-205359a^6+211420a^4-205359a^2+178850$.\\
For example, we have that;
\begin{align}
\sum_{k=1}^{\infty}\frac{(-1)^k\operatorname{cosech}(\pi k)}{k^{11}}&=-\frac{8018\pi^{11}}{27243216000}\\
\sum_{k=1}^{\infty}\frac{(-1)^k\operatorname{cosech}(2\pi k)}{k^{11}}&=\frac{4815611\pi^{11}}{66190924800000}	
