\section{An Alternate proof for $\Phi(p)$}
Before we proceed with presenting an alternative proof for $\Phi(p)$, it is essential to first establish a preliminary result in the form of a lemma and proposition. This lemma will serve as a foundational tool, providing the necessary groundwork for our argument.
\begin{lemma}
	\label{3.1}
	If $p,k,n$ are natural numbers such that 
	$$\vartheta(p,k,n):=\frac{1}{(2n+1)^{4p-2}((2n+1)^2+(2k+1)^2)}$$
	then,
	\begin{align*}
	\vartheta(p,k,n)&=\sum_{m=0}^{2p-3}\frac{(-1)^m}{(2n+1)^{4p-2m-2}(2k+1)^{2m+2}}\\ &+\frac{1}{(2n+1)^2(2k+1)^{4p-4}((2n+1)^2+(2k+1)^2)}
\end{align*}
\end{lemma}
\begin{proof}
	Set $q=2p-1,n=2n+1, k=2k+1$ in Lemma \ref{lemma2.1}.
\end{proof}
\begin{proposition}[Mittag-Leffler expansion for the tangent function] Let $z\in \mathbb{C}$, then
	\begin{equation}
		\label{mittag2}
		\pi\tan(\pi z)=-2z\sum_{n=0}^{\infty}\frac{1}{z^2-\left(n+\frac{1}{2}\right)^2}
	\end{equation}
	which appears in \cite{inteseries}
\end{proposition}

With the lemma now firmly established, we are in a position to revisit the main objective. We now turn to the formal statement and demonstration of this proof.
\begin{theorem}For $p\in \mathbb{N}$
$$	\sum_{k=0}^{\infty}\frac{\tanh\left(\frac{\pi(2k+1)}{2}\right)}{(2k+1)^{4p-1}}=\frac{\pi^{4p-1}}{2}\sum_{q=1}^{2p-1}(-1)^{q+1}\frac{(2^{4p-2q}-1)(2^{2q}-1)}{(2q)!(4p-2q)!}B_pB_{2p-q}.$$
\end{theorem}
\begin{proof}
 From equation \eqref{mittag2} $$\pi\tan(\pi z)=-2z\sum_{n=0}^{\infty}\frac{1}{z^2-\left(n+\frac{1}{2}\right)^2} \quad \text{for} \ z\in \mathbb{C}$$
then, with $z=iz_1$ where $z_1=(2k+1)/2$, we have that 
$$\frac{\pi}{4}\tanh\left(\frac{\pi(2k+1)}{2}\right)=\sum_{n=0}^{\infty}\frac{2k+1}{(2k+1)^2+(2n+1)^2}$$
check \cite[Entry. 1.421(2)]{inteseries}. To this end, we have that 
\begin{align*}
	\frac{\pi}{4}\sum_{k=0}^{\infty}\frac{\tanh\left(\frac{\pi(2k+1)}{2}\right)}{(2k+1)^{4p-1}}=\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{2k+1}{(2k+1)^{4p-1}((2k+1)^2+(2n+1)^2)}		
\end{align*}
Observe, using Lemma \ref{3.1};
\begin{align*}
	&\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{2k+1}{(2k+1)^{4p-1}((2k+1)^2+(2n+1)^2)}\\
	&=\sum_{m=0}^{2p-3}\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{(-1)^m}{(2n+1)^{4p-2m-2}(2k+1)^{2m+2}}+\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{1}{(2n+1)^2(2k+1)^{4p-2}}\\
	&-\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{2n+1}{(2n+1)^{4p-1}((2k+1)^2+(2n+1)^2)}
\end{align*}
Notice, that 
\begin{equation}
	\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{2k+1}{(2k+1)^{4p-1}((2k+1)^2+(2n+1)^2)}=\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{2n+1}{(2n+1)^{4p-1}((2k+1)^2+(2n+1)^2)}	
\end{equation}
Hence,
\begin{align*}
	&\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{2k+1}{(2k+1)^{4p-1}((2k+1)^2+(2n+1)^2)}\\
	&=\frac{1}{2}\left(\sum_{m=0}^{2p-3}\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{(-1)^m}{(2n+1)^{4p-2m-2}(2k+1)^{2m+2}}+\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{1}{(2n+1)^2(2k+1)^{4p-2}}\right)\\
	&=\sum_{m=0}^{2p-3}\frac{(-1)^m}{2^{4p-m+1}}\sum_{k=0}^{\infty}\frac{1}{(k+1/2)^{2m+2}}\sum_{n=0}^{\infty}\frac{1}{(n+1/2)^{4p-2m-2}}+\frac{1}{2^{4p+1}}\sum_{k=0}^{\infty}\frac{1}{(k+1/2)^{4p-2}}\sum_{n=0}^{\infty}\frac{1}{(n+1/2)^{2}}
\end{align*}
Recall that the polygamma function $\psi^{(m)}(z)$ order $m$ \cite[see Entry (5.15)]{NIST} is given by; 
$$\psi^{(m)}(z)=(-1)^{m+1}m!\sum_{k=0}^{\infty}\frac{1}{(z+k)^{m+1}}$$ 
for $n,m\in \mathbb{N}$ and $z\neq 0,-1,-2,\dots$
Thus, it follows immediately that, 
\begin{align*}
	\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{2k+1}{(2k+1)^{4p-1}((2k+1)^2+(2n+1)^2)}&=\sum_{m=0}^{2p-3}\frac{(-1)^m}{2^{4p-m+1}}\frac{\psi^{(2m+1)}(1/2)\psi^{(4p-2m-3)}(1/2)}{(2m+1)!(4p-2m-3)!}\\
	&+\frac{1}{2^{4p+1}}\frac{\psi^{(4p-3)}(1/2)\psi^{(1)}(1/2)}{(4p-3)!}
\end{align*}
To this end, using the identities 
$$\psi^{n}\left(\frac{1}{2}\right)=(-1)^{n+1}n!(2^{n+1}-1)\zeta(n+1) \quad \text{and} \quad \zeta(2n)=\frac{(2\pi)^{2n}}{2(2n)!}|B_{2n}|$$
which are in \cite[Entry (5.15.3)]{NIST} and \cite[Entry (25.6.2)]{NIST} respectively, then
$$	\sum_{k=0}^{\infty}\sum_{n=0}^{\infty}\frac{2k+1}{(2k+1)^{4p-1}((2k+1)^2+(2n+1)^2)}=\frac{\pi^{4p-1}}{2}\sum_{q=1}^{2p-1}(-1)^{q+1}\frac{(2^{4p-2q}-1)(2^{2q}-1)}{(2q)!(4p-2q)!}B_pB_{2p-q}$$
Hence the result.
\end{proof}
\section{Conclusion}
In this paper, we introduced a class of polylogarithm series characterized by two parameters and provided exact evaluations involving the Dirichlet eta function. This development generalizes certain known series identities. The closed-form expressions derived herein contribute to a deeper understanding of the interplay between special functions and infinite series.\\
In addition, we presented an alternative, entirely elementary proof for the hyperbolic sum $\Phi(p)$ demonstrating the efficacy of direct algebraic techniques in handling series traditionally approached via complex analysis. These methods not only offer conceptual clarity but may also serve as a foundation for analyzing other families of series involving polylogarithmic, trigonometric, or hyperbolic components.
\par For instance, the mittag-leffler expansion for the hyperbolic cotangent function is given by 
\begin{equation}
	\label{mittag3}
	\coth(\pi z)=\frac{1}{\pi z}+\frac{2z}{\pi}\sum_{k=1}^{\infty}\frac{1}{k^2+z^2}
\end{equation}
where $z\in \mathbb{C}\setminus\{0\}$. We can immediately deduce that for $p\in \mathbb{N}\setminus\{1\}$ such that $p\equiv 1\ (\text{mod}\ 2)$ and $r\in \mathbb{N}$,
\begin{equation}
	\label{conc1}
	\frac{\coth\left(\frac{r\pi}{2}\right)-2^{-4p}\coth(2r\pi)}{r^{2p+1}}=\frac{2-2^{-4p-1}}{\pi r^{2p+2}}+\frac{4-2^{-4p+2}}{\pi}\sum_{k=1}^{\infty}\frac{1}{r^{2p}(k^2+4r^2)}	
\end{equation}
Thus, 
\begin{equation*}
	\sum_{r=1}^{\infty}\frac{\coth\left(\frac{r\pi}{2}\right)-2^{-4p}\coth(2r\pi)}{r^{2p+1}}=\frac{2-2^{-4p-1}}{\pi}\sum_{r=1}^{\infty}\frac{1}{r^{2p+2}}+\frac{4-2^{-4p+2}}{\pi}\sum_{r=1}^{\infty}\sum_{k=1}^{\infty}\frac{1}{r^{2p}(k^2+4r^2)}	
\end{equation*}
Adopting notations from Remark 1, we see that 
\begin{equation}
	\sum_{r=1}^{\infty}\frac{\coth\left(\frac{r\pi}{2}\right)-2^{-4p}\coth(2r\pi)}{r^{2p+1}}=\frac{2-2^{-4p-1}}{\pi}\sum_{r=1}^{\infty}\frac{1}{r^{2p+2}}+\frac{4-2^{-4p+2}}{\pi}\nu_p(2)
\end{equation}
Hence,
\begin{align*}
	&\sum_{r=1}^{\infty}\frac{\coth\left(\frac{r\pi}{2}\right)-2^{-4p}\coth(2r\pi)}{r^{2p+1}}\\
	&=\frac{(2-2^{-4p-1})\zeta(2p+2)}{\pi}+\frac{4^{p+1}-4^{1-p}}{\pi(4^p+1)}\left\{\sum_{m=0}^{p-2}\frac{(-1)^m}{2^{2m+2}}\zeta(2p-2m)\zeta(2m+2)+\frac{(-1)^{p+1}}{4^p}\zeta(2p)\zeta(2)\right\}
\end{align*}
In 1976, Sayer \cite{sayer} evaluated a similar sum, where he stated that 
\begin{align*}
	\sum_{r=1}^{\infty}\frac{\coth\left(\frac{r\pi}{2}\right)-2^{-4p}\coth(2r\pi)}{r^{4p+1}}=\sum_{r=1}^{\infty}\frac{1+(-1)^{r+1}\cosh(r\pi)}{r^{4p+1}\sinh(r\pi)}, \qquad p=1,2,3,\cdots
\end{align*}
and he showed that
$$M_{4p+1}=(-1)^{p+1}\pi^{-4p-1}2^{-2p+2}(4p)!\sum_{r=1}^{\infty}\frac{1+(-1)^{r+1}\cosh(r\pi)}{r^{4p+1}\sinh(r\pi)}$$
where, 
\vspace{-3mm}
$$M_{4p+1}=(-1)^p\frac{(4p)!}{2^{2p-2}}\sum_{s=0}^{2p}(-1)^s\frac{(2^{4p-2s+2}-1)}{(2s)!(4p-2s+2)!}B_sB_{2p+1-s}$$










