\section{Proof of Main Results}\label{sec:proof}

For the following proofs, some further notation is useful. Let $b \geq 2$ and $x = 0.x_1 x_2 x_3 \ldots$ be the $b$-ary representation of some $x \in [0,1)$. For $d \in \{0,1,\ldots,b-1\}$ and $M \in \nn$, we set
\begin{equation}\label{eq:Lambda}
\Lambda_{b,d,M}(x) := \frac{1}{M} \sum_{j=1}^{M} \chi_{d}(x_j)
\end{equation}
with the characteristic function $\chi_d$, that is, $\chi_d(d) = 1$ and $\chi_d(k) = 0$ for $k \neq d$. In other words, $\Lambda_{b,M}(x)$ is the density of the digit $d$ in the first $M$ digits of the $b$-ary representation of $x$. For general $x \in \rr$, we simply set $\Lambda_{b,d,M}(x) := \Lambda_{b,d,M}(|x| \, \mathrm{mod} \,  1).$ We will be interested in the set $\mathcal{Z}_{b}$
of numbers with accumulations of zeros, that is,
\begin{equation}\label{eq:zero}
    \mathcal{Z}_{b} := \{x \in \rr \, | \, \limsup_{M \to \infty } \Lambda_{b,0,M}(x) = 1 \}
\end{equation}

Let us first demonstrate that the Hausdorff dimension $\dim_{\mathcal{H}}(\mathcal{Z}_b) = 0$ as claimed in Theorem~\ref{thm:main2}.

\begin{lemma}\label{lem:dim}
   Let $b \geq 2$ be an integer. Then,
   \begin{equation}
       \dim_{\mathcal{H}}(\mathcal{Z}_b) = 0.
   \end{equation}
\end{lemma}
The proof of Lemma~\ref{lem:dim} relies on a standard combinatorial estimate and basic properties of Hausdorff measures. As it does not directly follow from Egglestone's result on the Hausdorff-dimension of sets with specific asymptotic digit frequencies \cite{Egg49},  we choose to sketch the complete argument for the convenience of the reader.

\begin{proof}
    First, we recall the construction of the (outer) Hausdorff measure on the real line. For real numbers $s,\delta > $ we introduce the functional
    \begin{equation}
     \mathcal{H}^{s}_{\delta}(A) := \inf \left\{ \sum_{k}^{\infty} |I_k|^s \, \bigg| \, A \subset \bigcup_{k=1}^{\infty} I_k \text{ and } (I_k)_{k} \text{ are open intervals with } |I_k| < \delta \right\}
    \end{equation}
    for any set $A \subset \rr$. Then, the $s$-dimensional (outer) Hausdorff is defined as
    \begin{equation*}
        \mathcal{H}^{s}(A) := \sup_{\delta > 0} \mathcal{H}^{s}_{\delta}(A) = \lim_{\delta \to 0} \mathcal{H}^{s}_{\delta}(A).
    \end{equation*}
    A set $A \subset \rr$ is of zero Hausdorff dimension if and only if $\mathcal{H}^{s}(A) = 0$ for all $s > 0.$ Due to the subadditivity of the Hausdorff measure, it is hence enough to show
    \begin{equation}\label{eq:epss}
        \mathcal{H}^{s}_{\delta}( \mathcal{Z}_b\cap [0,1))
    \end{equation}
    for all $s, \delta > 0$. From now on, we fix the integer $b \geq 2$ and $s,\delta$. We proceed in two steps.

    \textit{Step 1: Combinatorial bound on zero-heavy finite words} \\
    Let us fix some $0 <\varepsilon < \frac12$ and for $M \in \nn$ we consider the set $\Omega_M := \{0,1,\ldots,b-1 \}^M$ of  $b$-ary words of length $M$. For any $w \in \Omega_M$ we set
    $$ N_M(w) = \frac{1}{M} \sum_{j=1}^{M} \chi_{0}(w_j),$$
    and define the set
    $$ \Omega_M^{\varepsilon} := \{ w \in \Omega_M \, | \,N_m(w) \geq 1 - \varepsilon \}. $$
    We note that the size of $\Omega_M^{\varepsilon}$ can be written in terms of a binomial expansion
    \begin{equation} |\Omega_M^{\varepsilon}| = \sum_{K \geq (1-\varepsilon) M}^{M} \binom{M}{K} (b-1)^{M-K} \leq \varepsilon M \binom{M}{\lceil (1-\varepsilon) M \rceil} (1-b)^{\varepsilon N},
    \end{equation}
    where the bound follows from the monotonicity of the binomial. We now employ Stirling's formula to obtain the asymptotic expansion
    $$ \binom{M}{\lceil (1-\varepsilon) M \rceil} = \exp((\gamma(\varepsilon) +o(1)) M),$$
    where we used Landau's $o$-notation and introduced the binary entropy $\gamma : [0,1] \to \rr,$
    \begin{equation}
        \gamma(x) = -x \ln(x) - (1-x) \ln(1-x).
    \end{equation}
    Note that by the above we may find some $M_0 = M_0(\varepsilon)$ s.t. that for all $M \geq M_0(\varepsilon)$
    \begin{equation}\label{eq:boundOmega}
    |\Omega_M^{\varepsilon}| \leq \exp((2 \gamma(\varepsilon) + \varepsilon\ln (1-b))M)
    \end{equation}
    and that the prefactor in the exponential tends to zero as $\varepsilon \to 0$. Therefore, for any $s > 0$, there exists some $\varepsilon(s) $ s.t. for all $\varepsilon < \varepsilon(s)$
    \begin{equation}\label{eq:eps} 2 \gamma(\varepsilon(s)) + \varepsilon(s)\ln (1-b) < \frac{s \ln(b)}{2}  \end{equation}

    \textit{Step 2: Construction of a suitable cover} \\
    We denote by $\phi_M :[0,1) \to \Omega_M$ the function, which maps $x$ to the word $w$ consisting of the $M$ first digits of $x$ with respect to $b$. The partial inverse $\psi_M :\Omega_M \to [0,1)$ maps a word $w$ to the number $x = 0.w_1 w_2 \ldots w_M.$ By definition,
    \begin{equation}\label{eq:cover}
    \mathcal{Z}_b \cap [0,1) \subset \bigcup_{M = K}^{\infty} \{ x \,| \, \Lambda_M(x) \geq 1 - \varepsilon \} = \bigcup_{M = K}^{\infty} \{ x \,| \, \phi_M(x) \in \Omega_{M}^{\varepsilon} \}
    \end{equation}
    for any integer $K$ and any $\varepsilon > 0.$
    Moreover, we note that 
    $$\{ x \,| \, \phi_M(x) \in \Omega_{M}^{\varepsilon} \} \subset \bigcup_{w \in \Omega_{M}^{\varepsilon}} I_M(w) := \bigcup_{w \in \Omega_{M}^{\varepsilon}}\left(\psi_M(w) - \frac{1}{b^M}, \psi_M(w) + \frac{1}{b^M} \right). $$

    We choose some $\varepsilon < \varepsilon(s)$ and we consider integers $K$ large enough s.t. $1/b^{K} < \delta$ and \eqref{eq:boundOmega} holds for all $M \geq K.$ Then, 
    \begin{align*} \mathcal{H}^{s}_{\delta}(\mathcal{Z}_b \cap [0,1)) &\leq \sum_{M =K}^{\infty} \mathcal{H}^{s}_{\delta}(\{ x \,| \, \phi_M(x) \in \Omega_{M}^{\varepsilon} \}) \leq \sum_{M =K}^{\infty} \sum_{w \in \Omega_{M}^{\varepsilon}} |I_M(w)|^{s} \\
    & \leq \sum_{M =K}^{\infty} |\Omega_{M}^{\varepsilon}| \frac{2^s}{b^{sM}} \leq 2^s \sum_{M =K}^{\infty} b^{-\frac{s}{2}M} = \frac{2^s}{(1-b^{s/2})b^{Ks/2}}.
    \end{align*}
    The first line is a consequence of \eqref{eq:cover} and the fact that the intervals $(I_M(w))_{w \in \Omega_{M}^{\varepsilon}} $ cover the set $\{ x \,| \, \phi_M(x) \in \Omega_{M}^{\varepsilon} \}$. The second line then follows from the choice $\varepsilon < \varepsilon(s),$ and equations \eqref{eq:boundOmega} and \eqref{eq:epss}. 
    As we can choose $K$ as large as we want, the last bound reveals $\mathcal{H}^{s}_{\delta}(\mathcal{Z}_b \cap [0,1)) = 0$, which completes the proof.


\end{proof}

Next, we demonstrate that $\mathcal{Z}_b$ is super-dense. 
\begin{proposition}\label{prop:main}
    For any $b \geq 2$ the $\mathcal{Z}_b$ is super-dense, that is, for any non-empty interval $I \subset \rr$ and nowhere constant continuous function $\varphi \colon I \to \rr$
    \begin{equation}\label{eq:prop}
    \varphi(I \cap \mathcal{Z}_{b}) \cap \mathcal{Z}_{b} \neq \emptyset. 
    \end{equation}
\end{proposition}

The proof of Proposition~\ref{prop:main} relies on an iterative "zig-zag" construction of an $x \in \mathcal{Z}_{b}$ such that $y = \varphi(x) \in \mathcal{Z}_{b}$, too. Via a two-step update we make sure that the $b$-ary representation of $x$ and $y$ are dominated by zeros infinitely often.
\begin{proof} We fix the basis $b \geq 2$ and assume without loss of generality that $I \subset (0,1)$. Let us introduce the set $T$,
\begin{equation}
    T := \{ x \in [0,1) \,|\, x = 0.x_1x_2 \ldots x_L  \text{ has a finite } b\text{-ary expansion} \},
\end{equation}
of numbers whose $b$-ary representation terminates and we set 
\begin{equation}
    \tau(x) := \inf \{ L \in \nn \, | \, x = 0.x_1\ldots x_L \}
\end{equation}
for $x \in T$ and otherwise $\tau(x) = \infty$. We need also  the second set 
\begin{equation}
    T' := \left\{  y = x + \frac{1}{b^{K}}  \,|\, x \in T \text{ and } K > \tau(x)^2 +1   \right\},
\end{equation}
which is slightly more stable under subtraction and we set $\tau'(y) = K $ for $y = x + \frac{1}{b^{K}} \in T'$.

Both, $T$ and $T'$ are dense sets.
We now construct 4 sequences 
$$
(x_M^{(1)})_{M \in \nn }, \, (x_M^{(2)})_{M \in \nn }, \quad (y_M^{(1)})_{M \in \nn }, \, (y_M^{(2)})_{M \in \nn }
$$
and will prove that $x := \lim_{M \to \infty} x_M^{(2)} \in \mathcal{Z}_b, $  $y := \lim_{M \to \infty} y_M^{(2)} \in \mathcal{Z}_b, $ and $y = \varphi(x).$

\textit{Step 1: Choice of starting points } \\
Since $T$ is a dense set, we find some $x_{1}^{(1)} \in T \cap I$
and define $L_{x,1} := \tau(x_{1}^{(1)}).$ Let  $y_{1}^{(1)} := \varphi(x_{1}^{(1)})$ be the corresponding function value.  Moreover, we introduce the intervals $$I_{1,x} = (x_{1}^{(1)}, x_{1}^{(1)} + b^{-L^{2}_{x,1} - f})  \quad I_{1,y} = (-\infty, \infty), $$ 
where we choose $f$ big enough s.t. the closure of $I_{1,x}$ is still in $I$.

To construct the two other starting values, we recall that $\varphi$ is nowhere constant, and thus we find some $z \in I_{1,x}$ such that $\varphi(z) \neq \varphi(x_{1}^{(1)}).$ Employing the intermediate value theorem and the density of $T'$, we in fact find some $x_{1}^{(2)} \in I_{1,x} $ such that $y_{1}^{(2)} := \varphi(x_{1}^{(2)}) \in T' $. We note that the $L_{x,1}$-th to the $L_{x,1}^2$-th digit of $x_{1}^{(2)}$ is zero.

\textit{Iterative procedure:} \\
Suppose that for some $M \in \nn$, we have already defined the values and intervals $$x_M^{(1)} \in T, \, x_M^{(2)} \in I_{M,x} , \quad y_M^{(1)} = \varphi(x_M^{(1)}), \, y_M^{(2)} = \varphi(x_M^{(2)}) \in T' \cap I_{M,y}.  $$


We describe how to construct the $M+1$-th values and intervals. We set $L_{y,M} := \tau'(y_M^{(2)})$ choose $K_{y,M} >L_{y,M} $ big enough s.t.

 \[ I_{M+1,y} := \left(y_M^{(2)} - \frac{1}{b^{K_{y,M}}}y_M^{(2)} + \frac{1}{b^{K_{y,M}}}\right) \subset I_{M,y}. \]
The $b$-ary representation of any $z \in I_{M+1,y} $ agrees with the one of $y_M^{(2)}$ up to the index $L_{y,M}-1$. By continuity of $\varphi$ we find some $x_{M+1}^{(1)} \in T \cap I_{M,x}$ s.t $y_{M+1}^{(1)} := \varphi(x_{M+1}^{(1)}) \in I_{M+1,y}.$ We set $L_{x,M+1} := \tau(x_{M+1}^{(1)})$ 
and $$I_{M+1,x} = (x_{M+1}^{(1)}, x_{M+1}^{(1)} + b^{-L^{2}_{x,M+1} - 1}) \cap I_{M,x} \neq \emptyset$$.
As in the first step, one finds
some $x_{M+1}^{(2)} \in I_{M+1,x} $ such that $y_{M+1}^{(2)} := \varphi(x_{1}^{(2)}) \in T' \cap I_{M+1,y}  $. We note that the $L_{x,M}$-th to the $L_{x,M}^2$-th digit of $x_{1}^{(2)}$ and the$\lceil\sqrt{L_{y,M}}\rceil$-th to the $L_{y,M}$-th digits of $y_{1}^{(2)}$ are zero.

Both $x_M^{(2)}$ and $y_M^{(2)}$ are Cauchy sequences and, thus, posses limits $x \in I$ and $y \in \rr$. By continuity of $\varphi$ one has $y = \varphi(x).$ By construction of $x$ one immediately obtains that 
$$ \Lambda_{b,0,L_{M,x}^2}(x) \geq 1 - \frac{1}{L_{M,x}},$$
which implies that $x \in \mathcal{Z}_b$ if $L_{M,x} \to \infty$ . If $L_{M,x}$ remains bounded the limit $x$ has only finitely many non-zero digits and thus $x \in \mathcal{Z}_b.$ One similarly shows that $y \in \mathcal{Z}_b,$ which completes the proof.
\end{proof}

It remains to show that the set of absolutely normal numbers $\mathcal{N}$ is not super-dense. In fact we will construct an even larger set $\mathcal{A} \supset \mathcal{N}$, which is not super-dense. 
We define 
$$ \mathcal{T}_1 := \{x \in \rr \, | \, \text{ the trinary decomposition of } x  \text{ has infinitely many ones} \}$$
and recall that the set of $2$-simply normal numbers is given by
$$ \mathcal{N}_{s,2} = \left\{ x \in \rr \, | \, \lim_{M \to \infty} \Lambda_{2,0,M} (x) = \frac12  \right\}.$$
We set
\begin{equation}
\mathcal{A} := \mathcal{T}_1 \cap \mathcal{N}_{s,2}.
\end{equation}
Of course, $\mathcal{N} \subset \mathcal{A}$. Hence, $\mathcal{A}^c$ is a null set. We want to show
\begin{proposition}
    The set $\mathcal{A}$ is not super-dense.
\end{proposition}

\begin{proof}
    The proof heavily relies on properties of Cantor's function $C:[0,1) \to [0,1),$ also commonly known as devil's staircase. We recall that $C$ is increasing and continuous. For our purposes, the following description of $C$ is handy. Let $x = 0. x_1 x_2 x_3 \ldots$ be the trinary representation of $x \in [0,1)$. If the trinary representation of $x$ contains no one, one sets $C(x) := x$. Otherwise, there exists a minimal index $m \in \nn$ s.t. $x_m = 1$ and we set  $y = C(x)$ to be the number whose $y = 0. y_1 y_2 y_3 \cdots$ is given by
        $$ y_i := \begin{cases}
            0, & \text{ if }  i > m, \\
            \min\{y_i,1\}, & \text{ if } i \leq m. 
        \end{cases}$$
    Note that $C$ maps all numbers in $\mathcal{T}_1$ to values with terminating binary representations. That is, \begin{equation}\label{eq:dense}
        C(\mathcal{A} \cap (0,1)) \cap \mathcal{A} = \emptyset.
    \end{equation}
    Unfortunately, $C$ is locally constant at the deleted thirds in the iterative construction of the Cantor set. The main idea will be to enrich $C$ by self-similar copies of itself in each interval such that it becomes a nowhere constant function, which still satisfies \eqref{eq:dense}.

    To this end, it is convenient to work with the symmetrized version $C_s$
    \begin{equation}
        C_s(x) := \begin{cases} C(x), & \text{ if } x \leq \frac12, \\
        C(1-x), & \text{ if } x > \frac12, 
        \end{cases}  
    \end{equation}
    which still is continuous and preserves the crucial property of the Cantor function that it maps all numbers with at least a '1' in the trinary representation to a number with finite binary decomposition. We now define the enriched Cantor function $\hat{C} : [0,1] \to [0,1]$. To this end, we distinguish the cases, where $x$ has finitely many '1's and infinitely many. If $x$ has no $1$, we set $\hat{C}(x) = C_s(x).$ If $x$ has $m$ '1's in its trinary representation, we write $x = 0. w_1 w_2 \ldots w_m \sigma, $ where the finite words $w_i$ contain exactly a $1$ as their last digit and $\sigma$ is a word without any $1$. Then, we set 
    \begin{equation}\label{eq:cantfinite}
        \hat{C}(x) := \sum_{r = 1}^{m} 2^{-r\sum_{k =1}^{r-1}|w_r|} C_s(w_r) + 2^{-(m+1)\sum_{k =1}^{r}|w_r|} C_s(\sigma),
    \end{equation}
    where the empty sum is understood as zero here.
    In the case, $m = 2$ one applies the normal Cantor function to the first part $w_1$, which gives a number terminating after $|w_1|$ bits. Then, one insert $|w_1|$ zeros and continues with $\sigma$ - reinterpreted as bit strings. For higher $m$, one alternates between inserting an increasing number of zeros and inserting the Cantor bit-string of each $w_i$ afterwards. 
    If $x$ has infinitely many '1's in its trinary representation, we write $x = 0. w_1 w_2 \ldots $ with the same definition for $w_i$ as above and one similarly sets
    \begin{equation}\label{cant:infinite}
        \hat{C}(x) := \sum_{r = 1}^{\infty} 2^{-r\sum_{k =1}^{r-1}|w_r|} C_s(w_r).
    \end{equation}
    The function $ \hat{C}(x) $ is nowhere constant as $C(x) \neq C(y)$ for any $y$ whose trinary representation terminates and an $x$ with infinitely many $0$s and $2$s - and both sets are dense. One also readily checks that $\hat{C}(x)$ is continuous: the probably easiest way is to consider the approximation $\hat{C}_m(x), $ which stops after the $m$-th one (as the original Cantor function stops after the first one). These functions $\hat{C}_m(x), $ are continuous as one inserts a damped copy of the original (symmetrized) Cantor function in each interval, where $\hat{C}_{m-1}$ is constant. Moreover, by construction 
    $$ \sup_{x \in (0,1)}|\hat{C}(x) -\hat{C}_M(x)| \leq 2^{-m^2}$$ 
    so that $\hat{C}_m$ converges uniformly to $\hat{C}$. This implies that $\hat{C}$ is continuous, too.
    It remains to show that $\hat{C}(\mathcal{T}_1) \cap \mathcal{N}_{2,s} = \emptyset. $ To this end, one simply notes that after the insertion of the Cantor string of $m$-th word $w_m$ of $x \in \mathcal{T}_1$ one has at most $\sum_{r=1}^{m} w_r $ ones but at least $(m-1) \sum_{r=1}^{m} w_r $ zeros. That is there a sequence of integers $L_m$ s.t. 
    $$ \Lambda_{2,0,L_m}(C(x)) \geq 1 - \frac1m.$$
    This finishes the proof.
\end{proof}
