\subsection{Banach Bundles}\label{sec:Bundles}
In this section we will recall some facts about Banach Bundles which will be relevant to our quotient construction in section~\ref{sec:Bundles} below. More specifically, we find that if the fibers are finite dimensional, our family of quotient spaces forms a Banach bundle in Theorem~\ref{thm:quotients_are_bbundled} below. Thus it is necessary to recount the relevant details.

The theory of Banach bundles goes back to at least the 1960's with \cite{DiximierDouady}, and the book by Fell and Doran serves as an informative reference \cite{FellDoran}. As there is some variance in the basic definitions of these objects, we point out that our working definition is that of Fell and Doran given in \cite[Definition 13.1]{FellDoran} (also written as (F)-Banach Bundles in \cite{Chirvasitu, DupreGillette}). 

%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
\subsubsection{Definition and Properties}
Let $X$ be an Hausdorff topological space and let $B$ be an Hausdorff space equipped with a continuous, open surjection $\pi: B\to X$. If $U\subset X$ is open, the subset $B_U:= \pi^{-1}(U)$ is the \textit{restriction} of $B$. The pre-image $B_x := \pi^{-1}(\{x\})$ is called the \textit{fiber} with base-point $x$.   It is said that $B$ is a \textit{Banach Bundle} whenever each $B_x$ is equipped with the structure of a complex Banach space and the following conditions are satisfied: 
\begin{enumerate}[label = (\roman*)]
    \item The mapping $e \mapsto \|e\|$, the Banach space norm of $e$ in $B_{\pi(e)}$ is a continuous map $B \to [0, \infty)$.
    \item The binary operation $(e,f) \mapsto e+f$ is a continuous map from $\Delta(B^2):=\{(e,f): \pi(e) = \pi(f)\}$ to $B$, where the domain $\Delta(B^2)$ is taken with the subspace topology inherited from the product topology on $B^2$.
    \item For each $\lambda \in \mathbb{C}$, the mapping $m_\lambda :B \to B$ via $e\mapsto \lambda e$ is continuous. 
    \item For every $x\in X$, the sets of the form 
        \[
            V_{U, \epsilon}:= \{e\in B \colon \pi(e) \in U, \|e\|<\epsilon\} \quad \text{so that } x\in U\subset X \text{ is open, and }\epsilon >0,
        \] form a neighborhood basis around the origin $0_x$ of the fiber $B_x$. 
\end{enumerate} 

\begin{rmk}
Item (iv) is equivalent to the following: 

\indent (iv)' If $x\in X$ and $(e_{j})_{j\in \mathcal{J}}\subset B$ is a net so that $\pi(e_j) \to x$ and $\|e_j\| \to 0$, then $e_j \to 0_x$ in $B$. 

\end{rmk}

We recall that a \textit{section} of $\pi$ is a continuous function $f:X\to B$ so that $\pi \circ f = \id_X$.  A Banach bundle is said to \textit{have enough sections} if for every $e\in B$, there is a section $f$ so that $f(\pi(e)) = e$. We denote the set of continuous sections by $\Gamma(B)$. Let us recall a fundamental result.

\begin{thm}[Theorem C.16 \cite{FellDoran}]
    Let $B$ be a Banach bundle over a locally compact Hausdorff space $X$. Then $B$ has enough continuous sections. 
\end{thm}

When equipped with the uniform norm, the linear space $\Gamma$ of continuous sections of $(B, \pi, X)$ forms a Banach space equipped with a natural multiplication by the algebra of $\C$-valued functions $C(X)$. Moreover, if $f\in \Gamma(B)$ and $\lambda \in C_0(X)$, one clearly has $\|\lambda f\|_{\Gamma(B)} \le \|\lambda\|_{C(X)} \cdot \|f\|_{\Gamma(B)}$. This makes $\Gamma(B)$ into a \textit{Banach $C(X)$-module} \cite[Chapter 2]{DupreGillette} (see also \cite{Chirvasitu}). 

\begin{lem}\label{lem:bundle_convergence}
    Let $B$ be a Banach bundle over a compact Hausdorff space $X$. Then, a net $(e_j)_{j\in \mathcal{J}}$ converges to a point $e$ in the topology of $B$ if and only if the net of base-points $\pi(e_j) \to \pi(e)$ in $X$ and one following equivalent criteria are met 
        \begin{enumerate}[label = (\roman*)]
            \item For every $f\in \Gamma(B)$ one has 
            \[
                \|e_j - f(\pi(e_j))\| \to \|e- f(\pi(e))\|
            \] in $\mathbb{R}$. 
            \item Let $W\subset \Gamma(B)$ be a dense $C(X)$-submodule. For every $w\in W$, one has 
            \[
                \|e_j - w(\pi(e_j))\| \to \|e- w(\pi(e))\|\,.
            \]
        \end{enumerate}
\end{lem}  
\begin{proof}
    $(i)$: The forward direction follows from continuity. For the converse, note there is some $g\in \Gamma(B)$ with $g(\pi(e)) = e$. Now, $\|e - g(\pi(e))\| = 0$, and by continuity, this means 
    $\|e_j - g(\pi(e_j))\| \to 0.$ By property (iv)', this implies that $e_j - g(\pi(e_j)) \to 0_{\pi(e)}$, from which we conclude that $\lim e_j = \lim g(\pi(e_j)) = e$, since addition is continuous. 

    $(iii)$: The only part which is nontrivial is the $(iii) \Rightarrow (ii)$ direction. Let $\epsilon >0$ and let $f\in \Gamma(B)$. By the assumption, we may find an approximant $w\in W$ so that $\|f-w\|<\epsilon/3$. Then, for $j$ large enough, one has $\left
                |\|e_j-w(\pi(e_j))\|- \|e- w(\pi(e))\|\right|<\epsilon/3$.
    By utilizing the reverse triangle inequality, the following chain of estimates holds: 
    \begin{align*}
        \left| \|e_j - f(\pi(e_j))\|\right. & - \left. \|e- f(\pi(e))\| \right |\le\left| \|e_j - f(\pi(e_j))\| - \|e_j - w(\pi(e_j))\| \right| + \left| \|e_j - w(\pi(e_j))\|- \|e- f(\pi(e_j))\| \right |\\
        &\le \|w(\pi(e_j)) - f(\pi(e_j))\| + \left| \|e_j - w(\pi(e_j))\| - \|e-w(\pi(e))\|\right| + \|w(\pi(e)) - f(\pi(e))\|\\
        &\le 2 \|f-w\| + \left| \|e_j - w(\pi(e_j))\| - \|e-w(\pi(e))\|\right|<\epsilon\,.\qedhere
    \end{align*}
\end{proof}

We will record a useful lemma. The original argument seems to go back to \cite{DiximierDouady}, but we record the proof below for the convenience of the reader.
\begin{lem}
    Let $B$ be a Banach bundle over $X$ with a space of continuous sections $\Gamma$. Then, the set 
        \[
            X_{\ge n}:=\{x \colon: \dim B_x \ge n\} 
        \] is open for each $n\ge 0$
\end{lem}
\begin{proof}
    Suppose $x_0 \in X_n$ and find $s_1,\dots s_n \in \Gamma$ so that $\{s_j(x_0)\}_{j=1}^n$ is linearly independent in $B_{x_0}$. Consider the map 
        \[
            s(y, \vec{c}) := \sum_{j=1}^n c_j \cdot s_j(y)
        \] which is a jointly continuous map from $X\times \C^n \to B$. Then, the function $\eta(y) = \inf_{\|\vec{c}\|=1}\|s(y, \vec{c})\|$ is a continuous mapping from $X \to [0, \infty)$. Since the unit sphere of $\C^n$ is compact, $\eta(x_0)>0$ by linear independence. Therefore, there is a neighborhood $V\ni x_0$ so that $\eta(y) >0$ for all $y\in V$. Equivalently, $\{s_j(y)\}_{j=1}^n$ are linearly independent in $B_y$. Thus $V\subset X_n$ as required.
\end{proof} 

In other words, the above lemma says that the dimension function is lower semi-continuous in $\omega$. The next theorem is a simplified version of the Stone-Weierstra{\ss} theorem for Banach bundles Theorem 4.2 in \cite{Gierz}. 
\begin{thm}(Stone-Weierstrass)
    Let $X$ be a compact Hausdorff space and let $B$ be a Banach bundle over $X$. A $C(X)$-submodule $W$ of the continuous sections $\Gamma(B)$ is dense in $\Gamma(B)$ if and only if for every $x\in X$, the set $\{s(x) : s\in W\}\subset B_x$ is dense.
\end{thm}
\begin{proof}
    For the forward direction, note that since $X$ is compact, it has enough sections \cite[Theorem C.11]{FellDoran}. So for any $e\in B_x$, there is a continuous section $s\in \Gamma(B)$ so that $s(x) = e$. Therefore, for any $\epsilon >0$ one may find $w\in W$ so that $\|w(x) - s(x)\| \le \|w - s\| <\epsilon$ as required. 

    Conversely, pick $s\in \Gamma(B)$. Fix $x_0 \in X$. Since $W$ is fiber-wise dense, there exists a section $w_{x_0} \in W$ so that $\|w_0(x_0) - s(x_0)\| < \epsilon$. Since the mapping $X\ni x\mapsto \|w(x) - s(x)\|$ is continuous, there is a neighborhood $U_{x_0}\ni x_0$ so that for all $y\in U_{x_0}$ one has $\|w_0(y) - s(y)\|<\epsilon$. \textit{Nota bene} that $\{U_{x} : x\in X\}$ (constructed as above) forms an open cover of $X$ from which we can extract a finite sub-cover $\{U_{x_1}, U_{x_2}, \dots, U_{x_k}\}$. Find a partition of unity $\{f_1:X \to [0,1]\colon 1\le j \le k\}\subset C(X)$ subordinate to this sub-cover, and define $w = \sum_{1}^k f_j w_{x_j}\in W$ since $W$ is a $C(X)$-module. 

    Hence, for any $y\in X$, 
        \begin{align*}
            \|w(y) - s(y)\| \le \sum_{j=1}^k f_j(y) \|w_j(y) - s_j(y)\| &\le \sum_{\substack{j_*:\\ y\in U_{x_{j_*}}}} |f_{j_*}(y)| \|w_{j_*}(y) - s_{j_*}(y)\|< \epsilon \sum f_j(y) = \epsilon.
        \end{align*} The claim follows.
\end{proof}

Moreover, \cite{FellDoran} give a general means of constructing Banach bundles from families of Banach spaces. 
\begin{thm}[Theorem 13.18 \cite{FellDoran}]\label{thm:Banach_Bundle}
    Let $X$ be an Hausdorff space. Let $A$ be a set equipped with a surjection $\varrho :A \to X$, so that $A_x := \varrho^{-1}(\{x\})$ is a complex Banach space. Suppose $\Gamma$ is a complex linear space of sections of $\varrho$ so that 
    \begin{enumerate}[label = (\alph*)]
        \item for all $f\in \Gamma$, the mapping $x\mapsto \|f(x)\|_{A_x}$ is continuous,
        \item for all $x\in X$, the set $\{f(x)\}_{f\in \Gamma} \subset A_x$ is dense. 
    \end{enumerate} 
Then, there exists a unique topology $\tau$ making $A$ a Banach bundle so that every element of $\Gamma$ is a continuous section of $\varrho$. In particular, a topological basis for $\tau$ is given by sets of the following form: 
    \begin{equation}
        W(f, U, \epsilon) = \{a\in A \colon \varrho(a) \in U,\, \|a- f(\varrho(a))\|<\epsilon\}
    \end{equation} 
where $\epsilon >0$, $U\subset X$ is an open set, and $f\in \Gamma$. 
\end{thm}

We will sometimes refer to Theorem~\ref{thm:Banach_Bundle} as the Fell-Doran theorem for simplicity. 

 Recall that a Banach bundle is \textit{locally trivial} if for every point $x\in X$, there exists a neighborhood $U\ni x$ and a fixed Banach space $F$, so that the restriction $B_U$ is homeomorphic to $F\times U$ in the product topology. In contrast to the typical definition of a vector bundle, Banach bundles make \emph{no assumptions} about local triviality, which leads to some interesting behavior.

 \begin{exmp}
     Let $\Omega = [0,1]$ be the unit interval equipped with the usual topology. Define $V_x=\C$ for all $x\in [0,1]\setminus \{1/2\}$ and $V_{1/2} = \{0\}$. Let $\Gamma$ be the subspace of $C([0,1])$ with $f(1/2) = 0$. Then by the Fell-Doran Theorem (Theorem~\ref{thm:Banach_Bundle}) there is a unique topology on $\mathcal{V}:=\{V_x\}_{x\in [0,1]}$ making $(\mathcal{V}, \pi, [0,1])$ into a Banach bundle with $\Gamma$ as a dense $C([0,1])$-submodule of the continuous sections by the Stone-Weierstra{\ss} theorem for Banach bundles. 
 \end{exmp}


\subsubsection{Homomorphisms}
We now recapitulate the theory of mappings between Banach bundles. It seems that the first formulation of notion of a \emph{homomorphism of Banach bundles} is due to \cite{Gutman_1}, and these were used in \cite{Gutman_1,GutmanKoptev} to investigate the notion of a \textit{dual bundle}. In view of Theorem~\ref{thm:Banach_Bundle}, one might hypothesize that the natural definition of the `dual' of a Banach bundle $X$ would be to take the dual spaces of each fiber $\{X_\omega^*: \omega \in \Omega\}$ together with the natural surjection, and topologize it via the homomorphisms into the trivial bundle which form a natural class of sections thereof. However, as is shown in Examples 2.13 of \cite{GutmanKoptev}, even in the case that the fibers of a given bundle are finite-dimensional, it is \textit{not} the case that the point-wise norm of every homomorphism is continuous -- a requirement of Theorem~\ref{thm:Banach_Bundle}.  

In general, a drop in dimension allows for the operator norm of a linear functional to have a discontinuity in its base points. The issue of existence of a dual is actually quite subtle for this reason. However, for practical purposes it will suffice to study \textit{homomorphisms} between bundles. In particular, we relax the requirement that the linear functionals form a bundle in and of themselves, to requiring that they are homomorphisms into the trivial bundle.

We introduce a slightly modified version of the definition of a homomorphism. 
\begin{define}\label{def:bundle_hom}
    Let $X$ and $Y$ be Banach bundles over the same topological base space $\Omega$, with modules of sections $\Gamma(X)$ and $\Gamma(Y)$ respectively. Suppose further that $\Omega$ is equipped with an homeomorphism $\vartheta:\Omega \to \Omega$. A function $H: \Omega \to \bigsqcup_{\omega \in \Omega} B(X_\omega, Y_{\vartheta \omega})$ via $\omega \mapsto H_\omega$ is a ($\vartheta$-)\textbf{covariant homomorphism} of $X$ to $Y$ if the associated mapping of the bundles $H:X\to Y$ via $e\mapsto H_{\pi(e)}e\in Y_{\vartheta \omega}$ is continuous. If $\vartheta$ is simply the identity map, then $H$ is simply referred to as a \textit{homomorphism}. 
\end{define}

\begin{note}
    The $C(\Omega)$-module of covariant homomorphisms will be written $\hom^\vartheta(X,Y)$, with the $\vartheta$-dropped if we are referring to the identity map on $\Omega$. If the pointwise norm function $\omega \mapsto \|H_\omega\|_{B(X_\omega, Y_{\vartheta\omega})}$ is bounded, then we say $H$ is a \textit{bounded homomorphism}. The submodule of bounded homomorphisms will be written $\hom^\vartheta_b(X,Y)$. Note that every covariant isometric isomorphism of Banach bundles is a covariant homomorphism. 
\end{note}

There is a natural action of the homomorphisms $\hom^\vartheta(X,Y)$ on the Banach modules of continuous sections $\Gamma(X)$ and $\Gamma(Y)$, as we note in the following lemma. 

\begin{lem}\label{lem:hom_action_sections}
    Let $\Omega$ be a compact Hausdorff space equipped with an homeomorphism $\vartheta$. Let $(X, \pi_X, \Omega)$ and $(Y, \pi_Y, \Omega)$ be two Banach bundles over $\Omega$ with $C(\Omega)$-modules of sections $\Gamma(X)$ and $\Gamma(Y)$ respectively. Let $H:\Omega \to \bigsqcup_{\omega\in \Omega}B(X_\omega, Y_{\vartheta \omega})$ be a $\vartheta$-covariant homomorphism. Then, for every section $\sigma \in \Gamma(X)$, the function $H\cdot \sigma: \Omega \to Y$ via $(H \cdot \sigma)(\omega) := H_\omega \sigma(\omega) \in Y_{\vartheta \omega}$ is continuous.
\end{lem}
\begin{proof}
    Let $(\omega_{\lambda})_{\lambda \in \Lambda}\subset \Omega$ be a net converging to $\omega$. Note that 
    \[
        \pi_Y(H_{\omega_\lambda}\sigma(\omega_\lambda)) = \vartheta \circ \pi_X(\sigma(\omega_\lambda)) = \vartheta \omega_\lambda 
    \] which converges to $\vartheta \omega = \pi(H_\omega \sigma(\omega))$. Now, let $f\in \Gamma(Y)$ be a continuous section, and note that in this case, the net $f(\vartheta (\omega_\lambda)) \to f(\vartheta( \omega))$, and similarly $\sigma(\omega_\lambda) \to \sigma(\omega)$. Whence $\|H_{\omega_\lambda} \sigma(\omega_\lambda) - f(\vartheta \omega)\| \to \|H_\omega \sigma(\omega) - f(\vartheta \omega)\|$ since $H$ is continuous in the bundle topology. Thus, $H\cdot \sigma$ is a continuous mapping into $Y$. 
\end{proof}

The following lemma uses the central idea in the proof of \cite[Theorem 1.4.5]{Gutman_1} to show that every covariant homomorphism of bundles over a compact Hausdorff space has a uniformly bounded point-wise norm. 

\begin{lem}
        Let $\Omega$ be a compact Hausdorff space equipped with an homeomorphism $\vartheta$. Let $(X, \pi_X, \Omega)$ and $(Y, \pi_Y, \Omega)$ be two Banach bundles over $\Omega$ with $C(\Omega)$-modules of sections $\Gamma(X)$ and $\Gamma(Y)$ respectively. Let $H\in \hom^\vartheta(X,Y)$. Then, $H$ is bounded, i.e.,  \[\|H\|_\infty := \sup_{\omega \in \Omega} \|H_\omega\|_{B(X_\omega, Y_{\vartheta \omega})}<\infty.\]
\end{lem}
\begin{proof}
    Recall that $\Gamma(X)$ and $\Gamma(Y)$ form Banach spaces when endowed with the uniform norm. By Lemma~\ref{lem:hom_action_sections}, the assignment $\omega \mapsto \|H_\omega \sigma(\omega)\|$ is continuous for every $\sigma\in \Gamma(X)$. Therefore, $\sup_{\omega} \|H_\omega\sigma(\omega)\| := K_\sigma <\infty$ since $\Omega$ is compact. 

    Setting $T_\omega:\Gamma \to \ell^1(\bigsqcup Y_\omega)$, via $T_\omega \sigma := H_\omega \sigma(\omega)\in Y_{\vartheta^{-1}\omega}$, the above observation yields 
        \[\sup_{\omega} \|T_\omega \sigma\|_{Y_{\vartheta^{-1}\omega}}= K_\sigma <\infty \] 
    for all $\sigma \in \Gamma$. Therefore, by the uniform boundedness principle (\cite[Theorem 2.6]{Rudin}), $M:=\sup_{\omega} \|T_\omega\|<\infty$. We are now ready to estimate $\|H_\omega e\|$ for $e\in X_\omega$. Our aim is to express $\|H_\omega e\|$ in terms of $T_\omega \sigma(\omega)$, for a suitable section $\sigma$. Recall that $\Omega$ being compact implies $X$ has enough sections: for all $e\in X_\omega$, there is some $\sigma_e\in \Gamma$ with $\sigma(\omega) = e$.  We need to modify $\sigma_e$ a bit in order to control its norm. 

    Let $\epsilon >0$. By  Urysohn's Lemma (\cite[Theorem 33.1]{Munkres}), there is a continuous function $f_\epsilon:\Omega \to [0,1]$ so that for $A = \{\pi(e)\}$ and $B = \{\omega: \|\sigma_e(\omega)\| \ge (1+\epsilon)\|e\|\}$ one has $f(A) = \{1\}$ and $f(B) = \{0\}$. Then, taking $\sigma_\epsilon = f\cdot \sigma_e$, one has $\|\sigma_\epsilon\|_\infty \le (1+\epsilon)\|e\|$, and $\sigma_\epsilon(\pi(e)) = e$. Then, 
        \[
            \|H_\omega e\|_{Y_{\vartheta \omega}} = \|H_\omega \sigma_\epsilon (\omega)\| = \|T_\omega \sigma_e\| \le M \|\sigma_e\|_\infty \le M (1+\epsilon) \|e\|
        \] and we are done. 
\end{proof}

The following is a specialization of \cite[Theorem 1.4.4]{Gutman_1}
\begin{lem}
    Let $\Omega$ be a compact Hausdorff space equipped with an homeomorphism $\vartheta$. Let $(X, \pi_X, \Omega)$ and $(Y, \pi_Y, \Omega)$ be two Banach bundles over $\Omega$ with $C(\Omega)$-modules of sections $\Gamma(X)$ and $\Gamma(Y)$ respectively. Let $H:\Omega \to \bigsqcup_{\omega\in \Omega}B(X_\omega, Y_{\vartheta \omega})$. The following are equivalent:
    \begin{enumerate}[label = (\roman*)]
        \item The function $H$ is a $\vartheta$-covariant homomorphism. 
        \item For every section $\sigma \in \Gamma(X)$, the functions $H\cdot \sigma: \Omega \to Y$ via $(H \cdot \sigma)(\omega) := H_\omega \sigma(\omega) \in Y_{\vartheta \omega}$ are continuous.
        \item For every section $\sigma$ in a dense $C(\Omega)$-submodule $W\le \Gamma(X)$, the function $H\cdot \sigma$ is a continuous. 
    \end{enumerate}  
\end{lem}
\begin{proof}
    $(i) \Rightarrow (ii):$ This is Lemma~\ref{lem:hom_action_sections}.

    $(ii)\Rightarrow (iii):$ This is obvious. 

    $(iii) \Rightarrow (i)$: Let $(e_\lambda)_{\lambda \in \Lambda}\subset X$ be a net converging to $e_0$ in the bundle topology. Let $\omega_{\lambda}:= \pi(e_{\lambda}) \to \omega_0 := \pi(e_0)$ be the associated net of base points which we know converges. Let $\epsilon >0$. Since $X$ has enough continuous sections, we may find $\sigma_0\in \Gamma(X)$ so that $\sigma_0(\omega_0) = e$. Furthermore, as $W$ is a dense sub-module of sections, we may find $w\in W$ with $\|w - \sigma_0\|_{\infty}<\frac{\epsilon}{\|H\|_\infty 3}$. 

    Now, let $f\in \Gamma(Y)$. Note that $\| f\circ \vartheta - H\cdot w \|$ is a continuous function in $\omega$, and that moreover by the reverse triangle inequality,
    \[
        \left| \|f(\vartheta \omega_0) - H_{\omega_0}w(\omega_0)\| - \|H_{\omega_0}e - f(\vartheta \omega_0)\| \right| \le \| H_{\omega_0}\| \|e - w(\omega_0)\| = \| H_{\omega_0}\| \|\sigma_0(\omega_0) - w(\omega_0)\|\le \frac{\epsilon}{3}\,.
    \] Therefore, for any $\eta >0$ there is $\lambda$ large enough so that
    \begin{equation}\label{pf:hom_continuity}
        \left| \|f(\vartheta \omega_\lambda) - H_{\omega_\lambda}w(\omega_\lambda)\| - \|H_{\omega_0}e - f(\vartheta \omega)\| \right| \le \frac{\epsilon}{3} + \eta\,.
    \end{equation}

The following bound holds by combining the triangle inequality and the reverse triangle inequality: 
    \begin{align*}
        \left| \|H_{\omega_\lambda}e_\lambda - f(\vartheta \omega) \| - \|H_\omega e - f(\vartheta \omega) \| \right|&\le \left| \|H_{\omega_\lambda}e_\lambda - f(\vartheta \omega_\lambda) \| - \|f(\vartheta \omega_{\lambda}) - H_{\omega_\lambda} \sigma_0(\omega_{\lambda}) \| \right|\\
        &\text{\hspace{8mm}}+\left| \|f(\vartheta \omega_{\lambda}) - H_{\omega_\lambda} \sigma_0(\omega_{\lambda}) \| - \|f(\vartheta \omega_{\lambda}) - H_{\omega_\lambda}w(\omega_\lambda) \| \right|\\
        &\text{\hspace{8mm}}+\left| \|f(\vartheta \omega_{\lambda}) - H_{\omega_{\lambda}}w(\omega_\lambda)\| - \| H_{\omega}w(\omega) - f(\vartheta \omega)\| \right|\\
        &\le \|H\|_{\infty}\left( \|e_\lambda - \sigma_0(\omega_{\lambda})\| +\|\sigma_0 - w\|_{\infty}\right) +\frac{\epsilon}{3} + \eta\\
        &\le \epsilon +\eta \text{ for $\lambda$ large enough.}
    \end{align*} Note we have used~(\ref{pf:hom_continuity}) to obtain the estimate on the third summand in the second inequality. Since $\eta$ and $\epsilon$ were chosen independently, this completes the proof.
\end{proof}


