\subsection{The Fundamental Theorem}

Let us recall the notation and set-up of the previous section. Fix a cut site $x\in \mathbb{Z}+ \frac12$, and consider the family of Banach spaces $\{\B_{x,\omega}^+\colon \omega \in \Omega\}$ defined fiber-wise by the equivalence relation $a\sim_\omega a$ if and only if $\psi(X\otimes (a-b)) = 0$ for all $X\in \A_x^-$. Consider also the family of selections $\B_x^+:=\{ \omega \mapsto [A(\omega), \omega]_x\}$ where $A\in C(\Omega,\A_x^+)$, which forms a linear space. Theorem~\ref{thm:Banach_Bundle} and Corollary~\ref{cor:small_corrs} motivate the following definition: 

\begin{define}\label{def:small_correlations}
    Let $\Omega$ be a compact Hausdorff topological space equipped with an homeomorphism $\vartheta$. Let $\psi_\omega$ a weakly* continuous mapping into the state space of the quasi-local algebra $\A_{\mathbb{Z}}$ that is translation co-variant with respect to $\vartheta$. If for every $\omega\in \Omega$, each quotient space $\B_{x,\omega}^+$  at the cut site $x\in \mathbb{Z}+\frac{1}{2}$, is finite dimensional, we say that $\psi_\omega$ \textbf{has small correlations}. 
\end{define} 

An example of such a TVCS is as follows.

\begin{exmp}\label{exmp:covariant_product_state}    
Let $\xi_\omega$ be the weakly*-continuous covariant product state from Proposition~\ref{prop:existence_TCPS}. Then, $\xi_\omega$ has small correlations with fiber dimension 1. 
\end{exmp}
\begin{proof}
    To see this, $a,b\in \A_x^+$. We note that if $a\sim_{x,\omega}b$, then, $\psi_\omega(a-b) = 0$ and so $I_{x,\omega} \subset \ker \psi_\omega|_{\A_{x}^+}$. Conversely, if $a\in \ker \psi_{\omega}|_{\A_{x}^+}$, then since $\psi_\omega$ factors over the bond at $x$, we get $\psi_\omega(c\otimes a) = \psi_\omega(c) \psi_{\vartheta^x \omega}(a)=0$ for all $c\in \A_{x}^-$ for all $\omega$. So $I_{x,\omega}$ is the kernel of a linear functional and is therefore of codimension one by general functional analysis, hence $\B_{x,\omega}^+ \cong \C$ for all $\omega$. 
\end{proof}

Several remarks are in order. 

\begin{rmk}
    The analysis in Example~\ref{exmp:covariant_product_state} works for any weakly* continuous function for which $\psi_\omega(a\otimes b) = \psi_\omega(a) \psi_{\omega}(b)$ for all $a\in \A_{x}^-$, all $b\in \A_{x}^+$ and all $\omega \in \Omega$ (i.e. a state with no correlations across the bipartition of the chain at $x$)
\end{rmk}
\begin{rmk}\label{rmk:dimension_may_vary}
    In general, we do not expect that the Bundle fibers are all equi-dimensional as in Example~\ref{exmp:covariant_product_state}. However, we show in Lemma~\ref{lem:cut_independent}  below, that the Banach bundle describing the correlations is independent of the cut-site up to isomorphism.
\end{rmk} 


\begin{rmk}\label{rmk:canonical_bundle}
    \textit{Nota bene} if $\psi_\omega$ has small correlations across $x$, then the Banach spaces $\{B_{x,\omega}^+\}_{\omega\in \Omega}$ equipped with the linear space of sections given by $\{\omega \mapsto [A(\omega), \omega)]_x\colon A\in C_{\Omega}(A_x^+)\}$ defined in Lemma~\ref{lem:quot_eval} form a Banach bundle over $\Omega$. We denote this bundle by $(\mathcal{C}, \pi, \Omega)$ (reference to a specific cut site is not necessary due to Remark~\ref{rmk:dimension_may_vary}), and we refer to it as the \textbf{small correlation bundle}. We shall see in Theorem~\ref{thm:minimal} below that the use of the definite article is justified since $\mathcal{C}$ is minimal with respect to certain natural conditions. 
\end{rmk}

We now show a TCVS analog of \cite[Proposition 2.1]{FannesNachtergaeleWerner} in Theorem~\ref{thm:Fundamental} below. We split the proof into a few easier but technical lemmas first. 
\begin{lem}\label{lem:pre-fundamental}
    Let $A$ be a unital $C^*$-algebra and let $\A_{\mathbb{Z}}$ be the associated quasilocal algebra. Let $\Omega$ be a compact Hausdorff space equipped with an homeomorphism $\vartheta$. Let $\psi_\omega$ be a weakly* continuous, translation covariant state on $\A_{\mathbb{Z}}$ with small correlations. Let also $\mathscr{B}_x$ be the Banach bundle at the cut site $x$. Fix $a\in \mathcal{A}$ and $\omega\in \Omega$. Define the mapping 
    \begin{equation}\label{eqn:canonical_transfer}
        \begin{split}
            E^x_{a,\omega}&:\B_{x,\omega}^+ \to \B_{x,\vartheta^{-1}\omega}^+ \text{ via }\\
            &[b,\omega]_x \mapsto [a\otimes \tau_1(b), \vartheta^{-1}\omega]_x\,.
        \end{split}
    \end{equation}
    The following properties hold. 
    \begin{enumerate}[label = (\alph*)]
        \item For each $a\in A$ and $\omega\in \Omega$, the $E^x_{a,\omega}$ mapping is well-defined bounded linear map on the fiber with 
        \begin{equation}\label{eqn:transfer_norm_est}
            \|E^x_{a,\omega}[b,\omega]\| \le \|a\|_A \|[b,\omega]_x\|
        \end{equation} 

        \item For all $a,b\in A$, the mapping 
            \begin{equation}
                \omega \mapsto E^x_{a,\omega}[b,\omega]_x \in B_{x,\vartheta^{-1}\omega}
            \end{equation} is continuous in the (unique) Banach bundle topology. Thus, $E_a \in \hom^\vartheta(\mathscr{B}_x, \mathscr{B}_x)$.
        \item There exists a continuous section $e^x\in \Gamma(\mathscr{B}_x)$ and a homomorphism $\varrho^x\in \hom(\mathscr{B}_{x}, \Omega \times \C)$ so that for any pure tensor $a\otimes b\otimes \cdots \otimes c\in \A_{[x, x+n]}$, one has
        \begin{equation}\label{eqn:transfer_factorization}
            \psi_\omega(a\otimes b\otimes \cdots \otimes c) = \varrho^x_\omega \circ E^x_{a,  \omega}\circ E^{x}_{b,\vartheta \omega}\circ \cdots \circ E^x_{c, \vartheta^{n}\omega}(e^x(\vartheta^n\omega))\,. 
        \end{equation} 
    \end{enumerate}
\end{lem}
\begin{proof}
$(a)$: Linearity in the argument is obvious, so let us check this map is well-defined. Let $c\in \A_{x}^-$ and note that 
    \[
        \psi_{\vartheta^{-1}\omega}(c \otimes a \otimes \tau_1(b)) = \psi_{\vartheta^{-1}\omega}(\tau_1(\, \tau_{-1}(c\otimes a) \otimes b\,)) = \psi_{\omega}( \tau_{-1}(c\otimes a) \otimes b)\,.
    \] Thus, if $[b,\omega]_x = 0$, its image $E^x_{a,\omega}[b,\omega]_x\in \B_{x, \vartheta^{-1}\omega}^+$ is also zero. To show the norm estimate, let $d\in I_{x,\omega}$, and note that 
    \[
        \|E^{x}_{a,\omega}[b,\omega]_x\|_{\B_{x,\vartheta^{-1}\omega}} = \|E^{x}_{a,\omega}[b+d,\omega]_x\|_{\B_{x,\vartheta^{-1}\omega}} = \inf_{f\in I_{x,\vartheta^{-1}\omega}}\| a\otimes \tau_1(b+d) + f\|_{\A_{x}^+}\le \|a\| \|b+d\|_{\A_{x}^+}\, 
    \] since $\tau_1$ is an automorphism. Taking the infimum in $d$, over both sides yields~(\ref{eqn:transfer_norm_est}). 

    $(b)$: Let $(\omega_{\lambda})_{\lambda\in \Lambda}$ be a net in $\Omega$ which converges to $\omega'$. We need to show that $E^x_{a, \omega_{\lambda}}[b, \omega_{\lambda}]_x \to E^x_{a, \omega'}[b, \omega']_x$ in the bundle $\mathscr{B}_x$. To begin, notice that by the Stone-Weierstra{\ss}   theorem for bundles combined with Theorem~\ref{thm:Banach_Bundle}, the linear space of sections given by 
    \[
        \B_x^+ := \{ \omega\mapsto [A(\omega), \omega]_x \colon A\in C_{\Omega}(\A_{Z})\}
    \] is dense in $\Gamma(\mathscr{B}_x)$. Therefore, by Lemma~\ref{lem:bundle_convergence} $(iii)$, it is sufficient to show that the basepoints converge and that for every $A\in C_\Omega(\A_{\mathbb{Z}})$, the net of norms $\|E^x_{a, \omega_{\lambda}}[b, \omega_{\lambda}]_x - [A(\omega_\lambda), \omega_\lambda]_x\| \to \|E^x_{a, \omega'}[b, \omega']_x - [A(\omega'), \omega']_x\|$. We note $\pi(E^x_{a,\omega_{\lambda}}[b, \omega_{\lambda}]_x ) = \vartheta^{-1}(\omega_\lambda) \to \vartheta^{-1}(\omega') = \pi(E^x_{a,\omega'}[b, \omega']_x)$ since $\vartheta$ is an homeomorphism. 

    Now, set $\tilde A(\omega) = a\otimes \tau_1(b) - A\circ \vartheta^{-1}(\omega_{\lambda}) \in C_{\Omega}(\A_x^+).$ By Lemma~\ref{lem:n-norm}, and the assumption that $\psi_\omega$ has small correlations, we have 
    \[
        \Omega \ni \omega \mapsto \|[\tilde A(\omega), \omega]_x\|_{B_{x,\omega}^+}
    \] is continuous. One computes
    \begin{align*}
        \|E^x_{a, \omega_{\lambda}}[b, \omega_{\lambda}]_x - [A(\omega_\lambda), \omega_\lambda]_x\|&= \|[a\otimes \tau_1(b) - A\circ \vartheta^{-1}(\omega_{\lambda}), \vartheta^{-1}(\omega_\lambda)]_x\|\\
        &= \|[\tilde A(\omega_{\lambda}, \vartheta^{-1}\omega_{\lambda}]_x\|_{B_{x,\vartheta^{-1}\omega_{\lambda}}^+}\\
        &\to \|[\tilde A(\omega'), \vartheta^{-1}\omega']_x = \|E^x_{a, \omega'}[b, \omega']_x - [A(\vartheta^{-1}\omega'), \vartheta^{-1}\omega']_x\|\,,
    \end{align*} concluding the proof. 

$(c)$: Take $e^x(\omega) = [\one_{\A_{x}^+}, \omega]_x$ and $\varrho_\omega[b,\omega]_x = \psi_\omega(\one_{\A_x^-} \otimes b)$. The section $e^x$ is continuous by definition of the topology on $\mathscr{B}_x$. Notice also that $\varrho^x_\omega[A(\omega), \omega] = \psi_\omega(\one\otimes A(\omega))$ is continuous by Lemma~\ref{lem:weak*_cts_on_C(A)}. To show~(\ref{eqn:transfer_factorization}), let us first start with two uncorrelated observables $a\otimes b\in \A_{[x, x+1]}$. One has 
\begin{align*}
    \psi_\omega(\one_{\A_x^{-}} \otimes a \otimes b) &= \varrho^x_{\omega}[a\otimes b, \omega]_x= \varrho^x_\omega[a\otimes \tau_{1}( \tau_{-1}(b)), \vartheta^{-1} \vartheta \omega]_x\\
    &= \varrho^x_\omega \circ E_{a,\omega}[\tau_{-1}(b), \vartheta \omega]_x= \varrho^x_\omega \circ E_{a,\omega}[\tau_1(\tau_{-1}(\tau_{-1}(b))), \vartheta^{-1} \vartheta(\vartheta \omega)]_x\\
    &= \varrho^x_\omega E_{a,\omega}^x \circ E_{b, \vartheta \omega}^x[\one_{A_{x}^+}, \vartheta^2\omega]_x = \varrho^x_{\omega} \circ E^x_{a,\omega} \circ E^x_{b, \vartheta \omega}(e^x(\vartheta^2\omega))\,.
\end{align*} Note that since $b$ is supported on a single site $\tau_{-2}(b\otimes \one_{\A_{x+2}^+}) = b \otimes \one_{\A_{x}^+}$, from which the last equality follows. The general formula now follows by induction.
\end{proof}

\begin{lem}[Freedom from a specific cut site.]\label{lem:cut_independent}
    Suppose that $\psi_\omega$ is a TCVS with small correlations. Then, for any cute site $x\in \mathbb{Z}+\frac12$ there is an isometric Banach bundle isomorphism $\tilde T$ between $\mathscr{B}_x$ and $\mathscr{B}_{x+1}$ which is covariant in $\vartheta$. Moreover the transfer operators defined in~(\ref{eqn:canonical_transfer}) obey
    \begin{equation}\label{eqn:transfer_automorphism_covariance}
        E_{a,\omega}^x = \tilde T^{-1} \circ E_{a,\vartheta^{-1}\omega}^{x+1} \circ \tilde T
    \end{equation}
\end{lem}
\begin{proof}
    Recall that possessing small correlations is enough to guarantee that the family $\{B_{x,\omega}^+\}_{\omega\in \Omega}$ forms a Banach bundle $(\mathscr{B}_x, \pi^x, \Omega)$ with a dense $C(\Omega)$-sub-module of sections given by $\{\omega \mapsto [A(\omega), \omega]_x \colon A\in C_\Omega(\A_x^+)\}\subset \Gamma(\mathscr{B}_x)$. By Corollary~\ref{cor:small_corrs}, we in fact have a family of Banach bundles indexed by the half-integers. 


    Let $\tilde T[b,\omega]_x = [\tau_1(b), \vartheta^{-1}\omega]_{x+1}$ as in Lemma~\ref{lem:bundlemap-covariance}. Notice that $\pi^{x+1}\circ \tilde T = \vartheta^{-1} \circ \pi^x$. Thus, $\tilde T$ preserves convergence of the base-points since $\vartheta$ is an homeomorphism. We have already seen that $\tilde T$ is fiber-wise a linear isometry, so all that needs to be done is to show that it is an homeomorphism in the bundle topology. This is immediate by observing that 
    \[
        \|[b,\omega]_{x} - [A(\omega), \omega]_{x}\| = \|\tilde T [ b-A(\omega), \omega]_x\| = \|[b,\vartheta^{-1}\omega]_{x+1} - [(K_{\vartheta}A)(\vartheta^{-1}\omega), \vartheta^{-1} \omega]_{x+1}\|\,.
    \]Since the Koopman operator $K_{\vartheta}$ is a $*$-isomorphism, it follows that $\{\omega \mapsto [K_{\vartheta}A(\omega), \omega]_x \colon A\in C_\Omega(\A_x^+)\}\subset \Gamma(\mathscr{B}_{x+1})\}$ is a dense $C(\Omega)$ sub-module of $\Gamma(\mathscr{B}_{x+1})$. Taking these observations together is enough to guarantee that whenever $(b_\lambda) \subset \mathscr{B}_x$ is a convergent net, then so is $(\tilde Tb_\lambda)\subset \mathscr{B}_{x+1}$ by Lemma~\ref{lem:bundle_convergence}. Equation~(\ref{eqn:transfer_automorphism_covariance}) follows from straightforward computation. 
\end{proof}

\begin{note}
    In view of this freedom of choice, we will henceforth drop the dependence on a choice of cut site and instead write all  formulae which follow with respect to the cut $x = -1/2$, so that $\A_x^+ = \A_{\mathbb{N}\cup \{0\}}=:\A^+$ and $\A_x^- = \A_{-\mathbb{N}}:= \A^-$. We will also reserve the letters $\varrho = \varrho^{-1/2}$, $E:=E^{-1/2}$, and $e^{1/2}:=e$ for the family of objects defined as in Lemma~\ref{lem:bundlemap-covariance} on the canonical bundle $(\mathcal{C}, \pi, \Omega)$. 
\end{note} 

 In \cite{FannesNachtergaeleWerner}, the transfer operators are defined in a slightly different way by considering a map $E$ defined on a tensor product of the on-site $C^*$-algebra $\mathcal{A}$ and the space of correlations $B$. This allows them to define iterates on successive tensor powers of $\mathcal{A}$. Since we prefer to point-wise notation for our transfer operators, it is not as obvious that such an extension exists but the repairs are only minimal as the following lemma shows. 

\begin{lem}[Iterates of Transfer Operators]\label{lem:iterate_hom}
    Let $\mathcal{A}$ be a unital $C^*$-algebra and $\A_\Z$ the associated quasilocal algebra. Let $\mathcal{C}$ denote the canonical bundle as in Remark~\ref{rmk:canonical_bundle}. Given a family of transfer operators $T_1:=\{E_a:a\in \mathcal{A}\}\subset \hom^{\vartheta^{-1}}(\mathcal{C}, \mathcal{C})$, and a positive number $p\in \mathbb{N}$, and any finite sum of pure tensors $\sum_{j}a_1^{(j)} \otimes \cdots \otimes a_p^{(j)} \in \mathcal{A}^{\otimes p}$, 
        \begin{equation}
            \|\sum_j E_{a_1^{(j)}}\circ \cdots \circ E_{a_p^{(j)}}\|\le \|\sum_{j}a_1^{(j)} \otimes \cdots \otimes a_p^{(j)}\|_{\min}
        \end{equation} Thus, there exists a family of transfer operators $\{E^{(p)}_{b} : b\in \mathcal{A}^{\otimes p}\} \subset \hom^{\vartheta^{-p}}(\mathcal{C}, \mathcal{C})$ extending length $p$ compositions $E_{a_1}\circ \cdots E_{a_p}$ of elements of $T_1$. 
\end{lem}
\begin{proof}
    We have already observed that the transfer operators are linear in $a$. It is clear that if the estimate holds, then for any $d\in \mathcal{A}^{\otimes p}$, one can find a sequence of iterates of the form $s$ as above converging to $d$ in $\|\cdot \|_{\min}$, and the resulting operator agrees with $[b,\omega] \mapsto [d\otimes b, \vartheta^{-p}\omega]$. So the proof reduces to showing that the estimate holds. We will show this in the case that $p=2$, and from there the proof follows easily by induction. 

    Let $v:= \sum_j a_j \otimes b_j \in \mathcal{A}\otimes_{\min} \mathcal{A}$, and consider the operator $E^{(2)}_{v, \omega} := \sum_{j} E_{a_j, \vartheta \omega} \circ E_{b_j, \omega}$. We see that for any $[x,\omega] \in \mathcal{C}$, one has
        \begin{align*}
            \|E^{(2)}_{v, \omega}[x, \omega]\| &= \|\sum_{j} E_{a_j, \vartheta \omega} \circ E_{b_j, \omega}[x,\omega] \|= \|\left[\sum_j a \otimes \tau_1(b) \otimes x, \vartheta^{-2}\omega \right] \|\\
            &\le \|\sum_j a \otimes \tau_1(b)\| \|[x, \vartheta^{-2}\omega]\|= \|v\|_{\min} \|[x, \vartheta^{-2}\omega]\|.
        \end{align*} To obtain the last equality, recall that in the expression $a\otimes \tau_1(b)$ we have identified $a$ with its image under the faithful representation $\iota_{0}:\mathcal{A} \to \A_\Z$ via $a\mapsto \one_{(-\infty, -1]} \otimes a \otimes \one_{[1, \infty)},$ and similarly with $b$ and $\iota_1$. Recalling that the value of the minimal tensor norm does not depend on the choice of faithful representation (\cite[Proposition 3.3.11]{BrownOzawa}), we obtain 
        \[
            \| \sum_j a \otimes \tau_1(b) \|_{\A_\Z} = \| \sum_j a \otimes b\|_{\min} = \|v\|_{\min},
        \] completing the proof. 
\end{proof}

\begin{thm}[Minimality]\label{thm:minimal}
    Suppose that $\psi_\omega$ is a TCVS with small correlations.  Let $\mathcal{C}$ be the canonical correlation bundle defined in Remark~\ref{rmk:canonical_bundle} with its native transfer apparatus $(\varrho, E,e)$. 

    Let $(\mathcal{E}, \pi, \Omega)$ be any Banach bundle satisfying the following:
            \begin{enumerate}[label = (\roman*)]
                \item a Banach bundle $(\mathcal{E}, \pi, \Omega)$ so that each fiber is nontrivial and has finite dimension, 
                \item a continuous section $f\in \Gamma(\mathcal{E})$, 
                \item a homomorphism $\varphi \in \hom(\mathcal{E}, \Omega \times \C)$, with $\varphi_\omega(f(\omega)) \equiv 1$ and $\sup_{\omega \in \Omega}\|f_\omega\|\le 1$
                \item and, a family of \textbf{transfer operators}
        \[
            \{F_{a,\omega}:\mathcal{E}_\omega \to \mathcal{E}_{\vartheta^{-1}\omega}\colon a\in \mathcal{A}, \omega \in \Omega\}\subset \hom^\vartheta(\mathcal{E}, \mathcal{E})
        \] which are bounded and linear in $a\in \mathcal{A}$ and $e\in \mathcal{E}_\omega$, and satisfy $F_{\one, \omega}(f(\omega)) = f(\vartheta^{-1}\omega)$ and $\varphi_{\vartheta^{-1}\omega} \circ F_{\one, \omega} = \varphi_\omega$. 
            \end{enumerate} so that whenever $n<m$ we have 
        \begin{equation}\label{eqn:transfer_expectation}
            \psi_\omega(a_n \otimes a_{n+1} \otimes \cdots \otimes a_m) = \varphi_{\vartheta^{-(n+1)}\omega}\circ F_{a_n,\vartheta^n \omega}\circ \cdots \circ F_{a_m, \vartheta^m \omega}( f(\vartheta^m \omega))
        \end{equation}


    Then the following two conditions are equivalent
    \begin{enumerate}[label = (\alph*)]
        \item There exists a $\vartheta^{-1}$-co-variant isometric isomorphism $\Phi: \mathcal{C} \to \mathcal{E}$. 
        \item For all $\omega$, the span of the transfer operators $\spn\{F_{a,\omega} \circ F_{b,\vartheta\omega} \circ \cdots \circ F_{c, \vartheta^n}\circ f(\vartheta^{n}\omega )\}\subset \mathcal{E}_{\vartheta^{-1}\omega}$ and, $\spn\{\varphi_{\vartheta^{-(n+1)}\omega}\circ F_{a,\vartheta^{-n} \omega} \circ F_{b,\vartheta^{-(n-2)}\omega} \circ \cdots\circ  F_{c, \vartheta^{-1}\omega}\}\subset \mathcal{E}^*_{\vartheta^{-1}\omega}$ are dense. 
    \end{enumerate}
Moreover, in the case that $(a)$ or $(b)$ holds, the transfer operators satisfy: 
    \begin{equation}
        F_{a,\omega} = \Phi \circ E_{a, \omega} \circ \Phi^{-1}
    \end{equation}

\end{thm}
\begin{proof}
    $(a)\Rightarrow (b)$ follows from the definition of a co-variant isometric isomorphism.  

    To see $(b)\Rightarrow (a)$, define $\Phi([a, \omega]) = F_{a,\omega}(f(\omega))$. In particular, we have that and $\Phi(e(\omega)) = \Phi([\one, \omega]) = f(\omega)$. 

    To check that $\Phi$ is well-defined, suppose $[a,\omega] = 0$. In which case, for all $X^-\in \mathcal{A}^-$,
        \begin{align*}
            0 = \psi_\omega(X^- \otimes a)\, .
        \end{align*} In particular, this holds for all $x_{-n} \otimes \cdots \otimes x_{-1}$. But by the transfer conditions, this means
        \[
            0  = \phi_{\vartheta^{-(n+1)}\omega}\circ F_{x_{-n}, \vartheta^{-n}\omega} \circ F_{x_{-1}, \vartheta^{-1}} \circ F_{a,\omega}(f(\omega))= \phi_{\vartheta^{-(n+1)}\omega}\circ F_{x_{-n}, \vartheta^{-n}\omega} \circ F_{x_{-1}, \vartheta^{-1}} \circ \Phi([a,\omega])\,. 
        \] By linearity, the above then holds for a dense subspace of $\mathcal{E}^*_{\vartheta^{-1} \omega}$, so it must be that the element $\Phi([a,\omega]) = 0_{\vartheta^{-1}\omega}$. 

        Now, let $a_0 \otimes \cdots \otimes a_n \in \mathcal{A}^+$, and observe that for any $d\in [0, \omega]\cap \mathcal{A}^{\loc}_\Z$
        \[
            \|\Phi([a_0\otimes \cdots \otimes a_n, \omega])\| = \|\Phi([a_0\otimes \cdots \otimes a_n +d, \omega])\|= \|F_{a + d, \omega} (f(\omega)) \| \le \|F_{a + d, \omega}\| \le \|a+d\|_{\mathcal{A}_\Z}
        \] Whence, 
        \[
            \|\Phi([a_0\otimes \cdots \otimes a_n, \omega])\|\le \|[a_0 \otimes \cdots \otimes a_n, \omega]\|_{\mathcal{C}_\omega}
        \] since $\mathcal{A}^{\loc}_{\Z}$ is dense and $[0, \omega]$ is a closed subspace of $\mathcal{A}_\Z$. Therefore, $\Phi$ extends to a linear map on all fibers in $\mathcal{C}$. By construction, one sees that $\Phi$ has a fiber-wise dense range in $\mathcal{E}$. 

        Moreover, $\Phi$ is an injection. To see this, suppose that $\Phi([a_0 \otimes \cdots \otimes a_n, \omega])= 0_{\vartheta^{-1}\omega}$. By the transfer property, this means that 
        \[
            0 = \varphi_\omega \circ F_{a_0, \omega}\circ \cdots \circ F_{a_n, \vartheta^n \omega} \circ f(\vartheta^n \omega) = \psi_\omega(a_0\otimes \cdots \otimes a_n)\,.
        \] By Lemma~\ref{lem:n-norm}, this means, 
        \[
            \|[a_0 \otimes \cdots \otimes a_n, \omega ]\| = \sup_{c\in (\mathcal{A}^-)_1} |\psi_\omega (c\otimes a_0 \otimes \cdots \otimes a_n)| \le 8|\psi_\omega (\one \otimes a_0 \otimes \cdots \otimes a_n)| = 0
        \] where the inequality is gotten by appealing to the Cartesian decomposition of operators in a $C^*$-algebra as in the argument leading up to inequality~(\ref{eqn:f_fam_equi}) in Lemma~\ref{lem:n-norm}. In fact, by working a little harder we can see that $\Phi$ is an isometry: appealing again to Lemma~\ref{lem:n-norm}, we have 
    \begin{align*}
        \|[b,\omega]\| &= \sup_{c\in (\A^-)_1}|\psi_\omega(c\otimes b)| = \sup_{d\in D\subset (\A^-)_1} |\varphi_{\vartheta^{\min\{\supp(d)\}-1}\omega} \circ F^{(|\supp(d)|)}_{d, \omega} \circ F_{b,\omega}(f(\vartheta \omega))| \\&= \sup_{g\in \mathcal{E}_{\vartheta^{-1}\omega}^*} |g(F_{b,\omega}(f(\omega)))| = \|F_{b,\omega}(f(\omega))\|\,    
    \end{align*} where by $D$ we denote intersection of $\mathcal{A}^{\loc}_{\Z}$ and $(A^-)_1$, which is dense in $(\mathcal{A}^-)_1$; and by $E^{(|\supp(d)|)}_{d, \omega}$ we mean the iterated transfer operator as in Lemma~\ref{lem:iterate_hom}.

        We need to check that $\Phi$ is an homeomorphism. This follows since $\Phi$ takes a dense submodule of $\Gamma(\mathcal{C})$ to the dense submodule induced by the transfer operators in $\Gamma(\mathcal{E})$. Indeed, let $\Gamma_0$ be the family of sections gotten by $\spn_{C(\Omega)}\{E_{a, \omega} \circ \cdots \circ E_{b, \vartheta^n \omega}\circ e\}$. Then, $\Phi(\Gamma_0) = \spn_{C(\Omega)}\{ \omega \mapsto F_{a,\omega}\circ \cdots \circ F_{b, \vartheta^n \omega}\circ f(\omega)\}$ which is fiber-wise dense in $\mathcal{E}$ by assumption. or equivalently, it is a dense $C(\Omega)$-submodule of $\Gamma(\mathcal{E})$. Thus, the topologies on $\mathcal{E}$ induced by the dense submodule $\Phi(\Gamma_0)$ sections are the same as that induced by $\Gamma(\mathcal{E})$, so we conclude $\Phi$ is continuous. The same argument works to show that $\Phi^{-1}$ is continuous. 
\end{proof}

\begin{rmk}
    In words, the minimality theorem says that with respect to properties (i)-(iv), having a dense subspaces generated by the transfer operators acting on distinguished sections $\varphi_\omega$ and $e(\omega)$, is enough to ensure that the whole apparatus is in fact isometrically isomorphic to the small correlations bundle. 
\end{rmk}

In Lemmas~\ref{lem:pre-fundamental}--~\ref{lem:iterate_hom} and Theorem~\ref{thm:minimal}, we have extensively explored the properties of the small correlations bundle $\mathcal{C}$. We have seen enough properties that we can now state our first main result.  
\begin{thm}[Theorem~\ref{thmx:Fundamental}]\label{thm:Fundamental}
    Let $\mathcal{A}$ be a unital $C^*$-algebra and $\A_{\Z}$ be the associated quasi-local algebra with canonical group action by translation $\Z \acts{\tau} \A_\Z$. Let $\Omega$ be a compact Hausdorff space equipped with an homeomorphism $\vartheta$. Suppose $\omega \mapsto \psi_\omega$ is a weakly*-continuous mapping into the states $\mathcal{S}(\A_{\Z})$ which is translation covariant. 
    The following are equivalent. 
    \begin{enumerate}[label = (\alph*)]
        \item For all $\omega \in \Omega$, the subspace $\spn \{\psi_\omega(X\otimes (\, \cdot \,))\colon X\in \A^-\}\subset (\A^+)^*$ is finite dimensional. 
        \item There exists a \textbf{transfer apparatus} consisting of a Banach bundle $(\mathcal{E}, \pi, \Omega)$ so that each fiber is nontrivial and finite dimensional, and a triple $(\phi, f, \{F_{a,\omega}\}_{a\in \A^+})$ of covariant homomorphisms implementing $\psi_\omega$ as in~(\ref{eqn:transfer_expectation}).
    \end{enumerate}
\end{thm}
\begin{proof}
    To see the $(a)\Rightarrow (b)$ direction, note that the spanning condition implies that the Banach spaces $B^-_{-1/2, \omega}:= \B^-_\omega$ are all finite dimensional. By our observations in Remark~\ref{rmk:nondegenerate}, there is a perfect bilinear pairing $\eta_\omega :B_\omega^- \times B^+_\omega \to \C$, and thus $\B_\omega^+$ is finite dimensional for all $\omega$ as well. Thus, $\psi_\omega$ has small correlations across every cut by Lemma~\ref{lem:cut_independent}. Further, all the Banach bundles $\mathscr{B}_x^+$ are isomorphic to the canonical bundle $\mathcal{C} = \mathscr{B}_{-1/2}^+$, which we take to be $\mathcal{E}$. The rest of the theorem statement follows from Lemma~\ref{lem:pre-fundamental}.


    The direction $(b)\Rightarrow (a)$ follows essentially the same argument as Proposition 2.1 in \cite{FannesNachtergaeleWerner} with some minor modifications. Define a pair of maps $Q^{+}_\omega : \mathcal{A}^{+} \to \mathcal{E}_\omega$ and $Q^{-}_\omega : \mathcal{A}^- \to \mathcal{E}_\omega^*$ using the homomorphisms $\varphi$, $F_a$ (with $a\in \mathcal{A}$), and the section $f$ as follows:
    \[
        \begin{split}
            Q^+_\omega(a_0 \otimes \cdots \otimes a_n) &= F_{a_0, \omega} \circ F_{a_1, \vartheta \omega} \circ \cdots \circ F_{a_n, \vartheta^n \omega}(f(\vartheta^n\omega))\in \mathcal{E}_{\vartheta^{-1}\omega}\\
            Q^-_{\omega}(a_{-n} \otimes \cdots \otimes a_{-1}) &= \varphi_{\vartheta^{-(n+1)} \omega} \circ F_{a_{-n}, \vartheta^{-n} \omega } \circ \cdots \circ F_{a_{-1}, \vartheta^{-1}\omega}\in \mathcal{E}^*_{\vartheta^{-1}\omega}. 
        \end{split}
    \] 

    One checks that for all $\omega\in \Omega$, both $Q^{\pm}$ are linear mappings from $\A^+\to \mathcal{E}_\omega$ and $\A^-\to \mathcal{E}^*_\omega$ respectively. We need to check that $Q_\omega^{\pm}$ extend to bounded operators. Since the span of pure tensors is dense in the minimal $C^*$-norm, it is sufficient to show that 
    \[
        Q_\omega^{+}\left( \sum_{j} a_1^{(j)}\otimes \cdots a_n^{(j)}\right) \le \left\| \sum_{j} a_1^{(j)}\otimes \cdots a_n^{(j)}\right\|_{\min}
    \] To do so, let $V_\omega = \spn\{ \varphi_{\vartheta^{-(n+1)}\omega} \circ F_{a,\vartheta^{-n}\omega} \circ \cdots \circ F_{b, \vartheta^{-1} \omega}\}$, and $W_\omega = \spn\{F_{a_0, \omega} \circ F_{a_1, \vartheta \omega} \circ \cdots \circ F_{a_n, \vartheta^n \omega}(f(\vartheta^n\omega))\}$.  Since every $\mathcal{E}_\omega$ is finite dimensional, so is each dual space $\mathcal{E}_{\omega}^*$, and hence so are $V_\omega$ and $W_\omega$. Now by the Minimality Theorem~\ref{thm:minimal}, we know that $V_\omega$ and $W_\omega$ can be mapped isometrically into the small correlations bundle. By Lemma~\ref{lem:n-norm}, we conclude that $V_\omega$ and $W_\omega$ are norming for one another. 

    Furthermore, one checks that 
    \begin{align*}
        Q^-_\omega\left(\sum_{j'} b_{-m}^{(j')}\otimes \cdots b_0^{(j')}\right)\circ Q_\omega^{+}\left( \sum_{j} a_1^{(j)}\otimes \cdots a_n^{(j)}\right) &= \psi_\omega\left\{\left(\sum_{j'} b_{-m}^{(j')}\otimes \cdots b_0^{(j')}\right)\otimes \left( a_1^{(j)}\otimes \cdots a_n^{(j)}\right)\right\}
    \end{align*} Therefore, by decomposing a $v\in (V_\omega)_1$ into a sum of pure tensors, we may rewrite \[|v(Q^+(\sum a_1 ^{(j)}\otimes \cdots \otimes a_n^{(j)})| = \psi_\omega( v'\otimes \sum a_1 ^{(j)}\otimes \cdots \otimes a_n^{(j)}),\] for some sum of pure tensors $v'\in \A^-$. Thus, we can bound $\|Q^+(a_1 ^{(j)}\otimes \cdots \otimes a_n^{(j)})\|\le 8|\psi_\omega(v' \otimes \one)| \|\sum_j a_1 ^{(j)}\otimes \cdots \otimes a_n^{(j)}\|$ by appealing to Cartesian decompositions if necessary. Therefore, $Q^+$ extends to a bounded linear operator since $|\psi_\omega(v' \otimes \one)|\le \|[v', \omega]^-\|_{\mathcal{C}_\omega^-} = \|v\|$, by Theorem~\ref{thm:minimal} once again. A similar argument works for $Q^-$. Therefore,  
    \[
        \psi_\omega(X^- \otimes X^+) = Q^-_\omega(X^-) \circ Q^+_\omega(X^+), \quad \forall X^-\in \A^-, X^+ \in \A^+\,.
    \] 


    Now, since the range of $Q_\omega^-$ is $\spn\{ \varphi_{\vartheta^{-(n+1)}\omega} \circ F_{a,\vartheta^{-n}\omega} \circ \cdots \circ F_{b, \vartheta^{-1} \omega}\}\subset \mathcal{E}_{\vartheta^{-1}\omega}^*$, the latter being finite dimensional, we have that \[\mathcal{E}^*_\omega \supset \spn\{ F^-_\omega(X^-) \colon X^- \in \A^-\}  \cong \spn\{ \psi_\omega(X^- \otimes (\, \cdot \,))\colon X^- \in \A^-\}\subset (\A^+)^*\] is finite dimensional for all $\omega$.  
\end{proof}

\begin{define}\label{def:apparatus}
    In view of Theorems~\ref{thm:Fundamental}, the existence of a triple $(\varphi, F, f)$ where $\varphi \in \hom(\mathcal{E}, \Omega \times \C)$, and $F = \{E_{a}\in \hom^{\vartheta^{-1}}(\mathcal{E}, \mathcal{E})\colon a\in \mathcal{A}\}$, and a section $f\in \Gamma(\mathcal{E})$ satisfying Theorem~\ref{thm:Fundamental}.(b)(i)-(iv) is inherent to the expansion of a TCVS $\psi_\omega$ with small correlations. To make the following more readable, we shall call such a triple a \textbf{transfer apparatus} on the bundle $(\mathcal{E}, \pi, \Omega)$. We shall reserve the letters $(\varrho, E, e)$ for the transfer apparatus defined on the canonical bundle $(\mathcal{C}, \pi, \Omega)$ as in Lemma~\ref{lem:bundlemap-covariance}.  
\end{define}

An immediate corollary is the following characterization of the small correlations property.
\begin{cor}
    Let $\psi_\omega$ be a TCVS on $\mathcal{A}_\Z$. Then $\psi_\omega$ has small correlations if and only if either of the equivalent conditions in Theorem~\ref{thm:Fundamental} are satisfied. 
\end{cor}



