\subsection{TCVS with Small Correlations are Weakly* Dense}
In \cite[Proposition 2.6]{FannesNachtergaeleWerner}, it is shown that the class of $C^*$-finitely correlated states is weakly* dense inside the translation invariant states. We aim to show an analogue of this for translation covariant states with small correlations. To do so, we need to recall some light details about direct sums and tensor products of Banach bundles. 

Let $X$ and $Y$ be two Banach bundles over $\Omega$. Form the family $\{Z_\omega := X_\omega \oplus Y_\omega\}_{\omega \in \Omega}$ by taking the topological direct sum of the fibers, equipped with the canonical surjection $\pi$ onto the base-points. Taking $\Gamma = \Gamma(X) \oplus \Gamma(Y)$ defines a Banach module of sections into $Z:= \bigsqcup_\omega Z_\omega,$ and therefore there exists a unique topology turning $(Z,\pi, \Omega)$ into a Banach bundle with $\Gamma(X) \oplus \Gamma(Y)$ a dense sub-module of continuous sections (Theorem~\ref{thm:Banach_Bundle}). We say that $Z$ is the \textit{direct sum} of $X$ and $Y$ and write $Z = X\oplus Y$. It is not difficult to check that the analogous definition for homomorphisms is valid.

\begin{note}\label{note:set_of_tcvs}
    Let $\mathcal{A}$ be a unital $C^*$-algebra and let $\A_{\Z}$ be the associated quasilocal algebra. Let $\Omega$ be a compact Hausdorff space equipped with an homeomorphism $\vartheta$. By $\mathfrak{C}$, we mean the set of translation co-variant states on $\A_\Z$. The subset of those translation co-variant states with small correlations is denoted by $\mathfrak{K}\subset \mathfrak{C}$. 
\end{note} 

\begin{lem}[$\mathfrak{C}$ is Convex]\label{lem:convex}
    With notation as in~\ref{note:set_of_tcvs}, both $\mathfrak{C}$ and $\mathfrak{K}$ are convex within the vector space of weakly*-continuous mappings into $\mathcal{S}(\A_\Z)$. 
\end{lem}
\begin{proof}
    The proof is essentially the same as in \cite[Proposition 2.6(2)]{FannesNachtergaeleWerner}. The nontrivial part is to show that $\mathfrak{K}$ is convex. To this end, let $\psi, \phi \in \mathfrak{K}$ and $\mu \in (0,1)$. Clearly, $g:= \mu \psi + (1-\mu) \phi \in \mathfrak{C}$. Theorem~\ref{thm:Fundamental} tells us there exists Banach bundles $(\mathcal{E}, \pi_{\mathcal{E}}, \Omega)$ and $(\mathcal{F}, \pi_{\mathcal{F}}, \Omega)$, sections $e\in \Gamma(\mathcal{E})$ and $f\in \Gamma(\mathcal{F})$, homomorphisms $\varrho\in \hom(\mathcal{E}, \Omega \times \C)$ and $\varphi\in \hom(\mathcal{F}, \Omega \times \C)$, and transfer operators $\{E_a\}_{a\in \mathcal{A}}\in \hom^\vartheta(\mathcal{E},\mathcal{E})$, and $\{F_a\}_{a\in \mathcal{A}}\subset \hom^\vartheta(\mathcal{F}, \mathcal{F})$, for $\psi$ and $\phi$ respectively. Form $\mathcal{G}:= \mathcal{E}\oplus \mathcal{F}$ as the direct sum of the Banach bundles. One readily checks that with $\gamma:= \mu \varrho + (1-\mu)\varphi \in \hom(\mathcal{G}, \Omega \times \C)$, $h:= e \oplus f$, and transfer operators $\{G_a := E_a \oplus F_a\}_{a\in \mathcal{A}},$ that the bundle $(\mathcal{G}, \pi_{\mathcal{G}}, \Omega)$ satisfies~(\ref{eqn:transfer_expectation}) for the state $g$. 
\end{proof}

\begin{lem}[$\mathfrak{K}$ is robust under grouping]
    Let $p\in \mathbb{N}$ and let $\psi\in \mathfrak{K}$. There exists a weakly* continuous mapping $\psi^{(p)}:\Omega \to \mathcal{S}( (\mathcal{A}^{\otimes p})_\mathbb{Z})$ that is $\vartheta^p$-covariant with respect to translation on $(\mathcal{A}^{\otimes p})_\Z$, and $\psi^{(p)}$ has small correlations. 
\end{lem}
\begin{proof}
    Just as in \cite[Proposition 2.6(3)]{FannesNachtergaeleWerner}, $\psi^{(p)}$ is just $\psi$ viewed as taking arguments from $(\mathcal{A}^{\otimes p})_{\Z}$, in which case, the iterated transfer maps from Lemma~\ref{lem:iterate_hom} determine the expectation values. 
\end{proof}

\begin{lem}[Aromatic Average]\label{lem:aromatic_average}
    Suppose that $\phi$ is a TCVS on $(\mathcal{A}^{\otimes p})_{\Z}$ with small correlations that co-varies with respect to $\vartheta^p$. I.e. $\phi \circ \tau_{kp} = \phi_{\vartheta^{kp}}$ for all $k\in \Z$. If $\phi$ has small correlations, then the state 
        \begin{equation}
            \bar \phi_\omega := \frac{1}{p} \sum_{n=0}^p \phi_{\vartheta^{-n}\omega}\circ \tau_n
        \end{equation} is translation covariant with respect to $\vartheta$ on $\A_{\Z}$ and has small correlations. 
\end{lem}
\begin{proof}
    Checking translation covariance is not difficult:  
        \[
            \bar \phi_\omega \circ \tau_1 = \frac{1}{p}( \phi_\omega \circ \tau_1 + \phi_{\vartheta^{-1}\omega}\circ \tau_2 + \cdots + \phi_{\vartheta^{-(p-1)}\omega}\circ \tau_p) =\frac{1}{p}( \phi_{\vartheta \omega} +\phi_\omega \circ \tau_1 + \cdots + \phi_{\vartheta^{-(p-1)}}\circ \tau_p) = \bar \phi_{\vartheta \omega}\,.
        \]
    Now we need to construct a bundle satisfying part (b) of Theorem~\ref{thm:Fundamental}. To begin, let $(\mathcal{C}^\phi, \pi, \Omega)$ be the canonical bundle associated to $\phi$ on $(\mathcal{A}^{\otimes p})_\Z$ equipped with transfer apparatus $(\varrho^\phi, \{E^{\phi}_x\}_{x\in \mathcal{A}^p}, e^\phi)$. 

    Let $0<n\le p-1$, consider the vector subspaces of $\mathcal{C}^\phi_\omega$ given by
    \[
        \mathcal{C}^{(n)}_\omega := \spn \{ [\one_{\mathcal{A}}^{\otimes n}\otimes \tau_n(\xi), \omega] \colon \xi \in \mathcal{A}_{[0, \infty)}\}. 
    \] We take $\mathcal{C}^{(0)}_\omega = \mathcal{C}^\phi_\omega$. For each $\omega\in \Omega$ we now define the finite-dimensional vector space 
    \begin{equation}
        \mathcal{R}_\omega := \spn \left\{ \bigoplus_{n=0}^{p-1} [\one_{\mathcal{A}}^{\otimes n} \otimes \tau_n(\xi), \vartheta^{-n}\omega] \colon \xi \in \mathcal{A}_{[0, \infty)}\right\} \subset \bigoplus_{n=0}^{p-1} \mathcal{C}^{(n)}_{\vartheta^{-n} \omega}
    \end{equation} equipped with the graph norm 
    \begin{equation}
        \left\| \bigoplus_{n=0}^{p-1} [\one_{\mathcal{A}}^{\otimes n} \otimes \tau_n(\xi), \vartheta^{-n}\omega]\right\|_{\mathcal{R}_\omega} := \sum_{n=0}^{p-1} \|[\one_{\mathcal{A}}^{\otimes n} \otimes \tau_n(\xi), \vartheta^{-n}\omega]\|_{\mathcal{C}^{\phi}_{\vartheta^{-n}\omega}}
    \end{equation} Note that each element of $\mathcal{R}_\omega$ is a $p$-tuple of equivalence classes of the translates of a single operator $\xi \in \mathcal{A}_{[0, \infty)}$ up to the cut $p$.  

    Now, let $\mathcal{R}:= \bigsqcup_{\omega \in \Omega}\mathcal{R}_\omega$ be equipped with the surjection $\pi(\oplus[\one^{\otimes n}\otimes \tau_n(\xi), \vartheta^{-n}\omega]) = \omega$. Let also $\Gamma$ be the linear space of functions of the form 
        \begin{equation}\label{eqn:aromatic_sections}
            \alpha: \omega \mapsto \bigoplus_{n=0}^{p-1}[\one^{\otimes n}\otimes \tau_n( A(\omega) ), \vartheta^{-n}\omega]
        \end{equation} where $A\in C(\Omega, \mathcal{A}_{[0, \infty)})$. One readily checks that $\Gamma$ is fiber-wise dense in $\mathcal{R}$. Furthermore, one checks that for all $\alpha \in \Gamma$, the assignment $\omega \mapsto \|\alpha(\omega)\|_{\mathcal{R}_\omega}$ is continuous since each summand in the graph norm is the norm of a translate of the continuous section $(\omega \mapsto [A(\omega), \omega])\in \Gamma(\mathcal{C}^\phi)$. Once again, we note that the tuple above is defined using the same function $A$ in each coordinate. 

    Therefore, by the Fell-Doran Theorem (Theorem~\ref{thm:Banach_Bundle} above), there is a unique topology making $\mathcal{R}$ into a Banach bundle with $\Gamma$ a dense $C(\Omega)$-submodule of continuous sections. For brevity, we will refer to $\mathcal{R}$ as the \textbf{aromatic bundle}. 

    We need to equip $\mathcal{R}$ with a transfer apparatus that implements the average $\bar \phi$. To do so, let $a\in \mathcal{A}$ and define the maps
    \begin{equation}
        \begin{split}
            F_{a,\omega} &\left(\oplus_{n=0}^{p-1} [\one_{\mathcal{A}}^{\otimes n} \otimes \tau_n(\xi), \vartheta^{-n} \omega] \right):= \bigoplus_{n=0}^{p-1}[\one_{\mathcal{A}}^{\otimes n}\otimes a \otimes \tau_{n+1}(\xi), \vartheta^{-(n+1)}\omega]\\
            &=[a\otimes \tau_1(\xi), \vartheta^{-1}\omega]\oplus [\one \otimes a \otimes \tau_2(\xi), \vartheta^{-2}\omega] \oplus \cdots \oplus [\one_{\mathcal{A}}^{\otimes (p-1)}\otimes a \otimes \tau_p(\xi), \vartheta^{-p}\omega]\,.
        \end{split}
    \end{equation} 
    \begin{claim}\label{claim:Fa_well_defined}
        The maps $F_{a,\omega}$ are well-defined $\vartheta^{-1}$-covariant homomorphisms of $\mathcal{R}$. 
    \end{claim}

    Postponing the proof of the claim for now, we aim to show the $F_a$'s form a set of transfer operators in a transfer apparatus (see Definition~\ref{def:apparatus}) for $\bar \phi$. To complete the transfer apparatus, let $f(\omega) = \bigoplus [\one, \vartheta^{-n}\omega]$, and let $\mu_\omega = \frac{1}{p} \bigoplus_{n=0}^{p-1} \varrho^\phi_{\vartheta^{-n} \omega}$. One checks that $f$ is a continuous section and that $\mu_\omega\in \hom(\mathcal{R}, \Omega \times \C)$. Furthermore, $\mu_\omega(f(\omega)) \equiv 1$. Now, let $a\in \mathcal{A}$. We will show that $F_{a,\omega}$ implements $\bar\phi$ with $f$ and $\mu$, and the general case will follow by iteration. One has
    \begin{align*}
        \mu_{\vartheta^{-1}\omega}(F_{a, \omega}(f(\omega))) &= \frac{1}{p}\sum_{n=0}^{p-1} \varrho^\phi_{\vartheta^{-(n+1)}\omega} [\one_{\mathcal{A}}^{\otimes n}\otimes a \otimes \one, \vartheta^{-(n+1)}\omega]= \frac{1}{p} \sum_{n=0}^{p-1} \phi_{\vartheta^{-(n+1)}\omega}(\one^{\otimes n}\otimes a)\\
        & = \frac{1}{p} \sum_{n=0}^{p-2} \phi_{\vartheta^{-(n+1)}}(\one^{\otimes n}\otimes a) + \frac{1}{p}\phi_{\omega}(a) = \frac{1}{p} \sum_{n=0}^{p-2} \phi_{\vartheta^{-(n+1)}}(\tau_n(a)) + \frac{1}{p}\phi_{\omega}(a)\\
        &= \bar \phi_\omega (a)
    \end{align*} where the second-to last inequality follows since $\phi$ is $\vartheta^p$-covariant, and the result of translating by $-p$ puts $a$ at the zero site. Therefore, $(\mathcal{R}, \pi, \Omega)$ is a Banach bundle whose fibers are finite dimensional with $(\mu, F, f)$ serving as a transfer apparatus for $\bar \phi$. Thus by Theorem~\ref{thm:Fundamental}, we conclude that $\bar \phi$ has small correlations. 
\end{proof}

Below, we record a proof of Claim~\ref{claim:Fa_well_defined}. 
\begin{proof}[Proof of Claim~\ref{claim:Fa_well_defined}]
    Recall that in any $C^*$-algebra, an element is generated by a Cartesian sum of self-adjoint elements. In fact, due to the triangle inequality, to show that the $F_a$ are well-defined, it is sufficient to show that if $\xi \in \mathcal{A}_{[0, \infty)}$ is self-adjoint and $r= \oplus [\one^{\otimes n} \otimes \xi, \vartheta^{-n}\omega]$ is zero, then $F_a(r) = 0$. 

    Now, let $a\in \mathcal{A}$. We may write $a = a_0 - a_1 +ia_3 -ia_4$ where each $a_j\ge 0$ and $\sum \|a_j\| \le 2 \|a\|$. Observe that for any $c\in (\mathcal{A}_{(-\infty, 0)})_{s.a.}$, one has the estimate 
    \begin{equation}\label{pf:eqn:long_inequality}
        -\|a_j\| \phi_{\vartheta^{-n}\omega}(c \otimes \one^{\otimes n} \otimes \tau_{n+1}(\xi)) \le \phi_{\vartheta^{-n}\omega}(c\otimes \one^{\otimes (n-1)}a_j\otimes \tau_{n+1}(\xi)) \le \|a_j\| \phi_{\vartheta^{-n}\omega}(c \otimes \one^{\otimes n}\otimes \tau_{n+1}(\xi))
    \end{equation}

    Now, we may write any $d\in \mathcal{A}_{(-\infty, 0)}$ as $d = \Re(d) + i\Im(d)=: d_1 + i d_2$, and $d_1,d_2 \in (\mathcal{A}_{(-\infty, 0)})_{s.a.}$. Therefore, by applying the inequality in~(\ref{pf:eqn:long_inequality}) for both $d_1$ and $d_2$, we obtain for any $0\le n \le p-1$ the inequality
    \begin{align*}
        |\phi_{\vartheta^{-n}\omega}(d \otimes \one^{\otimes (n-1)}&\otimes a \otimes \tau_{n+1}(\xi))|\le |\phi_{\vartheta^{-n}\omega}(d_1\otimes \one^{\otimes (n-1)}\otimes a \otimes \tau_{n+1}(\xi))| +|\phi_{\vartheta^{-n}\omega}(d_2 \otimes \one^{\otimes (n-1)}\otimes a \otimes \tau_{n+1}(\xi))|\\
        &\le 2\|a\|\left[ |\phi_{\vartheta^{-n}\omega}( \frac{d + d^*}{2} \otimes \one^{\otimes n} \otimes \tau_{n+1}(\xi) ) | + |\phi_{\vartheta^{-n}\omega}( \frac{d - d^*}{2} \otimes \one^{\otimes n} \otimes \tau_{n+1}(\xi) ) |\right]\\
        &\le 2\|a\| \left[|\phi_{\vartheta^{-n}\omega}( d \otimes \one^{\otimes n} \otimes \tau_{n+1}(\xi) ) |+|\phi_{\vartheta^{-n}\omega}( d^* \otimes \one^{\otimes (n+1)} \otimes \tau_{n+1}(\xi) ) | \right]\\
        &= 4 \|a\|  |\phi_{\vartheta^{-n}\omega}( d \otimes \one^{\otimes n} \otimes \tau_{n+1}(\xi) ) |
    \end{align*} where the last equality follows since $\xi$ is a self-adjoint. Now, since the fibers $\mathcal{C}^{\phi}_\omega$ are finite dimensional, Lemma~\ref{lem:n-norm} tells us that 

    \begin{equation}\label{pf:eqn:summands}
        \|[\one^{\otimes (n-1)}\otimes a \otimes \tau_{n+1}(\xi), \vartheta^{-(n+1)}\omega]\| \le 4\|a\| \|[\one^{\otimes n} \otimes \tau_{n+1}(\xi), \vartheta^{-(n+1)}\omega]\|\,. 
    \end{equation} Lastly, we note that for $n=p-1$

    \begin{equation}\label{pf:eqn:p-1}
        \|[\one^{\otimes p}\otimes \tau_{p}(\xi), \vartheta^{-p}\omega]\| \le \|[\xi, \omega]\|
    \end{equation} since $\phi$ is $\vartheta^p$-covariant: indeed, we note that
    \[
        \|[\one^{\otimes p}\otimes \tau_{p}(\xi), \vartheta^{-p}\omega]\| = \inf_{x\in \mathcal{I}_{\vartheta^{-p} \omega}}\|\one^{\otimes p}\otimes \tau_{p}(\xi) + x\| = \inf_{\tau_{-p}(x)} \|\xi + \tau_{-p}(x)\| \le \inf_{y \in \mathcal{I}_{\omega}} \|\xi + y\| = \|[\xi, \omega]\|.
    \]

    Finally, it follows by the triangle inequality, inequality~(\ref{pf:eqn:summands}), and inequality~(\ref{pf:eqn:p-1})  that for any element $r\in \mathcal{R}$ as defined in the beginning of the proof
    \begin{equation}\label{pf:eqn:estimate_for_s.a._elts_in_R}
        \|F_{a, \pi(r)}(r)\| \le 4 \|a\| \|r\|.
    \end{equation} Whence $F_a$ is well-defined for all $a\in \mathcal{A}$. 

    We now work a little harder to extend inequality~(\ref{pf:eqn:estimate_for_s.a._elts_in_R}) to all of $\mathcal{R}$. Notice that if $\xi \in \mathcal{A}_{[0,\infty)}$, then 
    \[
        \|[\xi, \omega]\|_{\mathcal{C}^\phi_\omega} = \|[\xi^*, \omega]\|_{\mathcal{C}^\phi_\omega}
    \] In fact, if $d\in \mathcal{I}_\omega$, then for any $x\in \mathcal{A}_{(-\infty, 0)}$ one has $0 = \phi_\omega(x\otimes d) = \overline{ \phi_\omega(x^*\otimes d^*)}$, whence  $\mathcal{I}_\omega = \mathcal{I}_\omega^*$ by letting $x$ range. Thus, 

    \begin{equation}\label{pf:eqn:bundle_norm_self_adjoint}
        \|[\xi, \omega]\|_{\mathcal{C}^\phi_\omega} = \inf_{d\in \mathcal{I}_\omega} \|\xi + d\| = \inf_{d\in \mathcal{I}_\omega} \|\xi^* + d^*\| = \|[\xi^*, \omega]\|_{\mathcal{C}^\phi_\omega}.
    \end{equation} In fact, $\|[\xi, \omega]\| = 0$ implies both $\|[\Re(\xi), \omega]\| = 0$ and $\|[\Im(\xi), \omega]\|=0$ by the triangle inequality. 

    Now, let $s = \oplus [\one^{\otimes n} \otimes \eta, \vartheta^{-n}\omega]$ for $\eta \in \mathcal{A}_{[0,\infty)}$, and let $s_1 = \oplus [\one^{\otimes n} \otimes \Re(\eta), \vartheta^{-n}\omega]$ and $s_2 = \oplus [\one^{\otimes n} \otimes \Im\eta, \vartheta^{-n}\omega]$ so that $s = s_1 + i s_2$ in $\mathcal{R}$. We note $\|s_j\| \le \frac{1}{2} ( \|s\| + \|s^*\|) =\|s\|$ by~(\ref{pf:eqn:bundle_norm_self_adjoint}). Therefore, 
    \begin{equation}\label{eqn:bound_for_aromatic_transfer}
        \|F_{a,\omega}(s)\| \le \|F_{a,\omega}(s_1)\| + \|F_a(s_2)\| \le 4\|a\|\left(\|s_1\| + \|s_2\| \right) \le 8\|a\| \|s\|_\infty
    \end{equation} Thus, we have also shown that $\|F_a\|_\infty\le 8 \|a\|$. 

    That $F_a$ is $\vartheta^{-1}$-covariant is now obvious, so the last thing to check is that for any $\alpha \in \Gamma(\mathcal{R})$, the image $F_a(\alpha)$ is a continuous function into $\mathcal{R}$. This follows immediately from the observation that $a\otimes \tau_1(A(\omega)) \in C(\Omega, \mathcal{A}_{[0, \infty)})$ for all $A\in C(\Omega, \mathcal{A}_{[0, \infty)})$, so in fact on the dense $C(\Omega)$ submodule $\Gamma$ given by sections as in~(\ref{eqn:aromatic_sections}),  $F_a \cdot \Gamma \subset \Gamma$, and we are done. 
\end{proof}

We now conclude this section with the following theorem. 
\begin{thm}[Theorem~\ref{thmx:w*dense}]\label{thm:w*_dense}
    Let $\mathcal{A}$ be a unital $C^*$-algebra and let $\A_{\Z}$ be the associated quasilocal algebra. Let $\Omega$ be a compact Hausdorff space equipped with an homeomorphism $\vartheta$. By $\mathfrak{C}$, we mean the set of translation co-variant states on $\A_\Z$ and the subset of those translation co-variant states with small correlations is denoted by $\mathfrak{K}\subset \mathfrak{C}$. One has that $\mathfrak{K}$ is weakly-* dense in $\mathfrak{C}$ uniformly in $\omega$. 
\end{thm}
\begin{proof}
    We roughly follow the strategy laid out in \cite[Proposition 2.6(d)]{FannesNachtergaeleWerner}. Let $\psi_\omega\in \mathfrak{C}$ be a translation co-variant state. For $p\in \mathbb{N}$, let $\phi_\omega = \psi_\omega |_{\mathcal{A}_{[0, p-1]}}$ denote the restriction to the local algebra on the interval $[0, p-1]$. Note that $\phi_\omega$ is weakly-* continuous as a function of $\omega$. Let $\phi'_\omega = \bigotimes_{n=-\infty}^\infty \phi_{\vartheta^{np}\omega}$ denote the $\vartheta^p$-covariant product state on $(\mathcal{A}^{\otimes p})_{\Z}$ as constructed in Proposition~\ref{prop:existence_TCPS}. 

    As we saw in Example~\ref{exmp:covariant_product_state}, it follows that $\phi'_\omega$ has small correlations on $(\mathcal{A}^{\otimes p})_{\mathbb{Z}}$. Let now $\bar \phi_\omega = \frac{1}{p} \sum_{n=0}^{p-1} \phi_{\vartheta^{-n}\omega}'\circ \tau_n$ be the Aromatic average. By Lemma~\ref{lem:aromatic_average}, we know that $\bar \phi$ is a $\vartheta$-TCVS on $\mathcal{A}_\Z$ with small correlations. 

    Now, let $a\in \mathcal{A}_{[0, \infty)}^{\loc}$. Find $p$ large enough so that $\supp(a) \subset [j, j+m] \subset [0, p-1]$, for some integers $j, m\in \mathbb{N}\cup \{0\}$. Notice that $\psi_\omega(a)$ and $\phi_{\vartheta^{-n}\omega}\circ \tau_n(a)$ agree unless $j+m+n\ge p$. Therefore, 
    \begin{align}\label{pf:eqn:w*_dense}
        |\psi_\omega(a) - \bar \phi_\omega(a)| &\le \frac{1}{p} \sum_{p-1-(j+m)}^{p-1} | \psi_\omega(a) - \phi_{\vartheta^n\omega}'\circ \tau_n(a)|\\
        \nonumber &\le 2\|a\| \frac{j+m}{p} \to 0
    \end{align} as $p\to \infty$. 

    To see that this inequality holds on all $(\mathcal{A})_{\Z}^{\loc}$, note that if $0\in \supp(a)$, then the translate $\tilde a = \tau_m(a) \subset [0, p-1]$ for $p$ large enough where we set $m = |\min\{\supp(a)\}|+1$. By translation co-variance, we have $|\psi_\omega(a) - \bar \phi_\omega(a)|= |\psi_{\vartheta^m\omega}(\tilde a) - \phi_{\vartheta^m \omega}(\tilde a)|$, so the inequality~(\ref{pf:eqn:w*_dense}) applies to the $\sim$-ed quantity. But $\|\tilde a\| = \|a\|,$ and we are done since the estimate is uniform in $\omega$. 
\end{proof}
