    In the event that there is a degenerate sequence of values, e.g. $z_j=0, z_{j+1}=\frac{\pi}{2}, z_{j+2}\in(0,\frac{\pi}{2})$, then the dimension of the two-point ground state spaces and the three point ground state spaces can all be different. In the example we just mentioned, one calculates that $\dim(\mathcal{G}_{j, j+1}) = 0$ and $\dim(\mathcal{G}_{j+1,j+2}) = 4$, while $\dim(\mathcal{G}_{j, j+1, j+2})=3$. Therefore, in the degenerate case the interaction length must be greater than 2, if it exists at all. 
\end{rmk}


\begin{cor}\label{cor:Parent_Hamiltonian}
    Let $\vec{z}$ be a bi-infinite sequence with entries in $(0, \pi/2) \cup (\pi/2, \pi)$, and let $\nu_{\vec{z}}$ be the corresponding state on $(\mathcal{A})_\Z$. Then, the parent Hamiltonian, h, of $\nu_{\vec{z}}$ is given by
    \begin{equation}\label{eqn:Parent_Hamiltonian}
        h_{j,j+1} = \text{proj}(\mathcal{G}_{j, j+1}^\perp) 
    \end{equation} One can explicitly calculate the vectors whose outer products define $h_{j, j+1}$ and we do so in Appendix~\ref{apdx:mathematica}.
\end{cor}
\begin{proof}
    The existence of the parent Hamiltonian is well established in \cite{Perez-Garcia_et_al}. One may explicitly compute the basis of $\mathcal{G}_{j, j+1}$ and the basis of $\mathcal{G}_{j+1, j+2}$ in terms of the $\{|\phi_{k\ell}(j)\rangle\}_{k,\ell = 1,2}$.
\end{proof}

Now that we have established that the interaction length for the $\nu_{\vec{z}}$ is two for suitable $\vec{z}$, we aim to show that  $\Gamma^{[m,n]}_{\vec{z}}$ maps in remains injective when $|m-n|$ increases in analogy to Lemma 5.3 of \cite{FannesNachtergaeleWerner}. We recall (see Section 5.8 in \cite{HornJohnson}) that the \emph{condition number} of a linear map $L$ is the quantity \[\kappa(L) := \|L\| \|L^{-1}\| = \inf_{x\neq 0} \frac{\|Lx\|}{\|x\|}\] Let 
\begin{equation}\label{def:condition_number_gamma}
    \kappa_{[m,n]}(\vec{z}) := \inf_{x\in \M_2} \frac{\|\Gamma^{[m,n]}_{\vec{z}}(x)\|^2}{\|x\|_{\rho}^2}
\end{equation} where $\|x \|_\rho = \frac{1}{2} \|x\|_{\HS}$, to account for the fact that the density matrix fixed by $E_{\one, \vec{z}}^\dagger$ is $\tfrac{1}{2}\one_{2\times 2}$

\begin{lem}
    For a fixed $\vec{z}$ in range, the following inequality holds
        \begin{equation}
            \kappa_{[m,n]}(\vec{z}) \ge (1-\|\Phi_{m,n} -T\|)
        \end{equation}
    and furthermore, 
        \begin{equation}
            \kappa_{[m,n]}(\vec{z}) \le \min\{ \kappa_{[m-1,n]}(\vec{z}),\, \kappa_{[m,n+1]}(\vec{z})\}
        \end{equation} That is, $\kappa_{[m,n]}$ is non-decreasing with respect to the interval length $|m-n|$. 
\end{lem}
\begin{proof}
    Once again the proof of \cite[Lemma 5.3]{FannesNachtergaeleWerner} is robust in this setting, so we will only emphasize the one place where our proof differs. Consider the interval $[m-1, n]$. By Lemma~\ref{lem:gamma_formulas}, we have 
    \begin{align*}
         \|\Gamma^{[m-1, n]}_{\vec{z}}(x)\|^2 &= \sum_{i_{m-1}, \dots, i_{n}} |\tr(x X^{i_{n}}_{z_n}\, \cdots X^{i_{m-1}}_{z_{m-1}}))|^2=\sum_{i_{m-1}} \sum_{i_m, \dots, i_n} |\tr( [X^{i_{m-1}}_{z_{m-1}}x]X^{i_{n}}_{z_n} \cdots X^{i_{m}}_{z_{m}}) )|^2\\
         &= \sum_{i_{m-1}}\|\Gamma^{[m,n]}_{\vec{z}}(X^{i_{m-1}}_{z_{m-1}}\, x)\|^2 \ge \sum_{i_{m-1}} \kappa_{m,n}(\vec{z}) \tr(\tfrac{1}{2}\one [X^{i_{m-1}}_{z_{m-1}}x]^*[X^{i_{m-1}}_{z_{m-1}}x])\\
        &= \kappa_{m,n}(\vec{z}) \sum_{i_{m-1}} \tr[\tfrac{1}{2}\one x^* X_{i_{m-1}}^* X_{i_{m-1}}x]= \kappa_{m,n}(\vec{z}) \|x\|_\rho^2,
    \end{align*} where we have used the fact that the Kraus matrices defining $E_{\one, \vec{z}}$ are trace preserving and unital both. 
\end{proof}


Let us now conclude with a proof that the $\nu_{\vec{z}}$ are pure states for suitable choices of $\vec{z}$. Recall that a state $\varphi$ on a $C^*$-algebra $C$ is pure if and only if whenever $\rho$ is a positive linear functional for which $\rho(c^*c) \le \varphi(c^*c)$ for all $c\in C$, there necessarily exists a $\lambda \in [0, 1]$ so that $\lambda \varphi = \rho$ (see \cite[Chapter 5]{Murphy}). 

\begin{thm}\label{thm:vec_state_pure}
    Let $\vec{z}$ be any bi-infinite sequence taking values in $(0, \frac{\pi}{2})\cup(\frac{\pi}{2}, \pi)$ and let $\nu_{\vec{z}}$ be the state as generated in equation~\ref{eqn:delta_state}. Then $\nu_{\vec{z}}$ is a pure state on $\mathcal{A}_{\Z}$. 
\end{thm}
\begin{proof}
    We largely follow the proof strategy of \cite[Theorem 5.7]{FannesNachtergaeleWerner}. Suppose that $\rho$ is a state majorized by $\lambda \nu_{\vec{z}}$ for some $\lambda\in (0,1)$. Then for every interval $[m,n]$, one has $\rho|_{\mathcal{A}_{[m,n]}} \le \lambda \nu_{\vec{z}}|_{\mathcal{A}_{[m,n]}}$. In particular, this means that $\rho|_{\mathcal{A}_{[m,n]}}(H^{[m,n]}) = \sum_{j=m}^{n-1} \rho|_{\mathcal{A}_{[m,n]}}(h_{j, j+1}) = 0$. Therefore $\rho|_{\mathcal{A}_{[m,n]}}$ is supported on the intersection in the right-hand side of equation~(\ref{eqn:intersect_ground_state}). But by choice of $\vec{z}$, we know equation~(\ref{eqn:intersect_ground_state}) holds, and therefore $\rho|_{\mathcal{A}_{[m,n]}}$ is supported by $\mathcal{G}_{[m,n]}$. 

    Thus, the density matrix $\hat 
    \rho$ representing $\rho|_{\mathcal{A}_{[m,n]}}$ may be decomposed as 
    \[
        \hat \rho = \sum_k \ket{\Gamma^{[m,n]}_{\vec{z}}(x_k)}\bra{\Gamma^{[m,n]}_{\vec{z}}(x_k)}
    \] with $\sum\|\Gamma^{[m,n]}_{\vec{z}}(x_k)\|^2 = \tr\hat\rho= 1$\,. Now, we see that for any $a$ with finite support $[m',n']\subset [m,n]$, and $|m-n|$ large enough so that $m'\neq m$ and $n'\neq n$, we have 

    \begin{align*}
        \left|\rho|_{\mathcal{A}_{[m,n]}}(a) - \nu_{\vec{z}}(a) \right|&=  \left|\sum_{k}\bra{\Gamma^{[m,n]}_{\vec{z}}(x_k)}a \ket{\Gamma^{[m,n]}_{\vec{z}}(x_k)} - \nu_{\vec{z}}(a)\<\Gamma^{[m,n]}_{\vec{z}}(x_k)|\Gamma^{[m,n]}_{\vec{z}}(x_k)\>\right| \\
        &\le  \left|\sum_k\bra{\Gamma^{[m,n]}_{\vec{z}}(x_k)}a \ket{\Gamma^{[m,n]}_{\vec{z}}(x_k)} - \tfrac{1}{2}\nu_{\vec{z}}(a)\<x_k |x_k\>_{\HS}\right| + 2\|\Phi_{m,n} - T\| \|a\| \sum_k \|x_k\|^2_{\rho}\\
        &\le (\|\Phi_{m, m'-1}-T\| + \|\Phi_{n'+1, n} -T\|+\|\Phi_{m,n} - T\|) 2 \|a\| \sum_k \|x_s\|_{\rho}^2 \\
        &\le 2\|a\| \, \frac{\|\Phi_{m, m'-1}-T\| + \|\Phi_{n'+1, n} -T\|+\|\Phi_{m,n}-T\|}{\kappa_{[m,n]}(\vec{z})} 
    \end{align*} where we have used the triangle inequality combined with inequality~(\ref{eqn:rho_product_estimate}) from Lemma~\ref{lem:gamma_formulas} part b to obtain the first inequality.

    The right-hand side of this can be made arbitrarily small by sending $m\to -\infty$ and $n\to \infty$. Therefore, it must be that $\rho|_{\mathcal{A}_{[m',n']}}$ agrees with $\nu_{\vec{z}}|_{\mathcal{A}_{[m',n']}}$. But this forces $\lambda = 1$, and so it must be that $\nu_{\vec{z}}$ is pure.  
\end{proof}


