\subsection{IID AKLT}\label{subsec:IID_AKLT}
In this section, we explore the consequences of having IID angles in the parameter space $[0,\pi)$ on the parent Hamiltonian $\{h_{j, j+1}(\varphi) \colon j\in \mathbb{Z}, \varphi \in [0, \pi)\}$ that we obtained in Corollary~\ref{cor:Parent_Hamiltonian}. To set this up, let $\{\theta_j: j\in \Z\}$ be a family of IID random variables taking values in $[0,\pi)$. Suppose further that $\theta \sim f(x) dx$ with a continuous density function $f(x)$ with compact support. By the Lemma~\ref{lem:IID_cts}, we can replace the $\vartheta_j$'s with an IID family of continuous random variables $\Theta_j:\Omega \to [0, \pi)$ which are related by an ergodic homeomorphism $\vartheta:\Omega \to \Omega$, and $\Omega$ is a compact Hausdorff space. For convenience, we shall write $\Theta_j(\omega) = \omega_j = \vartheta^j \omega_0 = \Theta_0(\vartheta^j(\omega))$. 

By considering $\omega:=(\omega_j)_{j\in \Z}$ as some sequence taking values in $((0,\frac{\pi}{2})\cup(\frac{\pi}{2}, \pi))^\Z$, define the state $\psi_\omega:= \nu_{(\omega_j)_{j\in \Z}}$ as in equation~(\ref{eqn:delta_state}). Then, by Corollary~\ref{cor:Parent_Hamiltonian}, there is a nearest neighbor parent Hamiltonian $h_{j,j+1}(\omega)$ for which $\psi_\omega$ is the unique bulk ground state by Theorem~\ref{thm:vec_state_pure}. 

\begin{lem}\label{lem:parent_covariance}
    In the above situation, the parent Hamiltonian is translation co-variant in the following sense: 
        \begin{equation}
            h_{j,j+1}(\omega) = h_{j+1, j+2}(\vartheta \omega)\,.
        \end{equation}
\end{lem}
\begin{proof}
    This follows from the coordinate expression of $h_{j, j+1}(\omega)$ in equation~(\ref{eqn:Parent_Hamiltonian}).
\end{proof}

We recall some notation from \cite{NachtergaeleSims}. Let $\mathscr{P}_0(\Z)$ denote the finite subsets of $\Z$ and let $\Phi:\mathscr{P}_0(\Z) \to \bigcup_{Z\in \mathscr{P}_0(\Z)}\mathcal{A}_Z$ be a mapping with self-adjoint images $\Phi(Z)=\Phi(Z)^*\in \mathcal{A}_Z$. Recall that for our model, the single site algebra is $\mathcal{A} = \M_3$. For some $\lambda>0$, the $\lambda$-norm of $\Phi$ is the quantity 
    \begin{equation}
        \|\Phi\|_{\lambda}:= \sup_{x\in \Z} \sum_{X\Subset \Z} 9^{|X|}|X|\|\Phi(X)\| e^{\lambda \diam(X)}
    \end{equation} We remark that the numerical quantity comes from the fact that the dimension of the single-site Hilbert space for the AKLT model is $3$. In \cite{NachtergaeleSims}, this is replaced with a more general bound. 

Note that since our parent Hamiltonian $h$ is nearest neighbor, for all $x\in \Z$, the sum in the $\lambda$-norm collapses to a sum over two sets, namely $\{x,x+1\}$ and $\{x-1,x\}$. Then since each $h_{j,j+1}(\omega)$ is a projector, $\|h_{j, j+1}(\omega)\| \equiv 1$. Therefore, the $\lambda$-norm is finite and in fact we have the following.
\begin{lem}
    Let $\{h_{j, j+1}(\omega) \colon j\in \Z, \omega \in \Omega\}$ be the IID parent Hamiltonian given by equation~(\ref{eqn:Parent_Hamiltonian}). Then, 
    \begin{equation}
        \sup_{\omega \in \Omega}\|h\|_{\lambda} = 324e^{2\lambda};\, \forall\lambda >0
    \end{equation}
\end{lem}

Now, we consider the quantum spin system with local Hamiltonians given by 
    \begin{equation}
        H^{\Lambda}(\omega) = \sum_{Z\subset \Lambda} h_{Z(\omega)} = \sum_{\substack{j\in \Z\colon\\ \{j, j+1\}\subset \Lambda}} h_{j,j+1}(\omega)\in \mathcal{A}_{\Lambda} \text{ where } \Lambda\Subset\Z \,.
    \end{equation}
Let $\alpha^{\Lambda}_{t;\omega}:= e^{itH^{\Lambda}(\omega)}(\,\cdot\,)e^{-itH^\Lambda(\omega)}$ be the dynamics generated by $H^{\Lambda}(\omega)$. We recall that $\alpha^{\Lambda}_{t;\omega}$ is a one-parameter group of automorphisms of $\mathcal{A}_\Lambda$ with respect to $t$. We now come to an interesting observation. 
\begin{lem}\label{lem:dynamics_covariance}
    Let $H^{\Lambda}(\omega)$ be the family of local Hamiltonians given by the IID parent Hamiltonians. Let $\alpha^{\Lambda}_{t;\omega}$ denote the local dynamics generated by $H^{\Lambda}(\omega)$. Then, for all $k\in \Z$, we have
    \begin{equation}\label{eqn:dynamics_covariance}
        \alpha^{\Lambda}_{t;\omega} = \tau_k \circ \alpha^{\Lambda - k}_{t,\vartheta^k} \circ \tau_{-k}
    \end{equation}
\end{lem}
\begin{proof}
    Recall that the nearest neighbor terms satisfy 
        \[
            h_{j, j+1}(\omega) = h_{j+k, j+k}(\vartheta^k \omega)\,.
        \] which is immediate from Lemma~\ref{lem:parent_covariance}. Therefore, 
        \[
            \tau_k(H^{\Lambda}(\omega))=\sum_{\substack{j\in \Z\colon \\\{j, j+1\}\subset \Lambda}} \tau_k(h_{j, j+1}(\omega) ) = \sum_{\substack{j\in \Z\colon \\\{j, j+1\}\subset \Lambda}} h_{j+k, j+1+k}(\vartheta^k \omega) ) = \sum_{\substack{j\in \Z\colon\\ \{j, j+1\} \subset \Lambda - k} } h_{j,j+1}(\vartheta^k \omega) = H^{\Lambda -k}(\vartheta^k) 
        \]
        Now, since $\mathcal{A}_{\Lambda}$ is a matrix algebra, the unitary $e^{-itH^{\Lambda}(\omega)}$ is just given by its Taylor series, and we observe that 
        \[
            \tau_k(e^{-itH^{\Lambda}(\omega)}) = \sum_{n=0}^\infty \frac{(-it)^n}{n!}\tau_k(H^{\Lambda}(\omega))^n = \sum_{n=0}^\infty \frac{(-it)^n}{n!} (H^{\Lambda-k}(\vartheta^k \omega))^n = e^{-itH^{\Lambda-k}(\vartheta^k\omega)}\,. 
        \]

        Now, for any $x\in \mathcal{A}^{\loc}_{\Z}$ and any $\Lambda\supset \supp(x)$ we have that 
        \begin{align*}
            \alpha^{\Lambda}_{t;\omega}(x) &= e^{itH^{\Lambda}(\omega)}\qedhere
        \end{align*}
\end{proof}

Furthermore, since $h_{j,j+1}(\omega)$ is nearest neighbor with a constant operator norm for all $\omega$, \cite{NachtergaeleOgataSims} says that the Thermodynamic limit $\alpha^{Z}_{t;\omega}\in \Aut(\mathcal{A}_{Z})$ exists strongly and forms a strongly continuous group of automorphisms. In fact, given any increasing sequence of finite volumes $\Lambda_1 \subset \Lambda_2 \subset \cdots \subset \Lambda_n\subset \cdots $ so that $\bigcup_n \Lambda_n = \Z$, then the following limit exists for all $a\in \mathcal{A}_{\Z}^{\loc}$
\begin{equation}
    \alpha^{\Z}_{t;\omega}(a) = \lim_{n\to \infty} \alpha^{\Lambda_n}_{t;\omega}(a)
\end{equation} but by the co-variance property in equation~\ref{eqn:dynamics_covariance} we obtain the following corollary: 
\begin{cor}\label{cor:thermo_covariance}
    The thermodynamic limit of the local dynamics $\alpha^{\Lambda}_{t;\omega}$ is a strongly continuous semigroup of automorphisms in $t$, and the following co-variance condition holds for all $k\in \Z$ all $t\in \mathbb R$ and all $\omega \in \Omega$:
        \begin{equation}\label{eqn:thermo_covariance}
            \alpha^{\Z}_{t;\omega} = \tau_k\circ \alpha^{\Z}_{t;\vartheta^k \omega} \circ \tau_{-k}
        \end{equation}
    Moreover, the state $\nu_\omega$ obtained by applying equation~(\ref{eqn:delta_state}) to $\vec{\omega}$ is a pure state satisfying \[
        \nu_\omega \circ \alpha^{\Z}_{t;\omega} = \nu_\omega,\, \forall \omega\in \Omega
    \]
\end{cor}
\begin{proof}
    All we need to show is the `moreover' part of the statement. Purity follows immediately from Theorem~\ref{thm:vec_state_pure}. The fact that $\psi_\omega$ is invariant for the dynamics follows by the fact that $\psi_\omega(h_{j,j+1}(\omega)) = 0$ for all $j$, by construction. 
\end{proof}

\begin{cor}\label{cor:spec_const}
    Let $\alpha^{\Z}_{t;\omega}$ be the disordered thermodynamic limit of the local dynamics $\{\alpha^{\Lambda}_{t;\omega}\}$ defined with respect to the IID nearest neighbor Hamiltonian from~(\ref{eqn:Parent_Hamiltonian}). Let $\psi_{\omega}$ be the invariant state gotten by applying equation~\ref{eqn:delta_state} to $\vec{\omega}$ and let also $(\mathcal{H}_\omega, \pi_\omega, \Psi_{\omega})$ be the GNS representation of $\mathcal{A}_{\Z}$ with respect to $\psi_{\vec{\omega}}$. Let also $S_{t;\omega}$ denote the one-parameter group induced on $\mathcal{H}_\omega$ by $\alpha^{\Z}_{t;\omega}$. There exist unitaries $\{U_k:\mathcal{H}_{\vartheta^k \omega} \to \mathcal{H}_{ \omega}\}_{k \in \Z}$ so that the GNS Hamiltonian $H^{GNS}_\omega$ generating $S_{t;\omega}$ is $\vartheta$-covariant. That is, 
    \begin{equation}\label{eqn:covariant_GNS_gen}
        H_\omega^{GNS} = U_k^* H_{\vartheta^k \omega}^{GNS}U_k\,;\, \forall \omega\in \Omega, k\in \Z
    \end{equation} In particular, $\spec(H^{GNS}_{\omega})$ spectrum is constant for almost every $\omega$. 
\end{cor}
\begin{proof}
    It is not difficult to show that the maps defined via 
    \begin{equation}
        U_k \pi_{\vartheta^k \omega}(a)\Psi_{\vartheta^k \omega} \mapsto \pi_\omega(\tau_k(a)) \Psi_{\omega}
    \end{equation} are densely defined linear operators preserving the inner product, whence the $U_k$ extend uniquely to a unitary $\mathcal{H}_{\vartheta^k \omega} \to \mathcal{H}_{\omega}$ for any $\omega$. The relation in~(\ref{eqn:covariant_GNS_gen}) follows from the covariance relation~(\ref{eqn:thermo_covariance}). 

From here, the proof follows essentially the same argument as the proof of \cite[Theorem 1]{KirschMartinelli}, though are in a case with non-constant fibers. The case of non-constant fibers is treated in a much broader context in \cite{LenzPeyerimhoffVesselic}, so we will only sketch the proof. 

    Recall that the heart of \cite[Theorem 1]{KirschMartinelli} is to show that given a random projection $P_\omega$, its trace (which is a measurable function) is $\vartheta$-invariant, then to apply this to the spectral decomposition of a covariant random Hamiltonian. In our case, we can achieve essentially the same thing as follows. 
    \begin{claim}
        Suppose $\omega \mapsto P_\omega\in B(\mathcal{H}_\omega)$ is a function taking values in the projections of the GNS representation of $\A_{\Z}$ so that the mappings $\omega \mapsto \<[a,\omega]| P_\omega|[b,\omega]\>$ are measurable. Suppose that $U^*_k P_\omega U_k = P_{\vartheta \omega}$. Then $\tr[P_\omega]$ is constant in $\omega$. 
    \end{claim}

    First, notice that since $\A_{\Z}$ is an inductive limit (see \cite[Chapter 6]{Murphy}) of tensor powers of $\M_3$, it is norm separable. It follows that $\mathcal{H}_{\omega}$ is separable as a Hilbert space for each $\omega$. Furthermore, the set of equivalence classes $\{[a,\omega] \colon a\in \A_{\Z}\}$ is a dense subspace of $\mathcal{H}_\omega$. Therefore we may find an orthonormal basis $\{[a_n,\omega]: a_n \in \A_{\Z}\} \subset \mathcal{H}_\omega$ for each $\omega$. Notice that for any $[a,\omega]$, we have $U_1^*[a,\omega] = [\tau_1(a), \vartheta \omega]$. Thus the image of an orthonormal basis under $U_1^*$ is necessarily an orthonormal basis again. 

    All this to say that, since the canonical trace is independent of a choice of orthonormal basis (\cite[Theorem 7.11(a)]{Weidmann}), we have that 
    \begin{align*}
        \tr[P_\omega] &= \sum_{j} \<[a_j, \omega]|P_\omega|[a_j,\omega]\>_{\mathcal{H}_{\omega}}= \sum_{j} \<[\tau_1(a_j), \vartheta \omega]|U_1P_\omega U_1^*|[\tau_1(a_j), \vartheta \omega]\>_{\mathcal{H}_{\vartheta  \omega}}\\
        &= \sum_j \<[\tau_1(a_j), \vartheta \omega]|P_{\vartheta \omega}|[\tau_1(a_j), \vartheta \omega]\>_{\mathcal{H}_{\vartheta \omega}}= \tr[P_{\vartheta \omega}]\,.
        \end{align*}

    Now, given $H_\omega$, one considers the spectral projections $\chi_{(\lambda, \mu)}(H_\omega)=:P_\omega$ for $\lambda<\mu$ rational numbers. The definition of these projections satisfies the weak-measurability condition of the claim by Stone's formula \cite[Theorem 7.17]{Weidmann}, and the GNS condition. By the claim, these projections have constant trace and now we can employ the rest of the argument from \cite{KirschMartinelli}.
\end{proof}

To recap, up to this point we have shown that with respect to our nearest neighbor Hamiltonian $h_{j, j+1}(\omega)$, where the parameter values are IID random variables that change spatially in $j$, then $h_{j, j+1}(\omega)$ admits a translation co-variant thermodynamic limit state which is a ground state of a co-variant automorphism group of dynamics on the quasilocal algebra of observables. In this case, the spectrum of the GNS Hamiltonian is constant. In particular, we say that the GNS Hamiltonian has a \emph{spectral gap}, if there is $\delta>0$ so that the interval $(0,\delta)\subset res(H_\omega^{GNS})$ the resolvent set. The \emph{bulk gap} is then the constant 
    \[
        \gamma:= \sup\{\delta >0 \colon (0,\delta)\subset \res(H_\omega^{GNS})\}\,.
    \] since $\spec(H_{\omega}^{GNS})\}$ is almost surely constant. 

We have arrived at the following theorem
\begin{thm}[Bulk Gap Alternative]
    The bulk gap of the IID AKLT model is constant almost surely.
\end{thm}

In fact, the bulk gap closes with probability one as we will show now. We write $S_{x}^z$ the spin-z matrix for a spin-1 particle at site $x\in \mathbb{Z}$. I.e. $$S_x^z = \begin{bmatrix}
    1 & 0 & 0\\ 0& 0 & 0\\ 0 & 0 & -1\\
\end{bmatrix}\in \mathcal{A}_{\{x\}} \text{ for }x\in \Z$$ 

\begin{lem}
    Let $\nu_{\omega}$ be the state on $\mathcal{A}_{\Z}$ generated by $\varrho_{\vec{z}} = \frac{1}{2} \tr$, $e(\vec{z}) = \one_{2\times 2}$ and the transfer operators $\{E_{\vec{z}, a}\}$ as in equation~(\ref{eqn:delta_state}). Let $(\mathcal{H}_{\omega}, \pi_{\omega}, \Psi_{\omega})$ denote the GNS representation of $\mathcal{A}_{\Z}$ with respect to $\nu_{\omega}$. Let $H^{GNS}_{\omega}$ denote the densely defined generator of the one-parameter group $(S_{t;\omega}\colon t\in \mathbb{R})\subset B(\mathcal{H}_\omega)$ induced by $(\alpha_{t;\omega}^{\Z}:t\in \mathbb{R})$ via 
    \[
        S_{t;\omega}\pi_\omega(a) \Psi_{\omega} = \pi_\omega(\alpha^{Z}_{\omega;t}(a)) \Psi_{\omega}\,.    
    \] Lastly, let $P_0$ denote the orthogonal projection onto $\ker(H_{\vec{z}}^{GNS})$.  Then,  $P_0\pi_\omega(S_x^z)\,\Psi_{\vec{z}} = 0$.
\end{lem}
\begin{proof}
    Notice that for any $\delta\in (0, \frac{\pi}{2})\cup(\frac{pi}{2}, \pi)$, the operator  $E_{S_x^z, \delta}(\one_{2\times 2}) =  \cos^2(\delta)\sigma^z$ where $\sigma^z = \begin{bmatrix}
            1 & 0\\ 0 & -1
        \end{bmatrix}$ is the Pauli-z matrix. Examine the inner product
    \begin{align*}
        \< \, \Psi_{\omega}| \pi_{\omega}(S_x^z) \, \Psi_{\omega}\> &= \psi_{\omega}(S_x^z)= \frac{1}{2}\tr[ E_{S_x^z, \omega_x}(\one_{2\times 2})]= \frac{1}{2}\cos^2(\omega_x)\tr[\sigma^z]=0\,.
    \end{align*} This implies that $\pi_{\omega}(S^z_x)\,\Psi_{\omega}$ is orthogonal to the cyclic vector $\Psi_{\omega}$. Since $\psi_\omega$ is \emph{surely} pure by Theorem~\ref{thm:vec_state_pure}, we know that $\ker{H^{GNS}}$ is one-dimensional. Indeed, since $\psi_\omega$ is pure, the GNS representation is \emph{irreducible} in the sense that the commutant $\pi_\omega(\mathcal{A}_{\Z})'=\C\one$ (see \cite[Theorem 5.1.6]{Murphy}). It is not difficult to show that if $\eta \in \ker(H^{GNS})$ where another vector different from $\Xi_\omega$ with $S_{t;\omega}\eta = 0$, then there is a unitary $u \in \pi_\omega(A)'$ relating the vector state $\<\eta| \cdot |\eta\>$ and $\psi_\omega$ so that $u\eta = \Psi_{\omega}$. But the commutant condition implies that $u$ is multiplication by a point on the unit circle, and so it must be that $\eta$ differs from $\Psi_\omega$ only by a phase. Hence $\ker H^{GNS} = \C \Psi_\omega$. Thus the projection condition is satisfied. 
\end{proof}

We have now verified the conditions of \cite[Theorem 2]{NachtergaeleSims} whence we obtain the following Lemma. 
\begin{lem}\label{lem:tee_up_contradiction}
    If $H^{GNS}_{\delta}$ has a spectral gap $\gamma >0$, then for any $\ell \ge 1$, $\lambda>0$ and any $x\in \Z$, we have
    \[
        |\nu_\omega(S_x^z S_{x+\ell}^z))| \le 3e^{-\mu_{\lambda} \ell}\,.
    \] where $\mu = \frac{\gamma \lambda}{4\|h\|_{\lambda} + \gamma}$
\end{lem}

We are now ready to state our second main result
\begin{thm}[Theorem~\ref{thmx:Gapless_Hamiltonian}]\label{thm:IID_AKLT_Gapless}
    Suppose that $\{\Theta_z\}_{z\in \Z}$ is a bi-infinite family of IID random variables on a probability space $(\Omega, \P)$. Assume the following
    \begin{enumerate}[label = \roman*.)]
        \item The family $\Theta_z \sim f(x) \frac{dx}{\pi}$ and $\supp f \subset [0,\frac{\pi}{4}]$. 
        \item For all $\delta>0$ small enough, assume that $p_0(\delta) := \P[\Theta_0 <\delta] >0$ and that $\P[\Theta_0 = 0] = 0$.
    \end{enumerate}
    Let $\nu_\omega = \nu_{(\omega_j)_{j\in \Z}}$ where $\omega_j = \Theta_j(\omega) = \vartheta^j \Theta_0(\omega)$ be the state constructed as in equation~(\ref{eqn:delta_state}) where $\vartheta$ is the ergodic shift. Then the following hold.
        \begin{enumerate}[label = \alph*.)]
            \item The state $\nu_\omega$ is a translation covariant state with small correlations. In particular, the triple $(\frac{1}{2}\tr,E_{a,\omega} ,\one)$ defines a transfer apparatus for $\nu_\omega$ on the trivial bundle $[0, \frac{\pi}{4}] \times \M_2$. 
            \item Furthermore $\nu_\omega$ admits a nearest neighbor parent Hamiltonian $h$ which is translation co-variant with respect to the ergodic shift. Thus Corollary~\ref{cor:spec_const} implies that the GNS Hamiltonian has a spectrum which is constant on a set $\Omega_s$ with $\P(\Omega_s) =1$. 
            \item Let $(\delta_n)_{n=1}^\infty$ be a sequence in $[0, \frac{\pi}{4})$ so that $\delta_n \downarrow 0$ as $n\to \infty$. Then, 
                \begin{equation}
                    \P\left(\forall \ell\in \mathbb N,\, \exists x\in \Z\colon\, |\cos(2\delta_\ell)|^\ell \le |\psi_\omega(S_x^z S_{x+\ell}^z)|\right) =1
                \end{equation}
            \item Therefore, taking $a-c.)$ together implies that the spectral gap of $H^{GNS}$ vanishes on a set with probability one.  

        \item Then, the following limit exists almost surely: 
        \begin{equation}
            \lim_{\ell \to \infty}\log\left(|\nu_\omega(S_x^z\, S_{x+\ell}^z)|^{\tfrac{1}{\ell}}\right) = \E\log(\cos(2\omega)) \le -\frac{\pi \|f\|_\infty}{4}\,\log(2)        \end{equation}
        \end{enumerate} 
\end{thm}
\begin{proof}
    a.) The covariance condition follows by construction of the probability space. Similarly, the fact that the trivial bundle implements $\psi_\omega$ here is by construction.


    b.) is immediate from Corollary~\ref{cor:Parent_Hamiltonian}, and Lemma~\ref{lem:parent_covariance}. 


    c.) First, we note that by construction of the $\nu_{\vec{z}}$ state, one has 
    \begin{align}
        \nonumber |\psi_{\omega}(S_x^z S_{x+\ell}^z)| &= \frac{1}{2}|\tr[E_{S^z_x, \omega_x}\circ E_{\one, \omega_{x+1}}\circ\cdots \circ E_{\one, \omega_{x+\ell -1}}\circ E_{S^z, \omega_{x+\ell}}(\one_{2\times 2})]|\\
        \nonumber &= \frac{1}{2}\cos^2(\omega_{x+\ell})|\tr[E_{S^z_x, \omega_x}\circ E_{\one, \omega_{x+1}}\circ\cdots \circ E_{\one, \omega_{x+\ell -1}}(\sigma^z))]|\\
        \nonumber &=\frac{1}{2}\cos(\omega_{x+\ell})^2\, \prod_{j=1}^{\ell-1} |\sin^2(\omega_{x+j}) - \cos^2(\omega_{x+j})|\, | \tr[E_{S^z_x, \omega_x}(\sigma^z)]|\\
        \label{pf:eqn:product_of_cosines}&=\cos^2(\omega_x)\cos^2(\omega_{x+\ell})\prod_{j=1}^{\ell-1} |\sin^2(\omega_{x+j}) - \cos^2(\omega_{x+j})| 
    \end{align} 

Now, since we assumed $\omega_0 \in [0, \frac{\pi}{4}]$, we know that $1\ge\cos(2\omega_0) \ge 0$ deterministically. Therefore by the power reduction formulas from trigonometry, 
    \begin{equation}\label{pf:eqn:product_of_cosines_lower}
        |\nu_{\omega}(S_x^zS_{x+\ell}^z)| = \left(\frac{1 + \cos(2\omega_x)}{2}\right)\left(\frac{1 + \cos(2\omega_{x+\ell})}{2}\right) \prod_{j=1}^{\ell -1} |\cos(2\omega_{x+j})|\ge \prod_{j=0}^\ell \cos(2\omega_{x+j})
    \end{equation}


    Now, consider the event $E_{x,\ell}(\delta) = [|\cos(2\delta)|^\ell \le |\nu_\omega(S_x^z S_{x+\ell}^z)|]$. Notice $\P E_{x, \ell}(\delta) \ge \P(\Theta_{x}, \Theta_{x+1}, \dots, \Theta_{x+\ell} <\delta) = p_0(\delta)^\ell>0$ for all $x\in \Z$, $\ell \in \mathbb{N}$ and $\delta>0$ sufficiently small by the IID assumption. Since we have 
    \[
        \nu_\omega (S_x^z S_{x+\ell}^z) = \nu_\omega( \tau_x \tau_{-x} S_x^z S_{x+\ell}^z) = \nu_{\vartheta^x \omega}(S_0^z S_\ell^z),
    \] the identity $E_{\ell, x}(\delta) = \vartheta^x E_{0,\ell}(\delta)$ holds. Let 
    \begin{equation}
        A_{\ell}(\delta) = \bigcup_{x\in \Z} E_{\ell,x}(\delta)\,
    \end{equation} which we note is a $\vartheta$ invariant set with $\P(A_{\ell}(\delta))\ge p_0(\delta)^\ell >0$. So $\P A_{\ell}(\delta) = 1$ for all $\ell \ge 0$ and $\delta>0$ by ergodicity. Now, for any sequence $\delta_n \downarrow 0$ we have that 
    \[
        \P \bigcap_{\ell=1}^\infty A_\ell(\delta_\ell) =1
    \] since this is a countable intersection of sets with full probability. 

    d.) Suppose that $H^{GNS}$ has a positive spectral gap on a set with probability one, say $\Omega_G$. Let \[\Omega_s = \bigcap_{\ell}(\Omega_G \cap A_{\ell}(2^{-\ell -1})).\] Then, by part c.), we have that 
        \[
            \P\Omega_s = \P[ \Omega_G \cap \bigcap_{\ell=0}^\infty A_\ell(2^{-\ell-1})] = 1
        \] By Lemma~\ref{lem:tee_up_contradiction} combined with the definition of the $A_\ell$'s we get that for all length scales $\ell$ and almost every $\omega\in \Omega$, there is some $x\in \Z$ depending on $\omega$ and $\ell$ so that 
        \begin{equation}
            |\cos(2^{-{\ell}})|^\ell \le |\nu_\omega(S_{x}^z S_{x+\ell})| \le 3e^{-\mu_{\lambda}\ell}\,.
        \end{equation} Taking $\underset{\ell \to \infty}{\limsup}$ of both sides (noting that the upper and lower bound are deterministic) yields a contradiction. Therefore it must be that $\mu_{\lambda} = 0$ on $\Omega_s$, but this is equivalent to $\gamma = 0$ almost surely, since $\spec(H^{GNS})$ is constant by Corollary~\ref{cor:spec_const}. 

    Part e.) follows by utilizing Birkhoff's ergodic theorem \cite[Theorem 6.2.1]{Durrett}. Explicitly, let $g(x) = \log |\cos(2x)|$ for $x\in [0, \frac{\pi}{4}]$. Under the assumption that $\omega_0 \sim f(x) dx$ where $f$ is a continuous density function, then we note $g\in L^1(\P)$ since $f\in L^1(dx)$. Indeed, 
    \[
        \int_0^{\pi/4} |\log (\cos(2x))| f (x) dx \le \|f\|_{\infty} \int_0^{\pi/4} -\log|\cos(2\pi)| dx = \|\rho\|_{\infty} \frac{\pi}{4} \log(2) < \infty\,.
    \]
    Then, by~(\ref{pf:eqn:product_of_cosines}) and~(\ref{pf:eqn:product_of_cosines}, we obtain the estimate
    \begin{align*}
         \frac{1}{\ell+1}\sum_{j=0}^{\ell}f(\omega_{x+j}) \le \log\left( |\nu_\omega(S_x^z\,S_{x+\ell}^z)|^{\tfrac{1}{\ell}}\right) \le \frac{1}{\ell-1}\sum_{j=1}^{\ell-1} f(\omega_{x+j})\,.
    \end{align*} which holds almost surely. Now, Birkhoff's ergodic theorem implies that the right- and left-hand sides of the above converge almost surely to a constant $\E[f(\omega)]\le - \frac{\|f\|_{\infty}\pi}{4}\log(2)$, as claimed. 
\end{proof}

\begin{rmk}
    We reiterate that the mechanism by which the spectral gap closes is the fact that the probability distribution of $\omega_0$ is allowed to take arbitrarily small values. A reasonable next question to ask is whether or not the spectral gap closes in the case when $\P[\pi/4 >\delta_1 \ge \omega_0 \ge \delta_2>0] = 1$, that is, if $\omega_0$ is valued in $[\delta_2, \delta_1]$ and is not allowed to venture toward degenerate values. It seems likely in this scenario that one could leverage that $gap(E_{\one, \omega})$ can  be explicitly computed in order to show that $gap(H^{GNS}_\omega)$ is open with large probability. However we shall defer a detailed discussion of this idea for later work. 
\end{rmk}

\subsection{Time Reversal Symmetry and an Index Calculation}

Another interesting question raised by our disordered AKLT model is whether or not the disorder affects the values of  topological indices. Many authors have worked on the classification of symmetry protected states via topological indices in recent years (see the sampling of works \cite{Bols_et_al, CarvalhodeRoeckJappens, KapustinSopenkoYang, Ogata_cmp, Ogata_cdm, Ogata_icm,  Sopenko_2d, Tasaki_prs, Tasaki_jmp}). Many (if not all) of the aforementioned works are concerned with unique \emph{gapped} ground states of local Hamiltonians which are protected against the action of some group on a spin system. Due to their explicit nature, Matrix Product State representations have played a crucial role in many of the aforementioned works, and specifically, the AKLT model is known to be protected by several different on-site symmetries. In the following we will show that the matrix product approximation to our disordered AKLT state $\nu_\omega$ is protected against the \emph{Time Reversal} symmetry which can be represented as an action of $\Z_2$ on the spin chain (see \cite{Ogata_z2, Pollman_et_al_z2, Tasaki_book} for more details). Furthermore, we aim to show that $\nu_\omega$ has a nontrivial $\Z_2$-index with high probability. 

To show that our disordered AKLT state is time-reversal invariant, we find it convenient to compute the coefficients explicitly first. 

\begin{lem}\label{lem:coefficient_expansion}
    Let $\nu_{\vec{z}}$ be the state from Notation~\ref{note:pre_disorder_AKLT_state}, where $\vec{z}$ is a bi-infinite sequence in $(0, \frac{\pi}{2})\cup(\frac{\pi}{2}, \pi)$. Let $L\ge 2$, and let Let $\sigma = (\sigma_{-L}, \dots, \sigma_{L+1})$ be a spin-z configuration on the interval $[-L, L+1]$ (i.e. a choice of basis vector at each site).  Let $J_\sigma\subset [-L, L+1]$ denote the set 
    \begin{equation}
        J_\sigma = \{x\in [-L, L+1] \colon \sigma_x \neq 0\}\,.
    \end{equation} Let it be understood that $J_\sigma^c = [-L, L+1] \setminus J$.  Then, the vector approximates $\Gamma^{[-L, L+1]}_\omega(\one)$ have the following expansion:
    \begin{enumerate}
        \item In the case that there are no excitations (i.e. $\sigma = (0, 0, \dots, 0)$, then the associated coefficient is
        \begin{equation}\label{eqn:zero_configuration}
            \tr[X_0(z_{L+1})\cdots X_0(z_{-L})] = 2\, \prod_{x=-L}^{L+1} \sin(z_x)
        \end{equation}
        \item More generally, if there is $k\ge 1$ so that $|J|=2k$ and the signs of $\sigma_x$ alternate as $x\in J$ increases, then
        \begin{equation}\label{eqn:admissible_configuration}
            \tr[X_{\sigma_{L+1}}(z_{L+1}) \cdots X_{\sigma_{-L}} (z_{-L})] =  
                (-1)^{P_\sigma} \prod_{x\in J_\sigma}\sigma_x\cos(z_{x}) \prod_{y\in J_\sigma^c} \sin(z_y), 
        \end{equation} where we have set 
        \begin{equation}
            P_\sigma = \delta(+, \sigma_{x_N})(L+1 - x_N) + \sum_{j=1}^{N-1}\delta_{+,j+1}(x_{j+1} - x_{j}) + \delta_{+,1} (x_1 - (-L))
        \end{equation} where $\delta_{+,j}=\delta(+1, \sigma_{x_j})$ is the Kronecker delta.
        \item Otherwise, the coefficient vanishes. 
    \end{enumerate} 
\end{lem}

\begin{proof}
    First, let us set some notation. We declare $D = E_{22} - E_{11}$ the difference of the two $2\times 2$ matrix units. Now, consider the case of the zero configuration $\zeta = (0, \dots, 0)$. Then each matrix in the trace: $\tr[X_{\zeta_{L+1}}(z_{L+1}) \dots X_{\zeta_{-L}}(z_{-L})]$ is proportional to $D$. Therefore, we may write 
    \[
        \tr[X_{\zeta_{L+1}}(z_{L+1}) \dots X_{\zeta_{-L}}(z_{-L})]  = \tr[X_{0}(z_{L+1}) \dots X_{0}(z_{-L})]= \tr[D^{2L+2}] \prod_{x=-L}^{L+1} \sin(z_x) = 2  \prod_{x=-L}^{L+1} \sin(z_x)
    \]
    Notice that for the sites $y\in J_\sigma^c$, the associated matrix $X_{\sigma_y}$ is proportional to $D:= E_{22} - E_{11}$, and otherwise the matrices $X_{\sigma_{x_j}}$ are proportional to one of the matrix units $E_{21}$ or $E_{12}$.  Write $J = \{x_1<x_2 < \cdots < x_N\}$ in increasing order.  One can factor out the constants to obtain 
        \[
         \tr[X_{\sigma_{L+1}}(z_{L+1}) \cdots X_{\sigma_{-L}} (z_{-L})] = \left(\prod_{y\in J^c} \sin(z_y)\right) \left( \prod_{x\in J} \sigma_x \cos(z_x)\right)\tr Y_J\] where we we have set 
         \begin{equation}\label{eqn:calc_coeff_Y_J}
         Y_J = D^{L+1 - x_N}E_{\sigma_{x_n}} D^{x_{N}-1 - (x_{N-1}+1)}E_{\sigma_{x_{N-1}}}\cdots D^{x_2 - x_1} E_{\sigma_{x_1}}D^{x_1 - (-L)}\,.
         \end{equation}

    Now, notice that for any power $p$, one has 
    \[
        \begin{split}
            D^p E_{12} &= (-1)^p E_{12}\\
            D^p E_{21}& = E_{21}
        \end{split}
    \] Therefore, it is immediate that $Y_J$ vanishes if there is a pair of subsequent equal indices $\sigma_{x_j} = \sigma_{x_{j+1}}$, since this would imply an $E_{12}^2$ or $E_{21}^2$ appears in $Y_J$. 

    Continuing in our reduction, we group the matrices in equation ~(\ref{eqn:calc_coeff_Y_J}) from left to right to see that
    \begin{equation}\label{eqn:Y_Jeval}
        Y_J = (-1)^{\delta(+, \sigma_{x_N})(L+1 - x_N) + \sum_{j=1}^{N-1}\delta(+1, \sigma_{x_{j+1}})(x_{j+1} - x_{j})} \tr[E D^{x_1 - L}]
    \end{equation} where $E$ is some alternating product of $E_{12}$ and $E_{21}$. Recalling that $E_{21} E_{12} = E_{22}$ and $E_{12} E_{21} = E_{11}$ and that $E_{11}E_{22} = E_{22} E_{11} = 0$, we see that $|J|$ cannot be odd, otherwise, $E$ is the zero matrix, whence the coefficient vanishes. 

    To recapitulate, we have shown that $\tr[X_{i_{L+1}}(\omega_{L+1}) \cdots X_{i_{-L}}(\omega_{-L})]$ equals zero unless $|J|=2k$ for some $0\le k \le L+1$, and the $\sigma$ must be alternating. 

    This means there are only two options for the value of $\tr[ED^{x_1 - (-L)}]$. Either 
    \[ \tr[E_\sigma D^{x_1-(-L)}]= \left\{ 
        \begin{array}{cc}
           \tr[E_{11}D^{x_1-(-L)}] = (-1)^{x_1-(-L)} & \text{ if $x_1 = +1$} \\
            \tr[E_{22}D^{x_1-(-L)}] = 1 & \text{ if $x_1 = -1$}\\
        \end{array}\right.\,,
    \] which completes the proof.
\end{proof}

\begin{cor}\label{cor:TR_symmetry}
    Let $\nu_\omega$ be the disordered AKLT state we construct above. Then $\nu_\omega$ is protected by time-reversal symmetry. 
\end{cor}
\begin{proof}
    It is sufficient to show that the matrix product state with vectors $\Gamma^{[-l, L+1]}_\omega(\one)$ is protected by time-reversal symmetry for all $L$. Recall that the weak* limit $\lim_{L \to \infty} \< \Gamma^{[-L, L+1]}_\omega(\one)| \cdot | \Gamma^{[-L, L+1]}_\omega(\one)\> =\nu_\omega$ almost surely by Theorem~\ref{lem:gamma_formulas} part c.). Therefore, it is sufficient to show that the coefficients of the MPS expansion are robust under the action of the symmetry.

    Recall that the matrices which generate $\nu_\omega$ at site $j$ are given by 
    \[
      X_{-1}(\omega_j) := \begin{bmatrix}
        0 & 0\\ -\cos(\omega_j) & 0\\
    \end{bmatrix}\,\,\,\,\,\,\,\,\,\,  X_{0}(\omega_j):= \begin{bmatrix}
        -\sin(\omega_j) & 0 \\
        0 & \sin(\omega_j)\\
    \end{bmatrix}\,\,\,\,\,\,\,\,\,\,   X_{1}(\omega_j) := \begin{bmatrix}
        0 & \cos(\omega_j)\\
        0 & 0\\
    \end{bmatrix} 
    \] Let $F:\M_2 \to \M_2$ be the quantum channel given by $F(x) = Z^*xZ$ where the unitary $Z= \begin{bmatrix}
        0 & 1\\ -1 & 0\\
    \end{bmatrix}.$ One readily checks that 
    \[
        \left\{ \begin{array}{c}
        F (X_{\pm 1}(\omega)) = - X_{\mp 1}(\omega)\\
        F(X_0(\omega)) =  X_0(\omega)
        \end{array} \right.
    \] for all values of $\omega$. 

    Lemma~\ref{lem:coefficient_expansion} shows that the nonzero coefficients of $\Gamma^{[-L, L+1]}_\omega(\one) \in \mathcal{H}^{[-L, L+1]}$ are functions of spin configurations $\sigma$ which have alternating sign and obey $\sum|\sigma_j| = 2k$ for some $0\le k \le L+1$. For such a $\sigma$, one has
    \begin{align*}
        \tr\left[X_{\sigma_{L+1}}(\omega_{L+1}) \cdots X_{\sigma_{-L}}(\omega_{-L})\right] &= \tr\left[Z^*ZX_{\sigma_{L+1}}(\omega_{L+1})\cdot Z^*Z X_{\sigma_{L}}(\omega_{L}) \cdots Z^*ZX_{\sigma_{-L}}(\omega_{-L})\right]\\
        &= \tr[F(X_{\sigma_{L+1}}(\omega_{L+1})) \cdots F(X_{\sigma_{-L}}(\omega_{-L})] \\
        &= (-1)^{|J_\sigma|} \tr[X_{-\sigma_{L+1}}(\omega_{L+1}) \cdots X_{-\sigma_{-L}}(\omega_{-L})]\\
        &= \tr[X_{-\sigma_{{L+1}}}(\omega_{L+1}) \dots X_{-\sigma_{{-L}}}(\omega_{-L})]
    \end{align*} Since $J_\sigma$ is the set of points in $[-L, L+1]$ where there is a $+$ or a $-$ spin, Lemma~\ref{lem:coefficient_expansion} says $|J_\sigma| = 2k$. 

Under the action of the time-reversal symmetry, any vector in the canonical basis expansion of $\Gamma^{[-L, L+1]}_\omega(\one)$ is mapped to 
    \[
        \tr\left[X_{i_{L+1}}(\omega_{L+1}) \cdots X_{i_{-L}}(\omega_{-L})\right] |i_{-L} \dots i_{L+1}\> \longmapsto \tr\left[X_{-i_{L+1}}(\omega_{L+1}) \cdots X_{-i_{-L}}(\omega_{-L})\right]|(-i_{-L}), \dots ,(-i_{L+1})\>
    \] but as we demonstrated above the coefficients are equal, hence either both or neither vector appears in the sum. Thus $\Gamma^{[-L, L+1]}_\omega(\one)$ is invariant under time-reversal symmetry for every nondegenerate bi-infinite sequence of values $(\omega_j)_{j\in \Z}$ in $(0, \pi/2) \cup (\pi/2, \pi)$. 
\end{proof}

