Recent works of Ogata \cite{Ogata_z2} generalized and extended the works of Pollmann et al. \cite{Pollman_et_al_z2, Pollmann_et_al_entanglement} and Tasaki \cite{Tasaki_prs, Tasaki_book} showing that for time-reversal protected pure states on the spin chain, there is a $\Z_2$-topological index. 

A key step in Ogata's method is the fact that injective matrix product states have a unique MPS representations (up to unitary conjugation and a phase)\cite{FannesNachtergaeleWerner_pure, Perez-Garcia_et_al}, and that furthermore, they obey Matsui's \emph{split property} \cite{Matsui_split, Matsui_entropy}.  Ogata shows in \cite[Theorem 6.1]{Ogata_cmp} that her index agrees with the index of \cite{Pollman_et_al_z2} in the case of a matrix product state. While it is generally known that string order parameters correspond to local symmetries of MPS \cite{PG_StringOrder} (which again utilizes the uniqueness of injective MPS representations) we do not currently know if such a uniqueness theorem exists for \emph{ergodically disordered} injective matrix product states. We are also not aware of any literature that shows that the index calculation in \cite{Tasaki_prs} is the same as the index from \cite{Ogata_z2} (though in the aforementioned works, both Tasaki and Ogata conclude that the AKLT state has index $-1$). For these reasons, we seek to explicitly compute the $\Z_2$-index of $\nu_\omega$ using the methods presented in \cite{Tasaki_prs}, without appealing to the methods of \cite{Ogata_z2,Pollman_et_al_z2,Pollmann_et_al_entanglement}, and \cite[Section 8.3.4]{Tasaki_book}.

We shall take a few lines to recall Tasaki's method from \cite{Tasaki_prs}. Recall that the \emph{Affleck-Lieb twist operator} is a pure tensor of local unitary operators in the spin chain defined as follows: for $L>1$ an integer, set 
\begin{equation}
    T_L := \bigotimes_{j\in [-L, L+1]} \exp\left\{-2\pi i\, \frac{j+L}{2L+1}\, S^{z}_j\right\}
\end{equation} with $S^z_j$ the $j$-site spin-z matrix for a spin 1. Tasaki then goes on to show the following
\begin{thm}[Theorem 1 \cite{Tasaki_prs}]
    Suppose $\varphi$ is the unique \emph{gapped} ground state of a local Hamiltonian on the spin-1 chain. Then, the value $\varphi(T_\ell)$ is real and has constant sign for $\ell$ sufficiently large. In particular, the quantity $\mathscr{O}(\varphi):= \lim_{\ell \to \infty} \frac{\varphi(T_\ell)}{|\varphi(T_\ell)|}\in \{\pm 1\}\,.$
\end{thm}

Even though our disordered state $\psi_\omega$ gapless, we show in Theorem~\ref{thm:Z2-index} below, that the $\Z_2$-index $\mathscr{O}(\nu_\omega) = -1$ in probability. We take a few lines to outline the steps we take in this direction. 
\begin{enumerate}
    \item First, we note that due to Lemmas~\ref{lem:gamma_formulas} and~\ref{lem:translation_operator_strictly_positive}, that we have the estimate 
    \[
        |\|\Gamma^{[m,n]}_\omega(\one)\|^2 - 1|=|\<\Gamma^{[m,n]}_\omega(\one)|\Gamma^{[m,n]}_\omega(\one)\> - \tfrac{1}{2} \nu_\omega(\one) \<\one, \one\>_{\HS}| \le \|\Phi_{m,n} - T\| \to 0
    \]
    Thus, the quantity $\|\Gamma^{[-L, L+1]}_\omega(\one)\|^2\to 1$ almost surely, and furthermore, $\nu_\omega(T_L)$ is almost surely approximated by $\<\Gamma_\omega^{[-L, L+1]}(\one)| T_L |\Gamma_\omega(\one)\>$. Therefore, it is sufficient to consider the quantity $\<\Gamma^{[-L, L+1]}_\omega(\one) | T_L + \one| \Gamma^{[-L, L+1]}_\omega(\one)\>\ge 0$  and show this goes to zero for large $L$. 
    \item Due to the Lemma~\ref{lem:pre_simulation} below, one can realize the expected value $\E \<\Gamma^{[-L, L+1]}_\omega(\one)| T_L+\one | \Gamma^{[L, L+1]}_{\omega}(\one)\>$ as the expected value of a function $f(\lambda_1, \dots, \lambda_L)$, of a classical stochastic process of IID random variables $(\lambda_j)_{j=1}^\infty$ whose distribution is chosen to ``simulate" the coefficients of $\E\Gamma^{[-L,L+1]}$.
    \item Finally, we show that the expected value of $f(\lambda_1, \dots, \lambda_L)$ (with respect to its native probability measure) converges to $0$ with large probability. 
\end{enumerate}

\begin{lem}\label{lem:pre_simulation}
    Let $(\omega_j)_{j\in \Z}$ be a bi-infinite sequence of IID random variables taking values in $[0, \frac{\pi}{4}]$. Assume that $\P[\delta< \omega_0] >0$ for all $\delta>0$ in range, and that $\P$ is non-atomic. Let also $\nu_\omega$ be the disordered AKLT state from Theorem~\ref{thm:IID_AKLT_Gapless}. Let $L>0$ and denote by $\sigma = (\sigma_x)_{x\in [-L, L+1]} \in \{-1, 0, +1\}^{2L+2}$ an arbitrary spin configuration. Let $k$ be an integer and let $A_{2k}$ be the set of those spin configurations with alternating signs and an even number of excitations. Then the following hold. 
    \begin{enumerate}[label = \roman*.)]
        \item Let $c^2 := \E \cos^2(\omega_0)$ and $s^2:= \E \sin^2(\omega_0)$. Then, $\frac{1}{2}<c^2<1$ and $0<s^2<\frac{1}{2}$ and furthermore $s^2+c^2 = 1$. 
        \item Let $\sigma\in A_{2k}$, and let $J_\sigma = \{x\in [-L, L+1] \colon \sigma_x \neq 0\}$. We shall write $J_\sigma = \{x_1 < x_2 < \cdots< x_{2k}\}$ in increasing order with the understanding that the $x_m$ depend on $\sigma$. Then, Tasaki's formula holds:
        \begin{equation*}
            \sum_{x=-L}^{L+1} \frac{x+L}{2L+1} \sigma_x = - \sigma_{x_1}\sum_{m=1}^{k} \frac{x_{2m}- x_{2m-1}}{2L+1}
        \end{equation*}
        \item Let $L>0$ and set $\Gamma_L = \Gamma^{[-L, L+1]}_\omega(\one)$ for convenience. Then, 
        \begin{equation}\label{eqn:pre_simulation}
            \E \<\Gamma_L| T_L |\Gamma_L\> = 2\sum_{k=0}^{L+1} (s^2)^{2L+2 - 2k}(c^2)^{2k}\sum_{\sigma\in A_{2k}}  \cos\left(2\pi \sum_{m=1}^{k} \frac{x_{2m}(\sigma)-x_{2m-1}(\sigma)}{2L+1} \right)
        \end{equation}
    \end{enumerate}
\end{lem}
\begin{proof}
    The proofs of parts i.) and ii.) are straightforward. To see part iii.) use equation~(\ref{eqn:admissible_configuration}) to compute directly the following:
    \[
        \<\Gamma_L|T_L|\Gamma_L\> = \sum_{\substack{\sigma:\\ \sum |\sigma_x| = 2k\\ k=0, \dots, L+1}} \prod_{x\in J_\sigma} \cos^2(\omega_x) \prod_{y\in J^c_\sigma} \sin^2(\omega_y)\, \exp\left\{-2\pi i \sum_{x=-L}^{L+1} \frac{\sigma_x(x+L)}{2L+1}\right\} 
    \] But notice that the summand associated to a given configuration $\sigma$ has a coefficient equal to the complex conjugate of the summand associated to its time-reversal, $-\sigma$. Thus, 
    \[
        \<\Gamma_L|T_L|\Gamma_L\> = 2\sum_{\substack{\sigma \in A_k}} \prod_{x\in J_\sigma} \cos^2(\omega_x) \prod_{y\in J^c_\sigma} \sin^2(\omega_y)\, \cos\left(-2\pi \sum_{x=-L}^{L+1} \frac{\sigma_x(x+L)}{2L+1}\right)\,.
    \] Taking expectations and using Tasaki's formula, and the fact that cosine is even yields equation~(\ref{eqn:pre_simulation}).
\end{proof}

We will now construct a classical stochastic process that models the coefficients of $\E\<\Gamma_L|T_L|\Gamma_L\>$. The idea is to treat the spaces between a pair of excitations in some spin configuration $\sigma\in A_{2k}$ as a random variable that occurs with a specific weight. 

\begin{note}\label{note:filling_process}
    Let $\lambda_1, \lambda_2, \dots$ be a sequence of $\N$-valued IID random variables with distribution 
        \begin{equation}
            \calp[\lambda = n] = c^2 (s^2)^{n-1}\quad n=1,2,\dots
        \end{equation} where $c^2$ and $s^2$ are as in Lemma~\ref{lem:pre_simulation} above. One easily checks $P$ is a probability distribution. We let $\cale_{\calp}$ denote expectation with respect to $\calp$, and notice $\cale_{\calp}\,  \lambda = (c^2)^{-1}$. It is a standard fact that one can find a measure $\calq$ for the process $(\lambda_n)_{n=1}^\infty$ whose finite dimensional distributions are given by
        \begin{equation}
            \calq[n_1, n_2, \dots, n_k] = \calp[\lambda_1 = n_1, \lambda_2 = n_2, \dots, \lambda_k = n_k] = (c^2)^{k}(s^2)^{(\sum_1^k n_j)-k}\,.
        \end{equation} Denote by $\cale_{\calq}$ the expectation with respect to $\calq$. 
\end{note}

We recall the following properties of geometric random variables which are more or less standard. 
\begin{lem}\label{lem:LDB/MGF}
    Let $\lambda$ be a geometrically distributed random variable with success parameter $r\in (0,1)$. That is,
    \[
        P[\lambda = n] = r (1-r)^{n-1}, \forall n\ge1\,.
    \] Then, 
    \begin{enumerate}
        \item The mean $\mu := E\lambda = \frac{1}{r}$,
        \item The moment generating function $m(t):= E[e^{t\lambda}]$ exists for all $t< - \log(1-r)$, which implies that $\lambda$ has finite moments. 
        \item (\cite[Remark 2.2.3(c) p.27]{DemboZeitouni}) If $\lambda_1, \lambda_2, \dots,$ are IID copies of $\lambda$ then for all $x>0$, we have 
        \begin{equation}\label{eqn:Cramer's_theorem}
            P[|\sum_{j=1}^n \lambda_j - n\mu|\ge nx] \le 2 e^{-n\min\{  \Lambda^*(\mu+x), \Lambda^*(-\mu -x)\}}
        \end{equation} where $\Lambda^*(\mu+x)$ is the function
        \[
            \Lambda^*(x+\mu) =\sup_{0\le t< - \log(1-r)}\{t(x+\mu) - \log\left(m(t)\right)\}
        \] In particular, the supremum is achieved at 
        \[
            t_* = \log (1 - (x+\mu)^{-1}) - \log(1-r)\,.
        \]
        \item The optimal both $\Lambda^*(\mu)$ and $(\Lambda^*)'(\mu) = 0$. Thus by Taylor's theorem, $\Lambda^*(\mu + \delta) = \delta^2 + o(\delta^2)$ as $\delta \downarrow 0$. In particular, this means that the exponential estimate above, we can replace $\min\{\Lambda^*(\mu + \delta), \Lambda^*(-\mu - \delta)\}$ with $\delta^2$ after some corrective constant depending on $\delta$. 
    \end{enumerate}
\end{lem} The proof of the above amounts to a straightforward exercise in probability theory. 

\begin{lem}\label{lem:simulation}
    Let $\vec{\lambda} = (\lambda)_{n=1}^\infty$ denote the stochastic process defined above. We may rewrite
    \[
        \E \<\Gamma_L|T_L +\one|\Gamma_L\> = 4\sum_{k=0}^{L+1}\cale_{\calq}[1_{\sum_1^{2k-1} \lambda_j \le 2L+1} f_k(\vec{\lambda})] + 
    \] where 
    \begin{equation}\label{eqn:simulation}
        f_k(\vec\lambda) := \left(2L+2-\sum_{m=1}^{2k-1} \lambda_m\right)(s^2)^{2L+2 - \sum_{m=1}^{2k-1}\lambda_m} \left[\cos\left(\frac{2\pi}{2L+1} \sum_{m=1}^{k} \lambda_{2m-1}\right) +1\right] \quad \forall k\ge 1
    \end{equation} and where we set $f_{0,L} = (s^2)^{2L+2}$ in the case of zero excitations. 
\end{lem}
\begin{proof}
    To begin, let $k\in [1, L+1]$, and consider an alternating spin configuration $\sigma \in A_{2k}$ with $2k$-many nonzero sites. Write $J_\sigma = \{x_1 < x_2 < \dots <x_{2k}\}$ and let $n_j = x_{j+1} - x_j$ for $j=1, 2, \dots, 2k-1$. In this way, we can re-write each $x_j = x_1 + n_1 +n_2 +\dots +n_{j-1}$ (each quantity depends on $\sigma$) for all $j=1,2,\dots, 2k$. Furthermore, we may employ Tasaki's formula for this specific $\sigma$ to the cosine term to obtain:
    \[
        \cos\left( 2\pi \sum_{m=1}^k \frac{x_{2m}-x_{2m-1}}{2L+1}\right) = \cos\left(2\pi \sum_{m=1}^{k} \frac{n_{2m-1}}{2L+1} \right)\,.
    \] This suggests we re-write our sum from the RHS of equation~(\ref{eqn:pre_simulation}) by specifying the lengths between excitations, and the starting point for the configuration. This yields the following:
    \begin{equation}
        \begin{split}
            \sum_{\sigma\in A_{2k}}  \cos\left(2\pi \sum_{m=1}^{k} \frac{x_{2m}-x_{2m-1}}{2L+1} \right) &= \sum_{n_1, n_2, \dots, n_{2k}\ge0} 1_{\sum n_j \le 2L+1} \cos\left(2\pi  \sum_{m=1}^{k} \frac{n_{2m-1}}{2L+1}\right) \times \cdots \\
            &\quad \cdots \times\sum_{\substack{y\in \Z \colon \\-L\le y \le L+1 - \sum n_j}} \sum_{\sigma\in A_{2k}} 1_{ x_j(\sigma) = y+ \sum_1^{j-1}n_m,\, \forall j}(\sigma)
        \end{split}
    \end{equation} The two innermost sums in the above expression specify the locations of the excitations in $\sigma$, but not their signs. However, we know the signs are alternating since $\sigma \in A_{2k}$. Therefore, we observe that 
    \[
        \sum_{\substack{y\in \Z \colon \\-L\le y \le L+1 - \sum n_j}} \sum_{\sigma\in A_{2k}} 1_{ x_j(\sigma) = y+ \sum_1^{j-1}n_m,\, \forall j}(\sigma) = 2|[-L, L+1-\sum_{m=1}^{2k-1}n_m]\cap \Z| = 2(2L+2 - \sum n_j)\,.
    \] 

    Now, define the family of functions $f_{k,L} : \N^{2k-1} \to \mathbb{R}$ via 
    \[
        \begin{split}
            f_{k,L}(n_1, \dots, n_{2k-1}) &= \chi(n_1, \dots, n_{2k-1}) \cdot (s^2)^{2L+2 - \sum n_m} \cdot \left(2L+2 - \sum_{m=1}^{2k-1}n_m\right)\cdot \left[ \cos\left( 2\pi \sum_{m=1}^{k} \frac{n_{2m-1}}{2L+1}\right) +1\right]
        \end{split}
    \] where we put $\chi_L = 1_{\{\sum n_m \le 2L+1\}}(n_1, \dots, n_m)$ the indicator function. 

    Taking this all together, we apply Lemmas~\ref{lem:coefficient_expansion}, and~\ref{lem:pre_simulation}, the following holds:  
    \begin{align*}
        \E\<\Gamma_L |T_L+\one|\Gamma_L\> &= 4\sum_{k=1}^{L+1} (s^2)^{2L+2 -2k} (c^2)^{2k} \sum_{\substack{n_1, \dots,n_{2k-1}\colon\\ \sum n_j \le 2L+1}} (2L+2 - \sum_{m=1}^{2k-1}n_m) \left(\cos\left( 2\pi \sum_{m=1}^{k} \frac{n_{2m-1}}{2L+1}\right)+1\right) + \cdots\\
        &\cdots + 4(s^2)^{2L+2}\\
        &= 4\sum_{k=1}^{L+1}  \sum_{\substack{n_1, \dots,n_{2k-1}\colon\\ \sum n_j \le 2L+1}}  \calq[n_1, n_2, \dots, n_{2k-1}]f_{k,L}(n_1, \dots, n_{2k-1}) + 4(s^2)^{2L+2}\\
        &= 4\sum_{k=0}^{L+1} \cale_{\calq}[f_{k,L}]
     \end{align*} where we have used the definition of the probability measure $\calq$ to obtain the last equality. 
\end{proof}

We aim to show that for large values of $L$, the value of $\E[ \< \Gamma_L|T_L +\one |\Gamma_L\>]$ is vanishingly small. To do so, we isolate six different regimes depending on $k$, $L$, and auxiliary parameters which will control how close $\sum \lambda_j$ is to its mean. We take a few lines to describe the heuristic reasoning behind our decomposition. 

Using Lemma~\ref{lem:simulation}, we know that for various numbers of excitations, we have a sum over the random lengths $\lambda_1, \dots, \lambda_{2k-1}$ between up/down pairs. Using the Law of Large numbers, we know that for large enough $k$, the empirical  sum will be close to the mean $\mu$. Thus, the leading coefficient of $f_{k,L}$ is can be manipulated as follows
\[
    2L+2 - \sum_{m=1}^{2k-1}\lambda_j = 2L+2 - (2k-1)\left[\sum_{m=1}^{2k-1}\lambda_j - \mu \right] - \mu(2k-1) \approx 2L+2 - \mu(2k-1).
\] we see that in order for this coefficient to increase in $L$ (which would force exponential decay of the integrand $f_{k,L}$ due to the $(s^2)$ term), that we should require $L>>\mu k$. Conversely, if $k > \mu^{-1} L$, then the only part of the integrand which \emph{could} decay is the cosine term. On the other hand, if $\sum \lambda_j$ is far from its mean, one expects to be able to use the large deviations principle to estimate the probability of these events. This will only get us exponential decay in $k$. However, these large deviation bounds fail for small $k<< \mu^{-1} L$. In this case, we invent a procedure that compares $k$ to a fractional power of $L$, to obtain stretched-exponential upper bounds. 

Let us now begin the rigorous proof. First, set the notation

\begin{note}
    Let $\xi >0$ be a real number and let $1\le k \le L+1$. The event when the empirical average $(2k-1)^{-1}\sum \lambda _m$ is within $\xi$ of the mean $\mu := \cale \lambda$ is written
    \begin{equation}
        M_{k,\xi}:= \left\{ \left|\frac{1}{2k-1}\sum_{m=1}^{2k-1}\lambda_m - \mu \right|< \xi  \right\}\,.
    \end{equation}
\end{note}

\begin{lem}\label{lem:small_k_close}
    Let $L>0$ and let $\epsilon>0$. For any $\delta \in (0, \mu-\epsilon)$ then, there is a constant $C_1>0$ depending on $\mu$ and $\epsilon$ only so that 
    \begin{equation}
        \sum_{k=0}^{(\mu+\epsilon)^{-1} L } \cale_\calq[|f_{k,L}|, M_{k,\delta}] \le C_1 (L+1)^2 (s^2)^{2(1- \delta(\mu+\epsilon)^{-1})L}
    \end{equation}
\end{lem}
\begin{proof}
    For a single $k$ in range, one has the bound
    \[
        -\delta(2k-1) \le \sum \lambda_m -\mu(2k-1)\le \delta(2k-1) 
    \] whence 
    \[
        2L+2 - \sum \lambda_m \ge 2L+2 -\delta(2k-1) \ge 2(1- \frac{\delta}{\mu+\epsilon})L +2-\mu - \epsilon >0\,.
    \] Notice that our assumption on $\delta$ ensures that $\delta(\mu+\epsilon)^{-1} <1$ Therefore, we may naively bound the integrand as follows: 
    \[
        f_{k,L}(\lambda) \le 2(L+1) (s^2)^{2(1- \delta(\mu+\epsilon)^{-1})L} (s^2)^{2-\mu - \epsilon}
    \]
     Whence, 
    \[
        \sum_{k=1}^{(\mu+\epsilon)^{-1}L} \cale_\calq [|f_{k,L}|, M_{k,\delta}] \le \frac{4(s^2)^{2-\mu - \epsilon}}{\mu+\epsilon} (L+1)^2s^{2(1-\delta(\mu+\epsilon)^{-1})L})\to 0 \text{ as }L\to \infty\,.
    \] 
\end{proof}
Let us turn to the complimentary case when the small number of excitations are far from the average distance apart.  Note that from now on, we will often implicitly use the indicator function $\one_{\sum \lambda \le 2L+1}$ to ensure that $(s^2)^{2L+2 - \sum \lambda_m} \le 1$. 

\begin{lem}\label{lem:small_k_far}
    Let $\epsilon >0$ and $L>0$, and pick $0<\delta <\mu-\epsilon$ as in Lemma~\ref{lem:small_k_close}, above. Then there is a constant $C_2>0$ depending on $\mu, \epsilon, s^2, c^2$ so that for any $p\in (0,1)$, we have
    \begin{equation}
        \sum_{k=0}^{(\mu+\epsilon)^{-1}L} \cale_\calq[f_{k,L}, M_{k,\delta}^c] \le C_2 L(L+1) \left[ e^{-\delta L^p} + e^{- (L^p / \delta)} + (s^2)^{2L - (1+\delta^{-1}\mu)L^p}\right]\,.
    \end{equation} Furthermore, if $p<\frac{2\delta}{\delta+\mu}$, then the RHS decays to zero as $L\to \infty$.
\end{lem}
\begin{proof}
Let $p\in (0,1)$ to be chosen later and consider $L^p$. For any given value of $\sum \lambda_j$, there are three possibilities for how large $L^p$ is in relation to the inequality $|\sum \lambda_j - \mu(2k-1)|\ge \delta(2k-1)$. Either $L^p$ is smaller than both, $L^p$ is in the middle, or $L^p$ is bigger than both. This suggests the following decomposition of $M_{k,\delta}^c$: 
\begin{equation}
\begin{split}
    M_{k,\delta}^c = \left[L^p < \delta(2k-1) \le |\sum \lambda - \mu(2k-1)|\right] &\sqcup \left[ \delta(2k-1)\le L^p \le |\sum \lambda - \mu(2k-1)|\right] \\
    &\sqcup \left[\delta(2k-1) \le |\sum \lambda - \mu(2k-1)|\le L^p\right]\\
    =: A_k \sqcup B_k \sqcup C_k
\end{split}
\end{equation}

In the first case, applying inequality~(\ref{eqn:Cramer's_theorem}) leads us to the bound 
\[\calq[A_k]\le 2\exp\{ - \delta^2 (2k-1)\}\le 2 \exp\{ - \delta L^p\] since here, we have $2k-1 > \delta^{-1} L^p$. Similarly, 
\[
    \calq[B_k] \le 2\exp\left\{ - (2k-1) \frac{L^{2p}}{\delta^2 (2k-1)^2} \right\}\le 2 \exp\{ - \delta^{-1} L^p\}
\] since $\delta(2k-1) \le L^p$ on this event. 

In the third case, we argue similarly to Lemma~\ref{lem:small_k_close} above: unwind the absolute value to see that we have the inequality 
\[
    \sum \lambda_j \le L^p + \mu(2k-1)
\] in particular, this yields a lower bound for the exponent on $s^2$ as 
\begin{equation}\label{pf:eventC_exponent}
    2L + 2 - \sum\lambda _j \ge 2L +2 - L^p - \mu(2k-1) \ge 2L+2 - (1 + \frac{\mu}{\delta})L^p 
\end{equation} where we have used the fact that on $C_k$, we also have $\delta(2k-1) <L^p$. 

Turning to the sum of the integrands, we get 
\begin{align*}
    \nonumber \sum_{k=1}^{(\mu+\epsilon)^{-1} L} \cale_\calq[f_{k,L}, M_{k, \delta}^c] &\le \frac{2}{\mu+ \epsilon}\, L(L+1) \left( 2e^{-\delta L^p} + 2 e^{-(L/\delta)} + (s^2)^{2-\mu}(s^2)^{2L - (1+\delta^{-1}\mu)L^p} \right)\\
    &\le \frac{4}{\mu-\epsilon} L(L+1) \left( e^{-\delta L^p} + 2 e^{-(L/\delta)} + (s^2)^{2L - (1+\delta^{-1}\mu)L^p} \right)
\end{align*}

 We note that a little calculus shows that taking $p<\frac{2\delta}{\delta+\mu}$ is sufficient to guarantee that the exponent $2L - (1+\delta^{-1}\mu)L^p$ is increasing in $L$. 
\end{proof}

Based on the heuristic reasoning above, we expect that the ``middle regime" where  $(\mu+\epsilon)^{-1}L \le k \le (\mu-\epsilon)^{-1} L$, that convergence to zero will be imparted by the cosine terms. Therefore we need slightly tighter control of the sum than we did before, so we introduce the following event. 
\begin{note}
Define the family of events 
    \begin{equation}\label{eqn:m_tilde}
        \tilde M_{k, \epsilon} = \left[\left| \frac{1}{k}\sum_{m=1}^{k} \lambda_{2m-1} - \mu\right|< \frac{\epsilon}{2} \right] \cap \left[\left| \frac{1}{k-1}\sum_{m=1}^{k-1} \lambda_{2m} - \mu\right|< \frac{\epsilon}{2} \right]\,,
    \end{equation} which is the event that the sums of the even intervals and odd intervals are close to their means. 
\end{note} Notice that $\tilde M_{k,\epsilon} \subset M_{k, \epsilon}$. Indeed, by the triangle inequality, 
    \[
        |\sum_{m=1}^{2k-1} \lambda_m - \mu(2k-1)| = |\sum_{m = 1}^k \lambda_{2m-1} - \mu \,k| + |\sum_{m=1}^{k-1} \lambda_{2m} - \mu (k-1)k| \le \epsilon(2k-1),
    \] however the reverse inclusion need not hold. 


\begin{lem}\label{lem:middle_k_close}
    Let $L,\epsilon >0$. Fix any $\eta>\frac{1}{2} +(\mu-\epsilon)^{-1}$ consider the regime where $(\mu+\epsilon)^{-1}L \le k \le (\mu-\epsilon)^{-1}L + \eta$ on the events $\tilde M_{k, \epsilon}$ defined as in~(\ref{eqn:m_tilde}). For any $\epsilon< \mu/7$, and any $L \ge \frac{4\eta(2\mu+\epsilon)-1}{2}$, there is a function $C_3(L)$ for which $\limsup_{L\to \infty} C_3 \le1$, so that  
    \begin{equation}
        \sum_{k\ge \frac{L}{\mu+\epsilon}}^{\frac{L}{\mu-\epsilon} +\eta} \mathcal{E}_Q[f_{k,L}, \tilde M_{k,\epsilon}] \le C_3 \left(\cos\left( \pi\left[\left(\frac{2\mu}{\mu+\epsilon} - \frac{\epsilon}{\mu-\epsilon}\right)\frac{L}{2L+1} - \frac{\epsilon \eta}{2L+1}\right] \right) +1\right) 
    \end{equation}
\end{lem}
\begin{proof}
    Recall that the function $x\mapsto \cos(\pi x)$ is decreasing on the interval $x\in (0,3/2)$. Our aim is to establish deterministic upper and lower bounds for $\sum_{m=1}^k \frac{2\lambda_{2m-1}}{2L+1}$ in terms of $L$ and $\epsilon$, which converge toward $1$ as $L\to \infty$. 

    For a fixed $k$ in range, on the event $\tilde M_{k, \epsilon},$ we have the we have the upper estimate 
    \begin{align*}
        \frac{2k}{2L+1}\left( \frac{1}{k}\sum_{m=1}^k \lambda_{2m-1} - \mu \right) + \frac{2\mu k}{2L+1} &\le \frac{k\epsilon}{2L+1} + \frac{2 \mu k }{2L+1} \\
        &\le \frac{(\epsilon + 2\mu)(L(\mu-\epsilon)^{-1} + \eta)}{2L+1}\\
        &= \frac{L}{2L+1} \frac{2\mu+\epsilon}{\mu-\epsilon} + \frac{\eta (2\mu+\epsilon)}{2L+2}
    \end{align*}

     Notice that for any $\epsilon< \mu/7$, and any $L \ge \frac{4\eta(2\mu+\epsilon)-1}{2}$, we have that 
    \[
        \frac{L}{2L+1} \frac{2\mu+\epsilon}{\mu-\epsilon} + \frac{\eta (2\mu+\epsilon)}{2L+2} \le  \frac{5}{4} + \frac{1}{4} = \frac{3}{2}
    \] 

On the flip side, we have the lower bound:  
   \begin{align*}
       \frac{2k}{2L+1}\left( \frac{1}{k}\sum_{m=1}^k \lambda_{2m-1} - \mu \right) + \frac{2\mu k}{2L+1} & \ge \frac{-\epsilon k }{2L+1} + \frac{\mu}{\mu+\epsilon}\frac{2L}{2L+1}\\
       &\ge \frac{-\epsilon (L/(\mu-\epsilon) +\eta) }{2L+1} + \frac{\mu}{\mu+\epsilon}\frac{2L}{2L+1}\\
       &\ge \frac{-\epsilon}{\mu - \epsilon}\, \frac{L}{2L+1} - \frac{\epsilon \, \eta}{2L+1} + \frac{\mu}{\mu + \epsilon}\frac{2L}{2L+1}\\
       &= \left(\frac{2\mu}{\mu+\epsilon} - \frac{\epsilon}{\mu - \epsilon} \right) \frac{L}{2L+1} - \frac{\epsilon \eta}{2L+1}
    \end{align*}

    In summary, for any $\epsilon< \mu/7$, and any $L \ge \frac{4\eta(2\mu+\epsilon)-1}{2}$, 
    \begin{equation}\label{pf:eqn:cosine_estimate}
            \begin{split}
                \left(\frac{2\mu}{\mu+\epsilon} - \frac{\epsilon}{\mu - \epsilon} \right) \frac{L}{2L+1} - \frac{\epsilon \eta}{2L+1} &\le \frac{2k}{2L+1}\left(\frac{1}{k}\sum_{m=1}^k \lambda_{2m-1} - \mu\right) + \frac{2\mu k}{2L+1}\\
                &\le \frac{L}{2L+1} \frac{2\mu+\epsilon}{\mu-\epsilon} + \frac{\eta (2\mu+\epsilon)}{2L+2} < \frac{3}{2}
            \end{split} \,.
    \end{equation} 

   Since the lower bound is strictly positive for all $L$, this means that we have the upper bound 
    \begin{equation}
        \cos\left( \pi \, \frac{2}{2L+1}\sum_{m=1}^k \lambda_{2m-1}\right) \le \cos\left( \pi\left[\left(\frac{2\mu}{\mu+\epsilon} - \frac{\epsilon}{\mu-\epsilon}\right)\frac{L}{2L+1} - \frac{\epsilon \eta}{2L+1}\right] \right)  \to -1 \text{ as $\epsilon \downarrow 0, L \to \infty$}\,.
    \end{equation} Since this bound holds independently of the trajectories, we see that 
    \begin{align*}
        \sum_{k\ge \frac{L}{\mu+\epsilon}}^{\frac{L}{\mu-\epsilon} +\eta} \mathcal{E}_Q[f_{k,L}, \tilde M_{k,\epsilon}] &\le \left(\cos\left( \pi\left[\left(\frac{2\mu}{\mu+\epsilon} - \frac{\epsilon}{\mu-\epsilon}\right)\frac{L}{2L+1} - \frac{\epsilon \eta}{2L+1}\right] \right) +1\right)\times \cdots\\
        &\cdots \times\sum_{k\ge (\mu+\epsilon)^{-1}L}^{(\mu-\epsilon)^{-1} + \eta} \cale_\calq[ (2L+2 - \sum \lambda_m) (s^2)^{2L+2-\sum \lambda_m}, \tilde M_{k, \epsilon}]\\
        &\le \left(\cos\left( \pi\left[\left(\frac{2\mu}{\mu+\epsilon} - \frac{\epsilon}{\mu-\epsilon}\right)\frac{L}{2L+1} - \frac{\epsilon \eta}{2L+1}\right] \right) +1\right) \E(\langle \Gamma_L | \one | \Gamma_L\rangle),
    \end{align*} where we have used the fact that $\E\langle \Gamma_L|\one |\Gamma_L\rangle$ has an expansion similar to that found in Lemma~\ref{lem:simulation}. Since we know that $\|\Gamma_L\|^2 \to 1$ almost surely as $L \to \infty$, so taking $C_3(L) = \E(\|\Gamma_L\|^2)$, the reverse Fatou lemma gives us the claimed inequality. 
\end{proof}

\begin{lem}\label{lem:k_middle_far}
    Let $L,\epsilon >0$ and $\eta> \frac{1}{2}(1 + (\mu-\epsilon)^{-1})$. Then is a constant $C_4>0$ depending only on $\mu$ and $\epsilon$ so that
    \begin{equation}
        \sum_{k\ge \frac{L}{\mu + \epsilon}}^{\frac{L}{\mu-\epsilon}+\eta} \cale_\calq[ f_{k,L}, \tilde M_{k,\epsilon}^c] + \sum_{k\ge \frac{L}{\mu-\epsilon} + \eta }^{L+1} \cale_\calq[f_{k,L}, M_{k,\epsilon}^c]\le C_4 L(L+1) \exp \left\{-\frac{\epsilon^2}{\mu+\epsilon} L \right\}
    \end{equation}
\end{lem}
\begin{proof}
    The strategy for each summand here is to apply Cram\'{e}r's theorem for sums of independent random variables \cite[Theorem 2.3.3]{DemboZeitouni} to estimate both of the probabilities $\calq[\tilde M_{k, \epsilon}^c]$ and $\calq[M_{k,\epsilon}]$. 

    In the $\tilde M_{k, \epsilon}$ case, we apply inequality~(\ref{eqn:Cramer's_theorem}) to get 
    \begin{align*}
        \calq[\tilde M_{k, \epsilon}^c]&\le  \calq[|\sum \lambda_{2m-1} - \mu k|\ge \epsilon k] + \calq[|\sum \lambda_{2k} - (k-1) \mu| \ge \epsilon (k-1)]\\
        &\le 2(1 + e^{\min\{ \Lambda^*(\mu + \epsilon), \Lambda^*(-\mu - \epsilon)\} }) e^{-k\Lambda^*(\mu+\epsilon)} \\
        &\le  2(1+e^{\min\{ \Lambda^*(\mu + \epsilon), \Lambda^*(-\mu - \epsilon)\} }) \exp\{- \frac{\min\{ \Lambda^*(\mu + \epsilon), \Lambda^*(-\mu - \epsilon)\} }{\mu + \epsilon} L \}\\
        &\lesssim 2 \exp\{- \frac{\epsilon^2}{\mu + \epsilon} L \} 
    \end{align*}

    Similarly, one finds that when $\frac{L}{\mu - \epsilon} \le k \le L+1$ that 
    \begin{align*}
        \calq[M_{k, \epsilon}^c] &\le 2 e^{-(2k-1)\min\{ \Lambda^*(\mu + \epsilon), \Lambda^*(-\mu - \epsilon)\} }\\
        &\le 2e^{\min\{ \Lambda^*(\mu + \epsilon), \Lambda^*(-\mu - \epsilon)\} } \exp\{-(\frac{2\min\{ \Lambda^*(\mu + \epsilon), \Lambda^*(-\mu - \epsilon)\} }{\mu -\epsilon}L \} \\
        &\lesssim \exp\{ - \frac{2\epsilon^2}{\mu-\epsilon} L\}
    \end{align*} Putting these pairs of regimes together in the sum yields the claim.
\end{proof}

\begin{lem}\label{lem:large_k_close}
    Let $L,\epsilon >0$. Let $\eta > \frac{1}{2}(1 + (\mu-\epsilon)^{-1})$ then,
    \begin{equation}
        \sum_{k\ge \frac{L}{\mu-\epsilon} + \eta}^{L+1} \cale_\calq[f_{k,L}, M_{k,\epsilon}]=0
    \end{equation}
\end{lem}
\begin{proof}
    We will show that the event $M_{k, \epsilon}\cap [ \sum \lambda_m \le 2L+1]$ is empty whenever $k\ge (\mu-\epsilon)^{-1}L + \eta$. Given 
    \[
        \left|\frac{1}{2k-1}\sum_{m=1}^{2k-1}\lambda_m - \mu \right| \le \epsilon,
    \] we obtain the lower bound 
    \[
        \sum_{m=1}^{2k-1} \lambda_m \ge (\mu-\epsilon)(2k-1) \ge 2(\mu-\epsilon)\left( \frac{L}{\mu - \epsilon} + \eta\right) - (\mu-\epsilon) \ge 2L + 2\eta (\mu-\epsilon) - (\mu - \epsilon) >2L+1\,, 
    \] which yields a contradiction. 
\end{proof}

\begin{thm}[Theorem~\ref{thmx:TasakiIndex}]\label{thm:Z2-index}
    Let $\nu_\omega$ be the disordered AKLT state as above. Then, 
        \begin{equation}
            \lim_{L\to \infty} \|\nu_\omega(T_L)+1\|_{L^1(\P)} =0\,.
        \end{equation}
\end{thm}
\begin{proof}
Let $0<\epsilon<\frac{\mu}{7}$, and fix $0<\delta<\mu-\epsilon$, $0<p<\frac{2\delta}{\delta+\mu}$, as in Lemmas~\ref{lem:small_k_close}--~\ref{lem:large_k_close} above. Taken together, we have shown there exists a function 
    \[
        0< g(L, \epsilon, \delta, \eta, p)=:g_\epsilon(L)
    \] so that
    \[
        \E\<\Gamma_L|T_L + \one |\Gamma_L\> \le g_\epsilon(L),
    \] and for any $\epsilon >0$, 
    \begin{align*}
        \limsup_{L\to \infty} g_\epsilon(L) &\le \limsup_{L\to \infty}\left(\cos\left( \pi\left[\left(\frac{2\mu}{\mu+\epsilon} - \frac{\epsilon}{\mu-\epsilon}\right)\frac{L}{2L+1} - \frac{\epsilon \eta}{2L+1}\right] \right) +1\right) \\
        &= \cos\left[\pi\left(\frac{\mu}{\mu+\epsilon}- \frac{\epsilon}{2(\mu-\epsilon)}\right)\right]+1\,.
    \end{align*}

Putting this together, we obtain
\begin{align*}
    \limsup_{L\to \infty} \E\<\Gamma_L|T_L+\one|\Gamma_L\> \le  \cos\left[\pi\left(\frac{\mu}{\mu+\epsilon}- \frac{\epsilon}{2(\mu-\epsilon)}\right)\right]+1
\end{align*} But the left-hand side does not depend on $\epsilon$ at all, so we may take $\epsilon \downarrow 0$, which yields
\[
    \lim_{L\to \infty} \|\<\Gamma_L|T_L+\one|\Gamma_L\>\|_{L^1(\P)} = 0
\] since $\<\Gamma_L|T_L+\one|\Gamma_L\>\ge 0$. 

Now, let $\Phi_{m,n} = E^{[m,n]}_{\one, \omega}$, be the ergodic quantum process defined by the random quantum channel $E_{\one, \omega}$ as in Lemma~\ref{lem:translation_operator_strictly_positive}, and let $\cal{T}$ denote the replacement channel defined by taking the normalized trace. Notice, $\|\Phi_{[-L,L+1]} - T\|\le 2$ almost surely thus, by the Dominated Convergence Theorem and using the upper bound from Lemma~\ref{lem:translation_operator_strictly_positive}, one obtains $\lim_{L\to \infty} \E \|\Phi_{[-L,L+1]}-\mathcal{T}\| = 0$


Recall from Lemma~\ref{lem:gamma_formulas} part c.) that the following inequalities hold almost surely,
\begin{equation}
   \left. \begin{array}{cc}
        |\<\Gamma_L|T_L|\Gamma_L\> - \nu_\omega(T_L)|&\le \|\Phi_{[-L,L+1]} - \mathcal{T}\|\\
        |\|\Gamma_L\|^2 - 1| &\le \|\Phi_{[-L,L+1]} - \mathcal{T}\|
    \end{array} \right\}
\end{equation} 

Therefore, using the triangle inequality, we have 
\begin{align*}
    \E|\nu_\omega(T_L) +1| & \le \E|\<\Gamma_L|T_L|\Gamma_L\> - \nu_\omega(T_L)| + \E|\<\Gamma_L|T_L + \one|\Gamma_L|+ \E|\|\Gamma_L\|^2 - \nu_\omega(\one)|\\
    &\le 2 \E \|\Phi_{[-L, L+1]} - \mathcal{T}\| + \E|\<\Gamma_L|T_L + \one |\Gamma_L\>| \to 0 \text{ as }L\to \infty, 
\end{align*} by the above arguments. 
\end{proof}


