\begin{DD}
Given an $h$-cobordism $W$ on $M$, we find, modulo smoothing the corners, another one $(W\times I, M\times I)$.
This defines for any compact manifold $B$ a map of sets $H_B(M)\to H_B(M\times I)$
and we set $\cH_B(M)=\operatorname{colim}_k H_B(M\times I^k)$.
\end{DD}


\subsection{$h$-cobordism spaces}\label{sec: hcob spac}


        \begin{DD}
            The \emph{$h$-cobordism space} of $M$ is the (geometric realisation of a) simplicial set $H(M)$, whose $k$-simplices $H(M)_k$ are defined to be the set of smooth families of $h$-cobordisms on $M$ parametrised by the standard $k$-simplex $\Delta^k$.
        \end{DD}
        \begin{RR}
            Strictly speaking, these are not sets. To resolve this, one must instead work with $h$-cobordisms which are embedded submanifolds in $\bR^\infty$; see \cite[Remark 1.1.2]{WJR} or \cite[Section 2.1]{HTW} for more details.
        \end{RR}
        \begin{RR}\label{rem:partitiondef}
            This differs from the definition considered in \cite{Wa82}, where $h$-cobordisms are required to be embedded in $M \times [0,1]$, or equivalently to be given a classical right inverse. However the corresponding $h$-cobordism spaces are homotopy equivalent when $\operatorname{Dim}(M) \geq 5$; as can be seen from the arguments in the proof of Lemma~\ref{lem:classicalinverses}.
	\end{RR}
        \begin{PP}\label{prop: bij iso rep}
            Let $B$ be a compact manifold. Then there is a canonical bijection of sets
            \begin{equation*}
                H_B(M) \cong [B, H(M)]
            \end{equation*}

            between isomorphism classes of smooth families of $h$-cobordisms on $M$ with homotopy classes of map $B \to H(M)$.
        \end{PP}
        \begin{proof}
            Follows from results in \cite[Section 2]{GRW:user's-guide}.
        \end{proof}
        The assignment $W \mapsto W\times I$ gives at the space level \emph{stabilisation maps} $\sigma: H(M) \to H(M \times I)$;
we refer to \cite[Section 1.1]{WJR} (or \cite{Wa82}, in a different model for the $h$-cobordism space) for more details. 
        \begin{DD}
            The \emph{stable $h$-cobordism space} $\cH(M)$ of $M$ is defined to be the colimit under repeated stabilisation:
            \begin{equation}\label{eq:stableH}
                \cH(M) := \operatorname{colim}_k H(M \times I^k)
            \end{equation}
        \end{DD}
        \begin{RR}\label{rmk: two stab}
            There are two different definitions of stabilisation maps $H(M) \to H(M \times I)$ in the literature, known in \cite{Wa82} as \emph{upper} and \emph{lower} stabilisation $\sigma^{+}, \sigma^{-}$ respectively, and either can be used in the definition of the stable $h$-cobordism space. 

            The two stabilisation maps $\sigma^{+}$ and $\sigma^{-}$ are not homotopic in general. However, they are related by a functorial autoequivalence of $H(M \times I)$, so the resulting stable $h$-cobordism spaces $\cH^{+}(M)$ and $\cH^{-}(M)$ are indeed homotopy equivalent.

            We follow the conventions of \cite{WJR} and \cite{Hat78}: we take $\sigma$ to be the lower stabilisation map $\sigma^{-}$. \cite{WW:Survey} uses upper stabilisation $\sigma^{+}$ everywhere, whereas \cite{Wa82} defines the stable $h$-cobordism space using a sequence of stabilisation maps which alternates between $\sigma^+$ and $\sigma^-$.
        \end{RR}

    \subsection{Functoriality}\label{subsec:functor}
        In this section, we recall how $\cH(\cdot)$ can be made into a functor from the category of compact manifolds to spaces.
In general, it can be extended to a functor from the category of spaces \cite{Wa82}, but this weaker form of functoriality is both simpler and sufficient for our purposes.

        Let $i: M \to N$ be a codimension 0 embedding of compact manifolds of dimension $n$.
        \begin{LL}\label{lem: hcob glue hcob}
            Let $W$ be an $h$-cobordism on $M$. Define $V$ to be the pair:
            \begin{equation}
                V = \left((N \times I) \cup_{M \times \{1\}} W, N \times \{0\}\right)
            \end{equation}
            where we equip this with a smooth structure as in Lemma \ref{lem: smooth structure on gluing}, and smooth corners implicitly.

            Then $V$ is an $h$-cobordism on $N$.
        \end{LL}
        \begin{proof}
            It is clear that the inclusion $N \to V$ is a homotopy equivalence. Let $M' = W \setminus \int(M)$, and $N' = (N \setminus \int(M)) \cup_{\partial M} M'$. Then $W$ is an $h$-cobordism from $M$ to $M'$, and $V$ is a cobordism from $N$ to $N'$.

            Since $M' \to W$ is an equivalence (relative to $\partial M$), so is the inclusion $N' \to (N \setminus \int(M)) \cup_{\partial M} W$. Then the inclusion of this second expression into $V$ is also an equivalence (the complement is $N \times [0,1)$).
        \end{proof}



        \begin{DD}
            We define a map $H(i): H(M) \to H(N)$ as follows. For a $k$-simplex $\bW = \{W_b\}_{b \in \Delta^k} \in H(M)_k$, we define $H(i)(\bW)$ to be the smooth family of $h$-cobordisms on $N$ over $\Delta^k$ defined by
            \begin{equation}\label{eq: glued hcob}
                \left\{
                \left(
                (N \times I) \cup_{M \times \{1\}} W_b, N \times \{0\}
                \right)
                \right\}_{b \in \Delta^k}
            \end{equation}
            Note these are $h$-cobordisms by Lemma \ref{lem: hcob glue hcob}.
        \end{DD}



        This can be made compatible with stabilisation and so induces a map on stable $h$-cobordism spaces $\cH(i): \cH(M) \to \cH(N)$.


        By Proposition \ref{prop: bij iso rep}, $H(i)$ induces a map $H_B(i): H_B(M) \to H_B(N)$ for any compact manifold $B$. We may describe this explicitly: this sends $\bW = \{W_b\}_{b \in B}$ to
        \begin{equation*}
            \left\{
            \left(
            (N \times I) \cup_{M \times \{1\}} W_b, N \times \{0\}
            \right)
            \right\}_b
        \end{equation*}
        again using Lemma \ref{lem: smooth structure on gluing} and smoothing corners implicitly.

For a general map $i:M\to N$, we approximate it by an embedding $M \to N\times D^k$ and take a tubular neighborhood $D_M \to N\times D^k$
which is now a codimension zero embedding, so we find a map $H(D_M)\to H(N\times D^k)$ which stably gives $\cH(M)\to \cH(N)$ (see \cite{Wa82} for more details). We use
this only for the inclusion of a point in $M$ (as in Theorem~\ref{thm:producteuler}) where it amounts to thickening the point to a disk in $M$
.

        We use two connectivity estimates (though these are significantly more refined than is required for our purposes):

        \begin{TT}[Igusa stability \cite{Igusa}]
            The stabilisation $\sigma: H(M) \to H(M \times I)$ is $k$-connected if $n \geq \operatorname{max}(2k+8, 3k+5)$.
        \end{TT}
        \begin{TT}[{\cite[Proposition 10.9]{BokMad}, \cite[1.1]{Waldhausen:TopI}}]
            The induced map on stable $h$-cobordism spaces $\cH(i): \cH(M) \to \cH(N)$ is $k$-connected if $i: M \to N$ is $(k+1)$-connected.
        \end{TT}
        \begin{CC}\label{cor: conn est}
            Let $B$ be a compact $d$-dimensional manifold. Assume $i: M \to N$ is $(d+2)$-connected and $\operatorname{Dim}(M)=\operatorname{Dim}(N) \geq \operatorname{max}(2d+12, 3d+11)$.

            Then $H_B(i): H_B(M) \to H_B(N)$ is a bijection.
        \end{CC}
        \begin{proof}
            The condition on $i$ implies $\cH(i)$ is $(d+1)$-connected, and the condition on $\operatorname{Dim}(M)$ implies the maps $H(M) \to \cH(M)$ and $H(N) \to \cH(N)$ are $(d+2)$-connected. Therefore $H(i)$ is $(d+1)$-connected, and we conclude by Proposition \ref{prop: bij iso rep}.
        \end{proof}


\subsection{The parametrised Whitehead torsion}\label{sec: para whit}

\begin{DD}\label{def:structurespaceB}
Let $B$ be a compact manifold, $M$ a closed manifold, $(L_b)_{b\in B}$ a family of
closed manifolds parametrised by $B$ and $g_b:L_b\to M$ a family of homotopy
equivalences. Two such families $(L_b,g_b)$ and $(L'_b,g'_b)$ are equivalent
if there exists a family of diffeomorphisms $\psi_b:L_b\to L'_b$ and a family of homotopies
between $g'_b\circ \psi_b$ and $g_b$.
We denote $\cS_B(M)$ the set of equivalence classes of such families.
\end{DD}

\begin{DD}\label{def:structurespace}
We define $\cS(M)$ to be (the geometric realisation of) the simplicial set whose $k$-simplices
are families $(L_b,g_b)_{b\in \Delta^k}$ as in Definition~\ref{def:structurespaceB} (not considered up to equivalence) and the face and degeneracy
maps are given by pullbacks along the standard face/degeneracy maps between simplices. This is called the \emph{structure space} of $M$.
\end{DD}

\begin{PP}\label{prop:classifyingS}
For any compact manifold $B$ and closed manifold $M$, there is a natural bijection
\[\cS_B(M) \to [B,\cS(M)].\]
\end{PP}

We will associate to an element of $\cS_B(M)$ a stable $h$-cobordism on $M$, well defined
up to isomorphism, namely an element of $\cH_B(M)$. When $B$ is a point, $\cH_B(M)=\Wh(\pi_1 M)$
and we recover the Whitehead torsion of a homotopy equivalence.

We will use the following standard lemma, and reproduce its proof for completeness.
\begin{LL}\label{lem:codim3hcob}
    Let $X$ be a closed connected manifold, and $X \to Y$ an embedding of codimension at least 3 into a compact manifold $Y$ which is a homotopy equivalence. Assume the inclusion $\del Y \to Y$ is an isomorphism on $\pi_1$.

    Then the complement $W=Y\setminus \int D_X$ of a tubular neighborhood $D_X$ of $X$ in $Y$ is an $h$-cobordism on $\del D_X$.
\end{LL}
\begin{proof}
    Since $k\geq 3$ the maps $\pi_1 \del D_X \to \pi_1 D_X$ and $\pi_1 W \to \pi_1 Y$ are isomorphisms (any map from a surface to $Y$ is homotopic to a map disjoint from $X$). Moreover since $\pi_1\del Y \to \pi_1 Y$ is an isomorphism the same holds for $\pi_1\del Y\to \pi_1 W$. We have $H_*(Y,D_X)=H_*(Y,X)=0$ with any local system and by excision the same holds for $H_*(W,\del D_X)$. By Hurewicz's theorem and Whitehead's theorem we then conclude that $\del D_X \to W$ is a homotopy equivalence. Using Poincaré-Lefschetz duality we obtain the same conclusion for the inclusion of the other boundary component $\del Y \to W$ (note that our assumptions imply that $\del Y$ is non-empty and connected).
\end{proof}

Pick $k\geq 3$ (large enough) and a family of embeddings $L_b\to \int (M \times D^k)$. Pick
a family of tubular neighborhoods $E_b$ of $L_b$ in $\int (M \times D^k)$. We define $W_b=(M\times D^k) \setminus \int E_b$. 
By Lemma~\ref{lem:codim3hcob} this is a family of $h$-cobordisms on $\del E_b$ or, seen from the other side, on $M\times S^{k-1}$.

For large enough $k$, the family of embeddings $L_b\to M\times D^k$ are isotopic, and thus the resulting $h$-cobordisms
$(W_b,M\times S^{k-1})$ are isomorphic. However to find a meaningful invariant we need to suppress the
dependence on $k$ so we require an extra step.

Pick a classical right inverse $(W'_b;M\times S^{k-1},\del E_b)$ to $W_b$ (see Lemma~\ref{lem:classicalinverses}), namely 
\[W_b\cup_{M \times S^{k-1}} W'_b\simeq \del E_b\times I.\]
We consider $E'_b=(M\times D^k)\cup_{M\times S^{k-1}} W'_b\simeq E_b$ and the pair 
\[(V_b,M\times D^k)=(E'_b\times I, M\times D^k\times \{0\}).\]

\begin{LL}
For each $b$, the pair $(V_b, M\times D^k)$ is an $h$-cobordism.
\end{LL}
\begin{proof}
We supress $b$ from the notations. $V$ deformation retracts onto $E'$ and then further to $M\times D^k$ since $W'$ is
an $h$-cobordism. For the other boundary component $\del_+ V=(E'\times \{1\}) \cup (\del E'\times I) \cup W'$, we observe the factorisation
\[E'\times \{1\}\cup ((\del E')\times I) \to \del_+ V \to E'\times I=V\]
where the map on the left and the composition are homotopy equivalences, hence so is $\del_+V \to V$.
\end{proof}

\begin{LL}\label{lem: stab comp w}
Under the natural embedding $D^k \to D^{k+1}$, the above construction of $(V_b\times I)$ gets stabilised
as in \eqref{eq:stableH}.
\end{LL}
\begin{proof}
We use the notations of the previous paragraph, but suppress the subscript $b$ for simplicity.
Pick a subinterval $J'=[1/3,2/3]\subset J=[0,1]$. We give subcripts $k$ to the object constructed
as above with the integer $k$. We have $E_k \subset M\times D^k$ and we thicken this to $E_{k+1}=E_k\times J' \subset M\times D^k\times J$.
Up to smoothing corners, $M\times D^k\times J\simeq M\times D^{k+1}$ and the $h$-cobordism $W_k=M\times D^k \setminus E_k$
becomes
\[W_{k+1}=(M\times D^k\times J) \setminus E_{k+1}.\]
To complete the construction at the range $k+1$ we need to pick a right inverse to $W_{k+1}$
but we observe that $W'_k\times J$ is such an inverse, where $W'_k$ is a right inverse of $W_k$.
Indeed, using that $W_k\cup W'_k$ is a trivial cobordism, we see that the embedding 
\[E_{k+1}=E_k\times J' \subset (M\times D^k\times J)\cup_{M\times S^{k-1}\times J} (W'\times J)=E'_k\times J = E'_{k+1}\]
is isotopic to a diffeomorphism.
Finally the $h$-cobordism $(V_k=E'_k\times I, M\times D^k\times \{0\})$ becomes 
\[V_{k+1}=(E'_{k+1}\times I, M\times D^k\times J'\times \{0\})=(E'_k\times I \times J, M\times D^k\times J'\times \{0\})\simeq V_k \times J,\]
which is precisely the stabilisation of $V_k$ as in Section~\ref{sec: hcob}.
\end{proof}

\begin{DD}\label{def:paramWh}
    The \emph{parametrised Whitehead torsion} of a family of homotopy equivalences
    $(L_b, g_b : L_b \to M)$ is the class of $(V_b,M \times D^k) \in \cH_B(M)$, constructed as above. This
defines a map
\[w:\cS_B(M)\to \cH_B(M).\]
which is well-defined by Lemma \ref{lem: stab comp w}.
\end{DD}

\begin{RR}\label{rem:spacelevelw}
Generalizing the arguments above we can construct $w$ at the space-level and obtain a map
\[\cS(M) \to \cH(M)\]
which gives the previous definition under the bijections from Proposition~\ref{prop:classifyingS} and Proposition~\ref{prop: bij iso rep}.
\end{RR}


\begin{RR}
    The definition of $w$ also depends on the convention for stabilisation as in Remark \ref{rmk: two stab}; since our convention for stabilisation differs from that of \cite{WW:Survey}, our definition of theirs also does. Our definition of parametrised Whitehead torsion is identical to that of \cite{WW:I}, \emph{except} for this difference in convention. In particular, under the autoequivalences that relates the two possible definitions of $\cH(M)$, the two definitions of the parametrised Whitehead torsion agree.
\end{RR}

    \subsection{Decompositions of total space}
        Let $N$ be a closed manifold.
        \begin{PP}\label{prop: tot hcob triv}
            Let $\pi: W \to C$ be a smooth fibre bundle over a compact connected manifold $C$, and $\iota: N \times C \to W$ an embedding of fibre bundles, such that for each $c \in C$ the fibre $(\pi^{-1}\{c\}, N)$ is an $h$-cobordism.  In particular, the total space $(W, N \times C)$ forms an $h$-cobordism.

            Assume further that each fibre $(\pi^{-1}\{c\}, N)$ is a trivialisable $h$-cobordism: it admits a diffeomorphism to $(N \times I, N \times \{0\})$ (crucially, we do \emph{not} assume there exists a family of such diffeomorphisms, varying smoothly in $c$).

            Then there is a diffeomorphism $(W, N \times C) \cong (N \times C \times I, N \times C \times \{0\})$ relative to $N \times C$, i.e. the total space of the bundle is a trivial $h$-cobordism.
        \end{PP}
        In general, the diffeomorphism produced will not respect the projection maps to $C$.
        \begin{proof}
            Let $\partial_- W = \operatorname{Im}(\iota)$ and let $\partial_+ W = \partial W \setminus \partial_- W$.

            We choose a Morse function $f:C\to \R$ together with a gradient-like vector field $Y$; we may choose these so that $Y$ points strictly inwards along $\partial C$.

            Above a neighborhood $U$ of the set $\crit(f)$ of critical points of $f$, we pick a trivialisation
            of the bundle $\varphi : U\times N \times [0,1] \overset{\sim}{\longrightarrow} \pi^{-1}(U)$.
            We pick a function $g:W\to [0,1]$ to be any function which has regular level sets $g^{-1}(0)=\del_- W$ and $g^{-1}(1)=\del_+ W$ and coincides with the projection to $[0,1]$
            in the trivialisation $\varphi$ above a neighborhood of $\crit(f)$. We then choose a fiberwise gradient-like
            vector field $X$ for $g$. Finally, we pick a lift $Y'$ of $Y$ which is horizontal above a neighborhood of $\crit(f)$ with respect to the trivialisation $\varphi$ and tangent to $\del W$.

            We claim that the vector-field $Z=X+Y'$ is gradient-like for the function $h^a=g+a\pi^*f$ for $a>0$ sufficiently large.
            Indeed we have:
            \[dh^a(Z)=dg(X)+dg(Y')+a\pi^*(df(Y)).\]
            We have $dg(X)\geq 0$ and $\pi^*df(Y)\geq 0$ everywhere. Near $\pi^{-1}(\crit(f))$, $dg(Y')=0$, $dg(X)>0$ so $dh^a(Z)>0$. Away from a neighborhood of
$\pi^{-1}(\crit(f))$, $\pi^* df(Y)>0$ and $dg(Y')$ is bounded, so $dh^a(Z)>0$ for sufficiently large $a>0$. Moreover $Z$ is transverse to $\del W$, inward pointing along $\del_- W$ and outward pointing along $\del_+ W$ since this is the case for $X$ and $Y'$ is tangent to $\del W$.

            So we conclude that all trajectories of $Z$ starting on $\del_- W$ go all the way to $\del_+ W$. After renormalizing $Z$, we then define a diffeomorphism $\del_-W \times [0,1] \to W$ uniquely by mapping $\del_-W \times \{0\}$ to $\del_- W$ by the identity map and mapping $\del_t$ (the vector field corresponding
            to the $t$-coordinate on $[0,1]$) to $Z$.
        \end{proof}

        A similar result holds when each fibre is not necessarily trivial:
        \begin{PP}\label{prop: tot hcob}

            Let $\pi: W \to C$ be a smooth fibre bundle over a compact connected manifold $C$, and $\iota: N \times C \to W$ an embedding of fibre bundles, such that for each $c \in C$ the fibre $(\pi^{-1}\{c\}, N)$ is an $h$-cobordism.

            Assume further that each $h$-cobordism $(\pi^{-1}\{c\}, N)$ is diffeomorphic to an $h$-cobordism $(V, N)$, and that $\operatorname{Dim}(V) \geq 6$.

            Then there is a diffeomorphism $(W, N \times C) \cong (V \times C, N \times C)$, i.e. the total space of the bundle is a product $h$-cobordism.
        \end{PP}
        More succinctly, this says that the total space of a bundle of $h$-cobordisms on a closed manifold $N$ splits as a product.
        \begin{proof}

            Let $N' = \partial V \setminus N$ be the other boundary component of $V$. Choose an $h$-cobordism $V'$ from $N'$ to $N$, along with diffeomorphisms $\phi: V' \cup_{N} V \cong N' \times I$ and $\phi': V \cup_{N'} V' \cong N \times I$ relative to the boundaries; this exists since $\operatorname{Dim}(V) \geq 6$ (this corresponds to a choice of inverse $h$-cobordism in the classical sense).

            Let $Z = (V' \times C) \cup_{N \times C} W$, and let $\pi': Z \to C$ be given by projection on the first term and $\pi$ on the second. $Z$ is now a smooth fibre bundle over $C$ with fibres which are trivial $h$-cobordisms on $N'$, so by Proposition \ref{prop: tot hcob triv}, there is a diffeomorphism $(Z, N' \times C) \cong (N' \times C \times I, N \times C \times \{0\})$. Gluing back on $V \times C$ along $N' \times C$ and using $\phi'$ then implies the result.
        \end{proof}
        The same result holds in families:
        \begin{PP}\label{prop: tot hcob param}
            Let $B$ and $C$ be compact connected manifolds, $\{\pi_b: W_b \to C\}_b$ a smooth family over $B$ of smooth fibre bundles over $C$, and $\iota: N \times C \times B \to \bW$ an embedding of fibre bundles. Assume for each $b \in B, c \in C$, the fibre $(W_{b,c}, N)$ is an $h$-cobordism. 

            Fix some $c_0 \in C$, and let $V_b = \pi_{b}^{-1}\{c_0\}$; these together assemble to form a smooth family $\bV=\{V_b\}_{b \in B}$ of $h$-cobordisms on $N$.

            Then there is an isomorphism of families of $h$-cobordisms on $C \times N$ over $B$:
            \begin{equation*}
                \left\{(W_b, N \times C) \cong (V_b \times C, N \times C)\right\}_{b \in B}
            \end{equation*}
        \end{PP}
        \begin{proof}

            All the steps in the proof of Proposition \ref{prop: tot hcob} (as well as that of Proposition \ref{prop: tot hcob triv}) can be carried out smoothly in families.
        \end{proof}

    \subsection{Monoid structure}\label{subsec:monoid}

        Once again, let $M$ and $B$ be compact manifolds. Assume $\operatorname{Dim}(M) \geq 5$. In this section, we equip $H_B(M \times I)$ with the structure of a group.

        \begin{DD}
            Let $W$ and $V$ be $h$-cobordisms on $M \times I$. We define $W+V$ to be the $h$-cobordism obtained by gluing $W$ and $V$ to $M \times I \times [0,1]$ along $M \times [0,1/2] \times \{1\} \cong M \times I \subseteq \partial W$ and $M \times [1/2,1] \times \{1\} \cong M \times I \subseteq V$ respectively.

            Performing the same construction in families defines a family of $h$-cobordisms $\{W_b+V_b\}_b$ associated to a pair of families $\{W_b\}_b$ and $\{V_b\}_b$ on $M \times I$.
        \end{DD}
        \begin{LL}
            The isomorphism class of $W+V$ only depends on the isomorphism classes of $W$ and $V$. In particular, $+$ descends to a well-defined map $+: H_B(M \times I) \times H_B(M \times I) \to H_B(M \times I)$.
        \end{LL}
        \begin{LL}
            The trivial $h$-cobordism $\{M \times I \times I\}_b$ is a unit for this operation. 
        \end{LL}

        \begin{LL}
            The operation $+$ on $H_B(M \times I)$ is associative.
        \end{LL}
        \begin{proof}
            Let $W,V,U$ be $h$-cobordisms on $M \times I$. $(W+V)+U$ and $W+(V+U)$ are both obtained by gluing on $W$, $V$ and $U$ to $M \times I \times I$ along a triple of subintervals in $I$ in the same order; by Lemma \ref{lem: isotopy diffeo}, it follows that they are isomorphic $h$-cobordisms on $M \times I$.
        \end{proof}


        \begin{LL}\label{lem:inverses}
            The monoid $(H_B(M \times I),+)$ admits inverses, i.e. is a group.
        \end{LL}
        \begin{proof}
We prove this when $B$ is a point; the general case is identical.

Let $(W;M\times I, N')$ be an $h$-cobordism on $M\times I$. Pick a classical right inverse $h$-cobordism $(W^c;N',M\times I)$.

Pick also a collar neighborhood $M\times I \subset \del W^c\setminus \int(N')$ of $M\times \{1\}$ (see Figure~\ref{fig: inverseU} where this collar is in red).
The manifold $N'$ is itself an $h$-cobordism from $M$ to $M$ and as such it admits an inverse $h$-cobordism $(N;M,M)$ (again in the classical sense). Decompose
$M\times [0,2]$ as $(M\times [0,1])\cup (M\times [1,2])$ and identify $M\times [1,2]$ with the concatenation $N\cup_M N'$.
Consider $N\times I$ attached to $N\subset M\times [1,2]$ along $N\times \{0\}$ and to $\del W^c$ along the collar neighborhood $M\times I$.
We define $U$ to be the union $W^c\cup_{M\times I} N\times I$ along the collar neighborhood $M\times I$ (see Figure~\ref{fig: inverseU} where $\del U$ is colored in blue). This manifold $U$ is an $h$-cobordism from $N'\cup N$ to $(M\times I)_{M\times \{1\}}\cup N$. The attaching region $N'\cup N$ of $U$ is diffeomorphic to $M\times I$
and it can therefore be isotoped to lie entirely inside $M\times [1,2]$, therefore by Lemma \ref{lem: isotopy diffeo} exhibiting the trivial cobordism $(M\times I \times [0,2]) \cup W\cup W^c \cup N\times I$ as
the sum $W + U$ (see the bottom of Figure~\ref{fig: inverseU}). Hence $U$ is an inverse to $W$ for the monoid structure of $H_B(M\times I)$.
