\subsection{General case}
    \begin{proof}[Proof of Theorem \ref{thm: prod decomp}]
        By induction on the dimension $n$ of $P$, we may assume the statement of Theorem \ref{thm: prod decomp} holds for all manifolds $P'$ of dimension $\leq n-1$ (the $n=0$ case is trivial).

        Choose a handle decomposition of $P$; let $s$ be the number of handles. Note that Propositions \ref{prop: int case}, \ref{prop: even case} and \ref{prop: odd case} prove the case where there is exactly one handle. By induction on the number of handles $s$, we may assume the statement of Theorem \ref{thm: prod decomp} holds for all manifolds $P$ of dimension $n$ which admit handle decompositions with $\leq s-1$ handles.

        We may write $P = P' \cup H^n_i$, where $H^n_i = D^i \times D^{n-i}$ is an $n$-dimensional $i$-handle, glued to $P'$ along some embedding $S^{i-1} \times D^{n-i} \to \partial P'$. By the above discussion, we may assume Theorem \ref{thm: prod decomp} holds for $P'$. Let $\chi = \chi(P, \partial P)$ and $\chi' = \chi(P', \partial P')$, so $\chi = \chi' + (-1)^{n-i}$.



        Applying Theorem \ref{thm: prod decomp} to $P'$, we obtain a diffeomorphism:
        \begin{equation}\label{eq: gen case 1}
            W \times P' \cong (R' \times I) \cup \left(\chi' \cdot (W \times D^n)\right)
        \end{equation}
        relative to $R'=(M \times P') \cup (W \times \partial P')$.

        Applying Theorem \ref{thm: prod decomp} to $D^{n-i}$ and taking products with $D^i$ on both sides, we obtain a diffeomorphism:
        \begin{equation}\label{eq: gen case 2}
            W \times H^n_i \cong (M \times I \times H^n_i) \cup \left( (-1)^{n-i} \cdot (W \times D^n) \right) \cup (W \times I \times D^i \times \partial D^{n-i})
        \end{equation}
        relative to the subspaces $(M \times \{0\} \times H^n_i) \cup (W \times \{0\} \times D^i \times \partial D^{n-i})$ on both sides.

        Extending (\ref{eq: gen case 1}) via the identity over $W \times H^n_i$, and noting that $(R' \times I) \setminus (W \times H^n_i) = (R \times I) \setminus (W \times H^n_i)$ (viewing these spaces as subspaces of $W \times P$), we obtain a diffeomorphism:
        \begin{equation}\label{eq: gen case 3}
            W \times P \cong (R \times I) \cup (\chi' \cdot (W \times D^n)) \cup (W \times H^n_i)
        \end{equation}
        relative to $R$. Since $R \cap (W \times H^n_i) = W \times D^i \times \partial D^{n-i}$, we may apply apply (\ref{eq: gen case 2}) to (\ref{eq: gen case 3}) (and apply the identity over the rest of the right hand side) to obtain a diffeomorphism:
        \begin{equation}
            W \times P \cong (R \times I) \cup (\chi' \cdot (W \times D^n)) \cup \left( (-1)^{n-i} \cdot (W \times D^n) \right)
        \end{equation}
        relative to $R$; since $\chi=\chi' + (-1)^{n-i}$ this is the desired isomorphism.
    \end{proof}


\section{Nearby Lagrangians and parametrised Whitehead torsion}\label{sec:nearbylag}
\subsection{Nearby Lagrangians and their Legendrian lifts}

     Given a manifold $X$, we write $\lambda_X$ for the tautological Liouville $1$-form on $T^*X$ and use the contact $1$-form $dz-\lambda_X$ on $J^1(X)=T^*X\times \R$.
\begin{DD}
For $M$ a closed connected manifold and $B$ a compact manifold.
A \emph{family of nearby Lagrangian submanifolds} in $T^* M$ parametrised by $B$ is a family $\bL={L_b}_{b\in B}$
of closed connected exact Lagrangian submanifolds
of $T^* M$. More explicitly, $\bL \to B$ is a smooth subbundle of the trivial bundle $T^*M \times B \to B$,
such that each fibre $L_b$ is a closed exact Lagrangian in $T^*M$. Exactness means that for each $b\in B$, there exists a smooth function $f_b$ on $L_b$ such that
$i_b^*\lambda_M=d f_b$ where $i_b:L_b\to T^* M$ is the inclusion.

Two such families are \emph{isotopic} if there exists a family over $B\times [0,1]$ which restricts to the given families
over $\{0,1\}$. We denote $\cL_B(M)$ the set of isotopy classes of families of nearby Lagrangian submanifolds parametrised by $B$.
\end{DD}

It is convenient, especially when considering generating functions, to lift exact Lagrangian submanifolds
of $T^*M$ to Legendrian submanifolds in $J^1(M)$. This amounts to a choice of a primitive function $f_b$
as in the above definition, and in our case this can be chosen smoothly in $b$.

\begin{LL}
Let $(L_b)_{b\in B}$ be a family of nearby Lagrangian submanifolds. There exists a smooth function $f$
on the total space such that for each $b \in B$, $i_b^*\lambda_M= df_b$.
\end{LL}
\begin{proof}
The function $f$ can be found locally near each $b$, but since all such primitives differ by a constant
($L_b$ is connected) we can globalise the construction and find the required smooth function on the total space
of the family.
\end{proof}

A function $f$ as provided by the previous lemma allows to view $(L_b)_{b\in B}$
as a family $(\widetilde{L_b})_{b\in B}$ of Legendrian submanifolds in $J^1(M)$ but such
a family is canonically the same thing as a single Legendrian submanifold (the total space)
in $J^1(M\times B)$ in view of the following lemma.

    \begin{LL}\label{LL:biglegendrian}
    Let $B$, $L$ and $M$ be manifolds.
    \begin{enumerate}
        \item If $j:L\to J^1(M\times B)$ is a Legendrian immersion such that the projection $\pi:L\to B$ is a submersion, then for each $b\in B$, the restriction of the projection $i:L\to J^1(M)$ to $\pi^{-1}(b)$ is a Legendrian immersion.
        \item If $\pi: L\to B$ is a submersion and $i:L\to J^1(M)$ a map which restricts to a Legendrian immersion $\pi^{-1}(b) \to J^1(M)$ for all $b\in B$, then there is a unique Legendrian immersion $j:L\to J^1(M\times B)$ which lifts $(i,\pi):L\to J^1(M)\times B$.
    \end{enumerate}
    \end{LL}
    \begin{proof}
    \begin{enumerate}
        \item We have $j^*(dz-\lambda_M -\lambda_B)=0$ on $TL$ and $j^*\lambda_B=0$ on $\ker d\pi$, so $j^*(dz -\lambda_M)=0$ on $\ker d\pi$. Hence $i:\pi^{-1}(b)\to J^1(M)$ is a Legendrian map for each $b\in B$.

        Furthermore $TL$ is transverse to each coisotropic subspace $T(T^* M \times T^*_b B)$, so the symplectic reduction map $\ker d \pi = T(\pi^{-1}(b))=TL \cap T(T^* M \times T^*_b B) \to T(T^* M)$ is injective and we conclude that $\pi^{-1}(b)\to J^1(M)$ is an immersion.

        \item The $1$-form $i^*(dz-\lambda_M)$ vanishes on $\ker d\pi$, so there is a unique map $\beta: L \to T^* B$ lifting $\pi$ (i.e. a section of $\pi^*T^*B\to L$) such that $\beta^*\lambda_B=i^*(dz-\lambda_M)$ or equivalently, such that the map $j=(i,\beta):L\to J^1 M\times T^* B = J^1(M\times B)$ satisfies 
        \[j^* (dz-\lambda_M - \lambda_B)=i^*(dz-\lambda_M)-\beta^* \lambda_B=0.\]
        The map $j$ is an immersion since $(i,\pi):L\to J^1(M)\times B$ is already an immersion.
    \end{enumerate}
    \end{proof}

\begin{DD}
We define $\cL(M)$ to be the (geometric realisation of the) simplicial set whose $k$-simplices are families of nearby Lagrangian
submanifolds parametrised by a standard simplex $\Delta^k$, with face and degeneracy maps given by pullbacks.
\end{DD}


\begin{PP}\label{prop:classifyingnearby}
For any compact manifold $B$, there is a canonical bijection of sets
\[\cL_B(M)\to [B,\cL(M)].\]
\end{PP}

\begin{RR}
We could also define $\cL(M)$ as the space of closed exact Lagrangian submanifolds with the $C^\infty$-topology
and we would get a (weakly) homotopy equivalent space but it is more convenient for us to define $\cL(M)$ as a simplicial
set as $\cH(M)$ is also defined this way.
\end{RR}


\subsection{Rephrasing Theorem~\ref{thm:main}}

    Let $M$ be a closed manifold of dimension $n$. Let $B$ be a compact manifold with boundary of dimension $d$. Let $\bL = \{L_b\}_{b \in B}$ be a smooth family of nearby Lagrangians in $T^*M$, parametrised by $B$. Let $\{g_b: L_b \to M\}_b$ be the canonical family of projections. In the next section, we will prove:

    \begin{TT}\label{thm:mainoverB}
        Assume $l \gg 0$. Then there is a smooth family of disk vector bundles $\{E_b \to L_b\}_b$ over $\{L_b\}_b$, and a smooth family of smooth $h$-cobordisms $\bX = \{X_b\}_b$ on $D^{l-1}$, such that there is a smooth family of diffeomorphisms
        \begin{equation}\label{eq: thm 412}
            \left\{ E_b \cong M \times (D^l \cup X_b)\right\}
        \end{equation}
        On the right-hand side, we glue along some fixed choice of embedding $i: D^{l-1} \hookrightarrow \partial D^l$. Furthermore the following diagram commutes up to homotopy (continuously in $b$):
        \begin{equation}\label{eq:mainoverB}
            \begin{tikzcd}
                E_b
                \arrow[r]
                \arrow[d]
                &
                M \times (D^l \cup X_b)
                \arrow[d]
                \\
                L_b 
                \arrow[r]
                &
                M
            \end{tikzcd}
        \end{equation}
    \end{TT}

    \begin{RR}
        The obstruction to being able to do this with trivial disc bundles, so $E_b = L_b \times \bR^l$, is that the virtual vector bundle $g_b^*TM-TL_b$ could be stably nontrivial. 

        The (Strong) Nearby Lagrangian conjecture predicts that this bundle is stably trivial, but this has not yet been proved.
    \end{RR}

    \begin{proof}[Proof of Theorem~\ref{thm:main} from Theorem \ref{thm:mainoverB}]
According to Remark~\ref{rem:CWorMFD} and Proposition~\ref{prop:classifyingnearby} it is enough
to treat the case of a smooth family of nearby Lagrangian submanifolds $(L_b)_{b\in B}$ for $B$ a compact manifold. 
According to Definition~\ref{def:paramWh}, the parametrised Whitehead torsion $w((L_b)_{b\in B})$
is represented by the family of $h$-cobordisms $(E_b\times I,M\times D^l\times \{0\})$, which is obtained from the trivial
$h$-cobordism $M\times D^l\times I$ by attaching $M\times X_b\times I$, an $h$-cobordism on $M\times D^{l-1}\times I$.
Hence the family $(X_b\times I)_b$ represents a map $\delta:B\to H(D^{l-1}\times I)\to\cH(\pt)$ such that $p\circ \delta=w((L_b)_{b\in B})$.
\end{proof}

\section{Generating functions and the factorisation through $\cH(\pt)$}\label{sec:genfun}


    \subsection{Generating functions of tube type and their difference functions}
        \begin{DD}\label{def:2}
            A smooth function $f: \bR^l \to \bR$ is \emph{almost quadratic} if it is of the form  $f=q+g$, where $q$ and $g$ are $C^1$ and satisfy:
            \begin{enumerate}
                \item $q$ is a degree 2 homogeneous function (meaning $q(\lambda v) = \lambda^2 q(v)$ for $\lambda \geq 0$ and $v\in \R^l$),
        	\item $\nabla q(v) \neq 0$ for all $v\neq 0$,
                \item $|\nabla g(v)|\leq c$ for some constant $c>0$.
            \end{enumerate}

A function is of \emph{tube type} if it is almost quadratic and homotopic to a non-degenerate quadratic form through almost quadratic functions.
        \end{DD}

\begin{RR}
    We do note require $q$ and $g$ themselves to be smooth: typically they will not be smooth at 0.
\end{RR}
\begin{RR}\label{rem:compactsupp}
Without changing the critical points of $f=q+g$, we can cut-off $g$ to make it compactly supported.
However the compactly supported condition is not well-behaved with respect to direct sum, that is why
we use the relaxed condition that $|\nabla g|$ is bounded.
\end{RR}

\begin{DD}
A function $f:M\times \R^l\to \R$ is a \emph{generating function of tube type} if each restriction $f:\{x\} \times \R^l \to \R$ is of tube type
and the map $\frac{\del f}{\del v}:M\times \R^l \to \R^l$ vanishes transversely.
\end{DD}

Such a function $f$ generates a Legendrian immersion in $J^1(M)$ by the assignment 
\[(x,v)\in \left\{\frac{\del f}{\del v}(x,v)=0\right\} \mapsto \left(x,\frac{\del f}{\del x}(x,v),f(x,v)\right).\]
If this map is an embedding with image $L$, we say that $L$ is \emph{generated by} $f$.

The generating functions of tube type are generalisations of the more traditional generating functions quadratic at infinity
which correspond to the case where $q$ is a non-degenerate quadratic form.

For Legendrian submanifolds $L$ which lift closed exact Lagrangian submanifolds of $T^* M$,
an existence result for generating functions was proved in \cite{ACGK} (and reformulated in this quadratic setting in \cite{AACK}).
However, the generating functions produced there are in general \emph{twisted} by a cocycle of non-degenerate quadratic forms.
\begin{TT}\label{thm:acgk}\cite{ACGK, AACK}
Let $M$ be a closed manifold, $L$ a closed Legendrian submanifold of $J^1M$ which projects injectively to $T^*M$ and $g_L:L\to M$ the projection.
There exists 
\begin{itemize}
\item a finite totally ordered open cover $(M_i)_{i\in I}$
\item integers $n_i\in \N$, 
\item generating functions of tube type $f_i:M_i\times \R^{n_i}\to \R$ generating $L_i=g_L^{-1}(M_i)$,
\item fiberwise non-degenerate quadratic forms
$q_{ij}:M_i\cap M_j \times \R^{n_j-n_i} \to \R$ for all $i<j$
\end{itemize}
 such that
for all $i<j$, $f_i\oplus q_{ij}=f_j$ on $(M_i\cap M_j) \times \R^{n_j}$ (and in particular $q_{ij}\oplus q_{jk}=q_{ik}$ over $M_i\cap M_j\cap M_k)$.
\end{TT}

\begin{RR}
Technically speaking, in \cite{AACK} the twisted generating function is constructed for a Legendrian submanifold $L'$ which is
Legendrian isotopic to $L$. However, twisted generating functions persist under Legendrian isotopy as demonstrated in \cite[Theorem 3.9]{ACGK} in the
linear at infinity setting (the proof works verbatim in the quadratic setting, see \cite[Remark 3.35]{AACK}).
\end{RR}

In \cite{ACGK} it is proved that the \emph{twisted difference function}  $(U_i,K_i=f_i\oplus (-f_i), q_{ij}\oplus (-q_{ij}))$ can be untwisted (see \cite[Lemma 3.21]{ACGK}), namely there exists fiberwise non-degenerate quadratic form $Q_i$ over $U_i$ such that $K_i\oplus Q_i=K_j\oplus Q_j$ over $U_{ij}$ (this comes from the fact that $q_{ij}\oplus (-q_{ij})$ is nullhomotopic as a map from $U_{ij}$ to the space of non-degenerate quadratic forms). Hence we obtain a global difference function $K:M\times \R^N \to \R$ with the following properties:
\begin{enumerate}
    \item $K$ is Morse-Bott with critical locus diffeomorphic to $L$,
    \item each restriction $K_x:\R^l\to \R$, for $x\in M$, is of tube type.
\end{enumerate}

The parametrised versions of these results can be deduced directly as follows.
Let $B$ be a compact manifold and $L\to B$ a bundle of closed Legendrian submanifolds which project injectively to $T^* M$. In view of Lemma~\ref{LL:biglegendrian}, $L$ lifts uniquely to a Legendrian submanifold $L'\subset J^1(M\times B)$, and the projection $L'\to T^*(M \times B)$ is injective. Next we observe that if $f':M\times B\times \R^l \to \R$ is a generating function for $L'$
then $f'_b:M\times \R^l\to \R$ is a generating function for $L_b$ for each $b\in B$.

The only issue is that $B$ may have boundary so we need one more step to apply Theorem~\ref{thm:acgk}.
Consider the double manifold $N=M\times (B\cup_{\del B} B)$ and the double Legendrian submanifold $L''\subset J^1(N)$
(after smoothing near $\del B$) which projects injectively to $T^*N$. We may then apply Theorem~\ref{thm:acgk}
and restrict everything to $M\times B \subset N$ to obtain the following datum:

\begin{itemize}
    \item a directed open cover $(U_i)_{i\in I}$ of $M\times B$,
    \item a generating function of tube type $f_i:U_i\times \R^{n_i}\to \R$ for $L'$ over $U_i$,
    \item a fiberwise non-degenerate quadratic form $q_{ij}:U_{ij}\times \R^{n_j-n_i} \to \R$ over $U_{ij}$,
\end{itemize}
satisfying for all $i<j$, over $U_i\cap U_j$,
\[f_i\oplus q_{ij}=f_j.\]
For each $b\in B$, the restriction $(M_i^b=U_i\cap (M\times\{b\}), f_i^b, q_{ij}^b)$ is a twisted generating function for $L^b$.
As above, the difference function can be untwisted and therefore we obtain a global function with Morse-Bott critical locus diffeomorphic to $L$.
The properties of this function that we will use are summarised in the following proposition. In fact we will not
need anything else from generating functions to prove our main result.

        \begin{TT}\label{prop:1}
Let $\{L_b\}_{b\in B}$ be a smooth family of nearby Lagrangian submanifolds of $T^* M$. There is a smooth family of functions $\{K_b: M \times \bR^l \to \bR\}_b$ such that:
            \begin{enumerate}
                \item Each $K_b$ is Morse-Bott.
                \item \label{prop1: pt 2} Each critical locus $\operatorname{Crit}(K_b)$ is diffeomorphic to $L_b$, such that the following diagram commutes:
                 \begin{equation*}
                    \begin{tikzcd}
                        \operatorname{Crit}(K_b) 
                        \arrow[rr, "\cong"]
                        \arrow[dr]
                        &&
                        L_b
                        \arrow[dl]
                        \\
                        &M&
                    \end{tikzcd}
                \end{equation*}
                \item The fibrewise negative eigenbundle of $\{K_b\}_b$ along $\{L_b\}$, viewed as a family of vector bundles over $\{L_b\}_b$ (or equivalently as a single vector bundle over the total space $L$), is trivial and of even rank $2k$.
                \item $l \gg n+2k$.
                \item Each $K_b$ is fibrewise of tube type.
            \end{enumerate}
            We call each $K_b$ a \emph{difference function of tube type}.
        \end{TT}

\begin{proof}
The construction of $K$ explained above has all properties except maybe for the two last ones.
Let $E_b$ be the (possibly non-trivial) negative eigenbundle of $L_b$ with respect to the Morse-Bott function $K_b$. Since $g_b:L_b\to M$ is a homotopy equivalence,
there are families of vector bundles $E_b'$ and $E_b''$ on $M$ such that $E_b'\oplus E_b'' \simeq M \times \R^m$ and $g_b^* E_b' \oplus E_b$ is trivial
of rank $2k$.
We then define $K':M\times B\times \R^m\times \R^l\to \R$ by the formula
\[K'(x,b,u',u'',v)=K(x,b,v)-|u'|^2+|u''|^2.\]
Then $K_b'$ is still Morse-Bott with critical locus $L_b$ and the negative eigenbundle of $L_b$ with respect to $K'_b$ is now trivial by construction.
The condition $l'=m+l\gg n+2k$ can be achieved by stabilizing $E''_b$ as much as necessary.
\end{proof}

