        \end{equation}
        These form a smooth fibre bundle $\{Z_b\}_b$ over $B$, with a smooth family of inclusions of boundary components $\{u_b: M \times S^{2k-1} \times S^{l-2k-1} \hookrightarrow Z_b\}_b$. By Lemma \ref{lem:codim3hcob} each $Z_b$ is an $h$-cobordism on $M \times S^{2k-1} \times S^{l-2k-1}$.
        \begin{LL}
            Each $\pi_{M,b}|_{Z_b}: Z_b \to M$ is a smooth fibre bundle.
        \end{LL}
        \begin{proof}
            Each $\pi_{M,b}: \partial_- A_{M,b} \to M$ is a smooth fibre bundle, and by Corollary \ref{cor: tub nbds}, each $\operatorname{Im}(u_b)$ is a smooth subbundle.
        \end{proof}

        We now choose a fixed point $x_0 \in M$. We set $Y_b = (\pi_{M,b}|_{Z_b})^{-1}\{x_0\}$ to be the fibre of $Z_b$ over $x_0$; these together form a smooth fibre bundle $\{Y_b\}_b$ over $B$ with each fibre an $h$-cobordism on $S^{2k-1} \times S^{l-2k-1}$. By Proposition \ref{prop: tot hcob param}, there is a smooth family of diffeomorphisms 
        \begin{equation}\label{eq: erwdsghdrgg}
            \{Z_b \cong M \times Y_b\}_b
        \end{equation}
        relative to $M \times S^{2k-1} \times S^{l-2k-1}$ (note that these diffeomorphisms need not be fibred over $M$ though).
        Choose a small (codimension 0) embedding $u: D^{l-2} \hookrightarrow S^{2k-1} \times S^{l-2k-1}$. By Corollary \ref{cor: conn est}, for $l \gg 0$ large enough there is a smooth family of $h$-cobordisms on $D^{l-2}$, which we call $\{V_b\}_b$ (in particular, this includes the data of a smooth family of embeddings into the boundary $\{D^{l-2} \hookrightarrow V_b\}_b$), along with a smooth family of diffeomorphisms:
        \begin{equation}
            \left\{Y_b \cong \left(S^{2k-1} \times S^{l-2k-1} \times [0,1] \right) \cup_{\operatorname{Im}(u) \times \{1\}} V_b \right\}_b
        \end{equation}
        Using (\ref{eq: erwdsghdrgg}) and by gluing $M \times S^{2k-1} \times D^{l-2k}$ back in along its boundary, we obtain:
        \begin{CC}\label{cor: phi}
            There is a smooth family of diffeomorphisms $\{\phi_b\}_b$:
            \begin{equation}
                \left\{\phi_b: \partial_- A_{M,b} \to M \times \left( (S^{2k-1} \times D^{l-2k}) \cup_{\operatorname{Im}(u)} V_b\right)\right\}_b
            \end{equation}
            such that for each $b$, $\phi_b \circ s_{M,b}$ is the inclusion $M \times S^{2k-1} \hookrightarrow M \times \left((S^{2k-1} \times D^{l-2k}) \cup V_b\right)$ of the zero-coordinate of $D^{l-2k}$: in particular, the image of $\phi_b \circ s_{M,b}$ does not touch $V_b$.

        \end{CC}

    \subsection{Reduction to a product $h$-cobordism}
        Choose a smooth family of retractions $\{r_b: V_b \to D^{l-2}\}_b$. Let $p_{12}: M \times S^{2k-1} \times D^{l-2k} \to M \times S^{2k-1}$ be the projection map to the first two factors, let $q_b = p_{12} \circ r_b: V_b \to M \times S^{2k-1}$, and set
        \begin{equation}
            p_{M,b} = q_b \circ \phi_b: \partial_- A_{M,b} \to M \times S^{2k-1}
        \end{equation}
        Then $\{p_{M,b}\}_b$ is a smooth family of maps, but each $p_{M,b}$ is not necessarily a fibre bundle.
        \begin{RR}
            Each $s_{M,b}$ is a section of $p_{M,b}$:
            \begin{align*}
                p_{M,b} \circ s_{M,b} 
                &= q_b \circ \phi_b \circ s_{M,b}
                \\
                &= \operatorname{Id}_{M \times S^{2k-1}}
            \end{align*}
            The first equality is by definition and the second is by Corollary \ref{cor: phi}.
        \end{RR}
        We define 
        \begin{equation}
            \iota_b = \phi_b \circ j_b \circ s_{L,b}: L_b \times S^{2k-1} \hookrightarrow M \times \left( (S^{2k-1} \times D^{l-2k}) \cup_{\operatorname{Im}(u)} V_b\right)
        \end{equation}
        These form a smooth family of embeddings $\{\iota_b\}_b$.

        \begin{LL}
            Assume $l \gg 0$. Then $\{\iota_b\}_b$ is isotopic (through smooth families of embeddings) to a smooth family of embeddings $\{\psi_b\}_b$ of the form
            \begin{equation}
                \psi_b: (x, s) \mapsto (g_b(x), s, h_b(x))
            \end{equation}
            for some smooth family of embeddings $\{\theta_b = (g_b, h_b): L_b \hookrightarrow M \times (D^{l-2k})^\circ \}_b$.
        \end{LL}
        Note that each $\psi_b$ does not hit $V_b$.
        \begin{proof}
            By homotopy commutativity of (\ref{eq:6}), there is a smooth family of homotopies $\{s_{M,b} \circ g'_b\}_b \simeq \{j_b \circ s_{L,b}\}_b$. Composing with $p_{M,b}$, we find that $\{g'_b\}_b \simeq \{q_b \circ \iota_b\}_b$. 

            Since $g'_b = g_b \times \operatorname{Id}_{S^{2k-1}}$, and $q_b$ is a homotopy equivalence, this implies that the family of embeddings $\{\iota_b\}_b$ is homotopic to a family of maps (but not necessarily embeddings) $\{\psi_b\}_b$ of the desired form (one may take any choice of $h_b: L_b \to (D^{l-2k})^\circ$, since the disc is contractible). By assuming $l \gg 0$ is sufficiently large, we can generically perturb both $\{\theta_b\}_b$ and the homotopy so that they are embeddings, as required.
        \end{proof}




        By Lemma \ref{lem: disc bun L}, $\{\phi_b \circ j_b(\partial_- A_{L,b})\}_b$ is a smooth family of tubular neighbourhoods of $\{\operatorname{Im}(\iota_b)\}_b$. By isotopy extension, there is a smooth family of embeddings $\{j'_b: \partial_- A_{L,b} \hookrightarrow \partial_- A_{M,b}\}_b$, such that $\{\phi_b \circ j'_b(\partial_- A_{L,b})\}_b$ form a smooth family of tubular neighbouhoords of $\{\operatorname{Im}(\psi_b)\}_b$. Since isotopic submanifolds have diffeomorphic complements, we find:
        \begin{CC}\label{cor: Wb simplify}
            There is a smooth family of diffeomorphisms
            \begin{equation}
                \left\{ W_b \cong \left( M \times \left( (S^{2k-1} \times D^{l-2k}) \cup_{\operatorname{Im}(u)} V_b \right) \right) \setminus \operatorname{Im}(\phi_b \circ j'_b)\right\}_b
            \end{equation}
            restricting to the natural diffeomorphism $\phi_b \circ j'_b \circ j_b^{-1}$ between the boundary components $\{j_b(\partial(\partial_- A_{L,b}))\}_b$ and $\{\phi_b \circ j'_b(\partial(\partial_- A_{L,b}))\}_b$
        \end{CC}

        Since $\psi_b = \theta_b \times Id_{S^{2k-1}}$ splits as a product, this admits a smooth family of tubular neighbourhoods $\{T_b \times S^{2k-1} \}_b$, where $\{T_b \subseteq M \times (D^{l-2k})^\circ\}_b$ is a smooth family of tubular neighbourhoods of the embeddings $\{\theta_b\}_b$. By Lemma \ref{lem:codim3hcob}, the complement of each $T_b$ in $M \times D^{l-2k}$ is an $h$-cobordism.
        By uniqueness of tubular neighbourhoods and Corollary \ref{cor: Wb simplify}, we find:
        \begin{CC}\label{cor: hcob is prod}
            There is a smooth family of diffeomorphisms
            \begin{equation}
                \left\{ W_b \cong \left( (M \times D^{l-2k}) \setminus T_b \right) \times S^{2k-1} \cup_{M \times \operatorname{Im}(u)} M \times V_b\right\}_b
            \end{equation}
        \end{CC}
        \begin{proof}[Proof of Theorem \ref{thm:mainoverB}]
            By Corollary \ref{cor: hcob is prod} and Theorem \ref{thm: prod decomp} (and the fact $\chi(S^{2k-1}) = 0$), we obtain a smooth family of diffeomorphisms
            \begin{equation}
                \left\{W_b \cong \partial (\partial_- A_{L,b}) \times [0,1] \cup_{\operatorname{Im}(v)} M \times V_b\right\}
            \end{equation}
            where $v_b: M \times D^{l-2} \hookrightarrow \partial(\partial_- A_{L,b})$ is given by composing $\Id_M \times u$ with the corresponding diffeomorphism. The embeddings $\{v_b\}$ are such that the composition of $v_b$ with $g_b \circ \pi_{L,b}$ is homotopic to the projection $M \times D^{l-2} \to M$, smoothly in $b$. 

            Gluing back in $\{\partial_- A_{L,b}\}_b$, we obtain a smooth family of diffeomorphisms 
            \begin{equation}\label{eq: aaa}
                \left\{\partial_- A_{M,b} \cong \partial_- A_{L,b} \cup_{\operatorname{Im}(v)} M \times V_b\right\}_b
            \end{equation}
            such that the induced embedding $\partial_- A_{L,b} \to \partial_- A_{M,b}$ is isotopic to the family $j_b$.

            Let $\{V'_b\}_b$ be a smooth family of inverses for $\{V_b\}_b$.
            Let $\{v'_b: M \times D^{l-2} \hookrightarrow \partial(\partial_- A_{L,b})\}_b$ be a smooth family of embeddings which is a small perturbation of $\{v_b\}_b$ off itself. Then gluing $\{V'_b\}_b$ into (\ref{eq: aaa}) along $\{\operatorname{Im}(v'_b)\}$ gives a family of diffeomorphisms
            \begin{equation}
                \partial_- A_{M,b} \cup_{\operatorname{Im}(w_b)} (M \times V'_b) \cong \partial_- A_{L,b}
            \end{equation}
            isotopic to the embeddings $j_b:\partial_- A_{L,b} \to \partial_- A_{M,b}$, 
            where $w_b: M \times D^{l-2} \hookrightarrow \partial_- A_{M,b}$ is the composition of $v'_b$ with the inverse of \ref{eq: aaa}.
Recall $A_{M,b}$ is endowed with a function $K_b$ which has no critical point outside of $A_{L,b}$. In particular its vertical boundary $\del^v A_{M,b}$
is trivialised as $\del(\del_- A_{M,b})\times I$ using the flow of $\nabla K_b$. We can thus glue $V'_b\times I$ along the vertical boundary of $A_{M,b}$
to obtain another disk bundle $A'_{M,b}$:
\[A'_{M,b}=A_{M,b}\cup_{\del^v A_{M,b}} V_b'\times I.\]
As we have shown above, the family of embeddings $j_b:\del_- A_{L,b} \to \del_- A'_{M,b}$ induced by the flow of $-\nabla K_b$ is isotopic to a diffeomorphism and it follows that $A_{L,b}\to A'_{M,b}$ is also isotopic to a diffeomorphism. Indeed we construct this isotopy in two steps.  First saturate $A_{L,b}$ under the flow of $\nabla K_b$ by an isotopy so that after the isotopy $\del_+ A_{L,b}\subset \del_+ A_{M,b}$ and $\del_- A_{L,b}\subset \del_- A_{M,b}$. Second consider the product of the isotopy $\del_- A_{L,b} \to \del_- A_{M,b}$ by the vertical $I$-factor obtained by flowing along $\nabla K_b$.


            The composition $\{p_{M,b} \circ w_b\}_b$ is homotopic to the projection $M\times D^{l-2} \to M$, so for $l \gg 0$, $\{w_b\}_b$ is isotopic to the embedding $\operatorname{Id}_M \times i$, where $i$ is as in the statement of Theorem \ref{thm:mainoverB}.
So we obtain the required family of diffeomorphims with $E_b=A_{L,b}$ (after smoothing corners). Finally we observe that the diagram \eqref{eq:mainoverB} homotopy commutes by construction.
        \end{proof}

\section{Mapping class groups of tori}\label{sec: mcg}

    In this section, we use Hatcher and Hsiang-Sharpe's computation of the mapping class groups of high-dimensional tori to prove Corollary \ref{cor: mcg tori}.
\subsection{Background on automorphism groups}  
    We begin by quickly recapping some notions from the study of high-dimensional geometric topology. We refer to \cite[Section 1]{WW:I} for a more comprehensive introduction to the subject, and to \cite[Section 2.2]{HLLOR} for more a precise definitions of block automorphism spaces. Let $M$ be a closed manifold.
\subsubsection*{Important spaces}
    \begin{DD}\label{def:spac}
        \begin{itemize}
            \item We write $G(M)$ for the space of homotopy autoequivalences of $M$.
            \item We write $\Diff(M)$ for the space of self-diffeomorphisms of $M$. 
            \item We write $\Top(M)$ for the space of self-homeomorphisms of $M$.
            \item We write $\widetilde{\Diff}(M)$ for the \emph{block diffeomorphism group} of $M$. Roughly, this is (the realisation of) the semisimplicial group $\widetilde{\Diff}(M)_\bullet$ whose $k$-simplices $\widetilde{\Diff}(M)_k$ consist of the set of self-diffeomorphisms of $M \times \Delta^k$, which are required to respect the boundary stratification coming from that of $\Delta^k$, and behave nicely in collar neighbourhoods . 

            This should be compared to a similar model for $\Diff(M)$, given by the realisation of a semisimplicial group defined the same except restricting to diffeomorphisms which are compatible with the projection map to $\Delta^k$.
            \item We write $\widetilde{\Top}(M)$ for the \emph{block homeomorphism group} of $M$, defined analogously to $\widetilde{\Diff}(M)$.
            \item The \emph{smooth structure space} of $M$ is $\cS(M) := G(M) / \Diff(M)$.
            \item The \emph{topological structure space} of $M$ is $\cS^{\Top}(M) := G(M) / \Top(M)$.
        \end{itemize}
        The groups $G(M)$, $\Diff(M)$ and $\Top(M)$ we will often treat as simplicial groups, whose $k$-simplices are automorphisms (in the appropriate category) of $\Delta^k \times M$ which are compatible to the projection to $\Delta^k$.
    \end{DD}
    The \emph{parametrised Whitehead torsion} can be constructed as a map $\cS(M) \to \cH(M)$, see Remark~\ref{rem:spacelevelw} or \cite[Section 1.5]{WW:Survey}.


    Note that $\Diff(M)$ includes into $\widetilde{\Diff}(M)$ in a natural way (and $\Top(M)$ into $\widetilde{\Top}(M)$ similarly). Essentially by definition, there are homotopy fibration sequences:
    \begin{equation}\label{eq: fib 1}
        \Diff(T^n) \to G(T^n) \to \cS(T^n)
    \end{equation}

    \begin{equation}\label{eq: fib 2}
        \widetilde{\Diff}(M) / \Diff(M) \to G(M)/\Diff(M) = \cS(M) \to G(M)/\widetilde{\Diff}(M)
    \end{equation}

    \begin{equation}\label{eq: fib 2 TOP}
        \widetilde{\Top}(M) / \Top(M) \to G(M)/\Top(M) = \cS^\Top(M) \to G(M)/\widetilde{\Top}(M)
    \end{equation}
    The map including diffeomorphisms into homeomorphisms induces a map from (\ref{eq: fib 2}) to (\ref{eq: fib 2 TOP}). We write $c$ for the first map in (\ref{eq: fib 2}). The second map in (\ref{eq: fib 2}) uses the identification $\widetilde G(M) \simeq G(M)$, where $\widetilde G(M)$ is the semisimplicial group of block homotopy autoequivalences of $M$.

    \begin{RR}
        It is convenient to work with the following model for $\widetilde{\Diff}(M)/\Diff(M)$, and similarly for the other quotients of semisimplicial groups we encounter. We define a classifying space $B\widetilde{\Diff}(M)$ using a bar construction (see \cite[Section 2]{Ebert-Randal-Williams} for a more precise definition). We then define the quotient $\widetilde{\Diff}(M)/\Diff(M)$ to be the homotopy fibre of the induced map $B\widetilde{\Diff}(M) \to B\Diff(M)$.
    \end{RR}

    \begin{RR}
        The space $\widetilde{\Diff}(M) / \Diff(M)$ can be analysed (in a range) using pseudoisotopy theory, following Weiss-Williams \cite{WW:I} and Hatcher \cite{Hat78}. The space $G(M)/\widetilde{\Diff}(M)$ can be analysed using surgery theory. Together, this comprises the surgery-pseudoisotopy approach to understanding the homotopy type of diffeomorphism groups.
    \end{RR}

    \begin{DD}
        We define the \emph{topological $h$-cobordism space of $M$}, $H^\Top(M)$, exactly the same as $H(M)$ in Section \ref{sec: hcob}, except we allow topological rather than smooth $h$-cobordisms. 

        The stabilisation map $H^\Top(M) \to H^\Top(M \times I)$ is defined similarly to the smooth case, and the \emph{stable} topological $h$-cobordism space is defined to be the colimit over $k$ of $H^\Top(M \times I^k)$. 

        The \emph{topological parametrised Whitehead torsion} $w^\Top: \cS^\Top(M) \to \cH^\Top(M)$ is defined identically to the smooth setting.
    \end{DD}
    From the definitions, we have:
    \begin{LL}
        The following diagram commutes:
        \begin{equation}
            \begin{tikzcd}
                \cS(M) 
                \arrow[r]
                \arrow[d, "w"]
                &
                \cS^\Top(M)
                \arrow[d, "w^\Top"]
                \\
                \cH(M) 
                \arrow[r]
                &
                \cH^\Top(M)
            \end{tikzcd}
        \end{equation}
    \end{LL}


\subsubsection*{Pseudoisotopy theory}
    \begin{DD}\label{DD:pseu}
        A \emph{pseudoisotopy of $M$} is a diffeomorphism $F: M \times I \to M \times I$ which is required to be the identity over $M \times \{0\}$ (and also over $\partial M \times I$ if $M$ has boundary)\footnote{This should be compared to an \emph{isotopy}, which is defined similarly, but is required to respect the projection maps to $I$ on each side.}. We write $P(M)$ for the space of pseudoisotopies on $M$; this is a group under composition.

        Similarly to the case of $h$-cobordisms, there is a stabilisation map $\sigma: P(M) \to P(M \times I)$ sending $F$ to $F \times \Id_I$ (and then unbending corners appropriately, see \cite[Figure 1]{Hat78}). 

        We define the \emph{stable pseudoisotopy space} via
        \begin{equation}
            \cP(M) := \operatorname{colim}_k P(M \times I^k)
        \end{equation}
    \end{DD}
    \begin{RR}
        In the literature, pseudoisotopies are also known synonymously as \emph{concordances}.
    \end{RR}
    \begin{LL}
        There is a homotopy equivalence $P(M) \simeq \Omega H(M)$.

        This is compatible with stabilisation, and in particular there is a homotopy equivalence $\cP(M) \simeq \Omega \cH(M)$.
    \end{LL}
    \begin{proof}[Sketch proof]
        A based loop of $h$-cobordisms gives a fibre bundle $E$ over $S^1$, with fibre over $1$ identified with $M \times I$, along with an inclusion of fibre bundles $M \times I \to E$ into the boundary. Monodromy around $S^1$ then gives a diffeomorphism $M \times I \to M \times I$ which is a pseudoisotopy. Conversely, given a pseudoisotopy $F$ of $M$, its mapping torus is a loop of $h$-cobordisms on $M$. These constructions can be upgraded to give an inverse pair of homotopy equivalences.
    \end{proof}
    For $M$ of dimension at least 5, there is an involution $\tau$ on $h$-cobordism spaces $H(M)$, defined to send an $h$-cobordism $W$ on $M$ to (a choice of) classical inverse $W'$, viewed as an $h$-cobordism on $M$ (cf. \cite{WW:I}, \cite[Section 5]{Munoz-Echaniz}).
    \begin{RR}\label{RR:6654rter9098ygt}
        $\tau$ induces an involution on $\pi_1 H(M) = \pi_0 P(M)$; it will help to have an explicit description of this. Let $i: I \to I$ be the reflection $t \mapsto 1-t$.

        For a pseudoisotopy $F: M \times I \to M \times I$ from $g$ to the identity, $\tau(F)$ is obtained by inverting $F$, reflecting in the $I$-direction, and composing with an appropriate isotopy so that $F$ is still the identity over $0 \in I$. 

        More explicitly, $\tau(F) = (g \times i) \circ F^{-1} \circ (\Id_M \times i)$.
    \end{RR}
    \begin{LL}[{\cite[Appendix I]{Hat78}, \cite[Lemma B.1]{Munoz-Echaniz}}]\label{lem: stab sign}
        Up to homotopy, the involution $\tau$ anticommutes with the stabilisation map $\sigma$; explicitly, the map:
        \begin{equation}
            \tau \circ \sigma + \sigma \circ \tau: H(M) \to H(M \times I)
        \end{equation}
        is nullhomotopic.
    \end{LL}
    \begin{DD}
        Let $B$ be a compact manifold. We define an involution $\tau^{st}: \cH_B(M) \to \cH_B(M)$ on the stable $h$-cobordism space to be given by $(-1)^k \cdot \tau: H_B(M \times I^k) \to H_B(M \times I^k)$ on each unstable $h$-cobordism space $H_B(M \times I^k)$ (for $k \geq 6$ so that $H_B(M \times I^k)$ admits a homotopy group structure).
    \end{DD}

    Lemma \ref{lem: stab sign} implies $\tau^{st}$ is well-defined on $\cH_B(M)$ (and in particular is the reason for the sign in the definition).

    \begin{RR}
        By incorporating a choice of homotopy from Lemma \ref{lem: stab sign}, $\tau^{st}$ can be extended to a space-level homotopy involution on $\cH(M)$ (cf. \cite[Section 5.2]{Munoz-Echaniz}). However this is not necessary for our purposes.
    \end{RR}

    Let $h: \pi_0 P(M) \to \pi_1 \widetilde{\Diff}(M)/\Diff(M)$ be defined as follows. Let $[F] \in \pi_0 P(M)$ be a class, and $F$ a representative. Then $F: M \times I \to M \times I$ determines a 1-simplex in $\widetilde{\Diff}(M)$ with boundary on $\Diff(M)$, and so we may define $h([F])$ to be the corresponding element of $\pi_1 \widetilde{\Diff}(M)/\Diff(M)$.
    \begin{RR}
        The map $h$ is exactly the edge homomorphism $E^1_{00} \to E^\infty_{00}$ in the Hatcher spectral sequence \cite[Section 3]{Hat78} for $\pi_{*+1}\widetilde{\Diff}(M)/\Diff(M)$.
    \end{RR}
    \begin{LL}
        $h$ is surjective.
    \end{LL}
    \begin{proof}

        It follows from \cite[Propositions 2.3 and 2.7]{Ebert-Randal-Williams} (applied to the standard simplicial circle) that any based loop in $\widetilde{\Diff}(M)/\Diff(M)$ is represented by some block diffeomorphism $F: M \times I \to M \times I$.

        Setting $f := (F_0: M \to M)$, we obtain a pseudoisotopy $F' := f^{-1} \circ F$, and $h([F'])$ represents the same class as $F$ in $\pi_1$.
    \end{proof}
    \begin{PP}\label{lem: w on P}
        The following diagram commutes.
        \begin{equation}
            \begin{tikzcd}
                \pi_0 P(M) 
                \arrow[rr, "y \mapsto y+\tau^{st}(y)"]
                \arrow[d, "h"]
                &&
                \pi_0 \cP(M)
                \arrow[d, "\cong"]
                \\
                \pi_1 \widetilde{\Diff}(M)/\Diff(M)
                \arrow[r, "c"]
                &
                \pi_1 \cS(M)
                \arrow[r, "w"]
                &
                \pi_1 \cH(M)
            \end{tikzcd}
        \end{equation}
    \end{PP}
    \begin{proof}
        Let $F \in P(M)$. Consider the map $F \times 0: M \times I \to M \times D^1 \times I$. This is homotopic to the embedding $Q: M \times I \to M \times D^1 \times I$ defined by:
        \begin{equation}
            Q(x, t) = (F(x, t)-t, t)
        \end{equation}
        $Q$ respects the projection maps to $I$ and is an embedding. The image of $Q$ splits $M \times D^1 \times I$ into two components, one component $U^+_t = (U^+_t)_{t \in [0,1]}$ containing $M \times \{1\} \times I$ and the other one $U^-_t$ containing $M \times \{-1\} \times I$. Both $U^+_t$ and $U^-_t$ fibre over the circle $S^1 := I/(0 \sim 1)$ and represent loops of trivial $h$-cobordisms from $M\times\{\pm 1\}$ to a (possibly non-trivial) bundle over $S^1$ with fiber $M$. The monodromy over $S^1$ of these bundles provide a pair of pseudoisotopies $\varphi^+$ and $\varphi^-$ on $M$.

Following the definition of the parametrised Whitehead torsion $w$, in order to compute $w\circ c\circ h([F])$ we need to glue (classical) inverses $V^-_t$, $V^+_t$ to $U^-_t$ and $U^+_t$ along $M\times \{-1\}$ and $M\times \{1\}$ respectively and stabilise by taking a product with $I$ to obtain a loop of $h$-cobordisms on $M\times D^1$.

Now by construction $U^-_t$ and $U^+_t$ are classical inverses to each other since $U^-_t\cup_{Q(M\times I)} U^+_t = M\times D^1 \times I$ so we may take $V^-_t=U^+_t$
and $V^+_t=U^-_t$. After taking product with $I$ (namely using the stabilisation $\sigma$) to complete the construction of $w$ we obtain
\begin{align*}
    w \circ c\circ h([F])
    &=[\sigma(\varphi^-)] + [\sigma(\varphi^+)]
\end{align*}
in $\pi_0 P(M\times D^1)$.

Next observe that if a loop of trivial $h$-cobordisms $U_t$ on $M$ has monodromy $\varphi \in P(M)$, then the classical inverse $V_t$ has monodromy $(g\times \Id)\circ \varphi^{-1}$ where $g \in \Diff(M)$ is the restriction of $\varphi$ to $M\times \{1\}$.
Hence, viewing $U_t^+$ as a cobordism on $M= M \times \{1\}$, because we identify $J:= [-1,0]$ with $I$ via the map $t \mapsto -t$, the monodromy is conjugated by the reflection $i(t)=1-t$ of $I$ and (similarly to Remark \ref{RR:6654rter9098ygt}) we get
\[\varphi^+=(\Id\times i)\circ(g\times \Id)\circ (\varphi^-)^{-1}\circ (\Id\times i)=\tau(\varphi^-).\]
So we obtain
\begin{align*}
    w\circ c\circ h([F])
    &=[\sigma(\varphi^-)] +[\sigma(\tau(\varphi^-))]\\
    &=[\varphi^-]+\tau^{st}[\varphi^-]
\end{align*}
in $\pi_0\cP(M)$.
Finally we compute explicitly $\varphi^-$ using the following trivialisation (as a bundle over $I$) $M \times J \times I \to U^-$:
        \begin{equation}
            (x, s, t) \mapsto \begin{cases}
                (x,s,t)
                & \textrm{ if }
                s \in [-1,-t]
                \\
                (F(x,s + t) - t, t)
                & \textrm{ if }
                s \in [-t, 0]
            \end{cases}
        \end{equation}
where $J=[-1,0]$. We obtain the monodromy $[\varphi^-]=[F]$ by setting $t=1$ (up to translating by $1$ to identify $J$ with $I$).
So we obtain the desired result:
\[w\circ c\circ h([F])=[F]+\tau^{st}([F]).\]
  \end{proof}




\subsection{Tori}
    We recap Hatcher's computation in more detail. This proceeds by first using the fibration sequence (\ref{eq: fib 1}), then studying $\cS(T^n)$ using the fibration sequence (\ref{eq: fib 2}). Up to extensions, this determines the mapping class group of $T^n$ in terms of three other groups, which are then computed individually.

    Throughout this section, we fix some $n \geq 6$; many of these computations break down in lower dimensions.

\subsubsection*{The individual pieces}
    Since $T^n$ is a $K(\pi,1)$, there is a homotopy equivalence of spaces:
    \begin{equation}
        G(T^n) \simeq T^n \times GL_n(\bZ)
    \end{equation}
    In particular, $\pi_0 G(T^n) \cong GL_n(\bZ)$ and $\pi_1 G(T^n) \cong \pi_1 T^n \cong \bZ^n$.

    From \cite[Section 3]{Siebenmann} (cf. also \cite[Section 4(5)]{Hat78}\footnote{Note the denominator of the LHS in \textit{loc. cit.} is missing a $\widetilde \cdot$.}):
    \begin{equation}\label{eq: piece 1}
        \pi_1 G(T^n)/\widetilde{\Diff}(T^n) \cong \bigoplus_{i=0}^n \left(\pi_{i+1}\Top/O\right)^{\oplus \binom{n}{i}}
    \end{equation}
    Here $\Top/O$ is the colimit over $k$ of $\Top(\bR^k)/O(k)$. This is a finite group, by \cite[Essay V, Theorem 5.5(II)]{Kirby-Siebenmann}.

    Using the computations $\pi_2 T^n \cong 0$, $Wh_2(\pi_1 T^n) \cong 0$, that $\pi_1 T^n$ is abelian and that the first $k$-invariant of $T^n$ vanishes, \cite[Theorem 3.1]{Hat78} shows that there is an isomorphism of groups:
    \begin{equation}\label{eq: piece 2.1}
        \pi_1 \cH(T^n) \cong (\bZ/2)[t_1, t_1^{-1}, \ldots, t_n, t_n^{-1}]/(\bZ/2)[1]
    \end{equation}
    The same computation applies in the topological setting, and we obtain:
    \begin{LL}[{\cite[Theorem 3.1]{Hat78}}]\label{lem: Diff Top iso}
        The map $\pi_1 \cH(T^n) \to \pi_1 \cH^{Top}(T^n)$ is an isomorphism.
    \end{LL}

    \cite[Lemma 4.3]{Hatcher-Wagoner} (see also \cite[Corollary 5.8]{Munoz-Echaniz}) identifies the involution $\tau$ on $\pi_1 \cH(T^n)$; under (\ref{eq: piece 2.1}), $\tau$ sends each $t_i$ to $t_i^{-1}$ and is extended multiplicatively (note that $\pi_1 \cH(M)$ is not in general equipped with a product, but it is convenient in this case to identify it with the underlying abelian group of a ring).
    \begin{LL}[{\cite[Theorem 3.1]{Hat78}}]\label{lem: stab P}
        The stabilisation map $\pi_0 P(T^n) \to \pi_0 \cP(T^n)$ is an isomorphism.
    \end{LL} 
    \begin{LL}
        Under the isomorphism $\pi_0 P(T^n) \cong \pi_0 \cP(T^n)$, the kernel of $h: \pi_0 P(T^n) \to \pi_1 \widetilde{\Diff}(T^n) / \Diff(T^n)$ is exactly the subgroup $I$ generated by elements of the form $x+\tau(x)$.

        In particular under (\ref{eq: piece 2.1}),
        \begin{equation}\label{eq: piece 2}
            \pi_1 \widetilde{\Diff}(T^n) / \Diff(T^n) = (\bZ/2)[t_1, t_1^{-1}, \ldots, t_n, t_n^{-1}]/((\bZ/2)[1] + I) \cong (\bZ/2)^\infty
        \end{equation}
    \end{LL}
    \begin{proof}
        This is proved in \cite[Section 2]{Hat78} using the Hatcher spectral sequence (cf. also \cite[Section 25.3]{Kupers:book}).
    \end{proof}




\subsubsection*{Reassembling the pieces}
    The map $\Diff(T^n) \to G(T^n)$ admits a homotopy section, so the long exact sequence on homotopy groups of (\ref{eq: fib 1}) splits, and so we obtain an isomorphism:
    \begin{equation}\label{eq: reassemble 1}
        \pi_0 \Diff(T^n) \cong GL_n(\bZ) \ltimes \pi_1 G(T^n) / \Diff(T^n)
    \end{equation}
    \begin{LL}[{\cite[Section 4(4)]{Hat78}}]
        The long exact sequence on homotopy groups of (\ref{eq: fib 2}) canonically splits on $\pi_1$ in the case $M=T^n$, and so we obtain an isomorphism:
        \begin{equation}\label{eq: reassemble 2}
            \pi_1 \cS(T^n)\cong \pi_1 \widetilde{\Diff}(T^n)/\Diff(T^n)\oplus \pi_1 G(T^n)/\widetilde{\Diff}(T^n)
        \end{equation}
    \end{LL}
    \begin{proof}
        Using the fact that $G(T^n)/\widetilde{\Top}(T^n)$ is contractible \cite[Theorem V.C.2(i)]{Kirby-Siebenmann}, we may combine (\ref{eq: fib 2}) and (\ref{eq: fib 2 TOP}) to obtain a commutative diagram with exact rows:

        \begin{equation}
            \begin{tikzcd}
                \ldots
                \arrow[r]
                &
                \pi_1 \widetilde{\Diff}(T^n)/\Diff(T^n)
                \arrow[d, "\cong"]
                \arrow[r]
                &
                \pi_1 G(T^n) / \Diff(T^n)
                \arrow[r]
                \arrow[d, "q"]
                &
                \pi_1 G(T^n)/\widetilde{\Diff}(T^n)
                \arrow[d]
                \arrow[r]
                &
                \ldots
                \\
                0
                \arrow[r]
                &
                \pi_1 \widetilde{\Top}(T^n)/\Top(T^n)
                \arrow[r, "\cong"]
                &
                \pi_1 G(T^n)/\Top(T^n)
                \arrow[r]
                &
                0
                &
            \end{tikzcd}
        \end{equation}
        The left vertical arrow is an isomorphism: this follows from \cite[Theorem 3.1]{Hat78}, or alternatively can be deduced from \cite[Theorem A]{WW:I}, using the fact that $\cH(T^n) \to \cH^{\Top}(T^n)$ is 1-connected. Thus the map labelled $q$ induces a splitting $g: \pi_1 G(T^n) / \widetilde{\Diff}(T^n) \to \pi_1 G(T^n) / \Diff(T^n)$.
    \end{proof}
    \begin{RR}\label{rmk: qg0}
        Note that the splitting $g$ is compatible with the splitting of the lower exact sequence $0 \to \pi_1 G(T^n)/\Top(T^n)$; in this case, this means that the composition $q \circ g$ is 0.
    \end{RR}

    Note that Theorem \ref{thm: hat} then follows from (\ref{eq: reassemble 1}), (\ref{eq: reassemble 2}), (\ref{eq: piece 1}) and (\ref{eq: piece 2}).

\subsubsection*{1-parameter Whitehead torsion}

    \begin{LL}\label{lem: w factor 1}
        Under the isomorphism (\ref{eq: reassemble 2}), $w$ is injective on the first factor.
    \end{LL}
    \begin{proof}
        From the description of $\pi_0 P(T^n) \cong \pi_0 \cP(T^n)$ in (\ref{eq: piece 2.1}) and the involution on it, we see from Proposition \ref{lem: w on P} that $w \circ c \circ h: \pi_0 P(T^n) \to \pi_1 \cH(T^n)$ has kernel $I = \ker(h)$. 

        Since $h$ is surjective, it follows that $w \circ c: \pi_1 \widetilde{\Diff}(T^n)/\Diff(T^n) \to \pi_1\cH(T^n)$ is injective.
    \end{proof}

    \begin{LL}\label{lem: w factor 2}
        Under the isomorphism (\ref{eq: reassemble 2}), $w$ vanishes on the second factor.
    \end{LL}
    \begin{proof}
        We have the following commutative diagram:
        \begin{equation}
            \begin{tikzcd}
                \pi_1 G(T^n) / \Diff(T^n)
                \arrow[d, "w"]
                \arrow[r, "q"]
                &
                \pi_1 G(T^n)/\Top(T^n)
                \arrow[d, "w^{\Top}"]
                \\
                \pi_1 \cH(T^n)
                \arrow[r]
                &
                \pi_1 \cH^{\Top}(T^n)
            \end{tikzcd}
        \end{equation}
        The bottom horizontal arrow is an isomorphism by Lemma \ref{lem: Diff Top iso}. Since $w^{\Top} \circ q \circ g$ vanishes (cf. Remark \ref{rmk: qg0}), this implies $w \circ g$ also vanishes, as desired.
    \end{proof}

    \begin{proof}[Proof of Corollary \ref{cor: mcg tori}]
        Let $\phi$ be as in the statement of Corollary \ref{cor: mcg tori}. The projection from $\pi_0 \Diff(T^n)$ to $GL_n(\bZ)$ is given by the action on $H_1(T^n)$, so since $\phi$ is homotopic to the identity, $[\phi]$ must project to 0 in the first factor.

        Since $\phi$ is homotopic to the identity, $[\phi]$ lifts to a class $\widetilde \phi \in \pi_1 \cS(T^n)$. The set of such lifts is exactly the image of the map $\pi_1 G(T^n) \to \pi_1 \cS(T^n)$; since $\pi_1 \Diff(T^n) \to \pi_1 G(T^n)$ is surjective, this image vanishes, meaning the lift is unique.

        By Corollary \ref{cor: main}, $w(\widetilde \phi)$ vanishes. By Lemmas \ref{lem: w factor 1} and \ref{lem: w factor 2}, under (\ref{eq: reassemble 2}) the first factor of $\widetilde \phi$ must vanish.
    \end{proof}

