    \caption{The canonical labeling for a binary tree $T$ of depth 2 with 7 vertices. The Kleene-Brouwer order on these vertices of $T$ induces the coordinate order of the distance vectors $\vec{l}$ in the tree distance set $\Delta^T(X)\subset \R^6$.}
    \label{fig:kleene-brouwer}
\end{figure}
We now state our main result in $\R^2$ as the following Theorem \ref{thm:tree}, which we prove in \S \ref{sec:tree}. Furthermore, the same proof in \ref{cor:2-chain-hausdorff-dimension-zero} gives a construction of a Cantor set in $\R^2$ of Hausdorff dimension 1 whose $T$ distance set has nonempty interior for a given finite tree $T$.

\begin{theorem}[Finite trees on subsets of $\R^2$]\label{thm:tree}\index{}
For each Cantor set $K \subset \mathbb{R}$ and finite tree $T$, there exists a Cantor set $\widetilde{K} \subset \R$ such that $\left( \Delta^T_{y} (K \times \widetilde{K} ) \right)^\circ \neq \varnothing$ for some $y\in K\times \widetilde{K}$.
\end{theorem}
\begin{corollary}[]\label{cor:tree-hausdorff-dimension-zero}\index{}
For any finite tree $T$, there exists a Cantor set $C\subset \R^2$ such that $\dim_{\rm H}(C)=1$ and the pinned tree distance set $\Delta^T_{y} (C)$ has nonempty interior for some $y\in C$.
\end{corollary}


\subsection{Generalization to $\R^d$ and to other types of distances}

In this section, we generalize previous results to $\R^d$ and to generalized distances. 
We first generalize distances to maps satisfying certain derivative conditions, following \cite{McDonald-Taylor-finite-point-configurations}.

\begin{definition}[]\label{def:derivative-condition}\index{}
Let $\phi:\R^d\times \R^d \to \R$, $X\subset \R^d$, and $T$ be a finite tree.
\begin{enumerate}
\item $\phi$ is said to satisfy the \textit{derivative condition} if there exists a nonempty open set $\mathcal{U}\subset \R^{d}$ such that for every pair of distinct points $a, b\in \mathcal{U}$, there exist nonempty open subsets $A, B \subset \mathcal{U}$ such that $a\in A$, $b\in B$, and
\begin{align}\label{eq:derivative-condition}
\frac{\partial \phi (x,y)}{\partial y_{i}} \neq 0 \quad \quad \forall (x,y)\in A\times B \quad \forall i\in \{1,\cdots, d\}.
\end{align}
\item If $\phi$ satisfies the derivative condition, we define:
\begin{enumerate}
\item \textit{$\phi$ distance set} as $\Delta^\phi (X) = \{ \phi (x,y): x, y\in X \}$;
\item \textit{pinned $\phi$ distance set} with pin $x\in X$ as $\Delta^\phi_x (X) = \phi (x, X) = \{ \phi (x,y): y\in X \}$;
\item \textit{$(\phi,T)$ distance set} as 
\begin{equation*}
\Delta^{\phi,T} (X)= \{ (\phi (x^\tau, x^\sigma) )_{\tau \sim \sigma}: \tau, \sigma \in T, \ \{x^\tau \in X\}_{\tau \in T} \text{ distinct } \}.
\end{equation*}
\item \textit{pinned $(\phi,T)$ distance set} with a pin $x\in X$ as
\begin{equation}\label{distance T phi set}
\Delta^{\phi,T}_x (X)= \{ (\phi (x^\tau, x^\sigma) )_{\tau \sim \sigma}: \tau, \sigma \in T, \ \{x^\tau \in X\}_{\tau \in T} \text{ distinct }, x^0=x \}.
\end{equation}
\end{enumerate}
\end{enumerate}
\end{definition}

\begin{example} We give several familiar examples as special cases of $(\phi, T)$ distance sets. Let $X\subset \R^{d}$ and $T$ be a finite tree.
    \begin{enumerate}
\item (Tree distance sets) For $X\subset \R^{d}$, the tree distance set $\Delta^T (X)$ is a special case of the $(\phi, T)$ distance set $\Delta^{\phi, T}(X)$ with $\phi:\R^{d}\times \R^{d}\to \R$ given by $\phi(x,y)= |x-y|$. Note that $\phi$ satisfies the derivative condition since \eqref{eq:derivative-condition} holds for $\mathcal{U}=\R^d$ and any disjoint open subsets $A, B \subset \mathcal{U}$.
\item ($p$-norm distance sets) The above example also applies with $\phi(x,y) = |x-y|_p$, where $|\cdot |_p$ is the $p$-norm in $\R^{d}$ with $p\geq 1$.
\item (Dot product sets) The \textit{tree dot product set} of a set $X\subset \R^d$ and tree $T$ with $n$ vertices is defined by
\begin{align*}
\{ (x^\tau \cdot x^\sigma)_{\tau\sim \sigma} : \{x^\tau\}_\tau  \text{ are distinct points in } X\}\subset \R^{n-1},
\end{align*}
where $x\cdot y = \sum_{i=1}^d x_i y_i$. If $T$ is a $1$-chain, then we recover the usual dot product set of $X\subset \R^{d}$ defined by $\{x\cdot y : x, y\in X\}$. By choosing $\mathcal{U}$ to be an open subset in $\R^{d}$ not containing $0$, we see that $\eqref{eq:derivative-condition}$ holds for all open subsets $A,B$ of $\mathcal{U}$.
\end{enumerate}
\end{example}

Furthermore, our key Lemma \ref{lem:pin-wiggling} in $\R$ for distance sets readily generalizes to $\R^d$ and for maps that satisfy the derivative conditions.
\begin{lemma}[Pin wiggling lemma in higher dimensions]\label{lem:pin-wiggling-Rd}
Let $\phi:\R^{2d}\times \R^{2d}\to \R$ be a map that satisfies the derivative condition, $K\subset \R^d$ be a Cantor set, $v=(v_1,v_2)\in \R^d\times \R^d$, and $Q\subset \text{conv}(K)$ be a nonempty open cube such that $K\cap Q\neq \varnothing$. Then, there exist a Cantor set $\widetilde{K}\subset Q$ with $|\widetilde{K}|>|K|$ and an open neighborhood $\mathcal{U}_v\subset \R^{2d}$ of $v$ such that
\begin{align*}
\left( \bigcap_{z\in \mathcal{U}_v} \phi (z, K\times \widetilde{K}) \right)^\circ \neq \varnothing.
\end{align*}
\end{lemma}

Using Lemma \ref{lem:pin-wiggling-Rd}, we obtain the most general result of this paper, Theorem \ref{thm:tree-Rd}, which we prove in \S \ref{sec:tree-Rd}. In particular, Theorem \ref{thm:2-chain}, Theorem \ref{thm:n-chain}, and Theorem \ref{thm:tree} are all special cases of Theorem \ref{thm:tree-Rd}. The same goes for our application of constructing Cantor sets with Hausdorff dimension $\frac{d}{2}$ and nonempty generalized distance sets.
\begin{theorem}[Finite trees on subsets of $\R^{2d}$]\label{thm:tree-Rd}\index{}
Let $\phi:\R^{2d}\times \R^{2d} \to \R$ be a map that satisfies the derivative condition in Definition \ref{def:derivative-condition} and let $K \subset \R^d$ be a Cantor set. Then, for every finite tree $T$, there exists a Cantor set $\widetilde{K} \subset \R^d$ with $|\widetilde{K}|>|K|$ such that $\left( \Delta^{\phi, T}_y (K \times \widetilde{K} ) \right)^\circ \neq \varnothing$ for some $y\in K\times \widetilde{K}$, where $\Delta^{\phi, T}_y(X)$ is the pinned tree distance set defined in \eqref{distance T phi set}.
\end{theorem}
\begin{corollary}[]\label{cor:tree-hausdorff-dimension-zero-Rd}\index{}
For any finite tree $T$, a map $\phi$ that satisfies the derivative condition, there exists a Cantor set $C\subset \R^{d}$ such that $\dim_{\rm H}(C)=\frac{d}{2}$ and the pinned $(\phi,T)$ distance set $\Delta^{\phi, T}_y (C)$ has nonempty interior for some $y\in C$.
\end{corollary}


\section{Proof of Lemma \ref{lem:pin-wiggling}}\label{sec:lem}
To prove Lemma \ref{lem:pin-wiggling}, we use the following result in \cite[Theorem 1.1]{jung-lai-interior-of-certain}. It is interesting to note that Theorem \ref{thm:jung-lai} does not rely on the Newhouse gap lemma, but rather on what the authors call the containment lemma. 

\begin{theorem*}{A}[Jung-Lai]\label{thm:jung-lai}
    Let $N\ge 1$ and $\Lambda\subset \R^N$ be a set with interior and let $\alpha_0\in \Lambda^{\circ}$. Let $Q_1 \subset Q_2\subset \R^d$ be open cubes and $Q_1 \ne \varnothing$.  Let $H:\Lambda\times Q_1\times Q_2 \to \R^d$ be a $C^1$ function such that the Jacobian on  $Q_2$ is invertible. Then for all Cantor sets $K_1\subset Q_1$, there exists a Cantor set $K_2\subset Q_2$ with $|K_2|>|K_1|$ and an open cube centered at $\alpha_0$, ${\mathtt Q}_{\epsilon}(\alpha_0) \subset \Lambda$ ($\epsilon>0$) such that 
    $$
    \left(\bigcap_{\alpha\in {\mathtt Q}_{{\epsilon}}(\alpha_0)} H(\alpha, K_1,K_2)\right)^{\circ}\ne \varnothing.
    $$
\end{theorem*}
Recall that if $\Lambda \subset \R^N$, $Q_1, Q_2 \subset \R^d$, and $H:\Lambda \times Q_1 \times Q_2 \to \R^d$ is a $C^1$ function, then denoting  $H(\lambda, x, y)=(H_1 (\lambda, x, y), \cdots, H_d (\lambda, x, y))$, the \textit{Jacobian} of $H$ on $Q_2$ is defined as the following $d\times d$ matrix:
\begin{align*}
    \left(\frac{\partial H_i(\lambda, x, y)}{\partial y_j}\right)_{i,j=1}^d.
\end{align*}

\begin{proof}[Proof of Lemma \ref{lem:pin-wiggling}]
We first prove a claim.

\noindent \textit{Claim}. There exist a nonempty open interval $Q\subset I$ and an open neighborhood $\Lambda_2$ of $v_2$ in $\R$ disjoint from $Q$ such that $K \cap Q \neq \varnothing$ contains a sub-Cantor set of $K$.

\begin{proof}[Proof of the claim]
This is straightforward if $v_2\not\in I$. If $v_2 \in I$, then let $p\in (K\cap I)\setminus \{v_2\}$. Then, there exist disjoint open intervals $Q, \Lambda_2 \subset I$ that separate $p$ and $v_2$, i.e., $p\in Q$ and $v_2\in \Lambda_2$. Since $Q$ contains a closed interval that contains $p$, $K\cap Q$ must contain a sub-Cantor set of $K$. This finishes the proof of the claim.
\end{proof}

Returning to the main proof, we are now ready to use Theorem \ref{thm:jung-lai}. Let $Q_1=Q_2=Q$ and $\Lambda = \R\times \Lambda_2$. Define
\begin{align*}
    H:\Lambda\times \R \times \R \to \R : (z,x,y)\mapsto \|(x,y)-z\|_2,
\end{align*}
where $z=(z_1,z_2)\in \R^2$ and $\|\cdot \|_2$ is the Euclidean norm in $\R^2$. By (i) of the above claim, we have
\begin{align*}
    \left|\frac{\partial H (z, x, y)}{\partial y}\right| = \frac{|y-z_2|}{\|(x,y)-z\|_2}>0 \quad \forall (z, x, y)\in \Lambda\times Q_1 \times Q_2.
\end{align*}
Hence, the Jacobian of $H$ on $I$ is invertible and the conditions of Theorem \ref{thm:jung-lai} are satisfied. By (ii) of the above claim, there exists a Cantor set $K_1\subset K\cap Q_1$. By Theorem \ref{thm:jung-lai}, there exist a Cantor set $K_2 \subset Q_2$ with $|K_2|>|K_1|$ and an open neighborhood $U_v\subset \Lambda$ of $v$ such that
\begin{align*}
     \left(\bigcap_{z\in U_v} H(z, K_1, K_2)\right)^\circ \neq \varnothing.
\end{align*}
Take $\widetilde{K}=K_2$ as our desired Cantor set. Then, since $K_1 \subset K$, we have
\begin{align*}
    \left(\bigcap_{z\in U_v} \Delta_z(K\times \widetilde{K})\right)^\circ=\left(\bigcap_{z\in U_v} H(z, K, \widetilde{K})\right)^\circ \supset \left(\bigcap_{z\in U_v} H(z, K_1, K_2)\right)^\circ \neq \varnothing.
\end{align*}
This completes the proof.
\end{proof}

\section{Proof of Theorem \ref{thm:2-chain}}\label{sec:2-chain}
\begin{proof}[Proof of Theorem \ref{thm:2-chain}]
Let $x^0, x^1, x^2 \in K \times K $ be three distinct points 
on the diagonal line $\{y=x\}$. Let $\mathcal{U}_2$ be an open neighborhood of $x^2$ in $\R^2$ such that $x^0, x^1\not\in \mathcal{U}_2$.
Since $x^2\in K\times K$ is in the diagonal line, there exists a nonempty open interval $I\subset \R$ such that $x^2 \in I\times I\subset \mathcal{U}_2$.
Applying Lemma \ref{lem:pin-wiggling} to $K_2=K\cap I$, $x^1$, and $I$, there exist a Cantor set $\widetilde{K}_2\subset I$ and an open neighborhood $\mathcal{U}_1$ of $x^1$ in $\R^2$ such that $K_2\times \widetilde{K}_2 \subset \mathcal{U}_2$ and
\begin{align}\label{eq:2-chain-interior-1}
    \left(\bigcap_{x\in \mathcal{U}_1} \Delta_x (K_2 \times \widetilde{K}_2) \right)^\circ \neq \varnothing.
\end{align}
Note that we may assume $\mathcal{U}_1$ does not contain $x^0$ by replacing it with a suitable open subset. Repeating the same argument with $\mathcal{U}_1$ in place of $\mathcal{U}_2$, $x^1$ in place of $x^2$, and $x^0$ in place of $x^1$, there exist a sub-Cantor set $K_1\subset K$, a Cantor set $\widetilde{K}_1$, and an open neighborhood $\mathcal{U}_0$ of $x^0$ in $\R^2$ such that $K_1\times \widetilde{K}_1 \subset \mathcal{U}_1$ and
\begin{align}\label{eq:2-chain-interior-2}
    \left(\bigcap_{x\in \mathcal{U}_0} \Delta_x (K_1 \times \widetilde{K}_1)\right)^\circ \neq \varnothing.
\end{align}
Let $\widetilde{K} = K\cup \left(\bigcup_{i=1}^2 \widetilde{K}_i\right)$ and $y=y^0 \in \mathcal{U}_0 \cap (K\times \widetilde{K})$, which is nonempty since it contains $x^0$. To prove that $\left(\Delta^2_{y} (K\times \widetilde{K})\right)^\circ \neq \varnothing$, by \eqref{eq:2-chain-interior-1} and \eqref{eq:2-chain-interior-2}, it suffices to show that
\begin{align}
    \Delta^2_{y} (K\times \widetilde{K}) \supset \left( \bigcap_{x\in \mathcal{U}_0} \Delta_x (K_1 \times \widetilde{K}_1) \right)^\circ \times \left( \bigcap_{x\in \mathcal{U}_1} \Delta_x (K_2 \times \widetilde{K}_2) \right)^\circ. \label{eq:2-chain-3}
\end{align}
To see that \eqref{eq:2-chain-3} holds, let
\begin{align*}
    (l^1,l^2) \in \left( \bigcap_{x\in \mathcal{U}_0 } \Delta_x (K_1 \times \widetilde{K}_1) \right)^\circ \times \left( \bigcap_{x\in \mathcal{U}_1} \Delta_x (K_2 \times \widetilde{K}_2) \right)^\circ.
\end{align*}
Then, since $l^1\in \left( \bigcap_{x\in \mathcal{U}_0} \Delta_x (K_1 \times \widetilde{K}_1) \right)^\circ$ and $y^0\in \mathcal{U}_0$, there exists $y^1\in K_1 \times \widetilde{K}_1\subset \mathcal{U}_1$ such that $l^1=|y^0-y^1|$. Also, since $l^2\in \left( \bigcap_{x\in \mathcal{U}_1} \Delta_x (K_2 \times \widetilde{K}_2) \right)^\circ$ and $y^1\in K_1 \times \widetilde{K}_1\subset \mathcal{U}_1$, there exists $y^2\in K_2 \times \widetilde{K}_2 \subset K\times \widetilde{K}$ such that $l^2=|y^1-y^2|$. Thus,
\begin{align*}
(l^1,l^2)\in \{ (|y^0-y^1|,|y^1-y^2|): y^1,y^2\in K\times \widetilde{K} \}= \Delta_y^{(2)} (K\times \widetilde{K}).
\end{align*}
This shows \eqref{eq:2-chain-3} and the proof is complete.
\end{proof}


\section{Proof of Theorem \ref{thm:n-chain}}\label{sec:n-chain}
\begin{proof}[Proof of Theorem \ref{thm:n-chain}]
Let $x^0, x^1, x^2, \cdots, x^{n-1} \in K \times K $ be $n$ distinct points lying on the diagonal line. We first prove the following claim, which is illustrated in Figure \ref{fig:5-chain}.

\noindent\textit{Claim.} There exist sub-Cantor sets $K_i$ of $K$, Cantor sets $\widetilde{K}_i\subset \R$ for each $i\in \{1, 2, \cdots, n-1\}$ and pairwise disjoint open neighborhoods $\mathcal{U}_j$ of $x^j$ for each $j\in \{0,1,\cdots, n-1\}$ such that for each $i\in \{1, 2, \cdots, n-1\}$,
\begin{enumerate}[(i)]
\item $K_i\times \widetilde{K}_i \subset \mathcal{U}_{i}$;
\item $\left(\bigcap_{x\in \mathcal{U}_{i-1}} \Delta_x (K_{i}\times \widetilde{K}_{i})\right)^\circ \neq \varnothing$;
\end{enumerate}
\begin{proof}[Proof of the claim]
We proceed inductively in reverse order. Let $\mathcal{U}_{n-1}$ be an open neighborhood of $x^{n-1}$ in $\R^2$ such that $x^0,\cdots, x^{n-2} \not\in \mathcal{U}_{n-1}$. Since $x^{n-1}\in K\times K$ lies in the diagonal line, there exists a nonempty open interval $I_{n-1}\subset \R$ such that $x^{n-1}\in I_{n-1}\times I_{n-1} \subset \mathcal{U}_{0i}$.
Then, applying Lemma \ref{lem:pin-wiggling} to $K_{n-1}=K\cap I_{n-1}$, $x^{n-2}$, and $I_{n-1}$, there exist a Cantor set $\widetilde{K}_{n-1} \subset I_{n-1}$ and an open neighborhood $\mathcal{U}_{n-2}$ of $x^{n-2}$ in $\R^2$ such that
\begin{align*}
K_{n-1}\times \widetilde{K}_{n-1}\subset \mathcal{U}_{n-1} \quad \text{and} \quad \left(\bigcap_{x\in \mathcal{U}_{n-2}} \Delta_x (K_{n-1}\times \widetilde{K}_{n-1})\right)^\circ \neq \varnothing.
\end{align*}
Suppose that, for some $j\in\N$, we have obtained the desired sets
\begin{align*}
\{\mathcal{U}_j\} \cup \{(K_i, \widetilde{K}_{i}, \mathcal{U}_i): i\in \{j+1,j+2, \cdots, n-1\}\},
\end{align*}
such that (i)-(ii) hold for $i\in\{j+1, j+2, \cdots, n-1\}$. Similarly as before, since $x^{j}\in K\times K$ is a point on the diagonal line, there exists a nonempty open interval $I_j\subset \R$ such that $x^{j}\in I_{j}\times I_j \subset \mathcal{U}_{j}$. Thus, using Lemma \ref{lem:pin-wiggling} on $K_{j}=K\cap I_j$, $x^{j-1}$, and $I_j$, we deduce that there exist a Cantor set $\widetilde{K}_j\subset I_j$ and an open neighborhood $\mathcal{U}_{j-1}$ of $x^{j-1}$ in $\R^2$ such that (i)-(ii) hold for $i\in\{j, j+1, \cdots, n-1\}$. Note that we may restrict $\mathcal{U}_{j-1}$ to its subset so that $\mathcal{U}_{j-1}, \cdots, \mathcal{U}_{n-1}$ are pairwise disjoint. Proceeding this process down to $j=1$, we obtain the desired sub-Cantor sets $K_i \subset K$, Cantor sets $\widetilde{K}_i\subset \R$, and open neighborhoods $\mathcal{U}_j$ of $x^j$ for each $i\in \{1,2, \cdots, n-1\}$ and $j\in \{0,1,\cdots, n-1\}$ that satisfy (i)-(ii).
\end{proof}

We now return to the main proof. Define $\widetilde{K} = K\cup \left(\bigcup_{i=1}^{n-1} \widetilde{K}_i\right)$ and let $y=y^0\in \mathcal{U}_0 \cap (K\times \widetilde{K})$, which is nonempty since it contains $x^0$. By (ii) of the above claim, to prove that $\Delta^n_{y} (K\times \widetilde{K})$ has nonempty interior, it suffices to show that
\begin{align}
    \Delta^n_{y} (K\times \widetilde{K}) \supset \left( \bigcap_{x\in \mathcal{U}_0} \Delta_x (K_1 \times  \widetilde{K}_1) \right)^\circ \times \cdots  \times \left( \bigcap_{x\in \mathcal{U}_{n-2}} \Delta_x (K_{n-1} \times \widetilde{K}_{n-1}) \right)^\circ. \label{eq:inclusion}
\end{align}
To prove \eqref{eq:inclusion}, let
\begin{align*}
    (l^0, \cdots, l^{n-2}) &\in \left( \bigcap_{x\in \mathcal{U}_0} \Delta_x (K_1 \times  \widetilde{K}_1) \right)^\circ \cdots \times \left( \bigcap_{x\in \mathcal{U}_{n-2}} \Delta_x (K_{n-1} \times \widetilde{K}_{n-1}) \right)^\circ.
\end{align*}
\eqref{eq:inclusion} holds if we find distinct points $y^1, y^2, \cdots, y^{n-1} \in K\times \widetilde{K}$ (different from $y^0$) such that
\begin{equation}\label{eq:1}
    l^{i+1}=|y^i-y^{i+1}| \quad (i\in \{0,\cdots, n-2\}).
\end{equation}
Each $y^i$ will be in $\mathcal{U}_i$ and we use the claim above to find these points inductively. Since $l^0\in \left( \bigcap_{x\in \mathcal{U}_0} \Delta_x (K_1 \times \widetilde{K}_1) \right)^\circ$ and $y^0\in \mathcal{U}_0$, there exists $y^1\in K_1 \times \widetilde{K}_1$ such that $l^0=|y^0-y^1|$. Next, since $l^1 \in \left( \bigcap_{x\in \mathcal{U}_1} \Delta_x (K_2 \times \widetilde{K}_2) \right)^\circ$ and $y^1\in \mathcal{U}_1$ by (i), there exists $y^2\in K_2 \times \widetilde{K}_2$ such that $l^1=|y^1-y^2|$. Note that $y^1, y^2$ are distinct since $\mathcal{U}_0$ and $\mathcal{U}_1$ are disjoint. Suppose that for some $j\in \N$, we have found distinct points $y^0, \cdots, y^j\in K\times \widetilde{K}$ such that $y^i \in \mathcal{U}_i$ and $l^i=|y^i-y^{i+1}|$ for each $i=0,1,\cdots, j$. Then, since $l^{j+1} \in \left(\bigcap_{x\in \mathcal{U}_{j}} \Delta_x (K_{j+1}\times \widetilde{K}_{j+1})\right)^\circ$, there exists $y^{j+1}\in K_{j+1}\times \widetilde{K}_{j+1}$ such that $l^{j+1} =|y^j-y^{j+1}|$. By (i), $y^{j+1}\in \mathcal{U}_{j+1}$, and since $\{\mathcal{U}_i: i\in \{0, 1, \cdots, j+1\}\}$ are pairwise disjoint, $y^0,\cdots, y^{j+1}$ are distinct. Proceeding upto $j=n-2$, we obtain all the desired distinct points $y^0, y^1,\cdots, y^{n-1}\in K\times \widetilde{K}$ such that \eqref{eq:1} holds. This proves \eqref{eq:inclusion}, and the proof is complete.
\end{proof}
