\section{Proof of Theorem \ref{thm:tree}}\label{sec:tree}
\begin{proof}[Proof of Theorem \ref{thm:tree}]
We first need the following claim, which is illustrated in figure \ref{fig:5-tree}.

\noindent\textit{Claim.} For every finite tree $T$ with root $0$ and distinct points $\{x^\tau \in K\times K: \tau \in T\}$, there exist sub-Cantor sets $K_\tau$ of $K$, Cantor sets $\widetilde{K}_\tau \subset \R$ for each $\tau \in T \setminus \{0\}$ and pairwise disjoint open neighborhoods $\mathcal{U}_\sigma$ of $x^\sigma$ for each $\sigma \in T$ such that for each $\tau \in T\setminus \{0\}$,
\begin{enumerate}[(i)]
\item $K_\tau\times \widetilde{K}_\tau \subset \mathcal{U}_{\tau}$;
\item $\left(\bigcap_{x\in \mathcal{U}_{\tau'}} \Delta_x (K_{\tau}\times \widetilde{K}_{\tau})\right)^\circ \neq \varnothing$, where $\tau'$ is the unique parent of $\tau$.
\end{enumerate}

\begin{proof}[Proof of the claim.]
We prove by induction on the depth of trees. For the base case, let $T$ be a tree of depth 1 with $n\geq 2$ vertices $0, 00, 01, \cdots, 0(n-2)$. Let $\{x^\tau \in K\times K: \tau \in T\}$ be distinct points and $\{\mathcal{U}_{0i}: i\in \{0, 1, \cdots, n-2\}\}$ be pairwise disjoint open sets in $\R^2$, where $\mathcal{U}_{0i}$ is an open neighborhoods of $x^{0i}$ in $\R^2$ and $x^0, x^{0j}\not\in \mathcal{U}_{0i}$ for each $j\neq i$. Note that since $x^{0i}\in K\times K$ lies in the diagonal line, there exists a nonempty open interval $I_i\subset \R$ such that $x^{0i}\in I_i\times I_i \subset \mathcal{U}_{0i}$. Then, for each $i\in \{0,\cdots, n-2\}$, applying Lemma \ref{lem:pin-wiggling} to $K_{0i} = K\cap I_{0i}$, $x^{0}$, and $I_i$, we deduce that there exist a Cantor set $\widetilde{K}_{0i} \subset I_i$ and an open neighborhood $\mathcal{V}_{0}^i$ of $x^0$ in $\R^2$ such that $K_{0i}\times \widetilde{K}_{0i}\subset \mathcal{U}_{0i}$ and
\begin{align*}
\left(\bigcap_{x\in \mathcal{V}_{0}^i} \Delta_x (K_{0i}\times \widetilde{K}_{0i})\right)^\circ \neq \varnothing.
\end{align*}
Define $\mathcal{U}_0 = \bigcap_{i=0}^{n-2} \mathcal{V}_0^i$, which is an open neighborhood of $x^0$ in $\R^2$, which we may assume, by taking its suitable open subset, to be disjoint from $U_{0i}$ for all $i\in\{0,\cdots, n-2\}$. Then, (i)-(ii) holds for the tree $T$ of depth 1.

For the induction step, suppose that the claim holds for all trees of depth at most $d$. Let $T$ be a tree of depth $d+1$ with root $0$ and $\{x^\tau \in K\times K: \tau \in T\}$ be distinct points. Denote $T(k)=\{\sigma \in T: \sigma \text{ has depth } k\}$ to be the vertices of $T$ of depth $k$ and for each $\sigma \in T$, denote $T_\sigma=\{\tau\in T: \sigma<\tau\}$ to be the subtree of $T$ that has $\sigma$ as its root and includes all of its vertices below it. Since the tree $T$ with the root $0$ removed is a union of disconnected trees $\{T_\sigma: \sigma \in  T (1)\}$ of depth at most $d$, by the induction hypothesis, for each $\sigma\in T (1)$, we have all the desired sub-Cantor sets $K_\tau$ of $T$ and Cantor sets $\widetilde{K}_\tau \subset \R$ except for $\tau\in T(1)$ and all the desired pairwise disjoint open neighborhoods $\mathcal{U}_\sigma$ of $x^\sigma$ except for $\sigma=0$. Similar to above, for each $\sigma \in  T (1)$, since $x_\sigma$ lies in the diagonal line, Lemma \ref{lem:pin-wiggling} states that there exist a sub-Cantor set $K_\sigma\subset K$, a Cantor set $\widetilde{K}_\sigma$, and an open neighborhood $\mathcal{V}_0^\sigma$ of $x^0$ in $\R^2$ such that
\begin{align*}
    K_\sigma \times \widetilde{K}_\sigma \subset \mathcal{U}_\sigma \quad \text{and} \quad \left(\bigcap_{x\in \mathcal{V}_{0}^\sigma} \Delta_x (K_{0i}\times \widetilde{K}_{0i})\right)^\circ \neq \varnothing.
\end{align*}

Define $\mathcal{U}_0=\bigcap_{\sigma\in T (1)} \mathcal{V}_0^\sigma$, which is an open neighborhood of $x^0$ in $\R^2$, and note that we may assume it to be disjoint from $\mathcal{U}_\tau$ for each $\tau \neq 0$ by taking a suitable open subset. This shows that the claim holds for all trees of depth $d+1$, and hence, by induction on the height of trees, the claim holds for all finite trees $T$.
\end{proof}

We now return to the main proof. Let $T$ be a finite tree of depth $d$ and $\{x^\tau \in K\times K: \tau \in T\}$ be distinct points. Using the claim above, define $\widetilde{K} = K\cup \bigcup_{\tau\in T\setminus \{0\}} \widetilde{K}_\tau$. Let $y=y^0 \in \mathcal{U}_0 \cap (K\times \widetilde{K})$. By (ii), to prove that $\left(\Delta^T (K\times \widetilde{K})\right)^\circ \neq \varnothing$, it suffices to show
\begin{align}
    \Delta^T (K\times \widetilde{K}) &\supset \underbrace{\left( \bigcap_{x\in \mathcal{U}_{{\sigma_{1,0}}'}} \Delta_x (K_{\sigma_{1,0}} \times  \widetilde{K}_{\sigma_{1,0}}) \right)^\circ \times \cdots \times \left( \bigcap_{x\in \mathcal{U}_{{\sigma_{1,n_1}}'}} \Delta_x (K_{\sigma_{1,n_1}} \times  \widetilde{K}_{\sigma_{1,n_1}}) \right)^\circ}_{ T (1)=\{\sigma_{1,0}, \cdots, \sigma_{1, n_1} \}}\times \nonumber\\
    \ & \vdots \nonumber \\
    &\times \underbrace{\left( \bigcap_{x\in \mathcal{U}_{{\sigma_{d,0}}'}} \Delta_x (K_{\sigma_{d,0}} \times  \widetilde{K}_{\sigma_{d,0}}) \right)^\circ \times \cdots \times \left( \bigcap_{x\in \mathcal{U}_{{\sigma_{d,n_d}}'}} \Delta_x (K_{\sigma_{d,n_d}} \times  \widetilde{K}_{\sigma_{d,n_d}}) \right)^\circ}_{ T (d)=\{\sigma_{d,0}, \cdots, \sigma_{d,n_d}\}},\label{eq:n-tree-inclusion}
\end{align}
where $\sigma'$ is the unique parent of $\sigma$ in tree $T$. To prove \eqref{eq:n-tree-inclusion}, let
\begin{align*}
    \vec{l}_T=\left(\underbrace{l^{\sigma_{1,0}}, \cdots, l^{\sigma_{1,n_1}}}_{T (1)=\{\sigma_{1,0}, \cdots, \sigma_{1,n_1}\}}, \cdots, \underbrace{l^{\sigma_{1,0}}, \cdots, l^{\sigma_{n_{1,0}}}}_{ T (d)=\{\sigma_{d,0}, \cdots, \sigma_{d,n_d}\}}\right)
\end{align*}
be an element on the right hand side of \eqref{eq:n-tree-inclusion}. Then, proving \eqref{eq:n-tree-inclusion} is equivalent to finding distinct points $\{y^\tau\}_{\tau\in T\setminus \{0\}}$ of $K\times \widetilde{K}$ such that
\begin{equation}\label{eq:n-tree-2} 
    \vec{l}_T= (|y^\tau - y^\sigma|)_{\tau \sim \sigma}.
\end{equation}
We again proceed inductively on the depth of trees. For the base case, suppose that $T$ is a tree of depth 1. Then, for each $\sigma\in  T (1)$, since $y^0\in \mathcal{U}_0$ and since $l^{\sigma} \in \bigcap_{x\in \mathcal{U}_{0}} \Delta_x (K_{\sigma}\times K_{\sigma})$ by (iv), there exists $y^\sigma \in K_\sigma\times K_{\sigma}$ such that $l^{\sigma} = |y^0-y^\sigma|$. Thus, \eqref{eq:n-tree-2} holds for the case of depth 1. For the induction hypothesis, suppose that for every tree of depth at most $d$, there exists distinct points $\{y^\tau\}_{\tau \in T\setminus \{0\}}$ such that \eqref{eq:n-tree-2} holds. Let $T$ be a tree of depth $d+1$. Then, for each $\sigma\in  T (1)$, since $y^0\in \mathcal{U}_0$ and since $l^{\sigma} \in \bigcap_{x\in \mathcal{U}_{0}} \Delta_x (K_{\sigma}\times K_{\sigma})$ by (ii), there exists $y^\sigma \in K_\sigma\times K_{\sigma}$ such that $l^{\sigma} = |y^0-y^\sigma|$. Moreover, since $T$ with the root $0$ removed is a union of disconnected trees $\{T_\sigma: \sigma \in  T (1)\}$ of depth at most $d$, by the induction hypothesis, each $T_\sigma$ has distinct points $\{y^{\tau}\}_{\tau \in T(\sigma)\setminus \{\sigma\} }$ such that \eqref{eq:n-tree-2} holds. Thus, we have found the desired distinct points $\{y^\tau\}_{\tau \in T\setminus \{0\} }$ such that \eqref{eq:n-tree-2} holds. By induction on the depth of trees, \eqref{eq:n-tree-2} holds for all finite trees. This completes the proof.
\end{proof}

