\section{Proof of Lemma \ref{lem:pin-wiggling-Rd}}\label{sec:lem-Rd}
\begin{proof}[Proof of Lemma \ref{lem:pin-wiggling-Rd}]
We use Theorem \ref{thm:jung-lai} analogously to the proof of Lemma \ref{lem:pin-wiggling}. Define
\begin{align*}
H:\R^{2d} \times \R^d \times \R^d \to \R^d : (z,x,y)\mapsto \left( \phi(z,(x,y)) , y_2, \cdots, y_d\right).
\end{align*}
The Jacobian determinant of $H$ with respect to $y$, whenever defined, is given by
\begin{align*}
\det \begin{pmatrix}
    \frac{\partial \phi(z, (x,y))}{\partial y_1} & \frac{\partial \phi(z, (x,y))}{\partial y_2} & \frac{\partial \phi(z, (x,y))}{\partial y_3} & \cdots & \frac{\partial \phi(z, (x,y))}{\partial y_d} \\
    0 & 1 & 0 & \cdots & 0 \\
    0 & 0 & 1 & \cdots & 0 \\
    \vdots & \vdots & \vdots & \ddots & 0 \\
    0 & 0 & 0 & \cdots & 1
\end{pmatrix}
=\frac{\partial \phi(z, (x,y))}{\partial y_1}.
\end{align*}
Let $k\in K\cap Q$. Since $\phi$ satisfies the derivative condition, there exists an open cube $\Lambda \subset \R^{2d}$ containing $v$ and an open cube $Q_2 \subset Q$ such that $k\in Q_2$ and
\begin{align*}
\frac{\partial \phi(z, (x,y))}{\partial y_1} \neq 0 \quad \forall z \in A \text{ and } \forall (x,y) \in Q_2 \times Q_2.
\end{align*}
This implies that the Jacobian of $H$ with respect to $y$ on $Q_2$ is invertible and the conditions of Theorem \ref{thm:jung-lai} are satisfied. For notational coherence, denote $Q_1=Q_2$. Then, since $k\in K\cap Q_1\neq \varnothing$, there exists a Cantor set $K_1 \subset K\cap Q_1$. By Theorem \ref{thm:jung-lai}, there exist a Cantor set $K_2\subset Q_2$ with $|K_2|>|K_1|$ and an open neighborhood $\mathcal{U}_v\subset \Lambda$ of $v$ such that
\begin{align*}
     \left(\bigcap_{z\in U_v} H(z, K_1, K_2)\right)^\circ \neq \varnothing.
\end{align*}
Taking $\widetilde{K}=K_2$ as our desired Cantor set, since $K_1 \subset K$, we have
\begin{align*}
    \left(\bigcap_{z\in U_v} \phi(z, K\times \widetilde{K})\right)^\circ=  \left(\bigcap_{z\in U_v} \pi_1 (H(z, K, \widetilde{K}))\right)^\circ \supset \pi_1 \left(\bigcap_{z\in U_v} H(z, K_1, K_2)\right)^\circ \neq \varnothing,
\end{align*}
where $\pi_1:\R^d\to \R$ is the projection map onto the first coordinate. Note that the last inclusion follows since projection is an open map and projection of an intersection is a subset of the intersection of projections. This completes the proof.
\end{proof}

\section{Proof of Theorem \ref{thm:tree-Rd}}\label{sec:tree-Rd}
\begin{proof}[Proof of Theorem \ref{thm:tree-Rd}]
The proof is a direct generalization of Theorem \ref{thm:tree}. Recall the claim in the proof of Theorem \ref{thm:tree} with the following (ii)$'$ in place of (ii) for each $\tau\in T\setminus \{0\}$:

\noindent (ii)$'$ $\left( \bigcap_{x\in \mathcal{U}_{\tau '}} \phi(x, K_\tau \times \widetilde{K}_\tau) \right)^\circ \neq \varnothing$, where $\tau'$ is the unique parent of $\tau$.

This version of the claim follows by using induction on the depth of trees in the proof of the original claim in Theorem \ref{thm:tree} with Lemma \ref{lem:pin-wiggling-Rd} in place of Lemma \ref{lem:pin-wiggling}. Returning to the main proof, let $T$ be a finite tree of depth $d$ and let $\{x^\tau \in K\times K: \tau \in T\}$ be distinct points. Using the claim above, define $\widetilde{K} = K\cup \  \bigcup_{\tau \in T\setminus \{0\}} \widetilde{K}_\tau$ and let $y\in \mathcal{U}_0 \cap (K\times \widetilde{K})$. The proof that $\left(\Delta^{\phi, T} (K\times \widetilde{K})\right)^\circ \neq \varnothing$ follows by using induction on the depth of trees in the same proof in Theorem \ref{thm:tree} with $\Delta^{\phi, T}$ in place of $\Delta^T$. This completes the proof.
\end{proof}

\section{Open questions}\label{sec:open-questions}
\begin{question}\label{q:1}
If $K\subset \R$ is a Cantor set, is there exists a Cantor set $\widetilde{K}$ such that $\Delta^T(K\times \widetilde{K})$ has nonempty interior for all finite trees $T$?
\end{question}
If the answer to Question \ref{q:1} is yes, then this provides a way to construct a Cantor set $C\subset \R^2$ with $\dim_{\rm H}=1$ such that $\Delta^T (C)$ has nonempty interior for all finite trees $T$. Note that by taking finite unions in Theorem \ref{thm:tree}, the answer to Question \ref{q:1} is yes for any finite collection of trees.

\begin{question}\label{q:2}
    For an odd integer $d\geq 3$ and for a finite tree $T$ with more than two vertices, can we construct $C\subset \R^d$ such that $\dim_{\rm H} (C)=\frac{d}{2}$ and $\Delta^T (C)$ has nonempty interior?
\end{question}
To our knowledge, it is unknown how to construct a Cantor set $C\subset \R^d$ for odd $d\geq 3$ such that $\dim_{\rm H} (C)=\frac{d}{2}$ and the pinned distance set $\Delta_x(C)$ has nonempty interior for some $x\in C$. We finish this section by asking several possible generalizations of tree distace sets.
\begin{question}
    Can we generalize our results (specifically, Theorem \ref{thm:tree-Rd} and Corollary \ref{cor:tree-hausdorff-dimension-zero-Rd}) to more general class of graphs?
\end{question}
These may include infinite chains and trees or graphs with loops, such as polygons. We may also impose requirements on the lengths of the distances like constant-gaps (see \cite{McDonald_Taylor_2023_infinite_chains}), such as equilateral triangles.

