\begin{document}

\title{Amplitude equations for stored spatially heterogeneous states}

\author{Akke Mats Houben}
\email{akkemats.houben@ub.edu}
\email{akke@akkehouben.net}
\affiliation{Departament de F\'{i}sica de la Mat\`{e}ria Condensada, Universitat de Barcelona, E-08028 Barcelona, Spain}
\affiliation{Universitat de Barcelona Institute of Complex Systems (UBICS), E-08028 Barcelona, Spain}

\begin{abstract}
    Coupled evolution equations for the amplitudes of heterogeneous states (memories) stored in the connectivity of distributed systems with distance-constrained non-local interactions are derived.
    The resulting system of coupled amplitude equations describes the spatio-temporal dynamics of the pattern amplitudes.
    %The procedure largely follows that for amplitudes of spatially periodic heterogeneous states, and results in a system of coupled reaction-diffusion equations.
    It is shown that these types of distributed systems perform pattern completion and selection, and that the distance restricted connections afford spatio-temporal memory pattern dynamics taking the form of patterning fronts. 
\end{abstract}

\maketitle

Many physical and biological phenomena involve the formation and maintenance of spatially patterned states~\cite{hohenberg1987anintroduction, hoyle2006pattern, cross2009pattern}.
The dynamics of inhomogeneous states arising from isotropic interactions can be understood by studying the linear stability of the homogeneous base-state of the system, and by performing small-amplitude perturbation analyses around the uniform base-state leading to amplitude equations capturing the pattern envelope dynamics~\cite{newell1969finite, segel1969distant}.
However, many processes depend on the formation of specific spatially heterogeneous patterns (a prominent example being auto-associative memory networks~\cite{little1974existence, hopfield1982neural, peretto1984collective, hopfield1984neurons, amit1985spinglass, amit1985storing}) often from interactions with restricted spatial extent (such as\textemdash in keeping with the example\textemdash memory in biological neural networks~\footnote{Connections between neurons in the cortex are spatially restricted~\cite{braitenberg1991anatomy}, leading to neurons predominantly connecting to nearby neurons.}).

In this letter amplitude equation derivation is generalised from spatially periodic modes to arbitrary spatially patterned states (memories) stored in spatially restricted non-local connectivity. 
Specifically, to a system extending over a space $\Omega$ for which the ``activity'' variable~\footnote{For simplicity of presentation, the derivation is presented for a scalar system, but the results are readily extended to multi-dimensional dynamics.} $u(\mathbf{r},t)$ at a location $\mathbf{r} \in \Omega$ evolves under the influence of local internal dynamics $f(u)$ and non-local recurrent coupling,
\begin{equation}\label{eq:du}
    \frac{\partial u(\mathbf{r}, t)}{\partial t} = f(u) + \gamma \int_{\Omega} J(\mathbf{r}, \mathbf{r}') g[u(\mathbf{r}', t)] d\mathbf{r}'.
\end{equation}
%For definiteness, in the following  $f(u)$ and $g(u)$ are assumed to be odd functions around $u=0$, but  and $f'(0) = a$ and $g'(0) = b$, in the following
The non-local, but spatially constrained by a non-negative spatial kernel $\Phi$, connectivity 
\begin{equation}
    J(\mathbf{r}, \mathbf{r}') = \Phi(|\mathbf{r}-\mathbf{r}'|) \sum_{k=1}^{M} \frac{\mu_k(\mathbf{r}) \mu_k(\mathbf{r}')}{M},
\end{equation}
with $\lVert \mu_k \rVert = 1$, $\int_{\Omega} \mu_k(\mathbf{r})d\mathbf{r} = 0$, $\int_{\Omega} \Phi(\mathbf{r}) d\mathbf{r} = 1$, and $\Phi(0)=0$, stores $M$ spatially heterogeneous states $u \propto \mu_k$ that the system can attain, and it will be for these states that the amplitude equations describe their evolution dynamics.
Approximately orthogonal memory patterns, $\langle \mu_k, \mu_m \rangle \approx \delta_{km}$, will be assumed, but the derived amplitude equations still allow to obtain qualitative understanding of the memory pattern dynamics for systems in which this assumption is relaxed.
The parameter $\gamma$ determines the global coupling strength.

%In case the $M$ memory patterns are uncorrelated then, for $M \gg 1$, to first approximation the coupling vanishes (Fig.~\ref{fig:Jij_M}).
%However, 
%\begin{figure}
%    \centering
    %\begin{tikzpicture}
    %\end{tikzpicture}%
%    \caption{Connectivity $J(\mathbf{x}, \mathbf{x}')$ for one-dimensional systems with $\Phi$ a Gaussian and varying number $M$ of random binary vectors (grey scale).
%    }\label{fig:Jij_M}
%\end{figure}

Assuming that the system Eq.~(\ref{eq:du}) has a base-state $u(\mathbf{r},t)=u_0$ unstable to perturbations of the form $u = u_0 + \varepsilon A_k \mu_k$ above some critical coupling
\begin{equation*}
    \gamma > \gamma_k = a_1 \left[ b_1 \int_{\Omega}\int_{\Omega} J(\mathbf{r}, \mathbf{r}') \mu_k(\mathbf{r}') d\mathbf{r}' \mu_k(\mathbf{r}) d\mathbf{r}\right]^{-1},
\end{equation*}
with $a_1$ and $b_1$ the first derivative of, respectively,  $f(u)$ and $g(u)$ with respect to $u$ evaluated at $u=u_0$, 
then for coupling close to the critical coupling $\gamma = (1+\varepsilon^2)\gamma_k$, $\varepsilon^2 \ll 1$, the system dynamics on slow temporal $\tilde{t} = \varepsilon^2 t$ and long spatial $\tilde{\mathbf{r}} = \varepsilon \mathbf{r}$ scales can be captured by the pattern amplitudes $A_k(\tilde{\mathbf{r}}, \tilde{t})$.

%Obtaining the evolution equations for the pattern amplitudes follows that for spatially periodic states~\cite{TODO}.

\emph{Amplitude equations.~}
The derivation of the amplitude equations is analogous to that for spatially periodic patterned states.
For clarity of exposition it will be assumed that $f(u)$ and $g(u)$ are odd functions around $u_0$, so that the second order derivatives vanish~\footnote{The presented procedure is valid for $f(u)$ or $g(u)$ with non-vanishing second order derivatives. In this case the perturbation analysis possibly has to be carried out to higher order since it can result in subcritical amplitude dynamics.}.
Introducing slow spatial $\tilde{\mathbf{r}}$ and temporal $\tilde{t}$ scales, and the perturbation expansion $U \sim U_0 + \varepsilon U_1 + \varepsilon^2 U_2 + \ldots$, with $U_0 = u_0$ and $U_1 = \sum_{k=1}^{M} A_k(\tilde{\mathbf{r}}, \tilde{t}) \mu_k(\mathbf{r})$, will give a system of $M$ coupled evolution equations for the pattern amplitudes $A_k$ as solvability conditions for the $O(\varepsilon^3)$ terms.

Writing $u(\mathbf{r}, t) = U(\mathbf{r}, \tilde{\mathbf{r}}, \tilde{t})$, Eq.~\ref{eq:du} becomes
\begin{equation*}
    \varepsilon^2 \frac{\partial U}{\partial \tilde{t}} = f(U) + (1+\varepsilon^2)\gamma_k \int_{\Omega} J(\mathbf{r}, \mathbf{r}') g[U(\mathbf{r}', \tilde{\mathbf{r}}', \tilde{t})] d\mathbf{r}'.
\end{equation*}
Then, plugging in the perturbation expansion, expanding $f(U)$ and $g(U)$ around $U=u_0$,
and expanding $U_i$ terms under the integral at $\tilde{\mathbf{r}}' = \tilde{\mathbf{r}}$, gives at $O(\varepsilon)$ the linearised dynamics
\begin{equation*}
    \frac{\partial U_1}{\partial \tilde{t}} = a_1 U_1 + \gamma_k b_1 \int_{\Omega} J(\mathbf{r}, \mathbf{r}') U_1(\mathbf{r}', \tilde{\mathbf{r}}, \tilde{t}) d\mathbf{r}',
\end{equation*}
and at $O(\varepsilon^3)$ the solvability criterion
\begin{widetext}
\begin{equation*}
    \frac{\partial U_1}{\partial \tilde{t}} = \gamma_k b_1 \int_{\Omega} J(\mathbf{r}, \mathbf{r}') U_1(\mathbf{r}', \tilde{\mathbf{r}}, \tilde{t}) d\mathbf{r}' + a_3 U_1^3 + \gamma_k b_3 \int_{\Omega} J(\mathbf{r}, \mathbf{r}') \left[U_1(\mathbf{r}', \tilde{\mathbf{r}}, \tilde{t})\right]^3 d\mathbf{r}' + \gamma_k b_1 \sum_{i=1}^{\dim{\Omega}} \int_{\Omega} J(\mathbf{r}, \mathbf{r}') \frac{(r_i'-r_i)^2}{2} d\mathbf{r}'~ \frac{\partial^2 U_1}{\partial \tilde{r}_i^2},
\end{equation*}
\end{widetext}
where $a_3 = f'''(u_0)/6$ and $b_3 = g'''(u_0)/6$.
Since $\Phi$ is symmetric, and assuming memory patterns with sufficient spatial variation, on average $J(\mathbf{r}, \mathbf{r}')$ will be symmetric around $\mathbf{r}'=\mathbf{r}$ so that terms involving odd-order derivatives of $U_1$ in the expansion vanish under the integral.
%\begin{align*}
%    f(U) =&~ f(u_0) + f'(u_0)(\varepsilon U_1 + \varepsilon^2 U_2) \\
%        &+ \frac{f''(u_0)}{2}(\varepsilon U_1 + \varepsilon^2 U_2)^2 \\
%        &+ \frac{f'''(u_0)}{3}(\varepsilon U_1 + \varepsilon^2 U_2)^3 + \ldots
%\end{align*}
%and similarly for $g(U)$, 
Finally, multiplying the evolution equation of $U_1$ by $\mu_k$ and integrating over the domain gives a system of coupled amplitude equations (in original variables and writing $A_k = \varepsilon A_k$)
\begin{widetext}
\begin{equation}\label{eq:ampleq}
    \frac{\partial A_k}{\partial t} = \varepsilon^2\sum_{m=1}^{M} \alpha_{km} A_m
    + \sum_{i=1}^{M} \sum_{j=1}^{M} \sum_{m=1}^{M} \beta_{kijm} A_i A_j A_m 
    %+ \sum_{m=1}^{M} \sum_{d=1}^{\dim{\Omega}} \frac{D_{km}^{(d)}}{2} \frac{\partial^2 A_m}{\partial r_d^2}
    + \sum_{m=1}^{M} \frac{D_{km}}{2} \nabla^2 A_m
\end{equation}
\end{widetext}
with coefficients
\begin{equation*}
    \alpha_{km} = \gamma_k b_1 \left\langle \int_{\Omega} J(\mathbf{r}, \mathbf{r}') \mu_m(\mathbf{r}') d\mathbf{r}', \mu_k \right\rangle,
\end{equation*}
\begin{equation*}
    \beta_{kijm} = \left\langle \int_{\Omega} \left[a_3 + \gamma_k b_3 J(\mathbf{r}, \mathbf{r}')\right] \mu_i(\mathbf{r}') \mu_j(\mathbf{r}') \mu_m(\mathbf{r}') d\mathbf{r}', \mu_k \right\rangle,
\end{equation*}
%and the $i$-th element of the vector $\mathbf{D}_{km}$,
%\begin{equation*}
%    D_{km}^{(i)} = \gamma_k b_1 \left\langle \int_{\Omega} J(\mathbf{r}, \mathbf{r}') (r'_i - r_i)^2 \mu_m(\mathbf{r}') d\mathbf{r}', \mu_k \right\rangle.
%\end{equation*}
and, since $\Phi$ is isotropic and assuming the memories to be nearly isotropic on average leads to isotropic diffusion, 
\begin{equation*}
    D_{km} = \gamma_k b_1 \left\langle \int_{\Omega} J(\mathbf{r}, \mathbf{r}') (\mathbf{r}'-\mathbf{r})^2 \mu_m(\mathbf{r}') d\mathbf{r}', \mu_k \right\rangle.
\end{equation*}

\emph{Pattern dynamics.~}
The $M$ coupled equations Eq.~\ref{eq:ampleq} describe the growth, interactions and (spatio-temporal) dynamics of the $M$ stored (memory) patterns in the full system.
The coupled amplitude equations constitute a gradient system $\partial \mathbf{A}/\partial t = - \nabla V[\mathbf{A}]$, given the potential
\begin{equation*}
    V[\mathbf{A}] = \int_{\Omega} \sum_{k=1}^{M} \left( -F_k[\mathbf{A}] + \frac{1}{2}\sum_{m=1}^{M} \nabla A_k \cdot D_{km} \nabla A_m \right) d\mathbf{r},
\end{equation*}
with
\begin{equation*}
    F_k[\mathbf{A}] = \left(\sum_{m=1}^{M} \frac{\alpha_{km}}{2} A_m
    + \sum_{i=1}^{M} \sum_{j=1}^{M} \sum_{m=1}^{M} \frac{\beta_{kijm}}{4} A_i A_j A_m \right) A_k.
\end{equation*}
Hence, the system at $\varepsilon \mathbf{r}$ spatial and $\varepsilon^2 t$ temporal scales will tend to settle into a time-independent state.

Bulk dynamics (Fig.~\ref{fig:bulk}) capture the pattern growth from low amplitude initial conditions, and the subsequent saturation of a sinlge pattern to amplitude $A_k \to A_{k}^{*} = \varepsilon \sqrt{\alpha_{kk}/\beta_{kkkk}}$, together with the supression of the other patterns $A_{m \neq k} \to 0$ due to the cubic interaction terms.
For small enough $\varepsilon$ the coefficients of the linear terms $A_k$ and cubic interactions $A_m^2 A_k$ in Eq.~\ref{eq:ampleq} will balance, so that in general the only stable equilibria will be single pattern states, as in the example of Fig.~\ref{fig:bulk}.
Symmetric states, with multiple patterns having the same non-vanishing amplitude, are unstable equilibria.
\begin{figure}
    \centering
    \includegraphics{amaeq-figure0}
    \caption{Bulk dynamics with $M=3$ stored patterns, comparing the pattern amplitudes $\hat{A}_k = \langle u(t,x), \mu_k\rangle$ obtained from simulating the full system (Eq.~\ref{eq:du}, grey markers), and the amplitudes obtained by numerically integrating the system of amplitude equations (Eq.~\ref{eq:ampleq}, black lines).}\label{fig:bulk}
\end{figure}

The spatial restriction of the connections, $\Phi$, leads to a finite diffusion rate of the memory patterns, and hence spatio-temporal pattern dynamics are expected in the full system.
The equations governing the pattern amplitudes (Eq.~\ref{eq:ampleq}) are $M$ coupled parabolic partial differential equations, so travelling wave-front solutions, connecting $A_k = A_{k}^{*} = \varepsilon \sqrt{\alpha_{kk}/\beta_{kkkk}}$ behind the wave-front to $A_k = 0$ infront of the wave-front, exist~\cite{fife1979mathematical, volpert1994traveling, saarloos2003front}.
These solutions correspond to a patterned solution, $u(\mathbf{r}, t) \propto \mu_k(\mathbf{r})$, invading an unpatterned spatially homogeneous domain~\footnote{analogous to patterning fronts for spatially periodic states~\cite{dee1983propagating}}, illustrated with the colourmap in Fig.~\ref{fig:patwave}.
The minimal front propagation velocity for a plane wave can be found by standard methods to be $c_k^{*} = \varepsilon \sqrt{2\alpha_{kk} D_{kk}}$.
The theoretical front position, using $c_k^{*}$, is indicated by the white dashed lines in Fig.~\ref{fig:patwave}.
\begin{figure}
\centering
    \includegraphics{amaeq-figure1}
    \caption{Spatio-temporal profile of a pattern forming wave-front invading a spatially homogeneous domain. 
        Colour intensity indicates the local pattern amplitude $u(r, t) \odot \mu_k(r)$, and the theoretical front position $r = r_0 + \varepsilon \sqrt{2 \alpha_{kk} D_{kk}}t$ is shown as white dashed lines.
    }\label{fig:patwave}
\end{figure}

\emph{Conclusion.~}
In conclusion, in this letter the derivation of pattern amplitude equations is extended from spatially periodic inhomogeneous sates to arbitrary spatially heterogeneous states that are stored in the spatially restricted non-local connectivity of the system.
The resulting amplitude equations have the same form as those for spatially periodic states, but with mode interactions leading to linear growth (non-vanishing off-diagonal entries in $\alpha_{km}$) and cross-diffusion (non-vanishing off-diagonal entries in $D_{km}$).

The memory pattern dynamics are universal for systems of the form Eq.~\ref{eq:du}, and are governed by the derived system of coupled amplitude equations (Eq.~\ref{eq:ampleq}) in case the spatially homogeneous base state of the system looses stability supercritically.
To derive the subcritical amplitude equations the perturbation expansion needs to be carried out to higher order, such that $O(\varepsilon^5)$ terms provide quintic terms saturating pattern growth.
