\section{A universal formula for computing $t_k$s}
\label{app:teekay-machinery}
Let us define the following  polynomial of degree $k{-}1$:
\begin{eqnarray}
    F_k(\lambda)= {}_2 F_1 \left(1-k, 1, \frac{3}{2},-\lambda \right)\ .
\end{eqnarray}
 We wish to find a family of (infinite order) operators $O_j$ such that:
\begin{equation}
    O_j F_k(\lambda = 0) = \delta_{jk}\ .
\end{equation}
If we have them, we can read off $t_k$s from the action of $O_j$ on the density function:
\begin{equation}
    \tilde{\rho}(\lambda, E_0) = \lambda^{-1/2} \rho_0(\lambda, E_0) \mp \frac{|\widetilde\Gamma|}{2\pi \hbar} \frac{1}{E_0 (1+\lambda)}\ .
\end{equation}
Note that $\tilde\rho(\lambda)$ is a smooth function. It will be convenient to introduce the following coefficients:
\begin{equation}
    a_n = \partial_\lambda^n F_{n+1}(\lambda=0) = \frac{2^n (n!)^2}{(2n+1)!!} = \frac{2^{2n} (n!)^3}{(2n+1)!}\ .
\end{equation}
Then, it is easy to notice that the following works:
\begin{eqnarray}
    O_1 = \sum_{n=0} \frac{(-1)^n}{a_n} \partial_\lambda^{n}\ .
\end{eqnarray}
 What about higher $O$s? The following do the job:
\begin{equation}
    O_2 = \sum_{n=1} \frac{(-1)^{n+1} n}{a_n}\partial^n_\lambda\ ,
\end{equation}
\begin{equation}
    O_3 = \frac{1}{2} \sum_{n=2} \frac{(-1)^n n(n-1)}{a_n} \partial_\lambda^n\ ,
\end{equation}
\begin{equation}
    O_4 =\frac{1}{6} \sum_{n=3} \frac{(-1)^{n+1} n(n-1)(n-2)}{a_n} \partial_\lambda^n\ ,
\end{equation}
\begin{eqnarray}
    O_5=\frac{1}{24}  \sum_{n=4} \frac{(-1)^n n(n-1)(n-2)(n-3)}{a_n} \partial_\lambda^n\ .
\end{eqnarray}
We thus see a clear pattern and we can write:
\begin{equation}
    O_k = \sum_{n=k-1} \frac{(-1)^{n+k-1}}{a_n} {{n}\choose{k-1}} \partial_\lambda^n\ .
\end{equation}
This can be written even more compactly if we introduce: 
\begin{equation}
    O(y) =  \sum_{n=0} \frac{(y-1)^n}{a_n} \partial_\lambda^{n}\ .
\end{equation}
Then, it is easy to see that:
\begin{equation}
    O_k = \frac{1}{(k-1)!}\partial_y^{k-1} O(y=0)\ ,
\end{equation}
or
\begin{equation}
    O(y) = \sum_{k=0} \frac{y^k}{k!} \partial_y^{k} O(y=0) = t^k O_{k+1}\ ,
\end{equation}
and so it follows that
\begin{equation}
    O(y) \hat{\rho}(\lambda = 0)
\end{equation}
is a generating function of the $t_k$s.






