\section{Preliminaries}

\subsection{Quasi-projections and quasi-idempotents}
Let~\( A \) be a \Cst-algebra and let~\( 0<\varepsilon<\frac{1}{4} \). An
\( \varepsilon \)-\emph{quasi-idempotent} is an element~\( e\in A \)
satisfying~\( \norm{e^2-e}<\frac{1}{4} \). If~\( \varepsilon=\frac{1}{4}
\), then we also call~\( e \) a \emph{quasi-idempotent} for short. An
\( \varepsilon \)-\emph{quasi-projection} is a self-adjoint~\( \varepsilon
\)-quasi-idempotent.

Let~\( e_0,e_1\in A \) be quasi-idempotents. 
A \emph{homotopy} between~\( e_0 \)
and~\( e_1 \) is a norm-continuous path 
\( e\colon [0,1]\to A \), such that each
\( e(t) \) is a quasi-idempotent, and that~\( e(0)=e_0 \) and~\( e(1)=e_1
\). Similarly, a homotopy between quasi-projections is a norm-continuous
path of quasi-projections connecting them.

If~\( e\in A \) 
is a quasi-idempotent, then~\( \spc(e) \) does not meet the line
\[
   L\defeq\set*{z\in\C\;\middle|\;\Re z=\sfrac{1}{2}}
\]
in the complex plane. Hence the function
\[ 
    \kappa_0\colon \C\setminus L\to\{0,1\},\quad \kappa_0(z)\defeq\begin{cases}
    1, & \Re z>\sfrac{1}{2};\\
    0, & \Re z<\sfrac{1}{2},
    \end{cases}
\]
is holomorphic on~\( \spc(e) \). Holomorphic functional calculus then gives
a projection~\( \kappa_0(e)\in A \) as well as a
well-defined class~\( [e]\defeq [\kappa_0(e)]\in\K_0(A) \). Similarly,
every quasi-idempotent~\( e\in\Mat_n(A) \) determines a class in~\( \K_0(A)
\). This allows for ``defining''~\( \K_0(A) \) using quasi-idempotents or
quasi-projections in the same way as projections, in the following sense:

\begin{proposition}[cf.~\cite{Willett-Yu:Higher_index_theory}*{Proposition
2.2.9}]\label{prop:K-theory_quasi-idempotents}
Let~\( A \) be a unital \Cst-algebra. 
Then~\( \K_0(A) \) is isomorphic to the Grothendieck group of the monoid
\( V(A) \), where~\( V(A) \) consists of homotopy-equivalence classes of
quasi-idempotents in~\( \Mat_{\infty}(A) \), and the sum is given by~\(
[e]+[f]\defeq\left[\left(\begin{smallmatrix}
    e & 0 \\ 0 & f
\end{smallmatrix}\right)\right] \). 
\end{proposition}

As opposed to projections or idempotents, quasi-idempotents and
quasi-projections form open sets in~\( A \). This is convenient for
constructing homotopies between them, and allowing more representatives for
classes in~\( \K_0(A) \). We provide below
a few quantitative estimates related to quasi-idempotents. Many
similar but not identical results have been used in the context of
quantitative K-theory for \Cst-algebras or Banach algebras, 
cf.~\cites{Oyono-Yu:Quantitative_K-theory,Chung:Quantitative_K-theory_Banach_algebras}.

\begin{lemma}\label{lem:estimate_f2-f}
Let~\( e,f\in A \), then we have the following inequality\textup{:}
\[ 
    \norm{f^2-f}\leq(2\norm*{e}+\norm{e-f}+1)\norm*{e-f}+\norm{e^2-e}.
\]
\end{lemma}
\begin{proof}
This follows from
\[ 
    f^2-f=(f-e)(f-e)+e(f-e)+(f-e)e+(e-f)+(e^2-e). \qedhere
\]
\end{proof}

\begin{lemma}\label{lem:homotopy_quasi-idempotents}
Let~\( e\in A \) be an~\( \varepsilon_e \)-quasi-idempotent,~\( f\in A \) an
\( \varepsilon_f \)-quasi-idempotent. Let~\( \delta\defeq\norm*{e-f} \).
Assume that
\[
    \max\{\varepsilon_e,\varepsilon_f\}+\frac{1}{4}\delta^2<\frac{1}{4},
\]
then~\( e \) and~\( f \) are homotopic as quasi-idempotents.    
\end{lemma}
\begin{proof}
For each~\( s\in[0,1] \), we have
\begin{align*} 
&\big((1-s)e+sf\big)^2-\big((1-s)e+sf\big)\\
=&(1-s)(e^2-e)+(s^2-s)e^2+s(f^2-f)+(s^2-s)f^2+(s-s^2)(ef+fe) \\
=&(1-s)(e^2-e)+s(f^2-f)+(s^2-s)(e-f)^2.
\end{align*}
Thus
\[ 
\norm*{\big((1-s)e+sf\big)^2-\big((1-s)e+sf\big)}<\max\{\varepsilon_e,\varepsilon_f\}+\frac{1}{4}\norm*{e-f}^2
<\frac{1}{4}.
\]
So~\( s\mapsto (1-s)e+sf \) is a homotopy of quasi-idempotents between~\( e
\) and~\( f \).    
\end{proof}

Combining the two preceding lemmas, we have the following
\begin{theorem}\label{thm:close_quasi-idempotents_homotopic}
Let~\( A \) be a \Cst-algebra and~\( e,f\in A \). Let~\( \delta\defeq
\norm*{e-f} \).   
\begin{enumerate}
\item If~\( e \) is an~\( \varepsilon \)-quasi-idempotent and
\( f \) satisfies
\[ 
    (2\norm*{e}+\frac{5}{4}\delta+1)\delta+\varepsilon<\frac{1}{4}.
\]
Then~\( f \) is a~\( ((2\norm*{e}+\delta+1)\delta+\varepsilon)
\)-quasi-idempotent, which is homotopic to~\( e \) via a
path of quasi-idempotents.
\item As a special case, if~\( e \) is a projection and~\( f\in A \) is
self-adjoint satisfying~\( \delta<\frac{1}{17} \).
Then~\( f \) is a~\( 4\delta \)-quasi-projection, which is homotopic to
\( e \) as quasi-projections.  
\end{enumerate}
\end{theorem}
\begin{proof}
Let~\( e \) be an~\( \varepsilon \)-quasi-idempotent. It follows from the
\Cref{lem:estimate_f2-f} that~\( f \) is an
\( \varepsilon_f \)-quasi-idempotent, where 
\[ 
    \varepsilon_f\defeq (2\norm*{e}+\delta+1)\delta+\varepsilon;
\]
and
\[ 
    \max\{\varepsilon_e,\varepsilon_f\}+\frac{1}{4}\delta^2<(2\norm*{e}+\frac{5}{4}\delta+1)\delta+\varepsilon<\frac{1}{4}.
\]
Then it follows from the assumption and
\Cref{lem:homotopy_quasi-idempotents} that~\( e \) and~\(
f\) are homotopic through the straightline path connecting them.

If~\( e \) is a projection and~\( \delta<\frac{1}{17} \), 
then~\( \varepsilon=0 \) and~\(
\norm*{e}=1 \). So 
\[ 
    (2\norm*{e}+\frac{5}{4}\delta+1)\delta+\varepsilon<(2+\frac{5}{4}+1)\delta<\frac{1}{4}.
\]
If~\( f \) is self-adjoint, then by (1), 
\( f \) is~\( 4\delta \)-quasi-projection which is homotopic to~\(
e\) via the straightline homotopy connecting~\( e \) and~\( f \) because
\[ 
    (2\norm{e}+\delta+1)\delta+\varepsilon<(2+1+1)\delta=4\delta.
\]
Since both~\( e \) and~\( f \) are self-adjoint, it follows that~\(
(1-s)e+sf \) is self-adjoint for each~\( s\in[0,1] \). This implies that
the~\( e \) and~\( f \) are homotopic through a path of self-adjoint
quasi-idempotents, i.e.~quasi-projections.       
\end{proof}

\subsection{Unbounded Kasparov modules}
We recall the definition of odd, unbounded Kasparov modules. In particular,
we explain how an unbounded Kasparov module determines
an \emph{extension class}, that is, a class in~\( \KK_1(A,B) \) represented
by an extension. This is required for Connes--Higson's construction of 
asymptotic morphism in \Cref{lem:Connes-Higson_extension_to_E}.

Let~\( \mathcal{E} \) and~\( \mathcal{F} \)
be Hilbert~\( B \)-modules for a \Cst-algebra~\( B \), we write:
\begin{itemize}
\item \( \Cpt_B(\mathcal{E}) \) for the \Cst-algebra of compact operators
on~\( \mathcal{E} \); 
\item \( \Fin^*_B(\mathcal{E}) \) for the algebra of all finite-rank
operators on~\( \mathcal{E}\);
\item \( \End^*_B(\mathcal{E}) \) for the \Cst-algebras of bounded
adjointable operators on~\( \mathcal{E} \);
\item \( \Hom^*_B(\mathcal{E},\mathcal{F}) \) for the space of all~\( B
\)-linear, bounded adjointable operators~\( \mathcal{E}\to \mathcal{F} \).
\end{itemize}
\begin{definition}
Let~\( A \) and~\( B \) be \Cst-algebras. An \emph{odd unbounded Kasparov
\( A \)-\( B \)--module} is a triple~\( (\mathcal{A},E,D) \), where: 
\begin{itemize} 
\item \( E \) is a Hilbert~\( B \)-module;
\item \( \varrho\colon A\to\End^*_B(E) \) is an \emph{essential}
\st-homomorphism, that is,
\( \overline{\varrho(A)E}=E \); and
\( \mathcal{A}\subseteq A \) is a dense \st-subalgebra; we shall always
abbreviate~\( \varrho(a) \) as~\( a \).  
\item \( D\colon\dom D\subseteq E\to E \) 
is a self-adjoint and regular operator.
\end{itemize} 
such that:
\begin{itemize} 
\item \( \varrho(a)(D+\mathrm{i})^{-1}\in\Cpt_B(E) \) 
for all~\( a\in\mathcal{A} \) (and hence for
all~\( a\in A \));
\item For every~\( a\in\mathcal{A} \),~\( \varrho(a) \) maps~\( \dom D \)
into~\( \dom D \), and~\( [D,\varrho(a)] \)
extends to an element of~\( \End^*_B(E) \).
\end{itemize}
\end{definition}

\begin{remark}
We note that in the common definition of odd unbounded Kasparov modules,
\( \varrho\colon A\to\End_B^*(E) \) is \emph{not} assumed to be
essential. However, this turns out to be necessary for several 
constructions of the present paper, in particular, in
\Cref{app:asymptotic_morphism}. Nevertheless, every class in~\(
\KK_1(A,B) \) can be represented by an essential odd unbounded
Kasparov module.

If~\( A \) is unital, then 
an essential \st-homomorphism~\( \varrho\colon A\to\End_B^*(E) \) is
always unital. This implies that~\(
(D+\mathrm{i})^{-1}=\varrho(1)(D+\mathrm{i})^{-1}\in\Cpt_B(E) \). If
moreover~\( B=\C \), then~\( D \) has compact resolvent, hence has discrete
spectrum.
\end{remark}

We follow the line of \cite{Kasparov:K-functor_extension}*{Section 7} to
construct an extension of \Cst-algebras from an odd bounded Kasparov
module. Let~\( \chi\colon \R\to[-1,1] \) be a chopping function, i.e.~\(
\lim_{x\to\pm \infty}\chi(x)=\pm 1 \), then 
the \emph{bounded transform}
\[ 
    (\mathcal{A},E,D)\quad\longmapsto\quad (A,E,\chi(D))
\]
gives a bounded Kasparov module 
(cf.~\cite{Baaj-Julg:Unbounded_Kasparov_theory}*{Proposition 2.2} for the
special case~\( \chi(x)\defeq x(1+x^2)^{-1/2} \)). 
Then the unbounded Kasparov module~\(
(\mathcal{A},E,D) \) gives rise to a Busby invariant 
\[ \beta\colon A\to\End_B^*(E)/\Cpt_B(E),\quad
a\mapsto q(P_1 aP_1) \]
where~\( P_1\defeq \frac{1}{2}(\chi(D)+1) \) is as in \eqref{eq:P_1}, and 
\( q\colon\End^*_B(E)\to \End^*_B(E)/\Cpt_B(E) \) is the quotient map. 
This Busby invariant 
corresponds to the semi-split extension 
\begin{equation}\label{eq:Kasparov_KK_to_extension} 
\begin{tikzcd}
\Cpt_B(E) \arrow[r, tail] & M
\arrow[r, two heads] & A \arrow[l,bend left, "s"] 
\end{tikzcd} 
\end{equation} 
with~\( M \) the \Cst-algebra
\[
M\defeq \set*{(a,T)\in A\oplus
\End_B^*(E)\;\middle|\;\beta(\varrho(a))=q(T)} \]
with the semi-split section~\( s\colon A\to M \) given by
\( s(a)=(a,P_1\varrho(a)P_1) \).

The odd unbounded Kasparov module~\( (\mathcal{A},E,D) \) represents a
class in~\( [D]\in\KK_1(A,B) \). Via the Kasparov product
\eqref{eq:KK_index_pairing}, 
it gives a map
\[ 
    \K_1(A)\xrightarrow{\times[D]}\K_0(B),
\]
which can now be rephrased as the following composition of maps:
\begin{equation}\label{eq:K-theoretic_index_pairing}
\K_1(A)\xrightarrow{\partial}\K_0(\Cpt_B(E))\xrightarrow{[E]}\K_0(B),
\end{equation}
where~\( \partial \) is the boundary map of the extension
\eqref{eq:Kasparov_KK_to_extension}, and 
the map~\( [E]\colon \K_0(\Cpt_B(E))\to\K_0(B) \) is induced by the proper
\Cst--\( \Cpt_B(E) \)-\( B \)--correspondence~\( E \). If~\( E \) is a
\emph{full} Hilbert~\( B \)-module, then~\( E \) becomes an imprimitivity
bimodule between~\( \Cpt_B(E) \) and~\( B \), and the induced map~\( [E] \)
is an isomorphism.

In the special case~\( B=\C \), then an odd unbounded Kaspaorv~\( A \)-\(
B\)--module is the same thing as an odd spectral triple~\(
(\mathcal{A},\mathcal{H},D) \). Every Hilbert space~\( \mathcal{H} \) 
is full as a Hilbert~\( \C \)-module, thus implements a Morita--Rieffel 
equivalence between~\( \Cpt(\mathcal{H}) \) and~\( \C \).

In the rest of this article, we shall write~\( \braket{[v],[D]} \) for the
image of~\( [v]\in\K_1(A) \) under the map~\( \partial\colon
\K_1(A)\to\K_0(\Cpt_B(E)) \), and call it the
\emph{\textup{(}\K-theoretic\textup{)} index pairing}. The Kasparov product
between the class~\( [v]\in\K_1(A) \) and~\( [D]\in\KK_1(A,B) \) will be
denoted by~\( [v]\times[D] \).   

\subsection{Asymptotic morphisms}
Let~\( A \) and~\( B \) be \Cst-algebras. 
An \emph{asymptotic morphism} from~\( A \) to~\( B \)
is a family of maps~\( \Phi_t\colon
A\to B \), parametrised by~\( t\in [1,\infty) \), that ``asymptotically''
becomes a \st-homomorphism. Such an asymptotic morphism defines an element
in the E-theory group~\( \E(A,B) \), which via the E-theory product
\begin{equation}\label{eq:E_index_pairing}\tag{E}
    \underbrace{\E_i(\C,A)}_{\simeq\K_i(A)}
    \times\E_j(A,B)\to\underbrace{\E_{i+j}(\C,B)}_{\simeq\K_{i+j}(B)},
\end{equation}
induces a group homomorphism~\( \K_0(A)\to\K_0(B) \).

We recall form~\cite{Connes-Higson:E-theory} 
some basic facts of asymptotic morphisms. 
We fix the following notation: let~\( (a_t)_{t\in[1,\infty)} \) 
and~\( (b_t)_{t\in[1,\infty)} \) be two nets of elements in
the same \Cst-algebra, then we write
\[ 
    a_t\sim b_t\qquad\text{iff}\qquad
    \lim_{t\to \infty}\norm*{a_t-b_t}=0.  
\]

\begin{definition}\label{def:asymptotic_morphism}
Let~\( A \) and~\( B \) be \Cst-algebras. An \emph{asymptotic morphism} from~\( A \) to
\( B \) consists of a family of maps~\( (\Phi_t\colon A\to
B)_{t\in[1,\infty)} \) such that:
\begin{enumerate}
\item \( t\mapsto \Phi_t(a) \) is continuous for all~\( a\in A \);
\item for all
\( a,a'\in A \) and~\( \lambda\in\C \),
\[ \Phi_t(a^*)\sim\Phi_t(a)^*,\quad
\Phi_t(aa')\sim\Phi_t(a)\Phi_t(a'),\quad \Phi_t(a+\lambda
a')\sim\Phi_t(a)+\lambda\Phi_t(a'). \]
\end{enumerate}
\end{definition}

\begin{definition}
Two asymptotic morphisms~\( (\Phi_t\colon A\to B) \) and
\( (\Psi_t\colon A\to B) \) are \emph{\textup{(}asymptotically\textup{)}
equivalent}, if for all~\( a\in A \), it follows that 
\(\Phi_t(a)\sim\Psi_t(a)\).

Two asymptotic morphisms~\( (\Phi^0_t\colon A\to B) \) and~\( (\Phi^1_t\colon
A\to B) \) are \emph{\textup{(}asymptotically\textup{)} homotopic}, 
if there exists an asymptotic morphism
\( \Phi_t\colon A\to\Cont([0,1],B) \) such that
\( \ev_i\circ\Phi_t\sim\Phi_t^i \) for~\( i=0,1 \).
\end{definition}

\begin{remark}
If two asymptotic morphisms are equivalent, then they are homotopic via a
straight line connecting them.
\end{remark}

\begin{definition}[Extension to matrix algebras and unitisations]
Let~\( (\Phi_t\colon A\to B) \) be an asymptotic morphism, then for each~\(
n\in\N\),~\( (\Phi_t) \)  extends
to an asymptotic morphism from~\( \Mat_n(A^+) \) to~\( \Mat_n(B^+) \)
(still denoted~\( \Phi_t \) for simplicity)
as follows: one first extends~\( \Phi_t \) to the minimal 
unitisations of~\( A \) and~\( B \)  by setting
\[ 
    \Phi_t(a,\lambda)\defeq (\Phi_t^+(a),\lambda),
\]
then extend to their matrix algebras by applying~\( \Phi_t \) entrywise. 
\end{definition}


The following result is well-known,
cf.~\cite{Guentner-Higson-Trout:Equivariant_E-theory}*{Chapter 1}:

\begin{proposition}
Let~\( (\Phi_t\colon A\to B) \) be an asymptotic morphism, then it induces a
map~\( \Phi_*\colon \K_0(A)\to\K_0(B) \) as follows: let~\( p\in\Mat_n(A^+)
\) be a projection. By definition, for sufficiently large~\( t_0>0 \), there
exists a projection~\( q_t \) that is close to~\( \Phi_t(p) \) for each~\(
t>t_0\), and all of these~\( q_t \)'s for~\( t>t_0 \)  
are homotopic. This gives a well-defined class in~\( \K_0(B) \).     
\end{proposition}

If we represent~\( \K_0 \)-groups by quasi-idempotents, then the preceding
proposition can be rephrased as: for each projection~\( p\in \Mat_n(A^+)
\), there exists~\( t_0>0 \), such that~\( [\Phi_t(p)] \) gives the same
class in~\( \K_0(B) \) for every~\( t>t_0 \), which is defined to be the
image of~\( [p] \) under the K-theory induced map of~\( (\Phi_t)_t \).      
We note in particular that, if~\( \Phi_t\colon A\to B \) and~\( \Psi_t\colon
A\to B \) are \emph{homotopic} asymptotic morphisms, then~\( \Phi_*\colon
\K_0(A)\to\K_0(B) \) coincides with~\( \Psi_*\colon \K_0(A)\to\K_0(B) \). 

\begin{proposition}
The asymptotic morphism
\begin{equation}\label{eq:Phi^D}
\Phi^D_t\colon \Co(\R)\otimes A\to\Cpt_B(E),\quad f\otimes a\mapsto
f(t^{-1}D)a
\end{equation}
induces a map~\( \K_0(\mathrm{S}A)\to\K_0(B) \),
which coincides with the
index pairing~\( \braket{[v],[D]} \) under the isomorphism~\(
\K_1(A)\simeq\K_0(\mathrm{S}A) \) in \Cref{lem:odd_K-theory}. 
Here~\( \mathrm{S}A \) refers to the
non-unital \Cst-algebra~\( \Co(\R)\otimes A \). 
\end{proposition}

\begin{proof}
We provide the proof in \Cref{app:asymptotic_morphism} based on the
following facts: given an unbounded Kasparov module 
\( (\mathcal{A},E,D) \), it gives an extension
of \Cst-algebras as in \eqref{eq:Kasparov_KK_to_extension} and hence an
asymptotic morphism~\( (\Phi^\mathrm{CH}_t) \)
via the Connes--Higson's construction
\[
\Phi^\mathrm{CH}_t\colon \Co(0,1)\otimes B\to I,\qquad f\otimes b\mapsto
f(u_t)s(b).
\]
Then~\( (\Phi^\mathrm{CH}_t) \) induces the K-theoretic index pairing
\[ 
    \partial\colon\K_0(\mathrm{S}A)\to\K_0(\Cpt_B(E))
\]
associated to the unbounded Kasparov module~\( (\mathcal{A},E,D) \) as in
\eqref{eq:K-theoretic_index_pairing}. It is invariant under
\emph{homotopies} of asymptotic morphisms. Thus, it suffices to show that 
\eqref{eq:Phi^D} is, up to identifying~\( \R \) with~\( (0,1) \) using a
homeomorphism,  
homotopic to the Connes--Higson asymptotic 
morphism~\( (\Phi^{\mathrm{CH}}_t)_t \). 
\end{proof}

\section{Index pairing via asymptotic morphisms}
\subsection{The odd K-theory class}
An odd unbounded Kasparov~\( A \)-\( B \)--module~\( (\mathcal{A},E,D) \)
gives rise to a semi-split extension \eqref{eq:Kasparov_KK_to_extension},
henceforce an asymptotic morphism~\( \Co(\R)\otimes A\to\Cpt_B(E) \). We
shall compute the image of the class~\( [v]\in\K_1(A) \) of a unitary~\(
v\in A \) under this asymptotic morphism. In order to do this,
we must first map the class~\(
[v]\in\K_1(A) \) of a unitary~\( v\in A \) to a class in~\(
\K_0(\mathrm{S}A) \) under the suspension isomorphism~\(
\K_1(A)\simeq\K_0(\mathrm{S}A) \).

\begin{lemma}\label{lem:odd_K-theory}
Let~\( v\in A \) be a unitary. Let~\( c,s\colon \R\to[0,1] \) be continuous
functions that satisfy
\[
    c^2(x)+s^2(x)=1,\quad \lim_{x\to\infty}s(x)=1,\quad
    \lim_{x\to-\infty}c(x)=1.
\]
Define~\( e,f\colon \R\to\Mat_2(A) \) as 
\begin{gather*} 
    e(x)\defeq
    \begin{pmatrix}
    s(x)^2\otimes1 & c(x)s(x)\otimes v \\
    c(x)s(x)\otimes v^* & c(x)^2\otimes 1
    \end{pmatrix};\quad
    f(x)\defeq
    \begin{pmatrix}
    0 & 0 \\ 0 & 1
    \end{pmatrix}.
\end{gather*}
Then both~\( e \) and~\( f \)  
are projections in~\( \Mat_2(\mathrm{S}A^+) \), and
\( [e]-[f]\in\K_0(\mathrm{S}A) \) is the image of~\(
[v]\in\K_1(A) \) under the suspension isomorphism~\(
\K_1(A)\xrightarrow{\sim}\K_0(\mathrm{S}A) \).  
\end{lemma}

\begin{proof}
Let
\[ \begin{tikzcd}
\mathrm{S}A\arrow[r, tail] & \mathrm{C}A \arrow[r, two heads,
"\ev_{+\infty}"] & A
\end{tikzcd} \]
be the suspension--cone extension, where~\( \mathrm{C}A\defeq
\Co((-\infty,+\infty],A) \) and~\( \ev_{+\infty}\colon \mathrm{C}A\to A \) is the evalutation map 
at~\( +\infty \).
The boundary map associated to this extension
\( \partial\colon\K_1(A)\to\K_0(\mathrm{S}A) \) is an isomorphism because
\( \mathrm{C}A \) is contractible. Up to a sign, this uniquely determines
the suspension isomorphism~\( \K_1(A)\simeq\K_0(\mathrm{S}A) \). 

We use the partial isometry picture to compute the suspension
isomorphism as in
\cite{Roerdam-Larsen-Laustsen:K-theory}*{Proposition 9.2.2}. Let~\(
z\colon\R\to\Mat_2(A) \) be defined as
\[ 
    z\defeq\begin{pmatrix}
    s(x)\otimes v & -c(x)\otimes 1
    \\
    0 & 0
    \end{pmatrix}.  
\]
Then~\( z\in\Mat_2(\mathrm{C}A^+) \) is a partial isometry, which lifts~\(
v\oplus 0 \) under~\( \ev_{+\infty} \). Thus we have
\[ 
    \partial[v]=[\mathbf{1}_{2\times 2}-z^*z]-[\mathbf{1}_{2\times
    2}-zz^*].
\]
We compute that
\begin{align*} 
\mathbf{1}_{2\times 2}-z^*z&=
\begin{pmatrix}
1 & 0 \\ 0 & 1
\end{pmatrix}-
\begin{pmatrix}
s^2(x)\otimes 1 &
-c(x)s(x)\otimes v^* \\
-c(x)s(x)\otimes v &
c^2(x)\otimes 1 
\end{pmatrix}\\
&=\begin{pmatrix}
c^2(x)\otimes 1 &
c(x)s(x)\otimes v^* \\
c(x)s(x)\otimes v &
s^2(x)\otimes 1 
\end{pmatrix}; \\
\mathbf{1}_{2\times 2}-zz^*&=
\begin{pmatrix}
1 & 0 \\ 0 & 1
\end{pmatrix}-\begin{pmatrix}
1 & 0 \\ 0 & 0
\end{pmatrix}
=\begin{pmatrix}
0 & 0 \\ 0 & 1
\end{pmatrix}=f.
\end{align*}
The claim follows as
\[ 
    e=\begin{pmatrix}
    0 & 1 \\ 1 & 0
    \end{pmatrix}\begin{pmatrix}
    c^2(x)\otimes 1 & c(x)s(x)\otimes v^* \\
    c(x)s(x)\otimes v & s^2(x)\otimes 1
    \end{pmatrix}
    \begin{pmatrix}
    0 & 1 \\ 1 & 0
    \end{pmatrix}.\qedhere
\]
\end{proof}
\begin{remark}
We note that the natural isomorphism 
\( \K_1(A)\simeq\K_0(\mathrm{S}A) \) is unique only up to a sign, as shown
by Elliott \cite{Elliott:Uniqueness_index_map_complex}. For
instance, if one replaces~\( \mathrm{C}A=\Co((-\infty,+\infty],A) \) by~\(
\Co([-\infty,+\infty),A) \) and~\( \ev_{+\infty} \) by~\( \ev_{-\infty} \),
then the same index map formula as in
\cite{Roerdam-Larsen-Laustsen:K-theory} yields
the inverse of the class~\( [e]-[f]\in\K_0(\mathrm{S}A) \) 
constructed above. The convention that we have adopted gives the correct
index pairing, 
cf.~\Cref{thm:index_pairing_quasi-projections,thm:index_pairing_submodule}.
\end{remark}



\subsection{Representing the odd index pairing by quasi-projections}
We apply the asymptotic morphism \eqref{eq:Phi^D} to the K-theory class
\( [e]-[f]\in\K_0(\mathrm{S}A) \). Set~\(c_t\defeq c(t^{-1}D) \) and 
\( s_t\defeq s(t^{-1}D) \);
define~\( \check{e}_t\defeq \Phi^D_t(e) \) and 
\( f_t\defeq \Phi^D_t(f) \). Then  
\[ 
\check{e}_t=\begin{pmatrix}
    s_t^2 & c_ts_tv \\
    c_ts_tv^* & c^2_t
    \end{pmatrix},\quad
f_t=\begin{pmatrix}
0 & 0 \\ 0 & 1
\end{pmatrix}.
\] 

Thus~\( (f_t)_{t\in [1,\infty)} \) 
is a constant family of projection.
The family of operators~\( (\check{e}_t)_{t\in [1,\infty)} \) satisfies
\[ 
    \check{e}_t^*-\check{e}_t\sim 0,\quad \check{e}_t^2-\check{e}_t\sim 0
\]
and hence ``asymptotically'' a projection. For sufficiently large~\( t \),
\( \check{e}_t \) is a quasi-idempotent, yet not self-adjoint. The
asymptotic self-adjointness, nevertheless, allows us to replace~\(
(\check{e}_t)_{t\in [1,\infty)} \) by a family~\( (e_t)_{t\in [1,\infty)} \)
of \emph{quasi-projections}, up to homotopies of
quasi-idempotents. To obtain a quantitative estimate as in
the proposition below, we need extra assumptions for the commutators
\[ 
    [v,c_t],\quad [v,s_t],\quad [v,\sqrt{c_ts_t}].
\]

\begin{proposition}
Let
\begin{equation}\label{eq:e_t}
    e_t\defeq\begin{pmatrix}
     s_t^2 & \sqrt{c_ts_t} v\sqrt{c_ts_t} \\
    \sqrt{c_ts_t} v^*\sqrt{c_ts_t} &  c_t^2
    \end{pmatrix},
\end{equation}
Assume that there exists a constant~\( R>0 \),
independent of~\( t \),  such that
\begin{equation}\label{eq:assmption_constants_R}
\left.\begin{array}{r}
\norm*{[c_t,v]} \\
\norm*{[s_t,v]} \\
\norm*{[\sqrt{c_ts_t},v]}
\end{array}\right\}\leq R\cdot t^{-1}\norm*{[D,v]}
\end{equation}
Let
\[ 
0<\varepsilon<\frac{8}{237}(\sqrt{1393}-34)\approx 0.1122. 
\]
Then for every~\( t>2\varepsilon^{-1}R\norm*{[D,v]} \), the following
holds\textup{:}
\begin{enumerate}
\item \( e_t \) is an~\( \varepsilon \)-quasi-projection.
\item \( \norm*{e_t-\check{e}_t}<\frac{\sqrt{2}}{4}\varepsilon \). 
\item \( e_t \) is homotopic to~\( \check{e}_t \) via a
path of quasi-idempotents.
\end{enumerate}
\end{proposition}

\begin{proof}
To prove (1), we compute that
\begin{align*} 
e_t^2&=\begin{pmatrix}
s_t^2 & \sqrt{c_ts_t} v\sqrt{c_ts_t} \\
\sqrt{c_ts_t} v^*\sqrt{c_ts_t} &  c_t^2
\end{pmatrix}\begin{pmatrix}
s_t^2 & \sqrt{c_ts_t} v\sqrt{c_ts_t} \\
\sqrt{c_ts_t} v^*\sqrt{c_ts_t} &  c_t^2
\end{pmatrix} \\
&=\begin{pmatrix}
s_t^2+\sqrt{c_ts_t}[v,c_ts_t]v^*\sqrt{c_ts_t} & 
\sqrt{c_ts_t}v\sqrt{c_ts_t}+[\sqrt{c_ts_t}v\sqrt{c_ts_t},c_t^2] \\
\sqrt{c_ts_t}v^*\sqrt{c_ts_t}+[c_t^2,\sqrt{c_ts_t}v^*\sqrt{c_ts_t}] &
c_t^2+\sqrt{c_ts_t}v^*[c_ts_t,v]\sqrt{c_ts_t}
\end{pmatrix}.
\end{align*}
So
\begin{align*}
e_t^2-e_t=&\begin{pmatrix}
\sqrt{c_ts_t}[v,c_ts_t]v^*\sqrt{c_ts_t} & 0 \\ 0 &
\sqrt{c_ts_t}v^*[c_ts_t,v]\sqrt{c_ts_t}
\end{pmatrix}\\
&+\begin{pmatrix}
0 & [\sqrt{c_ts_t}v\sqrt{c_ts_t},c_t^2] \\
[c_t^2,\sqrt{c_ts_t}v^*\sqrt{c_ts_t}] & 0
\end{pmatrix}.
\end{align*}
Therefore,
\begin{align*}
\norm{e_t^2-e_t}\leq&
\max\{\norm*{\sqrt{c_ts_t}[v,c_ts_t]v^*\sqrt{c_ts_t}},\norm*{\sqrt{c_ts_t}v^*[c_ts_t,v]\sqrt{c_ts_t}}\}\\
&+\norm*{[\sqrt{c_ts_t}v\sqrt{c_ts_t},c_t^2]}
\end{align*}
Now we note that~\( v^*,v,\sqrt{c_t},\sqrt{s_t} \) are all contractive
operators, and
\[
    0\leq c_ts_t\leq\frac{1}{2}\left(c_t^2+s_t^2\right)=\frac{1}{2}\cdot\id.
\]
So~\( \sqrt{c_ts_t} \) has norm bounded by~\( \frac{\sqrt{2}}{2} \). 
By assumption \eqref{eq:assmption_constants_R}, we obtain
\begin{alignat*}{3}
\norm*{\sqrt{c_ts_t}[v,c_ts_t]v^*\sqrt{c_ts_t}}&\leq
(\tfrac{\sqrt{2}}{2})^2\norm*{[v,c_t]}+(\tfrac{\sqrt{2}}{2})^2\norm*{[v,s_t]}&\leq
R\cdot t^{-1}\norm*{[D,v^*]};\\
\norm*{\sqrt{c_ts_t}v^*[c_ts_t,v]\sqrt{c_ts_t}}&\leq
(\tfrac{\sqrt{2}}{2})^2\norm*{[c_t,v]}+(\tfrac{\sqrt{2}}{2})^2\norm*{[s_t,v]}&\leq
R\cdot t^{-1}\norm*{[D,v^*]};\\
\norm*{[\sqrt{c_ts_t}v\sqrt{c_ts_t},c_t^2]}&\leq
(\tfrac{\sqrt{2}}{2})^2\norm*{[v,c_t]}+(\tfrac{\sqrt{2}}{2})^2\norm*{[v,c_t]}&
\leq R\cdot t^{-1}\norm*{[D,v^*]}.
\end{alignat*}
Therefore,~\( \norm*{e_t^2-e_t}\leq 2R\cdot t^{-1}\norm*{[D,v^*]}<\varepsilon \). 
Clearly~\( e_t
\) is self-adjoint. This finishes the proof of (1).

Now we prove (2).
Use again the assumption \eqref{eq:assmption_constants_R}, we have
\begin{align*} 
\norm*{e_t-\check{e}_t}&=\norm*{\begin{pmatrix}
    0 & \sqrt{c_ts_t}[v,\sqrt{c_ts_t}] \\
    \sqrt{c_ts_t}[v^*,\sqrt{c_ts_t}] & 0
\end{pmatrix}}\\
&\leq\norm*{\sqrt{c_ts_t}}\cdot\norm*{[v,\sqrt{c_ts_t}]}\leq
\frac{\sqrt{2}}{2}Rt^{-1}\norm*{[D,v]}<\frac{\sqrt{2}}{4}\varepsilon.
\end{align*}

Now we prove (3). Note
that~\( e_t \) is an~\( \varepsilon \)-quasi-projection, so~\(
\norm*{e_t}<1+\varepsilon \); and~\(
\delta\defeq\norm*{\check{e}_t-e_t}<\frac{\sqrt{2}}{4}\varepsilon \). 
It follows that (below we take~\( \sqrt{2}<1.5 \)):
\begin{align*} 
\left(2\norm*{e_t}+\frac{5}{4}\delta+1\right)\delta+\varepsilon&<
\left(2(1+\varepsilon)+\frac{5}{4}\cdot\frac{\sqrt{2}}{4}\varepsilon+1\right)\frac{\sqrt{2}}{4}\varepsilon+\varepsilon\\
&<\left(\frac{79}{32}\varepsilon+3\right)\cdot\frac{3}{8}\varepsilon+\varepsilon \\
&=\frac{237}{256}\varepsilon^2+\frac{17}{8}\varepsilon<\frac{1}{4}.
\end{align*}
Therefore, by \Cref{thm:close_quasi-idempotents_homotopic},~\( e_t \) and
\( \check{e}_t \) are homotopic via a path of quasi-idempotents. 
\end{proof}

Then \Cref{prop:K-theory_quasi-idempotents} leads to the following
result:

\begin{theorem}\label{thm:index_pairing_quasi-projections}
Let~\( \varepsilon<0.1121 \). Assume that there exists~\( R>0 \) such that
\eqref{eq:assmption_constants_R} holds.
Then the 
\K-theoretic index pairing~\( \braket{[v],[D]} \) is represented by
the formal difference of \emph{(quasi-)projections}
\[ 
  [e_t]-[f_t]=
  \left[\begin{pmatrix}
   s_t^2 & \sqrt{c_ts_t} v\sqrt{c_ts_t} \\
  \sqrt{c_ts_t} v^*\sqrt{c_ts_t} &  c_t^2
  \end{pmatrix}\right]-
  \left[\begin{pmatrix}
  0 & 0 \\ 0 & 1
  \end{pmatrix}\right]
\]
for any choice of~\( t\in [1,\infty) \) satisfying 
\( t>2\varepsilon^{-1}R\norm*{[D,v]} \). 
\end{theorem}

\begin{remark}
It is possible to improve the upper bound~\( 0.1121 \) for 
\( \varepsilon \) with a more accurate estimate of the
norm~\( \norm*{e_t-\check{e}_t} \), together with a finer assumption that
treats the constant~\( R \) for~\( c_t \),~\( s_t \) and~\( \sqrt{c_ts_t}
\) separately. However, we note that this is of little help for
constructing finite-dimensional K-theory representatives in the next
section, as the control of~\( \varepsilon \) will be dominated by
the estimate~\( \varepsilon+\delta<\frac{1}{400}=0.0025 \) in
\Cref{thm:index_pairing_submodule}.
\end{remark}


\section{Spectral truncation of the index pairing}
We have constructed from the previous section, a pair of
\emph{quasi-projections}~\( e_t \) and~\( f_t \), such that the K-theoretic
index pairing~\( \braket{[v],[D]} \) is given by
\[ 
    [e_t]-[f_t]\in\K_0(\Cpt_B(E)).
\]
The next goal is to apply a 
\emph{spectral truncation} to them. Namely, we shall
replace~\( e_t \) and~\( f_t \) by quasi-projections~\( p^e_{t,\lambda} \)
and~\( p^f_{t,\lambda} \) on a
submodule of~\( E\oplus E \), which 
corresponds to the ``low-lying spectrum'' of~\( D \). The submodule depends
on a sufficiently large choice of the parameter 
\( \lambda>0 \), which occurs 
as the threshold of this truncated spectrum of~\(D\). 
The existence of such a submodule is, however, not always assured. It
always exists if~\( B=\C \) and~\( E \) is a Hilbert space.  

We shall show that the quasi-projections~\( e_t \) and~\(
f_t\) are homotopic to direct sums of quasi-projections,
\[ 
    p^e_{t,\lambda}\oplus q^e_{t,\lambda},\quad p^f_{t,\lambda}\oplus
    q^f_{t,\lambda},
\]
also~\( q^e_{t,\lambda} \) is homotopic to~\( q^f_{t,\lambda} \). All these
homotopies are through quasi-projections in~\( \Mat_2(\Cpt_B(E)^+)
\). Therefore, it follows from the description of~\( \K_0(\Cpt_B(E)) \) by
quasi-idempotents or quasi-projections
(\Cref{prop:K-theory_quasi-idempotents}) that
\[ 
    [e_t]-[f_t]=[p^e_{t,\lambda}]+[q^e_{t,\lambda}]-[p^f_{t,\lambda}]-[q^f_{t,\lambda}]=[p^e_{t,\lambda}]-[p^f_{t,\lambda}].
\]

In this section, we shall prove that 
the K-theory representative~\( [p^e_{t,\lambda}]-[p^f_{t,\lambda}] \)
gives rise to 
the odd spectral localiser~\( L_{\kappa,\lambda} \) 
of Loring and Schulz-Baldes when~\( B=\C \). 
More precisely, we will show that the
spectral localiser~\( L_{\kappa,\lambda} \) can be recovered from a particular
choice of the functions~\( s \) and~\( c \), and that  
\[ 
    [e_t]-[f_t]=[p^e_{t,\lambda}]-[p^f_{t,\lambda}]=
    \frac{1}{2}\sig(L_{t^{-1},\lambda}).
\]
Thus our result gives a new proof of the main theorem in
\cites{Loring-SBaldes:Odd_spectral_localiser,Loring-SBaldes:Odd_spectral_localiser_sf},
as well as provides a new interpretation of the spectral localiser.

We also consider a special case of the \emph{numerical index pairing},
given by pairing the Kasparov product~\( [v]\times[D] \) with a finite
trace~\( \tau\colon B\to\C \). We show that the spectral truncation method
still applies, providing a representative of the numerical index pairing
that is supported on a spectral subspace of the localised Hilbert space~\(
\mathcal{H}^\tau\defeq E\otimes_BL^2(E,\tau) \). This recovers the
semi-finite spectral localiser of Schulz-Baldes and Stoiber
\cite{SBaldes-Stoiber:Semifinite_spectral_localizer}, and gives a new proof
of their main theorem in this special setting.

\subsection{Spectral decomposition of Hilbert \Cst-modules}
We introduce the following definition for studying spectral truncations of
index pairings.

\begin{definition}\label{def:spectral_decomposition}
Let~\( B \) be a \Cst-algebra,~\( \mathcal{E} \) be a Hilbert~\( B
\)-module, and~\( \mathcal{D} \) be an unbounded, self-adjoint regular operator
on~\( \mathcal{E} \). Given~\( \lambda>0 \),
A \emph{spectral decomposition} of~\( \mathcal{E} \)
for the operator~\( \mathcal{D} \) with \emph{spectral threshold}~\( \lambda \) 
is a pair of mutually \emph{complemented} submodules
\( (\mathcal{E}_{\lambda}^{\downarrow},\mathcal{E}_{\lambda}^{\uparrow}) \) 
of~\( \mathcal{E} \), such that the operator inequality
\[ 
    \braket{\mathcal{D}\xi,\mathcal{D}\xi}\geq\lambda^2\braket{\xi,\xi}
\]
holds for all~\( \xi\in\dom \mathcal{D}\cap \mathcal{E}^\uparrow_\lambda \). 
We call~\( \mathcal{E}_\lambda^{\downarrow} \) 
(resp.~\( \mathcal{E}_\lambda^{\uparrow} \)) the
\emph{lower} (resp.~\emph{upper}) \emph{spectral} submodule for the
decomposition~\( \mathcal{E}\simeq \mathcal{E}_\lambda^{\downarrow}\oplus
\mathcal{E}_\lambda^{\uparrow} \).
\end{definition}

Let~\((\mathcal{E}_{\lambda}^\downarrow,\mathcal{E}_{\lambda}^\uparrow) \)
be a spectral decomposition of~\( \mathcal{E} \). Write~\(
P_{\lambda}^{\downarrow} \) and~\( P_{\lambda}^{\uparrow} \) for the
orthogonal projections onto ~\( \mathcal{E}_{\lambda}^{\downarrow} \) and
\( \mathcal{E}_{\lambda}^{\uparrow} \).  Then under the direct sum
decomposition
\[ 
    \mathcal{E}\simeq \mathcal{E}_{\lambda}^{\downarrow}\oplus \mathcal{E}_{\lambda}^{\uparrow},
\]
any operator~\( T \) on~\( \mathcal{E} \) decomposes as a~\( 2\times 2
\)-block operator: 
\begin{equation}\label{eq:spectral_decomposition_operator}
    \begin{pmatrix}
    p^T & n^T{} \\
    m^T & q^T
    \end{pmatrix},    
\end{equation}
where~\( p^T \),~\( q^T \),~\( m^T \) and~\( n^T \)  
are \emph{truncated} operators,
defined as    
\begin{alignat*}{3} 
p^T &\defeq P_{\lambda}^{\downarrow} TP_{\lambda}^{\downarrow} &&\colon \mathcal{E}_{\lambda}^{\downarrow}\to \mathcal{E}_{\lambda}^{\downarrow}, \\ q^T
&\defeq P_{\lambda}^{\uparrow}TP_{\lambda}^{\uparrow} &&\colon
\mathcal{E}_{\lambda}^{\uparrow}\to \mathcal{E}_{\lambda}^{\uparrow},\\ m^T &\defeq
P_{\lambda}^{\uparrow}TP_{\lambda}^{\downarrow}&&\colon \mathcal{E}_{\lambda}^{\downarrow}\to
\mathcal{E}_{\lambda}^{\uparrow}, \\ n^T &\defeq
P_{\lambda}^{\downarrow} TP_{\lambda}^{\uparrow}&&\colon \mathcal{E}_{\lambda}^{\uparrow}\to
\mathcal{E}_{\lambda}^{\downarrow}.
\end{alignat*}
If~\( T \) is self-adjoint, then clearly 
both~\( p^T \) and~\( q^T \) are self-adjoint, and~\( n^T=m^T{}^* \).

\begin{example}[Spectral decomposition of a Hilbert
space]\label{ex:spectral_decomposition_Hilbert_space}
We explain the terminology in the Hilbert space setting, i.e.~\( B=\C \)
and~\( \mathcal{E} \) is given by a Hilbert space~\( \mathcal{H} \).  Let~\(
\mathcal{D} \) be an unbounded, self-adjoint operator on~\( \mathcal{H} \).
Let~\( I\subseteq \R \) be a Borel subset and~\( \chi_I \) be its
characteristic function. Then Borel functional calculus gives a spectral
projection~\( \chi_I(\mathcal{D})\in\Bdd(\mathcal{H}) \). If~\( \mathcal{D}
\) has discrete spectrum, then~\( \mathcal{H}_I\defeq
\chi_I(\mathcal{D})\mathcal{H} \) is spanned by eigenvectors~\( \xi \)
of~\( \mathcal{D} \) with eigenvalue in~\( I \).  In particular, let~\( I
\) be any Borel subset of~\( (-\infty,-\lambda)\cup(\infty,\lambda) \),
then~\( (\mathcal{H}_{\R\setminus I},\mathcal{H}_I) \) is a spectral
decomposition of~\( \mathcal{H} \) for the operator~\( \mathcal{D} \) with
spectral threshold~\( \lambda \).
\end{example}

\begin{remark}
We remark that the 
existence of a spectral decomposition of a Hilbert \Cst-module
can not be guaranteed in general. 
Unlike the Hilbert space case, there is no Borel functional calculus
for operators on Hilbert \Cst-modules due to a lack of spectral measure. 
This prevents one from constructing spectral decompositions 
from characteristic
functions as in \Cref{ex:spectral_decomposition_Hilbert_space}.
We anticipate that, in order to obtain a more broadly applicable notion of
spectral decomposition of Hilbert \Cst-modules, 
the \emph{mutual orthogonality} of the submodules~\(
\mathcal{E}_\lambda^\downarrow \) and~\( \mathcal{E}_\lambda^\uparrow \)
needs be relaxed. 
\end{remark}

Later, we shall be concerned with spectral decomposition of the Hilbert
\( B \)-module~\( \widehat{E}\defeq E\oplus E \).   
We caution that there are be two ways to 
decomposition~\( \widehat{E} \) as mutually complemented submodules, 
one as~\( E\oplus E \) and another being the spectral decomposition~\(
E_{\lambda}^{\downarrow}\oplus E_{\lambda}^{\uparrow} \). Both
decompositions yield a~\( 2\times2 \)-matrix expression of an operator~\(
T \) on~\( \widehat{E} \). The above notation~\( p^T,q^T \) and~\(
m^T \) of \eqref{eq:spectral_decomposition_operator} 
will be used only for the spectral decomposition~\(
\widehat{E}\simeq E_{\lambda}^{\downarrow}\oplus
E_{\lambda}^{\uparrow} \). 

\subsection{Truncating quasi-projections to spectral submodules}
Let~\( (E_{\lambda}^\downarrow,E_{\lambda}^\uparrow) \) be a spectral
decomposition of~\( \widehat{E}\defeq E\oplus E \) for the operator~\(
D\oplus D \) with spectral threshold~\( \lambda \).  
In order to apply truncations to the quasi-projections~\( e_t \) and~\( f_t
\) to~\( E_{\lambda}^\downarrow \) 
without changing their representing K-theory classes, one first
homotopes them to a diagonal operator under the direct sum decomposition of
Hilbert modules~\( \widehat{E}=E_{\lambda}^{\downarrow}\oplus
E_{\lambda}^{\uparrow} \), based
on the following lemma. 

\begin{lemma}[Reduction to the diagonal]\label{lem:reduction_to_diagonal}
Let~\( \mathcal{E} \) be a Hilbert~\( B \)-module, and~\(
\mathcal{F}\subseteq\mathcal{E} \) be a
complemented submodule. 
Let~\( e\in\End^*_B(\mathcal{E}) \) be an~\( \varepsilon \)-quasi-projection. 
Under the direct sum decomposition of Hilbert~\( B \)-module~\(
\mathcal{E}\simeq\mathcal{F}\oplus\mathcal{F}^\perp \), write
\[ 
    e=\begin{pmatrix}
    p & m^* \\ m & q
    \end{pmatrix}  
\]
where~\( p\in\End^*_B(\mathcal{F}) \),~\(
m\in\Hom^*_B(\mathcal{F},\mathcal{F}^\perp) \) and~\(
q\in\End^*_B(\mathcal{F}^\perp) \).
Assume that there exists~\( \varepsilon_q<\frac{1}{400}-\varepsilon \) 
such that~\( q \) is an~\( \varepsilon_q \)-quasi-projection.
Then:
\begin{enumerate}
\item \( p \) is an~\( (2\varepsilon+\varepsilon_q) \)-quasi-projection;
\item \( e \) is homotopic to~\( \left(\begin{smallmatrix}
    p & 0 \\ 0 & q
\end{smallmatrix}\right) \) as quasi-projections.   
\end{enumerate}
\end{lemma}

\begin{proof}
Since~\( e \) is an~\( \varepsilon \)-quasi-projection, it follows that  
\begin{align*} 
\varepsilon&>\norm{e^2-e}=\norm*{\begin{pmatrix}
        p^2-p+m^*m & pm^*+m^*q-m^* \\
        mp+qm-m & mm^*+q^2-q
    \end{pmatrix}}\\
    &\geq\max\left\{\norm{p^2-p+m^*m},\norm{q^2-q+mm^*}\right\}.
\end{align*}
Also~\( q \) is an~\( \varepsilon_q \)-quasi-projection, so
\begin{gather*} 
\norm{m}^2=\norm{mm^*}\leq\varepsilon+\norm{q^2-q}<\varepsilon+\varepsilon_q,\\
\norm{p^2-p}<\norm{m^*m}+\varepsilon<
2\varepsilon+\varepsilon_q.
\end{gather*}
Now let~\( f\defeq
\left(\begin{smallmatrix}
    p & 0 \\ 0 & q
\end{smallmatrix}\right) \) and~\( \delta\defeq \norm{e-f} \).
Then we have
\[ 
    \delta=\norm*{\begin{pmatrix}
        0 & m^* \\ m & 0
    \end{pmatrix}
    }=\norm*{m}<\sqrt{\varepsilon+\varepsilon_q}.
\]
Therefore,
\begin{align*} 
\big(2\norm*{e}+\frac{5}{4}\delta+1\big)\delta+\varepsilon
&<\big(2(1+\varepsilon)+\frac{5}{4}\sqrt{\varepsilon+\varepsilon_q}+1\big)
\sqrt{\varepsilon+\varepsilon_q}+\varepsilon \\
&<\big(2+2\sqrt{\varepsilon+\varepsilon_q}+\frac{5}{4}\sqrt{\varepsilon+\varepsilon_q}+1+\sqrt{\varepsilon+\varepsilon_q}\big)\sqrt{\varepsilon+\varepsilon_q}
\\
&=3\sqrt{\varepsilon+\varepsilon_q}+\left(2+\frac{5}{4}+1\right)\left(\varepsilon+\varepsilon_q\right) \\
&<\left(3+\frac{17}{80}\right)\cdot\frac{1}{20}<\frac{1}{4}.
\end{align*}
It follows from \Cref{thm:close_quasi-idempotents_homotopic} that~\( f \)
is also a quasi-projection that is homotopic to~\( e \).
\end{proof}

Assume that~\( (E^\downarrow_{\lambda},E^\uparrow_{\lambda}) \) is
a spectral decomposition of~\( \widehat{E} \) for~\( D\oplus D \) with
spectral threshold~\( \lambda \). Decompose
\begin{equation}\label{eq:spectral_decomposition_et_ft}
    e_t=\begin{pmatrix} 
    p^e_{t,\lambda} & {m^e_{t,\lambda}}^* \\
    m^e_{t,\lambda} & q^e_{t,\lambda} 
    \end{pmatrix},\quad
    f_t=\begin{pmatrix} p^f_{t,\lambda} & {m^f_{t,\lambda}}^* \\
    m^f_{t,\lambda} & q^f_{t,\lambda} 
    \end{pmatrix}
\end{equation}
as in \eqref{eq:spectral_decomposition_operator},
i.e.~\(
p^e_{t,\lambda},p^f_{t,\lambda}\in\End_B^*(E_{\lambda}^{\downarrow})
\),~\(
m^e_{t,\lambda},m^f_{t,\lambda}\in\Hom_B^*(E_{\lambda}^{\downarrow},E_{\lambda}^{\uparrow})
\), and~\(
q^e_{t,\lambda},q^f_{t,\lambda}\in\End_B^*(E_{\lambda}^{\uparrow})
\). Recall that~\( f_t \) is given by the constant family of projections~\(
\left(\begin{smallmatrix}
    0 & 0 \\ 0 & \id
\end{smallmatrix}\right)\) on~\( \widehat{E} \). Therefore, we have
\[ 
    m^f_{t,\lambda}=0,\quad p_{t,\lambda}^f=\begin{pmatrix}
    0 & 0 \\ 0 & \id_{E_{\lambda}^\downarrow}
    \end{pmatrix},\quad
    q_{t,\lambda}^f=\begin{pmatrix}
    0 & 0 \\ 0 & \id_{E_{\lambda}^{\uparrow}}
    \end{pmatrix}.
\]
We shall show that for sufficiently large~\( t \) and sufficiently small~\(
\lambda\), then~\( p^e_{t,\lambda} \) and~\( p^f_{t,\lambda} \) are
quasi-projections in~\( \Mat_2(\Cpt_B(E)^+) \) that represents the same
class in~\( \K_0(\Cpt_B(E)^+) \). To this end, define
\[ 
    \Theta_t\defeq \begin{pmatrix}
    c_t & s_t \\ -s_t & c_t
    \end{pmatrix}\in\Mat_2(\End_B(E)).
\] 
Then~\( \Theta_t \) is a unitary multiplier of~\( \Mat_2(\Cpt_B(E)^+) \)
which commmutes with~\( D\oplus D \). Thus under any spectral decomposition
\( (E_\lambda^\downarrow,E_{\lambda}^\uparrow) \) for~\( D\oplus D \), we
have~\( \Theta_t \) is diagonal;~\( p^{\Theta}_{t,\lambda} \) and~\(
q^{\Theta}_{t,\lambda} \) are unitary operators on~\(
E_{\lambda}^\downarrow \) and~\( E_{\lambda}^{\uparrow} \), respectively.
Moreover, since~\( f_t \) also commutes with~\( D\oplus D \), we have  
\[ 
    q_{t,\lambda}^{\Theta}q_{t,\lambda}^fq_{t,\lambda}^\Theta{}^*=q_{t,\lambda}^{\Theta
    f\Theta^*},
\]
which is the truncation of the following operator onto~\(
E_{\lambda}^{\uparrow} \): 
\[ 
    \Theta_tf_t\Theta_t^*=\begin{pmatrix}
    c_t & s_t \\ -s_t & c_t
    \end{pmatrix}
    \begin{pmatrix}
    0 & 0 \\ 0 & \id
    \end{pmatrix}
    \begin{pmatrix}
    c_t & -s_t \\ s_t & c_t
    \end{pmatrix}
    =\begin{pmatrix}
    s_t^2 & c_ts_t \\ c_ts_t & c_t^2
    \end{pmatrix}.
\]

\begin{lemma}\label{lem:spectral_decomposition}
For each~\( t\in[1,\infty) \) and~\( \delta>0 \), 
there exists~\( \lambda>0 \) that depends on~\( t \) and~\( \delta \),
such that the following holds\textup{:}

If 
\( (E_{\lambda}^{\downarrow},E_{\lambda}^{\uparrow}) \) is a spectral
decomposition of~\( \widehat{E} \) for~\( D\oplus D \)
with spectral threshold~\( \lambda \). Then
\[
    \norm{q_{t,\lambda}^e-q^{\Theta}_{t,\lambda}q_{t,\lambda}^fq^{\Theta}_{t,\lambda}{}^*}\leq\delta.
\]
\end{lemma}

\begin{proof}
We compute
\begin{multline*}
\norm*{e_t-\Theta_tf_t\Theta_t^*}\leq\norm*{\begin{pmatrix}
    s_t^2 & \sqrt{c_ts_t}v\sqrt{c_ts_t} \\
    \sqrt{c_ts_t}v^*\sqrt{c_ts_t} & c_t^2
\end{pmatrix}-\begin{pmatrix}
    s_t^2 & \sqrt{c_ts_t}\sqrt{c_ts_t} \\
    \sqrt{c_ts_t}\sqrt{c_ts_t} & c_t^2
\end{pmatrix}} \\
=\norm*{\begin{pmatrix}
    0 & \sqrt{c_ts_t}(v-1)\sqrt{c_ts_t} \\
    \sqrt{c_ts_t}(v^*-1)\sqrt{c_ts_t} & 0
\end{pmatrix}
}
=\norm*{\sqrt{c_ts_t}(v-1)\sqrt{c_ts_t}}
\leq 2\norm*{c_ts_t}.
\end{multline*}
The functions~\( s,c\colon \R\to[0,1] \) are continuous and satisfy
\[
\lim_{x\to+\infty}s(x)=1,\quad\lim_{x\to+\infty}c(x)=0.
\]
So both of them extend to continuous functions~\( [-\infty,+\infty]\to[0,1]
\). The function~\( c(x)s(x) \) is positive and 
tends to~\( 0 \) as~\( x\to\infty \), that is, fix
\( t\in[1,+\infty) \) and~\( \delta>0 \), 
there exists~\( \lambda>0 \) such that~\(
0<c(x)s(x)<\frac{1}{2}\delta \) for all~\( x>t^{-1}\lambda \). Then
for all~\( \xi\in E_{\lambda}^{\uparrow} \), the operator inequality
\[ 
    \braket{c_ts_t\xi,c_ts_t\xi}
    \leq\frac{1}{2}\delta\cdot\braket{\xi,\xi}
\]
holds. This proves the claim.
\end{proof}

Providing the existence of a spectral decomposition
\( (E_\lambda^{\downarrow},E_\lambda^{\uparrow}) \),
the lemmas above allows us to obtain a pair of quasi-projections that
are supported on the lower spectral submodule~\( E_{\lambda}^{\downarrow}
\). 

\begin{theorem}\label{thm:index_pairing_submodule}
Let~\( A \) be a unital \Cst-algebra. Let~\( (\mathcal{A},E,D) \) be an
odd unbounded Kasparov~\( A \)-\( B \)--module and
\( v\in \mathcal{A} \) be a unitary. Write~\( [v]\in\K_1(A) \) and~\(
[D]\in\KK_1(A,B) \) for their representing classes.
Assume that the followings hold\textup{:} 
\begin{enumerate}
\item There exist~\( 0<\delta<\frac{1}{400} \) 
and a spectral decomposition~\(
(E_{\lambda}^{\downarrow},E_{\lambda}^{\uparrow}) \) of~\( \widehat{E} \) 
with spectral threshold~\( \lambda \) such that
\[ 
\norm*{q_{t,\lambda}^e-q_{t,\lambda}^{\Theta}q_{t,\lambda}^fq_{t,\lambda}^{\Theta}{}^*}\leq\delta.
\]
\item There exists~\( R>0 \) such that \eqref{eq:assmption_constants_R}
holds. 
\end{enumerate}
Then for any~\( 0<\varepsilon<\frac{1}{400}-\delta \) and any~\(
t\in[1,\infty) \) that satisfy  
\[  
    t>2\varepsilon^{-1}R\norm*{[D,v]},
\]
the \K-theoretic index pairing~\( \braket{[v],[D]}\in\K_0(\Cpt_B(E)) \) 
is represented by the formal difference of \emph{quasi-projections}
\[ 
    [p^e_{t,\lambda}]-[p^f_{t,\lambda}],
\]
where both~\( p^e_{t,\lambda} \) and~\( p^f_{t,\lambda} \) are
quasi-projections supported on the lower 
spectral submodule~\( E_{\lambda}^{\downarrow} \) as in
\eqref{eq:spectral_decomposition_et_ft}.
\end{theorem}

\begin{proof}
Since~\( \Theta_t \) is unitary and commutes with~\( D\oplus D \), 
it follows that~\( q^{\Theta}_{t,\lambda} \) is also a unitary operator on 
\( E_{\lambda}^{\uparrow} \)  for any
spectral decomposition~\( (E_{\lambda}^\downarrow,E_{\lambda}^\uparrow) \).
Thus the operator
\( q^{\Theta}_{t,\lambda}q^f_{t,\lambda}q^{\Theta}_{t,\lambda}{}^* \)
is a projection on~\( E_{\lambda}^{\uparrow} \),
which is unitarily equivalent to~\( q^f_{t,\lambda} \). 
Since 
\[
    \norm*{q^e_{t,\lambda}-q^{\Theta}_{t,\lambda}q^f_{t,\lambda}q^{\Theta}_{t,\lambda}{}^*}\leq\delta<\frac{1}{400}-\varepsilon,
\]
it follows from \Cref{thm:close_quasi-idempotents_homotopic} that~\(
q^e_{t,\lambda} \) is a~\( 4\delta \)-quasi-projection that is homotopic 
to~\( q^{\Theta}_{t,\lambda}q^f_{t,\lambda}q^{\Theta}_{t,\lambda}{}^* \),
thus
\[ 
    [q^e_{t,\lambda}]=[q^\Theta_{t,\lambda}q^f_{t,\lambda}
    q^{\Theta}_{t,\lambda}{}^*]
    =[q^f_{t,\lambda}]\in\K_0(\Cpt_B(E)^+).
\]

Also \Cref{lem:reduction_to_diagonal} implies that~\( e_t \) is
homotopic to~\( p^e_{t,\lambda}\oplus q^e_{t,\lambda} \) via a straightline
homotopy
\[ 
    [0,1]\to\End_B(\widehat{E}),\quad s\mapsto\begin{pmatrix}
    p^e_{t,\lambda} & s\cdot m^e_{t,\lambda}{}^* \\ 
    s\cdot m^e_{t,\lambda} & q^f_{t,\lambda}
    \end{pmatrix}.
\]
In particular, since~\( e_t\in\Mat_2(\Cpt_B(E)^+) \), it follows that the
operator
\[ 
    \begin{pmatrix}
    0 & m_{t,\lambda}^e{}^* \\
    m_{t,\lambda}^e{}^* & 0
    \end{pmatrix}  
\]
is compact. This shows that this straightline homotopy actually
lands in~\( \Mat_2(\Cpt_B(E)^+) \). Therefore, we have
\[ 
[e_t]=\left[\begin{pmatrix}
p^e_{t,\lambda} & 0 \\ 0 & q^e_{t,\lambda}
\end{pmatrix}\right]=[p^e_{t,\lambda}]+[q^e_{t,\lambda}]\in\K_0(\Cpt_B(E)^+),
\]
and
\[ 
    [q^e_{t,\lambda}]=[q^f_{t,\lambda}]\in\K_0(\Cpt_B(E)^+).
\]
On the other hand, the operator~\( f_t \) is diagonal under the
spectral decomposition~\(
\widehat{E}\simeq E_{\lambda}^{\downarrow}\oplus E_{\lambda}^{\uparrow}
\). So  
\[
    [f_t]=[p^f_{t,\lambda}]+[q^f_{t,\lambda}].
\]
Therefore, we have
\[ 
    [e_t]-[f_t]=[p^e_{t,\lambda}]+[q^e_{t,\lambda}]-[p^f_{t,\lambda}]-[q^f_{t,\lambda}]=[p^e_{t,\lambda}]-[p^f_{t,\lambda}].\qedhere
\]
\end{proof}

Note that the choice of the lower spectral threshold~\( \lambda \) 
depends on~\( \delta \) and~\( t \).  
As~\( t \) increases, then the threshold
\( \lambda \) will typically also increase.
Nevertheless, for each \emph{fixed}~\( t\in
[1,\infty) \), legitimated by the condition
\[ 
    t>2\varepsilon^{-1}R\norm*{[D,v]}
\]
as in \Cref{thm:index_pairing_quasi-projections}, we are able to produce a
finite spectral threshold~\( \lambda \). Assume that there exists a
spectral decomposition~\( (E_\lambda^\downarrow,E_\lambda^\uparrow) \) with
spectral threshold~\( \lambda \), then we are able to ``spectrally''
truncate~\( [e_t]-[f_t] \) to the lower spectral submodule~\(
E_{\lambda}^{\downarrow} \), which represents the same K-theoretic index
pairing. 

\subsection{Emergence of the spectral localiser}
\label{sec:spectral_localiser_spectral_triple}
The precise formula for~\( p^e_{t,\lambda} \) and~\( p^f_{t,\lambda} \), as
well as their relevant constants~\( R>0 \) and~\( \lambda>0 \), are subject
to the specific choices of functions~\( c \) and~\( s \). The choices that
we will be employing to connect to the spectral localiser are given as
follows.

\begin{theorem}\label{thm:choice_cs}
Let
\begin{equation}\label{eq:choice_cs}
    c(x)\defeq\sqrt{\frac{1}{2}-\frac{1}{2}x(1+x^2)^{-\sfrac{1}{2}}},\quad 
    s(x)\defeq\sqrt{\frac{1}{2}+\frac{1}{2}x(1+x^2)^{-\sfrac{1}{2}}},
\end{equation}
\textup{(}see \Cref{fig:cs}\textup{)}. Then\textup{:}
\begin{enumerate}
\item The constant~\( R \) in \eqref{eq:assmption_constants_R} can be
chosen to be~\( 2 \).
\item The spectral threshold~\( \lambda \) as in
\Cref{lem:spectral_decomposition} can be chosen to be~\( t\delta^{-1}
\). 
\end{enumerate}
\end{theorem}

\begin{proof}
What (1) claims is the following: the following
estimation holds for all~\( t\in[1,\infty) \): 
\[
\left.\begin{array}{r}
\norm*{[c_t,v]} \\
\norm*{[s_t,v]} \\
\norm*{[\sqrt{c_ts_t},v]}
\end{array}\right\}\leq 2t^{-1}\norm*{[D,v]}.
\]
We provide the proof of (1) in \Cref{app:commutator_estimates}, based on
an integral formula as well as trigonometric substitutions. To see
(2), we note that
\[ 
    c(x)s(x)=\sqrt{\frac{1}{4}-\frac{1}{4}x^2(1+x^2)^{-1}}=\frac{1}{2}\frac{1}{\sqrt{x^2+1}}.
\]
So~\( c_ts_t=\frac{1}{2}(1+t^{-2}D^2)^{-\sfrac{1}{2}} \). Therefore, for
each~\( \delta>0 \), choose~\( \lambda>t\delta^{-1} \), it follows from
\Cref{lem:spectral_decomposition} that
\[
\norm*{q^e_{t,\lambda}-q^{\Theta}_{t,\lambda}q^f_{t,\lambda}q^{\Theta}_{t,\lambda}{}^*}\leq
\frac{1}{2}\frac{1}{\sqrt{1+t^{-2}\lambda^2}}
\leq\frac{1}{2t^{-1}\lambda}\leq
\frac{1}{2}\delta.\qedhere \]
\end{proof}

\begin{figure}[h!]
\centering
\includegraphics[width=0.8\textwidth]{cs.pdf}
\caption{The functions~\( c(x) \) and~\( s(x) \) in
\eqref{eq:choice_cs}.}
\label{fig:cs}
\end{figure}

Now we connect our results to the (odd) spectral localisers of Loring
and Schulz-Baldes.
In this case of interest, we let~\( B=\C \). Then an 
unbounded Kasparov~\( A \)-\( B \)--module is the same thing
as an odd special triple 
\( (\mathcal{A},\mathcal{H},D) \) over~\( A \).
As explained in \Cref{ex:spectral_decomposition_Hilbert_space}, any Borel
subset~\( I\subseteq(-\infty,-\lambda)\cup(\lambda,+\infty) \) gives a
spectral decomposition~\( (\mathcal{H}_{\R\setminus I},\mathcal{H}_I) \) 
with spectral threshold~\( \lambda \). Following the notations in
\cites{Loring-SBaldes:Odd_spectral_localiser,Loring-SBaldes:Odd_spectral_localiser_sf},
we set
\begin{gather*} 
\mathcal{H}_{\lambda}\defeq
\chi_{[-\lambda,\lambda]}(D\oplus D)\widehat{\mathcal{H}},\\
\mathcal{H}_{\lambda^\mathrm{c}}\defeq
\chi_{(-\infty,-\lambda)\cup(\lambda,\infty)}(D\oplus
D)\widehat{H}.
\end{gather*}
Then~\( (\mathcal{H}_{\lambda},\mathcal{H}_{\lambda^\mathrm{c}}) \) is a
spectral decomposition of~\( \widehat{\mathcal{H}} \) with spectral
threshold~\( \lambda \).  

The construction in the previous section gives 
a pair of quasi-projections~\( p^e_{t,\lambda} \)
and~\( p^f_{t,\lambda} \) on the spectral space~\(
\mathcal{H}_{\lambda} \). In particular,~\( \mathcal{H}_\lambda \) is
\emph{finite-dimensional} as~\( D \) has discrete spectrum.  
The formal difference
\[ 
    [p^e_t]-[p^f_t]
\]
defines a class in~\( \K_0(\Cpt)\simeq\Z \), which 
coincides with the index pairing~\( \braket{[v],[D]} \). 
Since both~\( p^e_{t,\lambda}
\) and~\( p^f_{t,\lambda} \) have finite rank, it follows that the class  
represented by the formal difference is
\[ 
    \rank(\kappa_0(p^e_{t,\lambda}))-\rank(\kappa_0(p^f_{t,\lambda})).
\]

Now we relate the
constructions in the previous chapter to the spectral localiser.
We begin with the following simple observation.

\begin{lemma}\label{lem:signature_quasi-projection}
Let~\( p \) be a quasi-projection on a finite-dimensional Hilbert space~\(
\mathcal{K}\), then
\begin{align*} 
    \sig(2p-\id_\mathcal{K})&=\rank(\kappa_0(p))-\rank(\kappa_0(\id_\mathcal{K}-p))\\ &=2\rank(\kappa_0(p))-\dim\mathcal{K}.
\end{align*}
\end{lemma}

\begin{proof}
Recall that the signature of a finite-dimensional, self-adjoint matrix~\( L
\) is given by
\[ 
    \sig(L)=\#(\text{positive eigenvalues of~\( L \)})-\#(\text{negative
    eigenvalues of~\( L \)}).
\]
Thus the signature of~\( L \) is the trace of the sign of~\( L \):  
\[ 
    \sig(L)=\tr(\operatorname{sign}(L)),\quad
    \operatorname{sign}(x)\defeq\begin{cases}
    1 & x>0; \\
    0 & x=0; \\
    -1 & x<0.
    \end{cases}
\]
Notice that
\[ 
    \operatorname{sign}(2x-1)=\begin{cases}
    1 & x>\sfrac{1}{2}; \\
    0 & x=\sfrac{1}{2}; \\
    -1 & x<\sfrac{1}{2}.
    \end{cases}    
\]
Since~\( p \) is a quasi-projection on~\( \mathcal{K} \), 
we have~\( \sfrac{1}{2}\notin\spc(p)
\) and~\( \sfrac{1}{2}\notin\spc(\id_{\mathcal{K}}-p) \), 
hence~\( \operatorname{sign}(2x-1) \) coincides with
\[
    2\kappa_0(x)-1=\kappa_0(x)-(1-\kappa_0(x))=\kappa_0(x)-\kappa_0(1-x)
\]
on the spectrum of~\( p \). Now the claim follows as
\begin{multline*} 
\sig(2p-\id_\mathcal{K})=\tr(\operatorname{sign}(2p-\id_\mathcal{K}))=\tr(2\kappa_0(p)-\id_\mathcal{K})\\
=2\tr\kappa_0(p)-\tr\id_{\mathcal{K}}=2\rank\kappa_0(p)-\dim\mathcal{K}.\qedhere
\end{multline*}
\end{proof}

\begin{remark}
We note that this is also the reason to replace quasi-idempotents~\(
\check{e}_t \) by quasi-projections~\( e_t \), since the signature is
only defined for self-adjoint matrices.  
\end{remark}



Now we recall the definition of (odd) spectral localisers of Loring and
Schulz-Baldes. Let~\( \kappa>0 \), define the following unbounded,
self-adjoint operator
\[ 
    L_{\kappa}\defeq \begin{pmatrix}
    \kappa D & v \\ v^* & -\kappa D
    \end{pmatrix}
\]
and set~\( L_{\kappa,\lambda} \) to be the truncation of~\( L_\kappa \) to~\(
\mathcal{H}_{\lambda} \), which is a self-adjoint matrix of dimension~\(
\dim\mathcal{H}_{\lambda} \). 
Then it was proven in
\cites{Loring-SBaldes:Odd_spectral_localiser,Loring-SBaldes:Odd_spectral_localiser_sf}
that for sufficiently small~\( \kappa<0 \) and sufficiently large~\( \lambda>0
\), it follows that the index pairing~\( \braket{[v],[D]} \) equals one
half of the signature of~\( L_{\kappa,\lambda} \). The precise conditions for
the tuning paramter~\( \kappa>0 \) and the spectral threshold~\( \lambda>0 \)
can be found in
\cite{Loring-SBaldes:Odd_spectral_localiser_sf}*{Page 2}.

We shall prove that the invertible matrix~\(
\mathcal{L}^e_{t^{-1},\lambda}\defeq 2p^e_{t,\lambda}-\id \) 
is congruent to the spectral localiser~\( L_{t^{-1},\lambda} \).
Controls of the tuning parameter~\( \kappa=t^{-1} \) and the spectral
threshold~\( \lambda \) are given by \Cref{thm:index_pairing_submodule}
(for the general setup) and 
\Cref{thm:choice_cs} (for the specific choice of functions~\( c(x) \) and
\( s(x) \)).

\begin{theorem}\label{thm:spectral_localiser}
For every~\( t,\lambda>0 \), there is an equality
\[ 
    \frac{1}{2}\sig(L_{t^{-1},\lambda})=
    \rank(\kappa_0(p^e_{t,\lambda}))-\rank(\kappa_0(p^f_{t,\lambda})).
\]
As a consequence, let~\( \varepsilon,\delta>0 \) satisfy~\(
\varepsilon+\delta<\frac{1}{400} \). For any choice~\( t,\lambda \)
satisfying~\(
t>4\varepsilon^{-1}\norm*{[D,v]} \) and~\( \lambda>t\delta^{-1}
\), the half-signature 
\( \frac{1}{2}\sig(L_{t^{-1},\lambda}) \) coincides with the index
pairing~\( \braket{[v],[D]} \).   
\end{theorem}

\begin{proof}
It follows from \Cref{thm:index_pairing_submodule,thm:choice_cs} 
that under the conditions for~\( \varepsilon,\delta,t
\) and~\( \lambda \), the index pairing~\( \braket{[v],[D]} \) is
given by
\[
    \rank(\kappa_0(p^e_{t,\lambda}))-\rank(\kappa_0(p^f_{t,\lambda}))\in\Z\simeq\K_0(\Cpt).
\]
By the preceding lemma, we have
\begin{align*} 
\rank(\kappa_0(p^e_{t,\lambda}))-\rank(\kappa_0(p^f_{t,\lambda}))&=
\frac{1}{2}\left(\sig(2p^e_{t,\lambda}-\id)+\dim\mathcal{H}_{\lambda}\right)-
\frac{1}{2}\left(\sig(2p^f_{t,\lambda}-\id)+\dim\mathcal{H}_{\lambda}\right)\\
&=\frac{1}{2}\sig(2p^e_{t,\lambda}-\id)-\frac{1}{2}\sig(2p^f_{t,\lambda}-\id).
\end{align*}
The operator~\( p_{t,\lambda}^f \) is given by 
\(\begin{pmatrix}
    0 & 0 \\ 0 & \id
\end{pmatrix}\). Hence
\[
    \sig(2p_{t,\lambda}^f-\id)=\sig\begin{pmatrix}
    -\id & 0 \\ 0 & \id
    \end{pmatrix}=0.
\]

Now let
\[
    \mathcal{L}^e_{t^{-1},\lambda}\defeq
    2p^e_{t,\lambda}-\id.
\]
Then~\( \mathcal{L}^e_{t^{-1},\lambda} \) is
the truncation of the following operator onto~\( \mathcal{H}_{\lambda}
\):
\[ 
    2\begin{pmatrix}
    s_t^2 & \sqrt{c_ts_t}v\sqrt{c_ts_t} \\
    \sqrt{c_ts_t}v^*\sqrt{c_ts_t} & c_t^2
    \end{pmatrix}-\begin{pmatrix}
    \id & 0 \\ 0 & \id
    \end{pmatrix}=
    \begin{pmatrix}
    2s_t^2-\id & \sqrt{2c_ts_t}v\sqrt{2c_ts_t} \\
    \sqrt{2c_ts_t}v^*\sqrt{2c_ts_t} & 2c_t^2-\id
    \end{pmatrix}.
\]
Abbreviate~\( D_t\defeq t^{-1}D \). We compute that
\begin{alignat*}{3}
2s_t^2-\id&=\id+D_t(1+D_t^2)^{-\sfrac{1}{2}}-\id&&=D_t(1+D_t^2)^{-\sfrac{1}{2}};\\
2c_t^2-\id&=\id-D_t(1+D_t^2)^{-\sfrac{1}{2}}-\id&&=-D_t(1+D_t^2)^{-\sfrac{1}{2}};\\
2c_ts_t&=2\sqrt{\frac{1}{4}-\frac{1}{4}D_t^2(1+D_t^2)^{-1}}&&=(1+D_t^2)^{-\sfrac{1}{2}}.
\end{alignat*}
Thus  
\[
    \mathcal{L}^e_{t^{-1},\lambda}=\begin{pmatrix}
    D_t(1+D_t^2)^{-\sfrac{1}{2}} &
    (1+D_t^2)^{-\sfrac{1}{4}}v(1+D_t^2)^{-\sfrac{1}{4}} \\
    (1+D_t^2)^{-\sfrac{1}{4}}v^*(1+D_t^2)^{-\sfrac{1}{4}} &
    -D_t(1+D_t^2)^{-\sfrac{1}{2}} &
    \end{pmatrix}
\]
where the right-hand side is considered as an operator on~\(
\mathcal{H}_\lambda \) through truncation. The operator~\(
(1+D_t^2)^{-\sfrac{1}{4}} \) is a positive, invertible operator on~\(
\mathcal{H} \) which commutes with the spectral projections of~\( D \), 
thus its truncation onto~\( \mathcal{H}_\lambda \) is also
positive and invertible. So we have
\[ 
    \mathcal{L}^e_{t^{-1},\lambda}=\begin{pmatrix}
    (1+D_t^2)^{-\sfrac{1}{4}} & 0 \\ 0 & (1+D_t^2)^{-\sfrac{1}{4}} 
    \end{pmatrix}
    \begin{pmatrix}
    D_t & v \\
    v^* & -D_t
    \end{pmatrix}
    \begin{pmatrix}
    (1+D_t^2)^{-\sfrac{1}{4}} & 0 \\ 0 & (1+D_t^2)^{-\sfrac{1}{4}} 
    \end{pmatrix}.
\]
Thus~\( \sig(\mathcal{L}^e_{t^{-1},\lambda}) \)
coincides with the signature of the truncation of
\[ 
    \begin{pmatrix}
    D_t & v \\ v^* & -D_t
    \end{pmatrix}=\begin{pmatrix}
    t^{-1}D & v \\ v^* & -t^{-1}D
    \end{pmatrix}.
\]
Then we conclude that
\begin{multline*} 
    \braket{[v],[D]}=\rank(\kappa_0(p^e_{t,\lambda}))-\rank(\kappa_0(p^f_{t,\lambda}))=\frac{1}{2}\sig(2p^e_{t,\lambda}-1)-\frac{1}{2}\sig(2p^f_{t,\lambda}-1)\\
    =\frac{1}{2}\sig\mathcal{L}^e_{t^{-1},\lambda}=\frac{1}{2}\sig L_{t^{-1},\lambda}.\qedhere
\end{multline*}
\end{proof}


\subsection{Numerical index pairings and their truncations}
In this last section, we shall explain how a large class of \emph{numerical}
index pairing can be computed using the spectral truncation method of
\Cref{thm:index_pairing_submodule}. In particular, a \emph{semi-finite}
version of the spectral localiser 
defined by Schulz-Baldes and Stoiber
\cite{SBaldes-Stoiber:Semifinite_spectral_localizer}
arises in this way.

The setting that we shall be working in is as follows. Let~\( A \) and~\( B
\) be unital \Cst-algebras,~\( \tau \) a \emph{finite}, 
\emph{faithful} trace on~\( B \).  Then~\( \tau
\) extends to~\( \Mat_n(B) \) for each~\( n\in\N \) by (still denoted by~\(
\tau\):)
\[
    \tau\colon\Mat_{n}(B)\to\C,\quad (b_{ij})_{i,j=1}^{n}\mapsto\sum_{i=1}^n
    \tau(b_{ii}),
\]
and hence induces a group homomorphism
(cf.~\cite{Willett-Yu:Higher_index_theory}*{Remark 2.1.6}):
\[ 
    \tau_*\colon \K_0(B)\to\R.
\]

As before, we let~\( (\mathcal{A},E,D) \) be an odd unbounded Kasparov~\( A
\)-\( B \)--module and~\( v\in\mathcal{A} \) be a unitary. Let~\(
[v]\times[D]\in\K_0(B) \) be their Kasparov product as in
\Cref{eq:K-theoretic_index_pairing}. Their~\( \tau \)-(\emph{numerical}) 
\emph{index pairing} is defined as the real number
\[ 
    \tau_*([v]\times[D])\in\R.
\]

We wish to compute the~\( \tau \)-index pairing using the quasi-projection
representative~\( [e_t]-[f_t]\in\K_0(\Cpt_B(E)) \) as in
\Cref{thm:index_pairing_quasi-projections}. Next, we shall apply 
the spectral truncation method as in 
\Cref{thm:index_pairing_submodule} to replace~\(
[e_t]-[f_t] \) by their truncations onto a spectral submodule. The first
step is established by tranferring the finite, faithful trace~\(
\tau\colon B\to\C \) to a semi-finite trace on~\( \Cpt_B(E) \) and
then applying \Cref{thm:commutative_diagram_trace} below.

A finite trace~\( \tau\colon B\to\C \) is completely positive. Hence, it
yields, via 
the KSGNS construction (cf.~\cite{Lance:Hilbert_Cst-modules}*{Chapter 5}),
a Hilbert space
\[
    \mathcal{H}^\tau\defeq E\otimes_BL^2(B,\tau),
\]
obtained from the interior tensor product of the Hilbert~\( B \)-module~\(
E\) with the GNS-Hilbert space~\( L^2(B,\tau) \) constructed from~\(
\tau\colon B\to\C\). 

The Hilbert space~\( \mathcal{H}^\tau \) carries a representation
\[ 
    \varrho^\tau\colon \End_B^*(E)\to\Bdd(\mathcal{H}^\tau),\quad
    \varrho^\tau(T)(\xi\otimes b)\defeq T\xi\otimes b,
\]
which is isometric because~\( \tau \) is faithful. Thus
we may identify~\( \End_B^*(E) \), as well as its \Cst-subalgebra~\(
\Cpt_B(E) \), with their images under~\( \varrho^\tau \).  

Now we transfer the finite trace~\( \tau\colon B\to\C \) to a
\emph{semi-finite} trace~\( \widehat{{\tau}} \) on~\( \Cpt_B(E) \). The
following presentation comes from Laca and Neshveyev, whereas they 
also attributed a more general result to the work of 
Combes and Zettl 
\cite{Combes-Zettl:Order_structures}*{Proposition 2.1 and 2.2}, in which 
\( \tau \) is merely assumed to be densely defined. 

\begin{lemma}[\cite{Laca-Neshveyev:KMS_states_quasi-free}*{Theorem
1}]\label{lem:transfer_trace}
Let~\( B \) be a \Cst-algebra with a \emph{finite} trace~\( \tau\colon
B\to\C \). Let~\( \mathcal{E} \) be a Hilbert~\( B \)-module. 
Denote by~\( \ket{\xi_1}\bra{\xi_2} \) the rank-one
operator
\( \ket{\xi_1}\bra{\xi_2}\xi_3\defeq \xi_1\braket{\xi_2,\xi_3} \).
Define
\[ 
    \widehat{\tau}\colon\End^*_{B}(\mathcal{E})_+\to[0,+\infty],\quad 
    \widehat{\tau}(T)\defeq \sup_I\sum_{\xi\in I}\tau(\braket{\xi,T\xi}),
\]
where~\( I \) ranges over all finite subsets of~\( \mathcal{E} \) such that
\( \sum_{\xi\in I}\ket{\xi}\bra{\xi}\leq \id_\mathcal{E} \). 
Extend~\( \widehat{\tau} \) by linearality. Then the following 
holds\textup{:}
\begin{enumerate}
\item \( \widehat{\tau} \) is a semi-finite trace on~\(
\End_{B}^*(\mathcal{E}) \). 
\item 
\( \widehat{\tau}(\ket{\xi_1}\bra{\xi_2})=\tau(\braket{\xi_2,\xi_1}) \) 
and~\( \widehat{\tau}(\ket{\xi_1}\bra{\xi_2})<+\infty \). 
As a consequence, every
element in~\( \Fin_B^*(\mathcal{E}) \) is~\( \widehat{\tau} \)-finite.  
\end{enumerate}
\end{lemma}

The semi-finite trace~\( \widehat{\tau} \) on~\( \End_B^*(E) \) extends to
the enveloping von Neumann algebra~\(
\mathcal{N} \) of~\( \varrho^\tau(\End_B^*(E)) \).
Denote by~\( \Fin_{\widehat{\tau}} \) the \st-subalgebra in~\( \mathcal{N}
\) generated by all~\( \tau \)-finite projections, 
and~\( \Cpt_{\widehat{\tau}} \) be the
norm-closed ideal generated by~\( \Fin_{\widehat{\tau}} \).    
It is shown in \cite{Kaad-Nest-Rennie:KK-theory_spectral_flow}*{Lemma
6.3} that~\( \Fin_{\widehat{\tau}} \) is
holomorphically closed in~\( \Cpt_{\widehat{\tau}} \). This gives a
well-defined group homomorphism 
(cf.~\cite{Kaad-Nest-Rennie:KK-theory_spectral_flow}*{Theorem 6.4}):
\[ 
    \widehat{\tau}_*\colon \K_0(\Cpt_{\widehat{\tau}})\to\R,\quad
    \widehat{\tau}_*([p]-[q])\defeq 
    \widehat{\tau}\big(p-s(p)\big)-
    \widehat{\tau}\big(q-s(q)\big),
\]
where~\( p,q\in\Mat_n(\Fin_{\widehat{\tau}}^+) \) are projections
such that~\( [s(p)]=[s(q)] \) in~\( \K_0(\C) \), and~\( s\colon
\Mat_n(\Fin_{\widehat{\tau}}^+)\twoheadrightarrow\Mat_n(\C) \)
is the projection onto the scalar matrix part.

\begin{theorem}\label{thm:commutative_diagram_trace}
The \st-homomorphism~\( \varrho^{\tau}\colon
\Cpt_B(E)\to\Bdd(\mathcal{H}^\tau) \)
maps~\( \Cpt_B(E) \) into~\( \Cpt_{\widehat{\tau}} \). Its induced map
\[ 
    \varrho^{\tau}_*\colon \K_0(\Cpt_B(E))\to\K_0(\Cpt_{\widehat{\tau}})
\]
makes the the following diagram commute:
\[ \begin{tikzcd}[row sep=large, column sep=large]
\K_1(A) \arrow[r, "\times{[D]}"] \arrow[rd, "\Phi^D_*"'] & \K_0(B)
\arrow[r, "\tau_*"] & \R \\
& \K_0(\Cpt_B(E))  \arrow[u, "{[E]}"]  \arrow[r,"\varrho^{\tau}_*"] &
\K_0(\Cpt_{\widehat{\tau}}) \arrow[u, "\widehat{\tau}_*"'].
\end{tikzcd} \]
\end{theorem}

We provide a detailed proof in \Cref{app:proof_commutativity}.
It follows immediately from the preceding theorem that:

\begin{corollary}
The~\( \tau \)-index pairing~\( \tau_*([v]\times[D])\in\R \) is
represented by
\[ 
    \widehat{\tau}_*\circ\varrho^\tau_*([e_t]-[f_t])=
    \widehat{\tau}_*([\varrho^\tau(e_t)]-[\varrho^\tau(f_t)]),
\]
where
\[ 
    e_t=\begin{pmatrix}
    s_t^2 & \sqrt{c_ts_t} v\sqrt{c_ts_t} \\
    \sqrt{c_ts_t} v^*\sqrt{c_ts_t} &  c_t^2
    \end{pmatrix},\quad f_t=\begin{pmatrix}
    0 & 0 \\ 0 & \id
    \end{pmatrix}
\]
are \textup{(}quasi-\textup{)}projections in~\( \Mat_2(\Cpt_B(E)) \), and
\( \varrho^\tau(e_t),\varrho^\tau(f_t)\in\Mat_2(\Cpt_{\widehat{\tau}^+}) \)
are their images under the injective \st-homomorphism~\(
\varrho^\tau\otimes\mathbf{1}_{2\times 2}\colon
\Mat_2(\Cpt_B(E)^+)\to\Mat_2(\Cpt_{\widehat{\tau}}^+) \). 
\end{corollary}

Now we apply spectral truncation to the quasi-projection
representative
\[
    [\varrho^\tau(e_t)]-[\varrho^\tau(f_t)]\in\K_0(\Cpt_{\widehat{\tau}}).
\]
where both~\( \varrho^\tau(e_t) \) and~\( \varrho^\tau(f_t) \) are
represented faithfully on the Hilbert
\emph{space}~\( \widehat{\mathcal{H}}^\tau\defeq \mathcal{H}^\tau\oplus
\mathcal{H}^\tau \). Hence, as explained in
\Cref{ex:spectral_decomposition_Hilbert_space}, 
a spectral decomposition may be
constructed from the spectral projections of an unbounded, self-adjoint
operator thereon.

In the case of interest, we consider spectral projections of the
unbounded, self-adjoint operator
\( D^\tau\oplus D^\tau \) obtained from the unbounded, self-adjoint and
regular operator~\( D \) on~\( E \), localised at the representation~\(
\End_B^*(E)\to\Bdd(\mathcal{H}^\tau) \). That is, let~\( D\otimes\id \)
denote the interior tensor product operator  
\[ 
    D\otimes\id\colon
    \dom D\otimes^{\mathrm{alg}}_BL^2(E,\tau)\subseteq
    \mathcal{H}^\tau\to\mathcal{H}^\tau,\quad
    (D\otimes\id)(\xi\otimes b)\defeq D\xi\otimes b,
\]
defined on the algebraic tensor product~\(
\dom D\otimes^{\mathrm{alg}}_BL^2(E,\tau) \). Then its closure, denoted by
\( D^\tau \), is a self-adjoint operator on~\( \mathcal{H}^\tau \) 
(cf.~\cite{Lance:Hilbert_Cst-modules}*{Chapter 10}).

Let~\( \lambda>0 \), we set
\begin{gather*} 
\mathcal{H}^{\tau}_{\lambda}\defeq
\chi_{[-\lambda,\lambda]}(D^\tau\oplus D^\tau)\widehat{\mathcal{H}}^\tau,\\
\mathcal{H}^{\tau}_{\lambda^\mathrm{c}}\defeq
\chi_{(-\infty,-\lambda)\cup(\lambda,\infty)}(D^\tau\oplus
D^\tau)\widehat{\mathcal{H}}^\tau.
\end{gather*}
Then~\( (\mathcal{H}_\lambda^\tau,\mathcal{H}_{\lambda^\mathrm{c}}^\tau) \)
is a spectral decomposition for the unbounded, self-adjoint operator~\(
D^\tau\oplus D^\tau \) with spectral threshold~\( \lambda \).
Similar as in \eqref{eq:spectral_decomposition_et_ft}, we write
\begin{equation}\label{eq:spectral_decomposition_et_ft_semifinite}
    \varrho^{\tau}(e_t)=\begin{pmatrix} 
    p^e_{t,\lambda} & {m^e_{t,\lambda}}^* \\
    m^e_{t,\lambda} & q^e_{t,\lambda} 
    \end{pmatrix},\quad
    \varrho^{\tau}(f_t)=\begin{pmatrix} 
    p^f_{t,\lambda} & {m^f_{t,\lambda}}^* \\
    m^f_{t,\lambda} & q^f_{t,\lambda} 
    \end{pmatrix},\quad
    \varrho^{\tau}(\Theta_t)=\begin{pmatrix} 
    p^\Theta_{t,\lambda} & {m^\Theta_{t,\lambda}}^* \\
    m^\Theta_{t,\lambda} & q^\Theta_{t,\lambda} 
    \end{pmatrix},
\end{equation}
where
\begin{align*}
p^e_{t,\lambda},p^f_{t,\lambda},p^{\Theta}_{t,\lambda}&\colon
\mathcal{H}^{\tau}_{\lambda}\to\mathcal{H}^\tau_{\lambda}, \\
m^e_{t,\lambda},m^f_{t,\lambda},m^\Theta_{t,\lambda}&\colon
\mathcal{H}^\tau_{\lambda}\to\mathcal{H}^\tau_{\lambda^\mathrm{c}}, \\
q^e_{t,\lambda},q^f_{t,\lambda},q^\Theta_{t,\lambda}&\colon
\mathcal{H}^\tau_{\lambda^\mathrm{c}}\to\mathcal{H}^\tau_{\lambda^\mathrm{c}}.
\end{align*}

Replacing~\( [\varrho^{\tau}(e_t)]-[\varrho^{\tau}(f_t)] \) by their
spectral truncations~\( [p_{t,\lambda}^e]-[p_{t,\lambda}^f] \) requires an
analogue of \Cref{lem:reduction_to_diagonal}, which allows for reducing
\( \varrho^{\tau}(e_t) \) to its spectral diagonal. In order to do this,
one key step is showing that~\( \chi_K(D^\tau) \) is
\( \widehat{\tau} \)-finite for every compact set~\( K \). 
We prove this in \Cref{lem:resolvent_tau_compact}, based on the remarkable
\Cref{lem:compactly_supported_fin_rank}, which states that 
\( f(D)\in\Fin_B^*(E) \) for all~\( f\in\Cc(\R) \).   

\begin{theorem}\label{thm:semi-finite_index_pairing_subspace}
Let~\( A \) and~\( B \)  be unital \Cst-algebras,~\( \tau \) be
finite faithful trace on~\( B \). Let~\( (\mathcal{A},E,D) \) be an
odd unbounded Kasparov~\( A \)-\( B \)--module and
\( v\in \mathcal{A} \) be a unitary. Write~\( [v]\in\K_1(A) \) and~\(
[D]\in\KK_1(A,B) \) for their representing classes. Then\textup{:}
\begin{enumerate}
\item For every~\( 0<\delta<\frac{1}{400} \), 
there exists~\( \lambda>0 \), such that under the spectral
decomposition~\(
(\mathcal{H}_\lambda^{\tau},\mathcal{H}_{\lambda^\mathrm{c}}^{\tau}) \), it
follows that
\( \norm{q_{t,\lambda}^e-q_{t,\lambda}^\Theta
q_{t,\lambda}^fq_{t,\lambda}^{\Theta}{}^*}\leq\delta \)\textup{;}
\item Assume that there exists~\( R>0 \) such that 
\eqref{eq:assmption_constants_R}
holds. 
Then for any~\( 0<\varepsilon<\frac{1}{400}-\delta \) and any~\(
t\in[1,\infty) \) that satisfy  
\[  
    t>2\varepsilon^{-1}R\norm*{[D,v]},
\]
then
\[ 
[\varrho^\tau(e_t)]-[\varrho^\tau(f_t)]=[p^e_{t,\lambda}]-[p^f_{t,\lambda}]\in\K_0(\Cpt_{\widehat{\tau}}).
\]
\end{enumerate}
\end{theorem}


\begin{proof}
The proof follows in a similar way as
\Cref{thm:index_pairing_submodule}, except that we
must show that the homotopy
\[ 
    [0,1]\to\Bdd(\widehat{\mathcal{H}}^\tau),\quad
    s\mapsto\begin{pmatrix}
    p^e_{t,\lambda} & s\cdot m^e_{t,\lambda}{}^* \\ 
    s\cdot m^e_{t,\lambda} & q^f_{t,\lambda}
    \end{pmatrix}
\]
lies inside~\( \Mat_2(\Cpt_{\widehat{\tau}}^+) \). To this end, write~\(
P_\lambda^{\tau}\colon
\widehat{\mathcal{H}}^\tau\to\mathcal{H}_{\lambda}^\tau \) for the
orthogonal projection onto~\( \mathcal{H}_\lambda^\tau \),
then~\( P_\lambda^\tau=\chi_{[-\lambda,\lambda]}(D^\tau\oplus D^\tau) \).
Since~\(
[-\lambda,\lambda] \) is a compact subset of~\( \R \), it follows from
\Cref{lem:resolvent_tau_compact} that~\( P_\lambda^{\tau} \) is a~\(
\widehat{\tau} \)-finite projection.  Since~\(
\Mat_2(\Cpt_{\widehat{\tau}})\subseteq \Mat_2(\mathcal{N}) \) is an ideal,
we conclude that~\( m^e_{t,\lambda}=m^e_{t,\lambda}P_\lambda^\tau \)
belongs to~\( \Mat_2(\Cpt_{\widehat{\tau}}) \) as well. 
\end{proof}

Similar as in the spectral triple case of
\Cref{sec:spectral_localiser_spectral_triple}, 
define the following unbounded,
self-adjoint operator on~\( \mathcal{H}^\tau \): 
\[ 
    L^\tau_\kappa\defeq \begin{pmatrix}
    \kappa D^\tau & \varrho^\tau(v) \\
    \varrho^\tau(v^*) & -\kappa D^\tau
    \end{pmatrix}
\]
and let~\( L^\tau_{\kappa,\lambda} \) be its truncation onto~\(
\mathcal{H}^\tau_{\lambda} \). We shall show that the~\(
\tau \)-index pairing~\( \tau_*\braket{[v],[D]} \) can be obtained as the
half--\( \tau \)-signature (defined below) of~\( L^\tau_{\kappa,\lambda} \)
for sufficiently small tuning parameter~\( \kappa \) and sufficiently large
spectral threshold~\( \lambda \).  

\begin{definition}\label{def:tau_rank_sig}
Let~\( A \) be a \Cst-algebra, and~\( \tau \) be a densely defined trace on
\( A \).
\begin{enumerate}
\item Let~\( p\in A \) be a quasi-projection such that~\( \kappa_0(p) \) is
\( \tau \)-finite. Then the~\( \tau \)-rank of~\( p \) is defined as
\[ 
    \rank_\tau(p)\defeq \tau(\kappa_0(p)).
\]
\item Let~\( L\in A \) be an invertible element such that~\(
\chi_{(0,+\infty)}(L) \) and~\( \chi_{(-\infty,0)}(L) \) are both~\( \tau
\)-finite. Then the~\( \tau \)-signature of~\( L \) is defined as
\[ 
    \sig_\tau(L)\defeq
    \tau(\chi_{(0,+\infty)}(L))-\tau(\chi_{(-\infty,0)}(L)).
\]
\end{enumerate}
\end{definition}

The following lemma generalises
\Cref{lem:signature_quasi-projection} where~\( A=\Bdd(\mathcal{K}) \) for
\( \mathcal{K} \) a finite-dimensional Hilbert space, and~\( \tau \) is the
standard trace on it..

\begin{lemma}
Let~\( A \) be a unital \Cst-algebra and~\(
\tau \) be a densely defined trace on~\( A \).
Let~\( p\in A \) be a quasi-projection such that both~\( \kappa_0(p) \) and
\( \kappa_0(1_A-p) \) are~\( \tau \)-finite. Then  
\[ 
    \sig_\tau(2p-1_A)=\rank_\tau(p)-\rank_\tau(1_A-p).
\]
\end{lemma}

Now we shall prove an analogue of \Cref{thm:spectral_localiser} in this
setting, replacing signature and rank 
by their~\( \widehat{\tau} \)-versions. 

\begin{theorem}\label{thm:spectral_localiser_semifinite}
For every~\( t,\lambda>0 \),~\( \sig_{\widehat{\tau}}(L^\tau_{t^{-1},\lambda}) \),~\(
\rank_{\widehat{\tau}}(p^e_{t,\lambda}) \) and~\( \rank_{\widehat{\tau}}(p^f_{t,\lambda}) \)
are well-defined and satisfy the equality
\[ 
    \frac{1}{2}\sig_{\widehat{\tau}}(L^{\tau}_{t^{-1},\lambda})=
    \rank_{\widehat{\tau}}(p^e_{t,\lambda})-
    \rank_{\widehat{\tau}}(p^f_{t,\lambda}).
\]
As a consequence, let~\( \varepsilon,\delta>0 \) satisfy~\(
\varepsilon+\delta<\frac{1}{400} \). For any choice~\( t,\lambda \)
satisfying~\(
t>4\varepsilon^{-1}\norm*{[D,v]} \) and~\( \lambda>t\delta^{-1}
\), the half--\( \widehat{\tau} \)-signature 
\( \frac{1}{2}\sig_{\widehat{\tau}}(L_{t^{-1},\lambda}) \) 
coincides with the~\( \tau \)-numerical index 
pairing~\( \tau_*(\braket{[v],[D]}) \).   
\end{theorem}

\begin{proof}
We have proven in \Cref{thm:semi-finite_index_pairing_subspace} that the
orthogonal projection~\( P_{\lambda}^\tau\colon
\widehat{\mathcal{H}}^{\tau}\to\mathcal{H}_{\lambda}^\tau \) is~\(
\widehat{\tau} \)-finite. Note that
\( L_{t^{-1},\lambda} \),~\( p^e_{t,\lambda} \) and
\( p^f_{t,\lambda} \) are all supported on~\( \mathcal{H}^\tau_{\lambda}
\). Therefore,
\[ 
    \kappa_0(p^e_{t,\lambda}),\quad\kappa_0(p^f_{t,\lambda}),\quad
    \chi_{(0,+\infty)}(L),\quad\chi_{(-\infty,0)}(L)
\]
are all subprojections of~\( P_{\lambda}^{\tau} \), hence 
\( \widehat{\tau} \)-finite. So 
\Cref{def:tau_rank_sig} applies to them for the
\Cst-algebra~\( A=\Mat_2(\Cpt_{\widehat{\tau}}) \) with densely defined
trace~\( \widehat{\tau} \). The rest of the proof
follows in the same way as \Cref{thm:spectral_localiser}.
\end{proof}

\begin{remark}
It is well-known that numerical index pairings can be stated in the
framework of \emph{semi-finite index theory}
(cf.~\cite{Carey-Gayral-Rennie-Sukochev:Index_theory_locally_compact}). In
this general setting, a numerical index pairing is expressed as a pairing
between a \emph{semi-finite spectral triple} with a K-theory class.
The proof of \Cref{thm:commutative_diagram_trace} actually show the
following:

Let~\( A \) and~\( B \) be unital \Cst-algebras,~\( \tau \) a finite trace
on~\( B \), and~\( (\mathcal{A},E,D) \) an odd unbounded Kasparov~\( A \)-\(
B \)--module. By \Cref{lem:resolvent_tau_compact}, the data
\[ 
    (\mathcal{A},\mathcal{H}^\tau,D^\tau)\defeq 
    (\mathcal{A},E\otimes_B L^2(E,\tau),D\otimes\id)
\]
is a semi-finite spectral triple relative to~\( (\mathcal{N},\tau) \)
in the sense of
\cite{Carey-Phillips-Rennie-Sukochev:Local_index_formula_1}*{Definition
2.1},
where~\( \mathcal{N} \) is the enveloping von Neumann algebra of~\(
\Cpt_B(E) \) in the representation~\( \varrho^\tau \)
(cf.~\Cref{thm:commutative_diagram_trace}). 
Similar results have been achieved in
\cite{Goffeng-Rennie-Usachev:KMS_states}*{Theorem 2.12}.

The operators~\( L^\tau_{\kappa} \) and~\( L^\tau_{\kappa,\lambda} \)
of \Cref{thm:spectral_localiser_semifinite} were introduced by
Schulz-Baldes and Stoiber as a variant of the
spectral localiser that works for semi-finite index pairings. Thus
\Cref{thm:spectral_localiser_semifinite} recovers a special case of the
main theorem of \cite{SBaldes-Stoiber:Semifinite_spectral_localizer}.

Finally, we note that the setting in
this section is, albeit specific, yet enough to
cover many interesting examples that naturally emerge from the index theory
of \emph{tight-binding models} of topological insulators as in 
\cites{Kellendonk-Richter-SBaldes:Edge_current_channels,Bourne-Kellendonk-Rennie:Bulk-edge_correspondence,Bourne-Prodan:Noncommutative_Chern_numbers,Bourne-Mesland:Topological_phases},
in which the \Cst-algebra~\( A \) is given by the reduced \Cst-algebra of
an \'etale groupoid~\( \mathcal{G}\rightrightarrows \Omega \), either from
a crossed product by~\( \Z^d \) or as a transversal of a crossed product by
\( \R^d \), hence unital; 
and~\( B \) is the commutative, unital \Cst-algebra~\(
\Cont(\Omega) \). A finite, faithful
trace on~\( B \) thus corresponds to a finite, regular Borel measure on~\(
\Omega\)  with full support. These conditions 
are usually legitimated by physical assumptions.
\end{remark}

