\section{The asymptotic morphism}
\label[appendix]{app:asymptotic_morphism}
Given an \emph{essential} odd unbounded Kasparov~\( A \)-\( B \)--module~\(
(\mathcal{A},E,D) \), where essential means~\( \overline{\mathcal{A}E}=E
\), then the family~\( (\Phi^D_t)_{t\in[1,\infty)} \)
\[
  \Phi_{t}^{D}\colon\Co(\mathbb{R})\otimes A\to \Cpt_B(E), \quad f\otimes
a\mapsto f(t^{-1}D)a,
\]
defines an asymptotic morphism, hence an odd
E-theory class~\( \llbracket\Phi^D_t\rrbracket\in\E_1(A,B) \).  It is
alluded to in the literature that the natural transformation~\(
\KK_{1}(A,B)\to\E_{1}(A,B) \) is implemented by the map~\(
(\mathcal{A},E,D)\mapsto \llbracket\Phi^{D}_{t}\rrbracket \). We provide a
rigorous proof of this folklore statement in \Cref{thm:Phi^D}.

For even unbounded Kasparov modules, a realisation of the natural
transformation~\( \KK_0(A,B)\to\E_0(A,B) \) has been described by Connes
and Higson in their unpublished note
\cite{Connes-Higson:Almost_homomorphisms}*{Section 8}.  Their construction
coincides with~\( (\Phi_t^D)_{t\in [1,\infty)} \) up to the Bott
periodicity isomorphism~\( \KK_0(A,B)\simeq\KK_1(A,\Co(\R)\otimes B) \).
For~\( D \) a Dirac-type operator on a Riemannian manifold and~\( B=\C \),
asymptotic morphisms of the form~\( f\otimes a\mapsto f(t^{-1}D)a \) 
have also been studied by
Guentner \cite{Guentner:PhD_thesis}*{Section 4.4} and
Dumitra\c{s}cu \cite{Dumitrascu:K-homology}*{Section 3}. For the Dirac
element in KK-theory for proper group actions on the Hilbert space, 
such an asymptotic morphism
has been considered by Higson and Kasparov
\cite{Higson-Kasparov:E-theory_KK-theory_groups}*{Section 8}.

Another such realisation of the natural transformation~\(
\KK\Rightarrow\E \) has been given by Dumitra\c{s}cu
\cite{Dumitrascu:KE-theory} based on
a variant of E-theory for~\( \Z/2 \)-graded \Cst-algebras.  
In particular, we note that the family of operators~\( (F_t\defeq
t^{-1}D(1+t^{-2}D^2)^{-\sfrac{1}{2}})_{t\in [1,\infty)} \) in
\eqref{eq:wt_Ft_Pt} below gives an \emph{asymptotic Kasparov module}
in the sense of \cite{Dumitrascu:KE-theory}*{Definition 3.6}.

The proof presented here is motivated by
\cite{Higson-Kasparov:E-theory_KK-theory_groups}*{Section 8}.
Recall that the odd unbounded Kasparov module~\( (\mathcal{A},E,D) \) 
gives a semi-split
extension \eqref{eq:Kasparov_KK_to_extension} of \Cst-algebras.
Connes and Higson has introduced in \cite{Connes-Higson:E-theory}, 
a ``standard'' asymptotic morphism
associated to a semi-split extension of \Cst-algebras. 
Its induced map in K-theory coincides the one induced by the Kasparov
product \eqref{eq:KK_index_pairing}:

\begin{lemma}[\cite{Connes-Higson:E-theory}*{Lemme
10}]\label{lem:Connes-Higson_extension_to_E}
Let
\[ \begin{tikzcd}
I \arrow[r,tail] & A \arrow[r, two heads, "p"] & B \arrow[l, bend left=30,
"s"]
\end{tikzcd} \]
be an extension of \Cst-algebras, which is semi-split by a section~\( s\colon
B\to A \). Then:
\begin{enumerate}
\item 
Let~\( (u_t)_{t\in [1,\infty)} \) be a
approximate unit of~\( I \) which is quasi-central for~\( A \). Then
there is an
asymptotic morphism~\( (\Phi^{\mathrm{CH}}_t\colon\Co(0,1)\otimes B\to
I)_{t\in[1,\infty)} \)
given by
\[
\Phi^\mathrm{CH}_t\colon \Co(0,1)\otimes B\to I,\qquad f\otimes b\mapsto
f(u_t)s(b).
\]
\item If~\( (u_t)_{t\in[1,\infty)} \) and~\( (v_t)_{t\in [1,\infty)} \) are
two different approximate units of~\( I \) that are quasi-central for~\( A
\). Then their induced asymptotic morphisms are asymptotically equivalent.  
\item If the extension is induced by an odd unbounded Kasparov module as in
\eqref{eq:Kasparov_KK_to_extension}, then asymptotic morphism becomes
\( \Phi_t^\mathrm{CH}\colon \Co(0,1)\otimes A\to\Cpt_B(E) \) 
and its induced map~\( \K_0(\Co(0,1)\otimes A)\to\K_0(\Cpt_B(E)) \) 
coincides
with the \K-theoretic index pairing~\( [v]\mapsto\braket{[v],[D]} \) up
to an isomorphism~\( \K_0(\Co(0,1)\otimes A)\simeq\K_1(A) \). 
\end{enumerate}
\end{lemma}

Our first step is to simplify the Connes-Higson asymptotic morphism in the
non-unital case. In what follows, we define
\begin{equation}\label{eq:wt_Ft_Pt}
\begin{aligned}
    w_t&\defeq (1+t^{-2}D^2)^{-1},\\
    F_t&\defeq t^{-1}D(1+t^{-2}D^2)^{-\sfrac{1}{2}},\\
    P_t&\defeq\frac{1+F_t}{2}
    =\frac{1+t^{-1}D(1+t^{-2}D^2)^{-\sfrac{1}{2}}}{2}.
\end{aligned}
\end{equation}
We note that~\( F_1=D(1+D^2)^{-\sfrac{1}{2}} \) and~\(
P_1=\frac{1+D(1+D^2)^{-\sfrac{1}{2}}}{2} \).
This amounts to choosing the chopping function~\(
\chi(x)\defeq x(1+x^2)^{-\sfrac{1}{2}} \) in \eqref{eq:P_1}.

\begin{lemma}\label{lem:reduction_of_au}
Let~\( (\mathcal{A},E,D) \) be an odd unbounded 
Kasparov~\( A \)-\( B \)--module,
\( (v_{t})_{t\in[1,\infty)}\subseteq\mathcal{A} \) 
an approximate unit for~\( A \) that is quasicentral for~\( P_{1} \).
Then the representative~\( f\otimes a\mapsto
f(w_{t}^{1/2}v_{t}w_{t}^{1/2})P_{1}a \) of the Connes--Higson asymptotic
morphism is asymptotically equivalent to~\( f\otimes a\mapsto
f(w_{t})P_{1}a \).
\end{lemma}

\begin{proof}
Since~\( \overline{AE}=E \), it follows that~\( v_{t}\to 1 \) \st-strictly and
\( w_{t}^{1/2}v_{t}w_{t}^{1/2} \) is an approximate unit for~\( \Cpt_B(E) \),
quasi-central for~\( A \) and~\( P_{1} \).

Observe that~\( w_{t}P_1a=P_1w_{t}a\in\Cpt_B(E) \) and
\( w_{t}^{1/2}v_{t}w_{t}^{1/2}P_1a=w_{t}^{1/2}v_{t}P_1w_{t}^{1/2}a\in\Cpt_B(E) \),
so both asymptotic families extend to families~\( \Co(0,1]\otimes A\to
\Cpt_B(E) \) (but do not give asymptotic morphisms!). The~\( \Cst \)-algebra
\( \Co(0,1] \) is singlely generated by the function~\( f(x)=x \), 
so it suffices to check that 
\[
    \lim_{t\to\infty}\Phi_{t}(h\otimes a)-\Psi_{t}(h\otimes a)=0,
\] 
for the function~\( h(x)=x \). Now
\begin{align*}
\Phi_{t}(h\otimes a)-\Psi_{t}(h\otimes a)&=(w_{t}-w_{t}^{1/2}v_{t}w_{t}^{1/2})P_1a\\
&\sim (w_{t}-w_{t}^{1/2}v_{t}w_{t}^{1/2})aP_1\\
&\sim w_{t}^{1/2}((1-v_{t})a)w_{t}^{1/2}P_1\sim 0,
\end{align*}
which establishes the result.
\end{proof}

Our next goal is to establish that~\( f\otimes a\mapsto f(w_{t})a \) is
asymptotically homotopic to~\( f(P_{t})a \).

\begin{lemma}\label{lem:difference_construction} 
Let~\( A,B,C \) be~\( \Cst \)-algebras with~\( A,B\subseteq C \). Suppose that~\(
\{\mathfrak{p}_t\}_{t\in[1,\infty)}\) and~\( \{\mathfrak{q}_t\}_{t\in
[1,\infty)} \) are continuous families of contractions in~\( C \), such
that for all~\( f\in \Co(0,1) \) and~\( a\in A \):
\begin{center}
\(\left(f(\mathfrak{p}_t)-
f(\mathfrak{q}_t)\right)a\in B\)\quad and\quad 
\( [\mathfrak{p}_t-\mathfrak{q}_t,a]\to 0\) in
norm.
\end{center}
Then~\( \Psi^{\mathfrak{p},\mathfrak{q}}_{t}\colon f\otimes a\mapsto
(f(\mathfrak{p}_t)-f(\mathfrak{q}_t))a \) is an asymptotic morphism
\( \Co(0,1)\otimes A\to B \).  
\end{lemma}

\begin{proof}
Since for each~\( t\in[1,\infty) \) the map
\( \Psi^{\mathfrak{p},\mathfrak{q}}_{t} \) is a difference of linear
contractions, we have 
\( \norm*{\Psi_{t}^{\mathfrak{p},\mathfrak{q}}}\leq 2 \) for
all~\( t \), and thus it suffices to check that
\( \Psi_{t}^{\mathfrak{p},\mathfrak{q}} \) is an asymptotic morphism on a dense
subalgebra of~\( \Co(0,1)\otimes A \). The maps
\( \Psi_{t}^{\mathfrak{p},\mathfrak{q}} \) extend to maps 
\( \Co(0,1]\otimes A\to C \) and 
the function~\( g(x)=x \) generates a dense \st-subalgebra of~\( \Co(0,1] \)
by the Stone--Weierstrass theorem. For~\( g \) we can estimate
\begin{gather*}
\Psi^{\mathfrak{p},\mathfrak{q}}_{t}(g\otimes
a)\Psi^{\mathfrak{p},\mathfrak{q}}_{t}(g\otimes
b)=(\mathfrak{p}_t-\mathfrak{q}_t)a(\mathfrak{p}_t-\mathfrak{q}_t)b\sim
(\mathfrak{p}_t-\mathfrak{q}_t)^{2}ab=\Psi^{\mathfrak{p},\mathfrak{q}}_{T}(g^{2}\otimes
ab),\\
(\Psi^{\mathfrak{p},\mathfrak{q}}_{t}(g\otimes a))^{*}=a^{*}(\mathfrak{p}_t-\mathfrak{q}_t)\sim (\mathfrak{p}_t-\mathfrak{q}_t)a^{*}=\Psi^{\mathfrak{p},\mathfrak{q}}_{t}(g\otimes a^{*}),
\end{gather*}
and we conclude that~\( \Psi^{\mathfrak{p},\mathfrak{q}}_{t} \) is an
asymptotic morphism on the dense \st-subalgebra generated by~\( g \), and thus
an asymptotic morphism~\( \Psi^{\mathfrak{p},\mathfrak{q}}_{t}\colon
\Co(0,1]\otimes
A\to C \). Since~\( f(\mathfrak{p}_t)a, f(\mathfrak{q}_t)a\in B \) 
for~\( f\in \Co(0,1) \), it
restricts to an asymptotic morphism
\( \Psi^{\mathfrak{p},\mathfrak{q}}_{t}\colon \Co(0,1)\otimes A\to B \).
\end{proof}

\begin{lemma}
\label{lem:error_reduction}
Let~\( f\in \Co(0,1) \) and~\( a\in\End^{*}_B(E) \). Let~\( P\in\End^{*}_B(E) \)
satisfy~\( 0\leq P\leq 1 \) and
\( (P^{2}-P)a\in\Cpt_B(E) \).
Let~\( \{u_t\}_{t\in[1,\infty)} \) be a family of positive contractions in
\( \End^*_B(E) \) such that~\( u_t\to \id_E \) \st-strictly,
and~\( u_{t}P=Pu_{t} \) for all~\( t\in [1,\infty) \). Then
\begin{equation}\label{eq:convergence_error_reduction}
    f(u_{t}P)a-f(P)a-f(u_{t})Pa\to 0.
\end{equation}
\end{lemma}
\begin{proof} 
The functions~\( f_{n}(x)=x^{n}(1-x)=x^{n}-x^{n+1},\,\, n\geq 1 \) generate
\( \Co(0,1) \) (in fact,~\( n=1,2 \) suffices). Now
\begin{align*}
(f_{n}(u_{t}P)-f_{n}(P)-f_{n}(u_{t})P)a&=(u^{n}_{t}P^{n}-u^{n+1}_{t}P^{n+1}-P^{n}+P^{n+1}-(u_{t}^{n}-u^{n+1}_{t})P)a\\
&=(u^{n}_{t}-1)(P^{n}-P^{n+1})a+u^{n}_{t}(1-u_{t})(P^{n+1}-P)a,
\end{align*}
and since 
\begin{gather*}
(P^{n}-P^{n+1})a=P^{n-1}(P-P^{2})a\in\Cpt_B(E),\\
(P^{n+1}-P)a=\sum_{k=0}^{n-1}P^{k}(P^{2}-P)a\in\Cpt_B(E).
\end{gather*}
Since~\( u_t\to\id_E \) \st-strictly, it follows that~\( u_t^nT\to T \) in
norm for every~\( T\in\Cpt_B(E) \). Thus we have found the convergence in
\eqref{eq:convergence_error_reduction}.
\end{proof}

\begin{proposition}\label{prop:homotopy_asymptotic_morphism}
The asymptotic morphism
\begin{equation}\label{eq:Higson-Kasparov}\tag{HK}
    \Phi^D_t\colon\Co(0,1)\otimes A\to \Cpt_B(E),\quad
    f\otimes a\mapsto f(P_t)a
\end{equation}
is asymptotically homotopic to the Connes--Higson asymptotic morphism
\begin{equation}\label{eq:Connes-Higson}\tag{CH}
    \Phi_t^{\mathrm{CH}}\colon \Co(0,1)\otimes A\to \Cpt_B(E),\quad
    f\otimes a\mapsto f(u_t)P_1a,
\end{equation}
hence they induce the same \K-theoretic index pairing 
\( \K_1(A)\to\K_0(\Cpt_B(E)) \). 
\end{proposition}

\begin{proof}
By \Cref{lem:reduction_of_au}, the Connes--Higson asymptotic morphism
\eqref{eq:Connes-Higson} is
equivalent to~\( f\otimes a\mapsto f(w_{t})P_{1}a \). 
For each~\( t\in [1,\infty) \) we define the following families of maps 
\( \Co(0,1)\otimes A\to\Cpt_B(E) \):
\begin{align}
f\otimes a&\longmapsto f(w_t)P_1a, \label{eq:asymptotic_1}\tag{a1} \\
f\otimes a&\longmapsto f(w_tP_1)a-f(P_1)a,
\label{eq:asymptotic_2}\tag{a2}\\
f\otimes a&\longmapsto f(P_t)a, \label{eq:asymptotic_3}\tag{a3}
\end{align}
Then all of them give asymptotic morphisms. For \eqref{eq:asymptotic_1} and
\eqref{eq:asymptotic_3} this is well known. For \eqref{eq:asymptotic_2},
this follows from \Cref{lem:difference_construction}. It follows from
\Cref{lem:error_reduction} that \eqref{eq:asymptotic_1} is asymptotically
equivalent \eqref{eq:asymptotic_2}.

The proof will be complete if we show that \eqref{eq:asymptotic_2} is
homotopic to \eqref{eq:asymptotic_3}. To this end, 
we consider the map~\( [1,\infty)\times
[0,1]\to \End^{*}_B(E) \)
\[(t,r)\mapsto (rw_{t}+1-r)P_{(1-r)t+r}, \quad (t,r)\mapsto rP_{(1-r)t+r},\]
which is norm-continuous. Thus, we have a family of maps
\[H_{t}\colon \Co(0,1)\otimes A\to\Cont([0,1],\Cpt_B(E)),\]
given by
\[H_{t}(f\otimes a)(r)\defeq
f((rw_{t}+1-r)P_{(1-r)t+r})-f(rP_{(1-r)t+r}))a,\]
such that for each~\( f\otimes a \), the map~\( t\mapsto H_{t}(f\otimes a) \) is
continuous. To prove that~\( H_{t} \) is an asymptotic morphism, we will use
\Cref{lem:difference_construction}, so we have to show that
\[(rw_{t}+1-r)P_{(1-r)t+r}-rP_{(1-r)t+r}=(rw_{t}+1-2r)P_{(1-r)t+r},\]
is~\( A \)-quasi-central for the sup-norm on~\( \Cont([0,1],\Cpt_B(E)) \), that is,
\begin{equation}
\label{eq:sup_norm_limit}
\lim_{t\to\infty}\sup_{r\in[0,1]}\norm*{\left[(rw_{t}+1-2r)P_{(1-r)t+r}\,,\,a\right]}=0,\quad
\text{for every~\( a\in A \).}
\end{equation}
To this end, for each~\( a\in A \) and every~\( r\in [0,1] \) we have
\begin{multline*}
[(rw_{t}+1-2r)P_{(1-r)t+r}\,,\,a]\\
=r[w_{t},a]P_{(1-r)t+r}+(1-r)[P_{(1-r)t+r}\,,\,a]+r(w_{t}-1)[P_{(1-r)t+r}\,,\,a].
\end{multline*}
For the first summand, applying
\Cref{prop:commutator_sqrt_ctst} with~\( s=1 \) gives
\[\norm*{r[w_{t},a]P_{(1-r)t+r}}\leq 2t^{-1}\norm{[D,a]}.\]
For the second summand, we observe that~\( [P_{t},a]=\frac{1}{2}[F_{t},a] \).
Setting~\( s=0 \) in \Cref{prop:commutator_Ds_Ft} gives  
\begin{align*}
\norm*{(1-r)[P_{(1-r)t+r},a]}\leq
\frac{3}{2}\norm{[D,a]}(1-r)((1-r)t+r)^{-1}\leq
\frac{3}{2}t^{-1}\norm{[D,a]}.
\end{align*}
For the last term, observe that~\( 1-w_{t}=t^{-2}D^{2}(1+t^{-2}D^{2})^{-1} \)
and for any~\( 0<s<1 \), \Cref{prop:commutator_Ds_Ft} now yields
\begin{align*}
\norm*{r(1-w_{t})[P_{(1-r)t+r},a]}&=rt^{-s}\norm*{t^{-2+s}\abs{D}^{2-s}(1+t^{-2}D^{2})^{-1}\abs{D}^s[P_{(1-r)t+r},a]}\\
&\leq t^{-s}C_s\norm{[D,a]}((1-r)t+r)^{s-1}\leq t^{-s}C_s\norm{[D,a]},
\end{align*}
where
\[ 
    C_s\defeq
    1+\frac{2\Gamma(\tfrac{1-s}{2})}{\sqrt{\pi}\Gamma(\tfrac{2-s}{2})}.
\]
Thus, the convergence in \eqref{eq:sup_norm_limit} is established and~\( H_{t} \) gives the desired homotopy.     
\end{proof}

Thus we have proven the following result:

\begin{theorem}\label{thm:Phi^D}
Let~\( (\mathcal{A},E,D) \) be an essential odd 
unbounded Kasparov~\( A \)-\( B \)--module.
Then the asymtotic morphism
\[ \Phi^{D}_{t}\colon\Co(\mathbb{R})\otimes A\to \Cpt_B(E),\quad 
f\otimes a\mapsto f(t^{-1}D)a \]
represents the class of the image of~\( [D]\in\KK_1(A,B) \) in~\( \E_1(A,B)
\) under the natural transformation~\( \KK_1\to\E_1 \). In particular,
\( \Phi^D_t \) induces the same map 
\( \K_0(\mathrm{S}A)\to\K_0(\Cpt_B(E)) \) as~\(
[D]\in\KK_1(A,B) \), up to an isomorphism 
\( \K_1(A)\simeq\K_0(\mathrm{S}A) \).   
\end{theorem}

\begin{proof}
Note that
\[
    \chi\colon \R\to(0,1),\quad \chi(x)\defeq x(1+x^2)^{-\sfrac{1}{2}}
\]
is monotonically increasing and continuous. Thus it 
induces an isomorphism of \Cst-algebras 
\( \Co(0,1)\simeq\Co(\R) \). The
claim follows from the fact that \eqref{eq:Higson-Kasparov} is the
pullback of \eqref{eq:asymptotic_3} along~\( \chi \). 
\end{proof}

\section{Some commutator estimates}
\label[appendix]{app:commutator_estimates}
Let~\( (\mathcal{A},E,D) \) be an odd unbounded Kasparov
module and let~\( a\in\mathcal{A}\). 
Then~\( [D,a] \) extends to a bounded, adjointable operator on~\( E \).
We shall provide the following commutator estimates in
\Cref{prop:commutator_ct_st,prop:commutator_sqrt_ctst,prop:commutator_Ds_Ft}.

\begin{enumerate}
\item Let~\( c(x),s(x)\colon \R\to(0,1) \) be functions as in
\eqref{eq:choice_cs}:
\[
    c(x)\defeq\sqrt{\frac{1}{2}-\frac{1}{2}x(1+x^2)^{-\sfrac{1}{2}}},\quad 
    s(x)\defeq\sqrt{\frac{1}{2}+\frac{1}{2}x(1+x^2)^{-\sfrac{1}{2}}},
\]
and let~\( c_t\defeq c(t^{-1}D) \),~\( s_t\defeq c(t^{-1}D) \). Then the
following estimate holds:  
\[ 
    \norm*{[c_t,a]}\leq\frac{1}{2}t^{-1}\norm*{[D,a]},\quad
    \norm*{[s_t,a]}\leq\frac{1}{2}t^{-1}\norm*{[D,a]},\quad
    \norm*{[\sqrt{c_ts_t},a]}\leq
    2t^{-1}\norm*{[D,a]}.
\]
\item Let~\( F_t\defeq t^{-1}D(1+t^{-2}D^2)^{-\sfrac{1}{2}} \). Then for
all~\( 0\leq s<1 \),~\( [F_t,a] \) maps~\( E \) into~\( \dom\abs{D}^s \)
and the following estimate holds:
\[\norm*{\abs{D}^{s}[F_{t},a]}\leq C_s t^{s-1} \norm*{[D,a]},\]
where
\[ 
    C_s\defeq
    1+\frac{2\Gamma(\tfrac{1-s}{2})}{\sqrt{\pi}\Gamma(\tfrac{2-s}{2})}.
\]
Here~\( \Gamma(\alpha) \) is the Gamma function
\eqref{eq:Gamma_function}. 
\end{enumerate}

Then (1) completes the proof of \Cref{thm:choice_cs}, and 
(2) completes the proof of \Cref{prop:homotopy_asymptotic_morphism} in
\Cref{app:asymptotic_morphism}.

Our main tool is the following lemma:

\begin{lemma}[\citelist{\cite{G-Bondia_Varilly_Joseph_Figueroa:Elements_of_NCG}*{Lemma
10.15}; \cite{Bratelli-Robinson:Operator_algebras_quantum_statistics_1}*{Theorem
3.2.32}}]\label{lem:commutator_estimate}
Let~\( B \) be a \Cst-algebra and 
\( \mathcal{E} \) be a Hilbert~\( B \)-module.  
Let~\( a\in\End^*_B(\mathcal{E}) \) and~\( \mathcal{D} \)
be a self-adjoint, regular, possibly unbounded operator on~\( \mathcal{E} \)
such that~\( [\mathcal{D},a] \) extends to an element in~\( \End^*_B(\mathcal{E}) \).
Then:
\begin{enumerate}
\item \(\norm*{[\mathrm{e}^{\mathrm{i}\mathcal{D}},a]}\leq\norm*{[\mathcal{D},a]}\).
\item Let~\( f \) be a function on~\( \R \) with Fourier transform
\( \widehat{f} \), such that
\[
C_f\defeq
\frac{1}{2\pi}\int_{-\infty}^{\infty}\abs*{\xi\widehat{f}(\xi)}\,\mathrm{d}\xi
=\frac{1}{2\pi}\int_{-\infty}^{\infty}\abs*{\widehat{f'}(\xi)}\,\mathrm{d}\xi
<+\infty.
\]
Then~\( \norm*{[f(\mathcal{D}),a]} \) is bounded and satisfies the estimate
\[ 
    \norm*{[f(\mathcal{D}),a]}\leq C_f\cdot\norm*{[\mathcal{D},a]}.
\]
\end{enumerate}
\end{lemma}

To compute the commutators~\( [c_t,a] \) and~\( [s_t,a] \), we will use the
following trigonometric substitutions.

\begin{lemma}
Define the function
\( u\colon \R\to\left[0,\pi\right] \) by~\(u(x)\defeq 
\frac{\pi}{2}+\arctan(x)\).
Then~\( c(x)=\cos\left(\frac{1}{2}u(x)\right) \) and~\(
s(x)=\sin\left(\frac{1}{2}u(x)\right) \).  
\end{lemma}

\begin{proof}
Recall that for~\( \theta\in[0,\pi] \), we have the following half-angle
formulae of trigonometric functions:
\[ 
    \cos\left(\frac{\theta}{2}\right)=\sqrt{\frac{1+\cos(\theta)}{2}},\quad
    \sin\left(\frac{\theta}{2}\right)=\sqrt{\frac{1-\cos(\theta)}{2}},\quad
    \text{for~\( \theta\in[0,\pi] \).} 
\]
Also,
\[ 
    \cos\left(\frac{\pi}{2}+\arctan x\right)=-\sin(\arctan
    x)=-\frac{x}{\sqrt{1+x^2}}.
\]
Thus we have
\begin{align*}
\cos\left(\frac{1}{2}u(x)\right)&=\sqrt{\frac{1+\cos(\frac{\pi}{2}+\arctan(x))}{2}}
=\sqrt{\frac{1}{2}-\frac{1}{2}x(1+x^2)^{-\sfrac{1}{2}}},\\
\sin\left(\frac{1}{2}u(x)\right)&=\sqrt{\frac{1-\cos(\frac{\pi}{2}+\arctan(x))}{2}}
=\sqrt{\frac{1}{2}+\frac{1}{2}x(1+x^2)^{-\sfrac{1}{2}}}.\qedhere
\end{align*}
\end{proof}

Let~\( u_t\defeq u(t^{-1}D)=\frac{\pi}{2}+\arctan t^{-1}D \). Then the
preceding lemma says that~\( c_t=\cos(\frac{1}{2}u_t) \) and~\(
s_t=\cos(\frac{1}{2}u_t) \).   

\begin{lemma}\label{lem:commutator_ut}
We have the following estimate\textup{:}
\[ 
    \norm*{[u_t,a]}\leq t^{-1}\norm*{[D,a]}.
\]
\end{lemma}

\begin{proof}
Note that~\( u'(x)=\frac{1}{1+x^2} \) and
\[
    \widehat{\frac{1}{1+x^2}}(\xi)=\pi\mathrm{e}^{-\abs*{\xi}}.
\]
Thus
\[
C_u
\defeq\frac{1}{2\pi}\int_{-\infty}^{\infty}\abs*{\xi\widehat{u}(\xi)}\,\mathrm{d}\xi
=\frac{1}{2\pi}\int_{-\infty}^{\infty}\abs*{\widehat{u'}(\xi)}\,\mathrm{d}\xi
=\frac{1}{2\pi}\int_{-\infty}^{+\infty}\pi\mathrm{e}^{-\abs*{\xi}}\mathrm{d}\xi=\int_{0}^{+\infty}\mathrm{e}^{-\xi}\mathrm{d}\xi
=1.
\]
So we obtain
\[ 
    \norm*{[u_t,a]}\leq
    C_u\cdot\norm{[t^{-1}D,a]}=t^{-1}\norm*{[D,a]}.\qedhere
\]
\end{proof}

\begin{proposition}\label{prop:commutator_ct_st}
We have the following estimates\textup{:}
\[ 
    \norm{[c_t,a]}\leq \frac{1}{2}t^{-1}\norm*{[D,a]},\quad 
    \norm{[s_t,a]}\leq \frac{1}{2}t^{-1}\norm*{[D,a]}
\]
\end{proposition}

\begin{proof}
We have
\begin{align*} 
c_t&=\cos\left(\frac{1}{2}u_t\right)
=\frac{1}{2}\left(\mathrm{e}^{\frac{\mathrm{i}}{2}u_t}+
\mathrm{e}^{-\frac{\mathrm{i}}{2}u_t}\right), \\
s_t&=\sin\left(\frac{1}{2}u_t\right)
=\frac{1}{2\mathrm{i}}\left(\mathrm{e}^{\frac{\mathrm{i}}{2}u_t}-
\mathrm{e}^{-\frac{\mathrm{i}}{2}u_t}\right).
\end{align*}
Since the operator~\( \tfrac{1}{2}u_t \) is self-adjoint, we may apply
\Cref{lem:commutator_estimate} to it, which gives
\begin{multline*} 
\norm{[c_t,a]}\leq
\frac{1}{2}\norm{[\mathrm{e}^{\tfrac{\mathrm{i}}{2}u_t},a]}+
\frac{1}{2}\norm{[\mathrm{e}^{-\tfrac{\mathrm{i}}{2}u_t},a]}
\leq\frac{1}{4}\left(\norm*{\left[
u_t,a\right]}+\norm*{\left[u_t,a\right]}\right) \\
\leq \frac{1}{2}\norm*{[u_t,a]}\leq \frac{1}{2}t^{-1}\norm*{[D,a]}.
\end{multline*}
The same estimate holds for~\( [s_t,a] \) as well. 
\end{proof}

The following results on special functions, 
specifically, Beta functions and Gamma
functions, are needed for computing the
constant factors in the two estimates below. Recall that
(cf.~\cite{Andrews-Askey-Roy:Special_functions}*{Definition 1.1.3}) the
\emph{Beta function}~\( \operatorname{B}(\alpha,\beta) \) is defined as the
integral
\[ 
\operatorname{B}(\alpha,\beta)\defeq \int_{0}^1
t^{\alpha-1}(1-t)^{\beta-1}\,\mathrm{d}t,\quad\text{for~\(\alpha,\beta\in\C\) with~\(\Re
\alpha>0,\,\Re\beta>0 \)};
\]
and the \emph{Gamma function}~\( \Gamma(\alpha) \) is defined as
(cf.~\cite{Andrews-Askey-Roy:Special_functions}*{Corollary 1.1.5}):
\begin{equation}\label{eq:Gamma_function}
    \Gamma(\alpha)\defeq
    \int_{0}^{\infty}t^{\alpha-1}e^{-t}\,\mathrm{d}t,\quad\text{for~\(
    \alpha\in\C \) with~\( \Re \alpha>0 \).} 
\end{equation}

The Gamma function satisfies the following \emph{Euler's reflection
formula} (cf.~\cite{Andrews-Askey-Roy:Special_functions}*{Theorem 1.2.1}):
\begin{equation}\label{eq:Euler_reflection}
\Gamma(\alpha)\Gamma(1-\alpha)=\frac{\pi}{\sin\pi\alpha}. 
\end{equation}
In particular, setting~\( \alpha=\tfrac{1}{2} \) yields~\(
\Gamma(\tfrac{1}{2})=\sqrt{\pi} \). 

The relation between the Beta function and the Gamma function is
well-known to be (cf.~\cite{Andrews-Askey-Roy:Special_functions}*{Theorem
1.1.4}):
\[ 
    \operatorname{B}(\alpha,\beta)=\frac{\Gamma(\alpha)\Gamma(\beta)}{\Gamma(\alpha+\beta)}.
\]
We substitute~\( \lambda=\frac{t}{1-t} \) in the expression of the Beta
function to get
\begin{equation}\label{eq:Beta_function}
\begin{aligned}
\operatorname{B}(\alpha,\beta)&=\int_{0}^{\infty}\left(\frac{\lambda}{\lambda+1}\right)^{\alpha-1}\left(\frac{1}{\lambda+1}\right)^{\beta-1}\frac{1}{(\lambda+1)^2}\,\mathrm{d}\lambda\\
&=\int_{0}^{\infty}\lambda^{\alpha-1}(\lambda+1)^{-\alpha-\beta}\,\mathrm{d}\lambda.  
\end{aligned}
\end{equation}

\begin{proposition}\label{prop:commutator_sqrt_ctst}
For all~\( 0<s\leq 1 \), the following estimate holds\textup{:}
\[ 
    \norm{[(1+t^{-2}D^2)^{-s},a]}\leq 2t^{-1}\norm{[D,a]}.
\]
As a consequence, we have
\[ 
    [\sqrt{c_ts_t},a]\leq 2t^{-1}\norm*{[D,a]}.
\]
\end{proposition}

\begin{proof}
Write~\( D_t\defeq t^{-1}D \) for abbreviation. 
For~\( s=1 \), we have
\begin{align*} 
[(1+D_t^2)^{-1},a]=&-(1+D_t^2)^{-1}[D_t^2,a](1+D_t^2)^{-1} \\
=&-(1+D_t^2)^{-1}D_t[D_t,a](1+D_t^2)^{-1}\\
&-(1+D_t^2)^{-1}[D_t,a]D_t(1+D_t^2)^{-1}.
\end{align*}
Since both~\( (1+D_t^2)^{-1}D_t \) and~\( (1+D_t^2)^{-1} \) are contractive
by functional calculus of~\( D_t \), we have
\[ 
    \norm{[(1+D_t^2)^{-1},a]}\leq2\norm*{[D_t,a]}=2t^{-1}\norm*{[D,a]}.
\]

For~\( 0<s<1 \), recall the following integral formula
(cf.~\cite{Carey-Phillips:Unbounded_Fredholm_modules}*{Remark 3}):
\begin{equation}\label{eq:integral_formula}
    (1+D_t^2)^{-s}=\frac{\sin(s\pi)}{\pi}\int_{0}^{\infty}\lambda^{-s}(1+D_t^2+\lambda)^{-1}\mathrm{d}\lambda,\quad
    0<s<1.
\end{equation}
This gives
\begin{align*}
[(1+D_t^2)^{-s},a]=&\frac{\sin(s\pi)}{\pi}\int_{0}^{\infty}\lambda^{-s}[(1+\lambda+D_t^2)^{-1},a]\mathrm{d}\lambda
\\
=&-\frac{\sin(s\pi)}{\pi}\int_{0}^{\infty}\lambda^{-s}(1+\lambda+D_t^2)^{-1}[1+\lambda+D_t^2,a](1+\lambda+D_t^2)^{-1}\mathrm{d}\lambda \\
=&-\frac{\sin(s\pi)}{\pi}\int_{0}^{\infty}\lambda^{-s}(1+\lambda+D_t^2)^{-1}[D_t^2,a](1+\lambda+D_t^2)^{-1}\mathrm{d}\lambda \\
=&-\frac{\sin(s\pi)}{\pi}\int_{0}^{\infty}\lambda^{-s}(1+\lambda+D_t^2)^{-1}D_t[D_t,a](1+\lambda+D_t^2)^{-1}\mathrm{d}\lambda \\
&-\frac{\sin(s\pi)}{\pi}\int_{0}^{\infty}\lambda^{-s}(1+\lambda+D_t^2)^{-1}[D_t,a]D_t(1+\lambda+D_t^2)^{-1}\mathrm{d}\lambda.
\end{align*}
We note that~\( (1+\lambda+D_t^2)^{-1}D_t=D_t(1+\lambda+D_t^2)^{-1}
\) is contractive by functional calculus of~\( D_t \). Therefore,
\begin{align*}
\norm*{[(1+D_t^2)^{-s},a]}&\leq\frac{2\sin(s\pi)}{\pi}\norm{[D_t,a]}\int_{0}^{\infty}\lambda^{-s}(1+\lambda+D^2)^{-1}\mathrm{d}\lambda\\
&\leq\frac{2t^{-1}\sin(s\pi)}{\pi}\norm{[D,a]}\int_{0}^{\infty}\lambda^{-s}(1+\lambda)^{-1}\mathrm{d}\lambda,
\end{align*}
while we know from the expression \eqref{eq:Beta_function} of the Beta
function as well as the Euler reflection formula
\eqref{eq:Euler_reflection} that, for all~\( 0<s<1 \): 
\begin{align*} 
\int_{0}^{\infty}\lambda^{-s}(1+\lambda)^{-1}\mathrm{d}\lambda
=\operatorname{B}(1-s,s)=\frac{\Gamma(s)\Gamma(1-s)}{\Gamma(1)}
=\frac{\pi}{\sin s\pi}.
\end{align*}
Then we conclude that
\[ 
    \norm{[(1+D_t^2)^{-s},a]}\leq 2t^{-1}\norm*{[D,a]},\quad 0<r\leq1.
\]
Now the estimate for~\( \norm{[\sqrt{c_ts_t},a]} \) follows from~\(
\sqrt{c_ts_t}=\frac{1}{\sqrt{2}}(1+D_t^2)^{-\sfrac{1}{4}} \).
\end{proof}

The estimate below follows similarly.

\begin{proposition} 
\label{prop:commutator_Ds_Ft}
Let~\( F_{t}\defeq t^{-1}D(1+t^{-2}D^{2})^{-\sfrac{1}{2}} \). Then for 
all~\( 0\leq s<1 \),~\( [F_{t},a] \) maps~\( E \) into~\( \dom\abs{D}^{s} \), and 
the following estimate holds\textup{:}
\[\norm*{\abs{D}^{s}[F_{t},a]}\leq t^{s-1} C_s\norm*{[D,a]},\]
where
\[ 
    C_s\defeq
    1+\frac{2\Gamma(\tfrac{1-s}{2})}{\sqrt{\pi}\Gamma(\tfrac{2-s}{2})}.
\]
In particular, setting~\( s=0 \) gives  
\[ 
    \norm*{[F_t,a]}\leq 3t^{-1}\norm*{[D,a]}.
\]

\end{proposition}

\begin{proof}
Write~\( D_t\defeq t^{-1}D \) for abbrevation. Then we have
\[ \abs{D}^{s}[F_{t},a]=\abs{D}^{s}(1+D_t^{2})^{-\sfrac{1}{2}}[D_t,a]
+\abs{D}^s[(1+D_t^{2})^{-\sfrac{1}{2}},a]D_t. \]
We address the two summands separately. For the first one it follows
that
\begin{align*}
\norm*{\abs{D}^{s}(1+D_t^{2})^{-\sfrac{1}{2}}[D_t,a]}
&=\norm*{\abs{D}^{s}t^{-1}(1+t^{-2}D^{2})^{-\sfrac{1}{2}}[D,a]}\\
&=
t^{s-1}\norm*{t^{-s}\abs{D}^{s}(1+t^{-2}D^{2})^{-\sfrac{1}{2}}[D,a]} \\
&\leq t^{s-1}\norm*{[D,a]},
\end{align*}
where the last inequality holds because~\(
t^{-s}\abs{D}^s(1+t^{-2}D^2)^{-\sfrac{1}{2}}=\abs{D_t}^s(1+D_t^2)^{-\sfrac{1}{2}} \) is contractive for~\( s<1 \).  

For the second summand, we expand~\( (1+D_t^{2})^{-\sfrac{1}{2}} \) with
the integral formula \eqref{eq:integral_formula} to get
\begin{align*}
&\abs{D}^{s}[(1+D_t^2)^{-\sfrac{1}{2}},a]D_t \\
=-\,&\frac{\abs{D}^{s}}{\pi}\int_{0}^{\infty}\lambda^{-\sfrac{1}{2}}(1+\lambda+D_t^2)^{-1}(D_t[D_t,a]+[D_t,a]D_t)(1+\lambda+D_t^2)^{-1}D_t\,\mathrm{d}\lambda\\
=-\,&\frac{t^{-1}\abs{D}^{s}}{\pi}\int_{0}^{\infty}\lambda^{-\sfrac{1}{2}}(1+\lambda+D_t^2)^{-1}(D_t[D,a]+[D,a]D_t)(1+\lambda+D_t^2)^{-1}D_t\,\mathrm{d}\lambda.
\end{align*}
Since~\( D_t(1+\lambda+D_t^2)^{-1}D_t=(1+\lambda+D_t^2)^{-1}D_t^{2} \) is
contractive, it follows that
\begin{align*}
\norm*{\abs{D}^{s}[(1+D_t^2)^{-\sfrac{1}{2}},a]D_t}
&\leq\frac{2t^{-1}}{\pi}\cdot\norm{[D,a]}\cdot\norm*{\int_{0}^{\infty}\abs{D}^s\lambda^{-\sfrac{1}{2}}(1+\lambda+D_t^2)^{-1}\,\mathrm{d}\lambda}\\
&=\frac{2t^{s-1}}{\pi}\cdot\norm{[D,a]}\cdot\norm*{\int_{0}^{\infty}\lambda^{-\sfrac{1}{2}}|D_t|^{s}(1+\lambda+D_t^2)^{-\frac{s}{2}}(1+\lambda+D_t^2)^{\frac{s-2}{2}}\mathrm{d}\lambda}\\
&\leq\frac{2t^{s-1}}{\pi}\cdot\norm{[D,a]}\cdot\norm*{\int_{0}^{\infty}\lambda^{-\sfrac{1}{2}}(1+\lambda+D_t^2)^{\frac{s-2}{2}}\mathrm{d}\lambda}\\
&\leq
\frac{2t^{s-1}}{\pi}\cdot\norm{[D,a]}\cdot\abs*{\int_0^\infty\lambda^{-\sfrac{1}{2}}(1+\lambda)^{\frac{s-2}{2}}\mathrm{d}\lambda}.
\end{align*}
Now by \eqref{eq:Beta_function} we have
\[ 
    \int_{0}^\infty\lambda^{-\sfrac{1}{2}}(1+\lambda)^{\frac{s-2}{2}}\,\mathrm{d}\lambda=\operatorname{B}(\tfrac{1}{2},\tfrac{1-s}{2})=\frac{\Gamma(\tfrac{1}{2})\Gamma(\tfrac{1-s}{2})}{\Gamma(\tfrac{2-s}{2})},
\]
whence
\begin{align*}
\norm*{\abs{D}^s[F_t,a]}&\leq
t^{s-1}\norm{[D,a]}+\frac{2t^{s-1}}{\sqrt{\pi}}\norm{[D,a]}\operatorname{B}(\tfrac{1}{2},\tfrac{1-s}{2})
\\
&=t^{s-1}\norm{[D,a]}\cdot\left(1+\frac{2\Gamma(\tfrac{1-s}{2})}{\sqrt{\pi}\Gamma(\tfrac{2-s}{2})}\right).\qedhere
\end{align*}
\end{proof}

\section{Numerical index pairings as traces}
\label[appendix]{app:proof_commutativity}
In this appendix, we shall provide the proof of
\Cref{thm:commutative_diagram_trace}:

\begin{theorem*}
The \st-homomorphism~\( \varrho^{\tau}\colon
\End_B^*(E)\to\Bdd(\mathcal{H}^\tau) \)
maps~\( \Cpt_B(E) \) into~\( \Cpt_{\widehat{\tau}} \). Its induced map
\[ 
    \varrho^{\tau}_*\colon \K_0(\Cpt_B(E))\to\K_0(\Cpt_{\widehat{\tau}})
\]
makes the the following diagram commute:
\begin{equation}\label{eq:commutative_diagram_trace}\tag{TR}
\begin{tikzcd}[row sep=large, column sep=large]
\K_1(A) \arrow[r, "\times{[D]}"] \arrow[rd, "\Phi^D_*"'] & \K_0(B)
\arrow[r, "\tau_*"] & \R \\
& \K_0(\Cpt_B(E))  \arrow[u, "{[E]}"]  \arrow[r,"\varrho^{\tau}_*"] &
\K_0(\Cpt_{\widehat{\tau}}) \arrow[u, "\widehat{\tau}_*"'].
\end{tikzcd} \end{equation}
\end{theorem*}

We recall the setup.
Let~\( A \) and~\( B \) be unital \Cst-algebras and~\( \tau\colon B\to\C \)
be a \emph{finite}, \emph{faithful} trace, which means that:
\begin{center}
\( \tau(b^*b)<+\infty \) for all~\( b\in B \)\quad and\quad
\( \tau(b^*b)=0 \) iff~\( b=0 \).
\end{center}
Let~\( (\mathcal{A},E,D) \) be a unital odd unbounded Kasparov~\( A \)-\( B
\)--module. The finite faithful trace~\( \tau\colon B\to\C \) transfers to a
semi-finite trace on~\( \Cpt_B(E) \), and generates an isometric
representation
\[ 
    \varrho^\tau\colon \End_B^*(E)\to\Bdd(\mathcal{H}^\tau),\quad T\mapsto
    T\otimes \id,
\]
where~\( \mathcal{H}_\tau \) is the Hilbert space~\( E\otimes_BL^2(B,\tau)
\), obtained as the localisation of~\( E \) at the GNS-representation~\(
B\to\Bdd(L^2(B,\tau)) \). The isometric representation also gives an
unbounded, self-adjoint operator~\( D^\tau \) on~\( \mathcal{H}^\tau \) as
the closure of~\( D\otimes\id \). 

We shall first prove that~\( \varrho^\tau \) maps~\( \Cpt_B(E) \) into~\(
\Cpt_{\widehat{\tau}} \), where~\( \Cpt_{\widehat{\tau}} \) is the
\Cst-algebra generated by all~\( \widehat{\tau} \)-finite projection inside
the enveloping von Neumann algebra~\( \mathcal{N} \) of~\(
\varrho^\tau(\End_B^*(E)) \).

The following lemma is of independent interest.

\begin{lemma}\label{lem:compactly_supported_fin_rank}
Let~\( \mathcal{D} \) be an unbounded self-adjoint regular operator on a Hilbert
\( B \)-module~\( \mathcal{E} \) such that 
\( (1+\mathcal{D}^2)^{-1}\in\Cpt_B(\mathcal{E}) \). 
Then for every~\( f\in\Cc(\R) \),~\( f(\mathcal{D})\in\Fin_B^*(\mathcal{E}) \).
\end{lemma}

\begin{proof} 
Recall that
(cf.~\cite{Blackadar:Operator_algebras}*{II.5.2.4})
the Pedersen ideal~\( \Ped(A) \) of 
a \Cst-algebra~\( A \) is a hereditary, dense
two-sided \st-ideal of~\( A \), generated as an ideal by elements
of the form~\( f(a) \) for~\( a\in A_+ \) and~\( f\in\mathfrak{F}_+ \),
where
\[ \mathfrak{F}_+\defeq\set*{f\in\Co[0,\infty)\;\middle|\;\text{\( f \)
vanishes on a neighbourhood of~\( 0 \)}}.
\]

We claim that~\( \varphi(\mathcal{D})\in\Ped(\Cpt_B(\mathcal{E})) \) for every
positive, even function~\( \varphi\in\Cc(\R) \). For such functions, there
exists~\( R\geq 0 \) such that~\( \varphi(x)=\varphi(-x)\geq 0 \) for all
\( x\in[-R,R] \); and~\( \varphi(x)=0 \) for all~\( x>R \). Then
\[ 
    \varphi(x)=\big(\varphi\circ\theta\big)\big((1+x^2)^{-1}\big)
\]
where~\( \theta \) is the function 
\[ 
    \theta\colon(0,1]\to[0,+\infty),\quad \theta(y)\defeq \sqrt{y^{-1}-1}.
\]
Since~\( \varphi(x) \) vanishes for all~\( x>R \) , the composition~\(
\varphi\circ\theta(y) \) vanishes for all~\( y\in(0,\tfrac{1}{R^2+1})
\), thus~\( \varphi\circ\theta\in\mathfrak{F}_+ \).
By assumption,~\( (1+\mathcal{D}^2)^{-1}\in\Cpt_B(\mathcal{E})_+ \). So
\( \varphi(\mathcal{D})=(\varphi\circ\theta)((1+\mathcal{D}^2)^{-1}) \) belongs to~\(
\Ped(\Cpt_B(\mathcal{E})) \). 

Now for every~\( f\in\Cc(\R) \), write~\( f=\sum_{i=1}^nf_i \) as a finite
linear combination of positive functions~\( f_i\in\Cc(\R) \),
then~\( f_i(\mathcal{D})\in\Cpt_B(E)_+ \). For each~\( f_i \), define
\( \varphi_i(x)\defeq f_i(x)+f_i(-x) \). Then~\( \varphi_i \) is a
positive, even function in~\( \Cc(\R) \) that dominates~\(
f_i \), thus~\( 0\leq f_i(\mathcal{D})\leq\varphi_i(\mathcal{D})  \). Hence,~\(
f_i(\mathcal{D})\in\Ped(\Cpt_B(E)) \) by hereditarity of the Pedersen
ideal, and~\( f(\mathcal{D})=\sum_{i=1}^nf_i(\mathcal{D})\in\Ped(\Cpt_B(E)) \) as well.  

It follows from \cite{Ara:Morita_equivalence_Pedersen_ideals
}*{Theorem 1.6} that the Pedersen ideal of~\( \Cpt_B(\mathcal{E}) \) is
given by~\( \Fin_B^*(\mathcal{P}) \), where~\( \mathcal{P} \) is a
submodule of~\( \mathcal{E} \)
(cf.~\cite{Ara:Morita_equivalence_Pedersen_ideals}*{Definition 1.2}).
A finite-rank operator on a Hilbert submodule of~\( \mathcal{E} \)  
is also a finite-rank operator on~\( \mathcal{E} \), regardless of whether
or not this submodule is complemented. Then we conclude that for all~\(
f\in\Cc(\R) \), 
\[ 
f(\mathcal{D})\in\Ped(\Cpt_B(\mathcal{E}))=\Fin_B^*(\mathcal{P})\subseteq\Fin_B^*(\mathcal{E}).\qedhere
\]
\end{proof}

\begin{lemma}\label{lem:resolvent_tau_compact}
For every compact set~\( K\subseteq \R \),~\( \chi_K(D^\tau) \) is~\(
\widehat{\tau} \)-finite.    
As a consequence, 
one has~\( (D^\tau+\mathrm{i})^{-1}\in\Cpt_{\widehat{\tau}} \). 
\end{lemma}

\begin{proof}
Let~\( K\subseteq\R \) be a compact subset.
Choose any~\( \varphi\in\Cc(\R)_+ \) 
such that~\( \chi_K\leq\varphi \). Since
\( (\mathcal{A},E,D) \) is a unital odd, unbounded Kasparov module,~\(
(1+D^2)^{-1}\in\Cpt_B(E)_+ \). Thus by  
\Cref{lem:compactly_supported_fin_rank}, 
\( \varphi(D)\in\Fin_B^*(E) \). It follows from
(2) of \Cref{lem:transfer_trace} that
\( \varrho^\tau(\varphi(D))=\varphi(D^\tau) \) is~\( \widehat{\tau}
\)-finite. Therefore,
\[ 
    \widehat{\tau}(\chi_K(D^\tau))\leq\widehat{\tau}(\varphi(D^\tau))<+\infty,
\]
that is,~\( \chi_K(D^\tau) \) is a~\( \widehat{\tau} \)-finite projection,
hence belongs to~\( \Cpt_{\widehat{\tau}} \). In particular,~\(
\chi_{[-R,R]}(D^\tau)\in\Cpt_{\widehat{\tau}} \) for any~\( R>0 \).  

Since~\( \Cpt_{\widehat{\tau}} \) is an ideal in~\( \mathcal{N} \), it follows 
that
\[ 
    (D^\tau+\mathrm{i})^{-1}\chi_{[-R,R]}(D^\tau)\in\Cpt_{\widehat{\tau}}
\]
holds for every~\( R>0 \). Now let 
\( \{\mathrm{d}p_\lambda\}_{\lambda\in\R} \) be the spectral resolution of 
\( \mathcal{H}^\tau \) given by the self-adjoint operator~\( D^\tau \),
then
\[ 
    f(D^\tau)=\int_{\lambda\in\R}f(\lambda)\mathrm{d}p_\lambda
\]
holds for any Borel function~\( f\colon \R\to\C \). In particular, we have
\begin{align*} 
\norm*{(D^\tau+\mathrm{i})^{-1}-(D^\tau+\mathrm{i})^{-1}\chi_{[-\lambda,\lambda]}}&=\norm*{\int_{\lambda\in\R}(\lambda+\mathrm{i})^{-1}\,\mathrm{d}p_\lambda-\int_{\abs*{\lambda}\leq
R}(\lambda+\mathrm{i})^{-1}\,\mathrm{d}p_\lambda} \\
&=\norm*{\int_{\abs*{\lambda}>R}(\lambda+\mathrm{i})^{-1}\,\mathrm{d}p_{\lambda}}\\
&<\frac{1}{\sqrt{1+R^2}}.
\end{align*}
So~\( \{(D^\tau+\mathrm{i})^{-1}\chi_{[-R,R]}\}_{R>0} \) is a Cauchy net
that converges to~\( (D^\tau+\mathrm{i})^{-1} \) in norm. Hence,
\( (D^\tau+\mathrm{i})^{-1}\in\Cpt_{\widehat{\tau}} \) as well.  
\end{proof}


\begin{proposition}\label{prop:injective_K_tau}
The representation~\( \varrho^\tau\colon
\End_B^*(E)\to\Bdd(\mathcal{H}^\tau) \) maps~\( \Cpt_B(E) \) into~\(
\Cpt_{\widehat{\tau}} \).   
\end{proposition}

\begin{proof}
Recall that~\( (D+\mathrm{i})^{-1}\in\Cpt_B(E) \) generates~\( \Cpt_B(E)
\) as an ideal.
Therefore,~\( \varrho^\tau(\Cpt_B(E)) \) is contained in the norm closure
of the ideal generated by 
\[
    \varrho^\tau(\Cpt_B(E)(D+\mathrm{i})^{-1})=\varrho^\tau(\Cpt_B(E))(D^\tau+\mathrm{i})^{-1}.
\]
We have shown that~\( (D^\tau+\mathrm{i})^{-1}\in\Cpt_{\widehat{\tau}}
\). Since~\( \Cpt_{\widehat{\tau}} \) is a norm-cloded ideal of~\(
\mathcal{N} \), it therefore follows that~\(
\varrho^\tau(\Cpt_B(E)) \) is also contained in~\( \Cpt_{\widehat{\tau}}
\).  
\end{proof}

Having defined the injective \st-homomorphism, we are now able to prove the
commutativity of the diagram \eqref{eq:commutative_diagram_trace}.

\begin{theorem}
The diagram \eqref{eq:commutative_diagram_trace} commutes.
\end{theorem}

\begin{proof}
The subtlety in the proof comes from the fact that
projections in~\( \Mat_n(\Cpt_B(E)^+) \) may fail to be~\(
\widehat{\tau} \)-finite, whence the 
composition of maps 
\[ 
    \K_0(\Cpt_B(E))\xrightarrow{[E]}\K_0(B)\xrightarrow{\tau_*}\R
\]
is hard to compute.
To overcome this, we replace~\( \Cpt_B(E) \) by~\(
\Cpt\otimes B \) using Kasparov's stablisation theorem
\cite{Kasparov:K-functor_extension}.

Since~\( E \) is countably generated, there exists an isometry~\(
V\in\Hom^*_B(E,\mathcal{H}_B) \), where~\( \mathcal{H}_B\defeq
\ell^2(\N)\otimes B \) is the standard countably generated Hilbert~\( B
\)-module. It follows from functoriality of the interior tensor product (or
the KSGNS construction) that the following diagram commutes:
\begin{equation}\label{eq:commutative_diagram_bottom_right}
\begin{tikzcd}
\Cpt_B(\mathcal{H}_B) \arrow[r, "\varrho^\tau"] &
\Cpt_{\widehat{\tau}}(\mathcal{H}_B) \\
\Cpt_B(E) \arrow[u, "\Ad_V"] \arrow[r, "\varrho^\tau"] &
\Cpt_{\widehat{\tau}}(E) \arrow[u, "\Ad_V\otimes\id"'],
\end{tikzcd} 
\end{equation}
here we distinguish the norm-closed ideals~\( \Cpt_{\widehat{\tau}}(E) \)
and~\( \Cpt_{\widehat{\tau}}(\mathcal{H}_B) \), both generated 
by~\( \widehat{\tau} \)-finite projections, 
but on different Hilbert spaces~\(
E\otimes_B L^2(B,\tau)\) and~\( \mathcal{H}_B\otimes L^2(B,\tau) \),
whereas~\( \Cpt_{\widehat{\tau}}(E) \) can be identified via~\(
\Ad_V\otimes\id \) as a corner in~\( \Cpt_{\widehat{\tau}}(\mathcal{H}_B)
\).    

Now we claim that the following augmented diagram commutes:
\begin{equation}\label{eq:commutative_diagram_trace_augmented}\tag{TR+}
\begin{tikzcd}[row sep=large, column sep=large]
\K_1(A) \arrow[r, "\times{[D]}"] \arrow[rdd, bend right=40, "\Phi^D_*"'] & \K_0(B)
\arrow[r, "\tau_*"] & \R \\
& \K_0(\Cpt_B(\mathcal{H}_B)) \arrow[u, "{[\mathcal{H}_B]}"'] \arrow[r,
"\varrho^\tau_*"] & \K_0(\Cpt_{\widehat{\tau}}(\mathcal{H}_B))
\arrow[u, "\widehat{\tau}_*"']  \\
& \K_0(\Cpt_B(E)) \arrow[uu, bend left=60, "{[E]}"]
\arrow[u, "{(\Ad_V)_*}"']  \arrow[r,"\varrho^{\tau}_*"] &
\K_0(\Cpt_{\widehat{\tau}}) \arrow[u, "(\Ad_V)_*\otimes\id"'].
\end{tikzcd} \end{equation}

The commutativity of the left quadrant follows from following equality of
maps in K-theory:
\[ 
    [\mathcal{H}_B]\circ(\Ad_V)_*=[E].
\]
To see this, we view~\( \Ad_V(\Cpt_B(E))\subseteq\Cpt_B(\mathcal{H}_B) \) 
as a \Cst--\( \Cpt_B(E) \)-\( \Cpt\otimes B \)--correspondence, and~\(
\mathcal{H}_B \) as a imprimivity bimodule between~\(
\Cpt_B(\mathcal{H}_B) \) and~\( B \). Thus the equality follows from the
isomorphism of Hilbert \Cst-modules
\[ 
\Ad_V\Cpt_B(E)\otimes_{\Cpt_B(\mathcal{H}_B)}\mathcal{H}_B\simeq
\Ad_V\Cpt_B(E)\otimes_{\Ad_V\Cpt_B(\mathcal{H}_B)}V^*\mathcal{H}_B\simeq 
V^*\mathcal{H}_B=E.
\]

The bottom right square 
of \eqref{eq:commutative_diagram_trace_augmented} follows
from the commutativity of \eqref{eq:commutative_diagram_bottom_right} as
well as functoriality of K-theory. Thus, we are left to show that the top
right square commutes. Note that
\[
    \Cpt_B(\mathcal{H}_B)\simeq
    \Cpt\otimes B=\lim_{\longrightarrow}\Mat_n(B),
\]
and K-theory preserves direct limits. So every class in~\(
\K_0(\Cpt\otimes B) \) is represented by a formal differences of
projections~\( [p]-[q] \) where~\( p,q\in\Mat_{\infty}(B) \). 
Here we have used the assumption that
\( B \) is unital. It also follows that the induced K-theory map~\(
[\mathcal{H}_B] \) maps such a class to~\( [p]-[q] \),
viewed as an element in~\( \K_0(B) \).

The transferred trace~\( \widehat{\tau} \) on~\( \Fin^*_B(\mathcal{H}_B) \)
is, by \Cref{lem:transfer_trace}, given by
\[ 
    \widehat{\tau}(\ket{\varphi\otimes a}\bra{\psi\otimes b})
    \defeq
    \tau(\braket{\psi\otimes b,\varphi\otimes
    a})=\braket{\psi,\varphi}\cdot\tau(b^*a)
\]
for~\( a,b\in B \) and~\( \varphi,\psi\in\ell^2(\N) \).

Now let~\( (b_{ij})_{i,j=1}^n \) be a projection in~\( \Mat_n(B) \). Under
the isomorphism~\( \Cpt\otimes B\simeq\Cpt_B(\mathcal{H}_B) \), it gets
mapped to
\[
    \sum_{i,j=1}^n\ket{\delta_j\otimes b_{ij}}\bra{\delta_i\otimes 1}\in\Fin^*_B(\mathcal{H}_B),
\]
where~\( \delta_i\in\ell^2(\N) \) is the function~\( \N\to\C \) sending~\(
i\) to~\( 1 \) and~\( 0 \) otherwise. Thus we have
\begin{multline*} 
\widehat{\tau}\left(\sum_{i,j=1}^n\ket{\delta_j\otimes
b_{ij}}\bra{\delta_i\otimes 1}\right)=
\tau\left(\sum_{i,j=1}^n\braket{\delta_i\otimes 1,\delta_j\otimes
b_{ij}}\right)=\\
\sum_{i,j=1}^n\braket{\delta_i,\delta_j}\tau(b_{ij})=\sum_{i=1}^n\tau(b_{ii})=\tau((b_{ij})_{i,j=1}^n),
\end{multline*}
that is, the top right square of
\eqref{eq:commutative_diagram_trace_augmented} commutes, hence
the whole diagram commutes.
Now the commutativity of \eqref{eq:commutative_diagram_trace} 
follows from it.
\end{proof}

