\section*{Methods}

\subsection{\add{Axisymmetric formulation of the 3D IMHD equations}}
% \textcolor{orange}{[MOVED FROM MODEL]} 

The pressure field $p$ \add{in the IMHD equations~\eqref{eq:imhd_full}} can be eliminated using the vorticity $\bom=\nabla \times \bu$ and the current density
$\bj=\nabla \times \bdb$ and rewriting the above equations in 
the following vorticity and current formulation: 
\begin{align}
\partial_t \bom &= \nabla \times ( \bu \times \bom ) + \nabla \times ( \bj \times \bdb )\,;  \label{eq:imhd_w} \\
\partial_t \bj &= \nabla \times (\nabla \times ( \bu \times \bdb ))\,.   \label{eq:imhd_j}
\end{align}
In 3D, the stream function $\bpsi$ and magnetic potential $\bphi$ are vector quantities that are related to the primitive variables in Eqs.~\eqref{eq:imhd_u}-\eqref{eq:imhd_j} via
$\bu = \nabla \times \bpsi$ and $\bdb = \nabla \times \bphi$.
We represent vector fields in the 3D axisymmetric domain as follows: $\bu (r,z,t)=u^r(r,z,t) \ \hat{e}_r+u^{\theta}(r,z,t) \ \hat{e}_{\theta}+u^z(r,z,t) \ \hat{e}_z$, where $\hat{e}_r, \,\hat{e}_{\theta}$ and $\hat{e}_z$ are the basis vectors in the cylindrical coordinate system. We introduce the transformed variables~\cite{luo2014potentially,kolluru2022insights}
\begin{equation}
u^1 \equiv \frac{u^\theta}{r}; \; \omega^1 \equiv \frac{\omega^\theta}{r}; \; b^1 \equiv \frac{b^\theta}{r}; \; {\rm{and}}\; j^1 
\equiv\frac{j^\theta}{r}\,;
\label{eq:u1etc}
\end{equation}
%as in Refs.~\cite{luo2014potentially,kolluru2022insights}. 
and we rewrite Eq.~\eqref{eq:imhd_full} as follows:
\begin{subequations}
\begin{align}
\partial_t u^1  =& (b^r \partial_r + b^z \partial_z) b^1 - (u^r \partial_r + u^z \partial_z)u^1 -2(b^1 \partial_z \phi^1 - u^1 \partial_z \psi^1)\,; \label{eq:main1} \\
\partial_t \omega^1  =& (b^r \partial_r + b^z \partial_z) j^1 - (u^r \partial_r + u^z \partial_z)\omega^1 +  \partial_z ( (u^1)^2 - (b^1)^2)\,;\label{eq:main2} \\
\partial_t b^1  =& (b^r \partial_r + b^z \partial_z) u^1 - (u^r \partial_r + u^z \partial_z)b^1\,; \label{eq:main3} \\
\partial_t j^1  =& -(j^1 + 2\partial^2_z \phi^1)(2\partial_r u^r -\partial_z \psi^1) + (\omega^1 + 2\partial^2_z \psi^1)(2\partial_r b^r -\partial_z \phi^1) + \nonumber \\ 
&     (b^r \partial_r + b^z \partial_z) \omega^1 - (u^r \partial_r + u^z \partial_z) j^1 - b^1 \partial_z u^1 + u^1 \partial_z b^1\,. \label{eq:main4} 
\end{align}
\label{eq:main}
\end{subequations}
The Poisson equations for $\psi^1$ and $\phi^1$ are given below:
\begin{subequations}
\begin{align}
 \left( \partial_r^2 + \frac{3}{r} \partial_r + \partial_z^2 \right) {\psi^1} &= -\omega^1\,; \label{eq:pois_om_psi} \\
\left( \partial_r^2 + \frac{3}{r} \partial_r + \partial_z^2 \right) {\phi^1} &= -j^1\,. \label{eq:pois_j_phi}
\end{align}
\label{eq:poisson}    
\end{subequations}
The radial and axial components of the $\bu$ and $\bdb$ fields are obtained from $\bpsi$ and $\bphi$, respectively: 
\begin{subequations}
    \begin{align}
        u^r = -r \partial_z \psi^1\,; &\; \; \; u^z  = 2\psi^1 + r \partial_r \psi^1\,;  \\
        b^r = -r \partial_z \phi^1\,; &\; \; \; b^z  = 2\phi^1 + r \partial_r \phi^1\,. 
    \end{align}      \label{eq:main_rz} 
\end{subequations}
The solution of the above equations, in terms of the transformed variables $\{ u^1, \, \omega^1, \, ... \}$ [see Eq.~\eqref{eq:u1etc}], ensures that the corresponding fields $\{ u^{\theta}, \, \omega^{\theta}, \, ... \}$ remain smooth at the coordinate singularity on the axis of the cylinder ($r=0$).
We obtain the pressure $p$ by taking divergence of Eq.~\eqref{eq:imhd_u}, which yields the following Poisson-type equation:
\begin{subequations}
\begin{align}
    \nabla^2 \left( p + \frac{|\bdb|^2}{2} \right) &= - \nabla \cdot [(\bu \cdot \nabla) \bu] +  \nabla \cdot [(\bdb \cdot \nabla) \bdb]\,, \\
    \partial_r \left( p + \tfrac{1}{2} |\bdb|^2 \right)  &= ((u^\theta)^2 - (b^\theta)^2)\,, \qquad \qquad \text{BC at $r=1$,    $\forall (z,t)$.}
\end{align}
    \label{eq:mhd_pressure}
\end{subequations} 
% \textcolor{orange}{[MOVED FROM MODEL]}

\subsection{\add{Numerical method}}
We use Fourier-Chebyshev pseudospectral methods to solve Eqs.~\eqref{eq:main}. The domain $\mathcal{D}(1,L)$ is discretised using the collocation grid $\mathbf{X}_{N,M} \coloneqq \{ (r_i,z_j) : i=0,1,...,N-1 \text{ and } j=0,1,...,M-1 \}$. In the periodic $z$ direction, the collocation points $\{z_j = \tfrac{Lj}{M}: j=0,1...M-1 \}$ are distributed uniformly. In the wall-bounded $r$ direction, the collocation nodes $\{r_i = \frac{1}{2}(1+\cos(\frac{\pi(i-0.5)}{N}): i=0,1,...N-1\}$ are the roots of $T_N(2r-1)$, the order-$N$ Chebyshev polynomial of the first kind; these roots are spaced non-uniformly and they cluster near $r=0$ and $r=1$. % In FIG.~\ref{fig:cyl}, we display the collocation grid (black dots) embedded in the cylindrical domain $\mathcal{D}(1,L)$. 
Given a function $f(r,z)$, its Fourier-Chebyshev approximation on the grid $\mathbf{X}_{N,M}$ is
'
If $N=M$, the spacing between Chebyshev nodes, near $r=1$ and $r=0$, is much smaller than the spacing between the Fourier nodes.
Therefore, we use $M>N$; specifically, in our direct numerical simulation (DNS), we use $N=256$ and $M=512$, 
{which suffice to uncover the FTSs we explore and the associated tyger oscillations}. We use a fourth-order Runge-Kutta scheme, with an adaptive time step that ensures Courant–Friedrichs–Lewy (CFL) stability in both the Fourier-discretised $z$-direction and the Chebyshev-discretised $r$-direction. We compute the derivatives in spectral space and, subsequently, the nonlinear terms in physical space. In order to 
remove aliasing errors, in both Fourier and Chebyshev spectral approximations, we use the $2/3$-dealiasing method~\cite{uhlmann2000need}. We use our Tau Poisson solver~\cite{kolluru2022insights} to solve the Poisson equations \eqref{eq:pois_om_psi} and \eqref{eq:pois_j_phi} with the\noop{BCs} \add{boundary conditions.}%~\eqref{eq:bc}.
\noop{In Section~\ref{subsec:pressure},} We use the Tau Poisson solver for solving the pressure-Poisson problem~\eqref{eq:mhd_pressure}.

