\title{Passive Quantum Interconnects:\\ High-Fidelity Quantum Networking at Higher Rates with Less Overhead}
\author{Seigo Kikura}
\email{seigo.kikura@nano-qt.com}
\affiliation{Nanofiber Quantum Technologies, Inc. (NanoQT), 1-22-3 Nishiwaseda, Shinjuku-ku, Tokyo 169-0051, Japan}

