\title{{\Large Discrete Spectrum and Spectral Rigidity of a Second-Order \\  Geometric Deformation Operator}}


\author{Anton Alexa}
\email{mail@antonalexa.com}
\thanks{ORCID: \href{https://orcid.org/0009-0007-0014-2446}{0000-0007-0014-2446}}
\affiliation{Independent Researcher, Chernivtsi, Ukraine}
