\subsection{Modular functors}

%-------------------------------------------------------------------------------------------------------------------------


We reproduce here the definition of geometric modular functor of \cite[2.4]{godfardHodgeStructuresConformal2024}.
This definition is equivalent to that given by Bakalov-Kirillov in \cite[6.4.1, 6.7.6]{bakalovLecturesTensorCategories2000}.

\begin{definition}[Modular Functor]\label{definitiongeometricmodularfunctor}
  Let $\Lambda$ be a finite set with involution $\lambda\mapsto\lambda^\dagger$ and preferred fixed point $0\in\Lambda$.
  Let $r,s\geq 1$ be integers.
  Then a geometric modular functor with level $(r,s)$ is the data,
  for each $g,n\geq 0$, $(g,n)\neq (0,0),(0,1),(1,0)$, and $\ul\in\Lambda^n$,
  of a bundle with flat connection $(\Nu_g(\ul),\nabla)$ over $\Mgrbt{g}{n}{r}{s}$, together with some isomorphisms
  described below.
  \begin{description}
      \item[(G-sep)] For each gluing map
      \begin{equation*}
        q:\Mgrbt{g_1}{n_1+1}{r}{s}\times\Mgrbt{0}{2}{r}{s}\times\Mgrbt{g_2}{n_2+1}{r}{s}\lra \Mgrbt{g_1+g_2}{n_1+n_2}{r}{s}
      \end{equation*}
      and each $\ul$, an isomorphism preserving the connections
      \begin{equation*}
        q^*\Nu_{g_1+g_2}(\lambda_1,\dotsc,\lambda_n)\simeq \bigoplus_\mu\Nu_{g_1}(\lambda_1,\dotsc,\lambda_{n_1},\mu)\otimes
        \Nu_0(\mu,\mu^\dagger)^\vee\otimes
        \Nu_{g_2}(\lambda_{n_1+1},\dotsc,\lambda_n,\mu^\dagger);
      \end{equation*}
      \item[(G-nonsep)] For each gluing map
      \begin{equation*}
        p:\Mgrbt{g-1}{n+2}{r}{s}\times\Mgrbt{0}{2}{r}{s}\lra \Mgrbt{g}{n}{r}{s}
      \end{equation*}
      and each $\ul$, an isomorphism preserving the connections
      \begin{equation*}
        p^*\Nu_g(\lambda_1,\dotsc,\lambda_n)\simeq \bigoplus_\mu\Nu_{g-1}(\lambda_1,\dotsc,\lambda_n,\mu,\mu^\dagger)
        \otimes \Nu_0(\mu,\mu^\dagger)^\vee;
      \end{equation*}
      \item[(N)] For each forgetful map $f:\Mgrbt{g}{n+1}{r}{s}\ra\Mgrbt{g}{n}{r}{s}$, and each $\ul$, an isomorphism preserving the connections
      \begin{equation*}
        f^*\Nu_g(\lambda_1,\dotsc,\lambda_n)\simeq \Nu_g(\lambda_1,\dotsc,\lambda_n,0)
      \end{equation*}
      and a canonically isomorphism $(\Nu_0(0,0),\nabla)\simeq (\cO,d)$ (trivial flat bundle);
      \item[(Perm)] For each $\ul\in\Lambda^n$ and permutation $\sigma\in S_n$, an isomorphism
      \begin{equation*}
        \Nu_g(\lambda_1,\dotsc,\lambda_n)\simeq \sigma^*\Nu_g(\lambda_{\sigma(1)},\dotsc,\lambda_{\sigma(n)}).
      \end{equation*}
  \end{description}
  The isomorphisms of \textbf{(G-sep)}, \textbf{(G-nonsep)}, \textbf{(N)} and \textbf{(Perm)}
  are to be compatible with each other and repeated applications.
  Moreover, we ask for the gluing to be symmetric in the sense that
  for each gluing isomorphism above, the change of variable $\mu\mapsto\mu^\dagger$
  on the right-hand side has the same effect as permuting the summands and applying the \textbf{(Perm)} isomorphisms
  $\Nu_0(\mu,\mu^\dagger)\simeq\Nu_0(\mu^\dagger,\mu)$ induced by $\sigma\in S_2\setminus\{\id\}$.

  The functor is also assumed to verify the non-degeneracy axiom
  \begin{description}
      \item[(nonD)] For each $\lambda$, $\Nu_0(\lambda,\lambda^\dagger)\neq 0$.
  \end{description}
\end{definition}

Sometimes, we will shorten $\Nu_0(\ul)$ to $\Nu(\ul)$.
Because $\Mgrbt{g}{n}{r}{s}$ is a $\mu_s$-gerbe, $\mu_s$ acts on the fibers of $\Nu_g(\ul)$.
Using the gluing axiom, one sees that this action is by scalars and independent of $g$ and $\ul$.
Hence to each modular functor $\Nu$ is associated a complex number $c\in\C$ corresponding to the action of $e^{2\pi i/s}$,
called the \textbf{central charge} of $\Nu$.

\begin{remark}
  We use somewhat non-standard gluing maps involving $\Mgrbt{0}{2}{r}{s}$: the points are not directly glued together, but are first glued to the marked
  points of a twice marked sphere, which is then contracted as it is an unstable component in the image. Adding it may seem pointless.
  However, we use it to have a more compact way to deal with the symmetry of the gluing. Indeed, even when $\mu=\mu^\dagger$,
  there are some examples for which the permutation isomorphism $\Nu_0(\mu,\mu)\simeq\Nu_0(\mu,\mu)$ induced by $\sigma\in S_2\setminus\{\id\}$
  is not the identity. See \cite[rmk. 2.7]{godfardHodgeStructuresConformal2024} for more details.
\end{remark}

\begin{definition}[Genus $0$ Modular Functor]
  Let $\Lambda$ be a finite set with involution $\lambda\mapsto\lambda^\dagger$ and preferred fixed point $0\in\Lambda$.
  Let $r\geq 1$ be an integer.
  Then a geometric genus $0$ modular functor with level $r$ is the data,
  for each $n\geq 2$ and $\ul\in\Lambda^n$,
  of a bundle with flat connection $(\Nu(\ul),\nabla)$ over $\Mgrb{0}{n}{r}$ together with isomorphisms
  as in \Cref{definitiongeometricmodularfunctor}, with the $\Mgrbt{0}{n}{r}{s}$ replaced by the $\Mgrb{0}{n}{r}$,
  satisfying all the same axioms\footnote{Note that \textbf{(G-nonsep)} is vacuous in genus $0$.}.
\end{definition}

\begin{remark}\label{remarklevel}
  The choice of level is not significant in the definition of (genus $0$) modular functor.
  Indeed, if $r'$ is a multiple of $r$ and $s'$ a multiple of $s$, pullback along the maps $\Mgrbt{g}{n}{r'}{s'}\ra\Mgrbt{g}{n}{r}{s}$
  produces a modular functor of level $(r',s')$ from a modular functor of level $(r,s)$.
  Similarly for genus $0$ modular functors.
\end{remark}

