\subsection{Relation with modular/ribbon/braided fusion categories}\label{subsectionfullfaithfulness}

%-------------------------------------------------------------------------------------------------------------------------

For definitions of monoidal category, rigid monoidal category, fusion category, braided monoidal category,
twist on a braided monoidal category and modular category, see \cite[2.1, 2.10, 4.1, 8.1, 8.10 and 8.13]{etingofTensorCategories2015}.
In these notes, the base field for such categories will always be $\C$.

The natural category of braided tensor categories is not a $1$-category. However, here we work with fusion categories and
we only care about isomorphisms of fusion categories with structure, not all morphisms. In this context,
we can produce a groupoid of braided/ribbon/modular fusion categories that is a $1$-groupoid by imposing restrictions on
how morphisms behave on the underlying structures of linear category.
These restrictions are benign: any braided/ribbon/modular fusion category is equivalent to one in the groupoids $\Braid/\Rib/\Modcat$ defined below.

\begin{notation}
  For $\Lambda$ a finite set, $\VL$ denotes the category $(\mathrm{Vect}_\C)^\Lambda$ of $\Lambda$-colored vector spaces.
  The object of $\VL$ corresponding to the vector space $\C$ colored by $\lambda\in\Lambda$ will be denoted $[\lambda]$.
\end{notation}

\begin{definition}[{\cite[5.5]{godfardHodgeStructuresConformal2024}}]\label{definitionribbon}
  Let $\Rib$ be the groupoid whose:
  \begin{description}
    \item[(1)] objects are pairs $(\Lambda,\VL)$, where $\Lambda$ is some finite set, and $\VL$ is endowed with
    the structure of a ribbon fusion category;
    \item[(2)] morphisms from $(\Lambda_1,\VLone)$ to $(\Lambda_2,\VLtwo)$ are pairs $(f,\phi)$, with $f:\Lambda_1\ra\Lambda_2$ a bijection and 
    $\phi:\otimes_1\simeq f^*\otimes_2$ a natural isomorphism, such that they induce a monoidal isomorphism $\VLone\ra\VLtwo$
    compatible with braidings and twists. In other words, morphisms form $(\Lambda_1,\VLone)$ to $(\Lambda_2,\VLtwo)$ are ribbon isomorphisms that
    are induced by a bijection $f:\Lambda_1\ra\Lambda_2$ at the level of the $\C$-linear categories and are strict on tensor units.
  \end{description}
  One similarly defines the groupoid $\Braid$ of braided fusion categories and the full sub-groupoid $\Modcat\subset \Rib$
  of modular fusion categories.
\end{definition}

\begin{remark}
  A fusion structure on $\VL$ induces a unique involution $\lambda\mapsto\lambda^\dagger$ of $\Lambda$
  and the choice of a preferred fixed point $0\in\Lambda$ of this involution, by imposing that for each $\lambda$, $[\lambda]^*\simeq [\lambda^\dagger]$
  and $1\simeq [0]$.
\end{remark}


\begin{definition}
  For $c\in\C^\times$, will denote by $\GMod_c$ the groupoid of geometric modular functors with central charge $c$,
  where we identify modular functors of different levels as in \Cref{remarklevel}.

  An isomorphism between $\Nu$ and $\Nu'$ in $\GMod_c$ is a bijection $\phi:\Lambda\simeq\Lambda'$ preserving the involution and $0$ together with
  a family of isomorphisms $\Nu_g(\ul)\simeq\Nu'_g(\phi(\ul))$ compatible with gluing, forgetful, normalization and permutation isomorphisms.

  We will use the notation $\GMod^0$ for the groupoid of genus $0$ geometric modular functors, up to change of level,
  and the notation $\BraidFun$ for the groupoid of geometric braided functors, up to change of level.
\end{definition}

One can associate to a geometric (genus $0$) modular functor over $\C$ a ribbon weakly fusion category and to a geometric braided functor over $\C$ a
braided weakly fusion category, see \cite[5.5.1]{bakalovLecturesTensorCategories2000} and \cite[5.]{godfardHodgeStructuresConformal2024}.
Moreover, Etingof and Penneys recently proved the long-standing conjecture that braided weakly fusion categories are braided fusion categories
\cite{etingofRigidityNonnegligibleObjects2024}. Together with the work of Bakalov and Kirillov \cite[5.4.1, 6.7.13]{bakalovLecturesTensorCategories2000},
this implies that to a modular functor is associated a modular fusion category, to a genus $0$ modular functor is associated a ribbon fusion category,
and to a braided functor is associated a braided fusion category.
These can be put into the commutative diagram of categories below.
For more details, see \cite[5.]{godfardHodgeStructuresConformal2024}. 
