\caption{Choice of neighborhoods}
\label{fig.3}
\end{figure}

Now let $y_1,y_2 \in \Ball_{r_2}(y)$ and put $x_j \coloneq f^{-1}(y_j)$.
Denote the shortest geodesic from $y_1$ to $y_2$ by $\gamma\colon [0,1]\to N$.
Since $r_2$ is smaller than the convexity radius of $N$, the curve $\gamma$ is entirely contained in $\Ball_{r_2}(y)$.
Thus, $c \coloneq f^{-1}\circ\gamma\colon [0,1]\to M$ is a continuous curve connecting $x_1$ and $x_2$ which is contained in $\Ball_{r_1}(x)$.

By the Lipschitz property of $f$, we have $f(B_r(c([0,1])))\subseteq \Ball_{Lr}(\gamma([0,1]))$ for any $r>0$.
Since $f$ is volume preserving, this implies 
\begin{equation}
\vol_M(\Ball_r(c([0,1]))) \le \vol_N(\Ball_{Lr}(\gamma([0,1]))).
\label{eq.lip1}
\end{equation}

Let $v_1,v_2\in \Ball_{r_1}(0)\subseteq T_x M$ be the tangent vectors with $\exp_{x}(v_j)=x_j$.
We obtain a second curve $\bar{c}\colon [0,1]\to M$ connecting $x_1$ and $x_2$ by putting $\bar{c}(t) \coloneq \exp_x(\ell(t))$ where $\ell(t)=tv_2+(1-t)v_1$ is the straight line connecting $v_1$ and $v_2$.
This curve is also contained in $\Ball_{r_1}(x)$, see \cref{fig.2}.
