\end{figure}
Each point of $X$ is at distance $<r$ from some point of $\exp_x^{-1}\circ c([0,1])$, hence we have 
\begin{equation}
X\subseteq \Ball_r(\exp_x^{-1}\circ c([0,1])).
\label{eq.claim1}
\end{equation}
Moreover, for each $t\in[0,1]$ the hyperplane $H_0+\ell(t)$ intersects $\exp_x^{-1}\circ c([0,1])$ because $\exp_x^{-1}\circ c([0,1])$ is connected.
Therefore, the coarea formula yields
\[
\vol_{T_xM}(X)
\ge
\vol_{T_xM}(Y_1) + \len_{T_xM}(\ell)\cdot\vol_{H_0}(D_r) + \vol_{T_xM}(Y_2)
=
\vol_{T_xM}(\Ball_r(\ell([0,1]))) .
\]
Together with \eqref{eq.claim1} this proves the claim.
\hfill\checkmark

\smallskip

For sufficiently small $r>0$, we have $\Ball_r(\ell([0,1]))\subseteq \Ball_{r_1}(0)$, $\Ball_r(\exp_x^{-1}\circ c([0,1]))\subseteq \Ball_{r_1}(0)$, $\Ball_r(c([0,1]))\subseteq \Ball_{r_1}(x)$, and $\Ball_r(\bar{c}([0,1]))\subseteq \Ball_{r_1}(x)$.
The bounds on the singular values of the differential of $d\exp_x$ imply $\Ball_{(1-\eps)r}(\bar{c}([0,1]))\subseteq \exp_x(\Ball_r(\ell([0,1])))\subseteq \Ball_{(1+\eps)r}(\bar{c}([0,1]))$ and hence
\begin{align}
(1-\eps)^n\,\vol_M\big(\Ball_{(1-\eps)r}(\bar{c}([0,1]))\big)
&\leq 
\vol_{T_xM}\big(\Ball_r(\ell([0,1]))\big) \notag\\
&\leq 
(1+\eps)^n\,\vol_M\big(\Ball_{(1+\eps)r}(\bar{c}([0,1]))\big) .
\label{eq.lip3}
\end{align}
Similarly, we get
\begin{align}
(1-\eps)^n\,\vol_M\big(\Ball_{(1-\eps)r}(c([0,1]))\big)
&\leq 
\vol_{T_xM}\big(\Ball_r(\exp_x^{-1}\circ c([0,1]))\big) \notag\\
&\leq 
(1+\eps)^n\,\vol_M\big(\Ball_{(1+\eps)r}(c([0,1]))\big) .
\label{eq.lip4}
\end{align}
Combining these estimates, we find
\begin{align}
\vol_N(\Ball_{L(1+\eps)r}(\gamma([0,1])))
&\stackrel{\eqref{eq.lip1}}{\geq}
\vol_M(\Ball_{(1+\eps)r}(c([0,1]))) \notag\\
&\stackrel{\eqref{eq.lip4}}{\geq}
(1+\eps)^{-n}\,\vol_{T_xM}\big(\Ball_r(\exp_x^{-1}\circ c([0,1]))\big) \notag\\
&\stackrel{\eqref{eq.lip2}}{\geq}
(1+\eps)^{-n}\,\vol_{T_xM}(\Ball_r(\ell([0,1]))) \notag\\
&\stackrel{\eqref{eq.lip3}}{\geq}
\big[\tfrac{1-\eps}{1+\eps}\big]^n\,\vol_{M}(\Ball_{(1-\eps)r}(\bar{c}([0,1]))) .
\label{eq.lip5}
\end{align}
The power series expansion of the volume of thin tubes around a smooth curve yields
\begin{align*}
\vol_M(\Ball_{\rho}(\bar{c}([0,1]))) 
=
\len_M(\bar{c})\cdot\omega_{n-1}\cdot \rho^{n-1} + \O(\rho^{n+1})
\quad \text{ as }\rho\searrow 0 \, ,
\end{align*}
and similarly for the curve $\gamma$ in $N$.
Dividing \eqref{eq.lip5} by $\omega_{n-1}\cdot r^{n-1}$ and letting $r$ tend to $0$, we obtain
\[
L^{n-1}\,(1+\eps)^{n-1}\,\len_N(\gamma) \geq \big[\tfrac{1-\eps}{1+\eps}\big]^n\,(1-\eps)^{n-1}\,\len_M(\bar{c}).
\]
This yields
\[
L^{n-1}\cdot\dist(y_1,y_2)
=
L^{n-1}\cdot\len_N(\gamma)
\ge
\big[\tfrac{1-\eps}{1+\eps}\big]^{2n-1}\,\len_M(\bar{c})
\ge
\big[\tfrac{1-\eps}{1+\eps}\big]^{2n-1}\,\dist(x_1,x_2).
\]
This shows that $f^{-1}$ is Lipschitz with Lipschitz constant $\le L^{n-1}\cdot\big[\tfrac{1+\eps}{1-\eps}\big]^{2n-1}$ on the ball $\Ball_{r_2}(y)$.
Since $y$ is arbitrary, $f^{-1}$ is locally Lipschitz on $N$ with this global bound on the (local) Lipschitz constant.
Thus $f^{-1}$ is globally $\big(\big[\tfrac{1+\eps}{1-\eps}\big]^{2n-1}\cdot L^{n-1}\big)$-Lipschitz on $N$.
The limit $\eps\searrow 0$ concludes the proof.
\end{proof}

\begin{proposition}\label{1lip_injectivity}
Let \(M\) and \(N\) be connected closed Riemannian manifolds of the same dimension \(n \geq 1\).
Let \(f \colon M \to N\) be an $L$-Lipschitz map such that \(\vol(M) \le \vol_N(f(M))\) and \(\lvert\det(df)\rvert\le1\) almost everywhere.

Then \(f\) is a homeomorphism and $f^{-1}\colon N\to M$ is $L^{n-1}$-Lipschitz.
In particular, if $f$ is $1$-Lipschitz, it is an isometry.
Moreover, for every measurable subset \(A \subseteq M\), we have \(\vol_N(f(A)) = \vol_M(A)\).
\end{proposition}

\begin{proof}
Let \(A \subseteq M\) be measurable. 
By the coarea formula for Lipschitz maps, the fiber \(f^{-1}(y)\) is finite for almost all \(y \in N\), and we obtain 
\begin{align*}
\vol_M(A) 
&\geq 
\int_{M} \charFun_A \lvert\det(d_x f)\rvert \dV_M 
= 
\int_N \sum_{x \in f^{-1}(y)} \charFun_A(x) \dV_N(y) \\
&= 
\int_N \#(f^{-1}(y) \cap A) \dV_N(y) 
\geq 
\vol_N(f(A)).
\end{align*}
Applying this to \(A = M\) and using the assumption \(\vol(M) \le \vol_N(f(M))\), we obtain equality in each inequality, which implies that \(\lvert \det(d_x f) \rvert = 1\) for almost all \(x \in M\) and \(\# f^{-1}(y) = 1\) for almost all \(y \in f(M)\).
Thus we actually have equality in the previous chain of inequalities for any measurable subset \(A \subseteq M\) which shows that \(\vol_M(A) = \vol_N(f(A))\).

In particular, the set of injectivity points has full measure in $M$.
Here, by \enquote{injectivity point}, we mean a point \(x \in M\) which is the unique preimage of its image under $f$.
Note that for each injectivity point \(x \in M\), the \(\Z_2\)-mapping degree of \(f\) satisfies \(\deg_{\Z_2}(f) = 
\deg_{\Z_2}(f \rvert_x)\), where \(\deg_{\Z_2}(f \rvert_x)\) denotes the local mapping degree of \(f\) at the point \(x\).
Moreover, if \(x \in M\) is a point where \(f\) is differentiable and \(d_x f\) is invertible, then \(x\) is a discrete point in the fiber \(f^{-1}(f(x))\) and \(\deg_{\Z_2}(f \rvert_x) = 1\).
Since \(\lvert \det d_x f \rvert = 1\) almost everywhere on \(M\), the set of such points also has full measure.
Finding an injectivity point \(x \in M\) where \(f\) is differentiable with \(d_x f\) invertible, we conclude
\[
   \deg_{\Z_2}(f) = \deg_{\Z_2}(f\rvert_x) = 1.
\]
In particular, \(f\) is surjective.


It remains to verify injectivity.
Since both \(M\) and \(N\) are compact and without boundary, we can find an \(r_0 > 0\) such that for any \(r \leq r_0\), \(x \in M\) and \(y \in N\), we have 
\[
\vol_M(\Ball_r(x)) \geq \tfrac{3}{4} r^n \omega_n, \qquad
\vol_N(\Ball_r(y)) \leq \tfrac{4}{3} r^n \omega_n.
\]
%where \(\omega_n\) is the volume of the Euclidean unit \(n\)-disk.

Denote the Lipschitz constant of \(f\) by \(L\).
Let $x_1,\dots,x_N\in M$ be pairwise distinct preimages of a point $y\in N$ under $f$.
Choose \(0 < r \leq \frac{r_0}{L}\) such that the \(\Ball_r(x_i)\) are pairwise disjoint.
For \(i\neq j\) it follows that 
\begin{equation}
\vol_N(f(\Ball_r(x_i)) \cap f(\Ball_r(x_j)))=0
\label{eq.almost_disjoint}
\end{equation}
since \(\# f^{-1}(y) \leq 1\) for almost all \(y \in N\).
Moreover, since \(f\) is \(L\)-Lipschitz, we have \(f(\Ball_r(x_i)) \subseteq \Ball_{Lr}(y)\).
Therefore, we have
\begin{align*}
\tfrac{3N}{4} r^n \omega_n
&\le
\sum_{i=1}^N \vol_M(\Ball_r(x_i)) 
=
\sum_{i=1}^N \vol_N(f(\Ball_r(x_i))) \\
&=
\vol_N\bigg(f\Big(\bigcup_{i=1}^N \Ball_r(x_i)\Big)\bigg)
\le
\vol_N(\Ball_{Lr}(y)) 
\le 
\tfrac43 L^nr^n\omega_n.
\end{align*}
Hence \(N\le \tfrac{16}{9} L^n\).
In particular, each \(y\in N\) has only finitely many preimages under \(f\).

Since the $\Z_2$-mapping degree of \(f\) is non-trivial and coincides with the sum of the local $\Z_2$-mapping degrees of the preimages, there must be a preimage \(x \in M\) of \(y\) such that the local mapping degree at \(x\) is non-trivial.
In particular, \(f(\Ball_r(x))\) contains an open neighborhood of \(y\), i.e.\ \(\Ball_\rho(y)\subseteq f(\Ball_r(x))\) for some \(\rho>0\).
Assume that there is another preimage \(x'\in M\) of \(y\). 
Choose an injectivity point $x''\in \Ball_{\rho/2L}(x')$.
Then we have \(f(x'')\in \Ball_{\rho/2}(y)\) and the local $\Z_2$-mapping degree of $f$ at $x''$ in nontrivial.
Hence $f(\Ball_{\rho/2L}(x''))$ contains an open neighborhood of $f(x'')$.
Note that \(f(\Ball_{\rho/2L}(x''))\subseteq \Ball_{\rho/2}(f(x''))\subseteq \Ball_\rho(y)\), see Figure~\ref{fig.1}.
Hence, \(f(D_r(x))\cap f(D_r(x'))\) contains a non-empty open set, contradicting \eqref{eq.almost_disjoint}.

