This shows that \(f\) is injective.
Every bijective continuous map between compact manifolds is a homeomorphism.
\cref{lip_homeomorphism} now shows that $f^{-1}$ is $L^{n-1}$-Lipschitz.
In particular, if \(f\) is \(1\)-Lipschitz, then so is \(f^{-1}\) and hence \(f\) is an isometry.
\end{proof}

\begin{proof}[Proof of \cref{Ricci_volume_llarull}]
   Since \(\Ric \geq n-1\), the Bishop--Gromov volume comparison theorem (see e.g.~\cite{Gallot-Hulin-Lafontaine}*{Theorem~4.19}) yields \(\vol(M) \leq \vol(\Sphere^{n})\).
   \Cref{1lip_injectivity} now implies that \(f\) is a bi-Lipschitz homeomorphism and that $\vol(M)=\vol(\Sphere^{n})$.
   Thus, \(M\) is isometric to \(\Sphere^n\) by the equality discussion of Bishop--Gromov volume comparison~\cite{Gallot-Hulin-Lafontaine}*{Theorem~4.20}.
   Moreover, if \(f\) is \(1\)-Lipschitz, it is an isometry, again by \cref{1lip_injectivity}.
\end{proof}

\section{Proof of Theorem~\ref{thmB}}
\label{sec.B}

We start with the construction of the metric on $M$.

\begin{lemma}\label{existence_of_the_wurst}
   Let \(M\) be a closed connected $n$-dimensional manifold which admits a Riemannian metric of positive scalar curvature with $n\ge3$.

   Then for each \(S_0 > 0\) there exists a constant \(\delta(M,S_0) > 0\), such that for each $\delta\in(0,\delta(M,S_0)]$ and each \(l > 0\) there exists a Riemannian metric \(g_M\) on \(M\) with \(\scal_{g_M} \geq S_0\) and an isometric embedding \([0,l] \times \Sphere^{n-1}_\delta \hookrightarrow (M, g_M)\). 
   Moreover, we can ensure that \(M \setminus ([0,l] \times \Sphere^{n-1}_\delta)\) is disconnected.
\end{lemma}

\begin{proof}
   We fix a metric $g'$ on the open $n$-ball $\Disk^n$ such that $(\Disk^n, g')$ contains an isometric copy of $[0,\infty)\times \S^{n-1}$ and $\scal_{g'}>0$.
   This is possible because $n\ge3$.
   Pick a point $p\in \Disk^n\setminus [0,l']\times \S^{n-1}$.
   Furthermore, fix a metric $g_0$ on $M$ with $\scal_{g_0} > 0$ and choose a point $q\in M$.

   We perform Gromov-Lawson surgery (\cite{GL}*{Theorem~A}) to obtain a Riemannian metric $g_1$ on $M\sharp \Disk^n=M\setminus \{\text{point}\}$ with $\scal_{g_1} > 0$ which differs from $g_0$ and $g'$ only in a small neighborhood of $q$ and $p$, respectively.
   In particular, $(M\setminus \{\text{point}\},g_1)$ still contains an isometric copy of $[0,\infty)\times \S^{n-1}$, see \cref{fig.5}.
