The remaining cylinder $[0,l]\times \S^{n-1}_\delta$ can be capped off at $\{l\}\times \S^{n-1}_\delta$ to yield the desired metric $g_M$ on $M$, see \cref{fig.6}.
\end{proof}

\begin{lemma}\label{projection_of_the_wurst}
   Let \(M\) be a closed connected $n$-dimensional manifold which admits a Riemannian metric of positive scalar curvature with $n\ge3$.

   Then for each \(S_0 > 0\) there exists a constant \(\delta(M,S_0) > 0\), such that for each $\delta\in(0,\delta(M,S_0)]$ and each \(l > 0\) there exists a Riemannian metric \(g_M\) on \(M\) with \(\scal_{g_M} \geq S_0\) and a smooth surjective $1$-Lipschitz map \(f \colon M \to [0,l]\times\Disk^{n-1}_\delta\).
   Here \([0,l]\times\Disk^{n-1}_\delta\) carries the flat product metric.
\end{lemma}

\begin{proof}
According to \cref{existence_of_the_wurst}, given $S_0$, $\delta$ and $l$, we can find a Riemannian metric $g_M$ on $M$ with $\scal_{g_M} \geq S_0$ such that $M$ is isometric to 
\[
M_-\cup_{\{-3\}\times\S^{n-1}_\delta} \Big([-3,l+3]\times\S^{n-1}_\delta\Big)\cup_{\{l+3\}\times\S^{n-1}_\delta} M_+ \,,
\] 
where $M_+$ and $M_-$ are compact Riemannian manifolds with boundary isometric to $\S^{n-1}_\delta$.
The orthogonal projection $\R^n\to \{0\}\times\R^{n-1}=\R^{n-1}$ restricts to a smooth surjective $1$-Lipschitz map $\pi_\delta\colon\S^{n-1}_\delta\to\Disk^{n-1}_\delta$.
Choose a smooth function $\varphi\colon\R\to\R$ with the properties
\begin{enumerate}[label=$\triangleright$]
\item \(0\le\varphi\le 1\) everywhere,
\item \(\varphi = 0\) outside \([-3,l+3]\),
\item \(\varphi = 1\) on \([-1,l+1]\),
\item \(\lvert\dot{\varphi}\rvert < 1\) everywhere,
\end{enumerate}
and a smooth function \(\psi\colon\R\to\R\) satisfying
\begin{enumerate}[label=$\triangleright$]
\item \(0\le\psi\le l\) everywhere,
\item \(\psi = 0\) on \((-\infty,-1]\),
\item \(\psi = l\) on \([l+1,\infty)\),
\item \(\lvert\dot{\psi}\rvert < 1\) everywhere.
\end{enumerate}
Then the map
\begin{gather*}
f(x)=
\begin{cases}
(\psi(t),\varphi(t)\pi_\delta(y)), &\text{if } x=(t,y)\in [-3,l+3]\times\S^{n-1}_\delta, \\
(0,0), &\text{if } x\in M_-, \\
(l,0), &\text{if } x\in M_+,
\end{cases}
\end{gather*}
does the job.
\end{proof}

\begin{proof}[Proof of \cref{thmB}]
If suffices to consider the case $\eps=2$ because for arbitrary $\eps>0$ one can then apply the $(\eps=2)$-result with scalar curvature bound $S_0\cdot(2\eps)^{-2}$ and then rescale the metric on $M$.
In view of \cref{projection_of_the_wurst}, we need to construct a smooth surjective $2$-Lipschitz map $[0,l]\times \Disk^{n-1}_\delta\to N$ for some $\delta>0$ and $l>0$.

Let $\delta(M,S_0)$ be as in \cref{projection_of_the_wurst}.
Choose $\delta\in(0,\delta(M,S_0)]$ so small that $\lvert d_v\exp_y\rvert < 2$ whenever $v\in T_yN$ with $\lvert v\rvert\le\delta$.
We choose a smooth curve $\gamma\colon [0,l_1]\to N$ parametrized by arc-length which is $\delta$-dense in $N$, meaning that the $\delta$-tube about the trace of $\gamma$ covers all of $N$, i.e., $\Ball_\delta(\gamma([0,l_1]))=N$.

We choose an orthonormal frame $e_1,\dots,e_{n-1}$ of $\dot{\gamma}(0)^\perp\subseteq T_{\gamma(0)}N$ and parallel translate it along $\gamma$ w.r.t.\ the normal connection.
We obtain an orthonormal frame $e_1(t),\dots,e_{n-1}(t)$ of $\dot{\gamma}(t)^\perp \subseteq T_{\gamma(t)N}$ for all $t\in[0,l_1]$.
We fix a constant $\Lambda > 0$ to be chosen later and consider the map
\[
h\colon [0,\Lambda l_1]\times \Disk_\delta^{n-1}\to N, 
\quad 
(t,x)\mapsto \exp_{\gamma(t/\Lambda)}\bigg(\sum_{i=1}^{n-1} x_i e_i(t/\Lambda)\bigg).
\]
The map $h$ is smooth and surjective.
The derivatives in the $x_i$-directions are bounded by $2$ because of the choice of $\delta$.
The same holds for the derivate in the $t$-direction if we choose $\Lambda$ large enough.
Thus $h$ is $2$-Lipschitz as desired.
\end{proof}


