\section{Scalar one-loop integrals}
\label{sec:masint}

In this appendix we list basic scalar one-loop integrals for massless theories in $D = 4 - 2\epsilon$ dimensions.
These results can be found in \cite{Bern:1993kr}, and the repository of basic scalar integrals with internal masses can be found in \cite{Ellis:2007qk}.
The prefactor $e^{\epsilon \gamma_{\text{E}}}$ is introduced to remove Euler constant $\gamma_{\text{E}}$ from the final result, because we chooses the modified minimal subtraction scheme $\overline{\text{MS}}$.
Following the notation of Passarino-Veltman master integrals in \texttt{FeynCalc}, all momenta $p_{i}$ are incoming, $p_{1} + p_{2} + p_{3} + p_{4} = 0$.  

\subsection*{Bubble integral}
The bubble integral
\begin{equation}
    \begin{split}
        B_{0}( p_{1}^{2}, m_{0}^{2}, m_{1}^{2} ) = e^{\epsilon \gamma_{\text{E}}} \int \frac{ d^{D} \ell }{ i \pi^{D/2} } \frac{ 1 }{ \ell^{2} - m_{0}^{2} + i \varepsilon } \frac{ 1 }{ ( \ell + p_{1} )^{2} - m_{1}^{2} + i \varepsilon } \,
    \end{split}
\end{equation}
is given by (in the massless case)
\begin{equation}
    B_{0}( p_{1}^{2}, 0, 0 ) = \frac{1}{\epsilon} - \log\left( \frac{ -p_{1}^{2} -i\varepsilon }{ \mu^{2} } \right) + 2 + \mathcal{O}(\epsilon) \,.
\end{equation}
%The bubble integral 
It has UV divergences, but no IR divergences.
We take the shorthand $B_0(s) = B_0(s, 0, 0)$.


\subsection*{Triangle integral}
The triangle integral
\begin{equation}
    \begin{split}
        &C_{0}( p_{1}^{2}, p_{2}^{2}, (p_{1} + p_{2})^{2}, m_{0}^{2}, m_{1}^{2}, m_{2}^{2} ) \\
        =& e^{\epsilon \gamma_{\text{E}}} \int \frac{ d^{D} \ell }{ i \pi^{D/2} } \frac{ 1 }{ \ell^{2} - m_{0}^{2} + i \varepsilon } \frac{ 1 }{ ( \ell + p_{1} )^{2} - m_{1}^{2} + i \varepsilon } \frac{ 1 }{ ( \ell + p_{1} + p_{2} )^{2} - m_{2}^{2} + i \varepsilon } \,
    \end{split}
\end{equation}
%
is given by
%
\begin{equation}
    \begin{split}
        &C_{0}( 0, 0, (p_{1} + p_{2})^{2}, 0, 0, 0 ) \\ 
        =& \frac{1}{s} \left( \frac{1}{\epsilon^2} - \frac{1}{\epsilon} \log \left( \frac{ - s -i\varepsilon }{ \mu^{2} } \right) + \frac{1}{2} \log^{2} \left( \frac{ - s -i\varepsilon }{ \mu^{2} } \right) - \frac{1}{2} \zeta_{2} \right) + \mathcal{O}(\epsilon) \,, 
    \end{split}
\end{equation}
where $\zeta_2 = \frac{\pi^2}{6}$.
Power counting of the superficial degree of divergence shows that the triangle integral cannot have UV divergences. %only IR divergences. 
%Additionally, the $1 / \epsilon^2$ results from the interplay between soft and collinear divergences.
The $1 / \epsilon$ and $1 / \epsilon^2$ terms come from the IR (soft and collinear) divergences. 
We take the shorthand $C_0(s) = C_0(0, 0, s, 0, 0, 0)$.

\subsection*{Box integral}
The box integral
\begin{equation}
    \begin{split}
        &D_{0}( p_{1}^{2}, p_{2}^{2}, p_{3}^{2}, p_{4}^{2}, (p_{1} + p_{2})^{2}, (p_{2} + p_{3})^{2}, m_{0}^{2}, m_{1}^{2}, m_{2}^{2}, m_{3}^{2} ) \\
        =& e^{\epsilon \gamma_{\text{E}}} \int \frac{ d^{D} \ell }{ i \pi^{D/2} } \Big( \frac{ 1 }{ \ell^{2} - m_{0}^{2} + i \varepsilon } \frac{ 1 }{ ( \ell + p_{1} )^{2} - m_{1}^{2} + i \varepsilon } \frac{ 1 }{ ( \ell + p_{1} + p_{2} )^{2} - m_{2}^{2} + i \varepsilon } \\
        &\quad \quad \quad \quad \quad \times \frac{ 1 }{ ( \ell + p_{1} + p_{2} + p_{3} )^{2} - m_{3}^{2} + i \varepsilon } \Big) \,
    \end{split}
\end{equation}
is given by
\begin{equation}
    \begin{split}
        &D_{0}( 0, 0, 0, 0, (p_{1} + p_{2})^{2}, (p_{2} + p_{3})^{2}, 0, 0, 0, 0 ) \\
        =& \frac{ 1 }{ s u } \Bigg( \frac{ 4 }{ \epsilon^2 } - \frac{ 2 }{ \epsilon } \log \left( \frac{ - s -i\varepsilon }{ \mu^{2} } \right) - \frac{ 2 }{ \epsilon } \log \left( \frac{ - u -i\varepsilon }{ \mu^{2} } \right) \\
        & \quad + \log^{2} \left( \frac{ - s -i\varepsilon }{ \mu^{2} } \right) + \log^{2} \left( \frac{ - u -i\varepsilon }{ \mu^{2} } \right) - \log^{2} \left( \frac{ - s -i\varepsilon }{ - u -i\varepsilon } \right) - 8 \zeta_2 \Bigg) + \mathcal{O}(\epsilon) \, .
    \end{split}
\end{equation}
For the same reason, the box integral has only IR divergences.
We take the shorthand $D_0(s,u) = D_0(0, 0, 0, 0, s, u, 0, 0, 0, 0)$.


