\section{Dim-4 one-loop $\aaaa$ amplitudes}
\label{sec:aaaadim4}


The dim-4 one-loop amplitude of $\gamma^{y}\gamma^{y} \to \gamma^{y}\gamma^{y}$, generated by a scalar loop, is given by
%
\begin{equation}
\label{eq:A4yyyy}
    \begin{split}
        \mathcal{A}^{[4],\text{1-loop}}_{yy \to yy} = & \frac{ e^4 }{ 8 \pi^2 } \Big[ (s^2 + t^2 + u^2) \left( \frac{1}{su} B_0(t) + \frac{1}{tu} B_0(s) + \frac{1}{st} B_0(u) \right) \\
        &+ \frac{ s^3 ( 3 t^2 + 3 u^2 - s^2 ) }{ t^2 u^2 } C_0(s) + \frac{ t^3 ( 3 s^2 + 3 u^2 - t^2 ) }{ s^2 u^2 } C_0(t) \\
        &+ \frac{ u^3 ( 3 s^2 + 3 t^2 - u^2 ) }{ s^2 t^2 } C_0(u) \\
        &+ \frac{s^2 u^2}{t^2} D_0(s, u) + \frac{t^2 u^2}{s^2} D_0(t, u) + \frac{s^2 t^2}{u^2} D_0(s, t) \Big] - \frac{ e^4 }{ 4 \pi^2 } \,.
    \end{split}
\end{equation}
%
It is straightforward to verify that the UV divergences in this amplitude cancel precisely, as required by the absence of a corresponding four-photon counterterm in \autoref{eq: scalar qed d<=4}. The IR divergences that appear in \(C_0\) and \(D_0\) cancel each other completely. 
%
However, simple poles of the form \(1/t\) and \(1/t^2\) still appear, seemingly contradicting the result in \autoref{sec:sQED}, which asserts the absence of a \(t\)-channel simple pole. 
On the other hand, the 2-to-2 tree-level cross section
%
\begin{equation}
    \sigma(\gamma^{y} \gamma^{y} \to \phi \phi^{\dagger}) = \frac{ e^{4} }{ 8 \pi s } \, 
\end{equation}
%
is finite, which implies that $ \mathcal{A}^{[4],\text{1-loop}}_{yy \to yy}$ is well defined in the forward limit, according to the dispersion relation \autoref{eq:Sigmapos}.   
To obtain a finite and consistent result, it is essential to keep $t$ as a small quantity and perform a \textit{Taylor expansion} for the $\log(-u) = \log(s) + \log( 1 + \frac{t}{s} )$ and $\frac{1}{u} = - \frac{1}{s} \frac{1}{ 1 + \frac{t}{s} }$ terms in \autoref{eq:A4yyyy}. By doing so, the $1/t$ and $1/t^2$ terms cancels and we obtain
\begin{equation}
    \begin{split}
        A^{[4],\text{1-loop}}_{yy \to yy} \simeq&\frac{ e^4 }{ 8 \pi^2 } \Big[ - \log(-s) - \log(s) + 2 \log(-t) - 3 + \mathcal{O}\left( \frac{t}{s} \right) \Big] \, ,
    \end{split}
\end{equation}
%
which gives
%
\begin{equation}
    \label{eq:sigma yyyy dim-4}
    %\Sigma^{[4]}_{yy} \equiv 
    \oint_{\gamma} \frac{ds}{ 2\pi i } \frac{ s^{3} A^{[4],\text{1-loop}}_{y y \to y y} }{ (s^{2} + s_{0}^{2})^{3} } = \frac{2}{\pi} \int_0^{\infty} ds\,\frac{ s^4 \sigma(\gamma^{y} \gamma^{y} \to \phi \phi^{\dagger}) }{\left(s^2+s_0^2\right)^3}  = \frac{ e^{4} }{ 16 \pi^2 s_{0}^{2} } \,,
\end{equation}
%
consistent with the dispersion relation \autoref{eq:Sigmapos}.  This contribution is subtracted in \autoref{eq:sigmaa1xs}.  


Similarly, for $\gamma^{y}\gamma^{x} \to \gamma^{y}\gamma^{x}$, the dim-4 one-loop amplitude is
%
\begin{equation}
\label{eq:4-gamma-1loop-d4}
    \begin{split}
        \mathcal{A}^{[4],\text{1-loop}}_{y x \to y x} = & \frac{ e^4 }{ 8 \pi^2 } \frac{1}{s^2 t^2 u^2} \Big[ 2 s^3 u t (s+2u) B_0(s) + 2 u^3 s t (2s + u) B_0(u) \\
        & + t^2 su (s^2 + t^2 + u^2) B_0(t) + t^5(3 s^2 + 3 u^2 - t^2) C_0(t) \\
        & + (s^2 + t^2 + u^2) \Big( s^4 (u-t) C_0(s) + u^4 ( s - t ) C_0(u) \Big) \\
        &- s^4 u^4 D_0(s, u) + s^4 t^4 D_0(s, t) + t^4 u^4 D_0(t, u) \Big] + \frac{e^4}{4\pi^2} \,.
    \end{split}
\end{equation}
%
By doing a Taylor expansion around $t=0$, it becomes
%
\begin{equation}
    \begin{split}
        A^{[4],\text{1-loop}}_{y x \to y x} \simeq \frac{ e^4 }{ 8 \pi^2 } \Big[ - \log(-s) - \log(s) + 2 \log(-t) + 3 + \mathcal{O}\left( \frac{t}{s} \right) \Big] \, ,
    \end{split}
\end{equation}
%
which is consistent with the 2-to-2 tree-level cross section
\begin{equation}
\label{eq:crosec-yxphph}
    \sigma(\gamma^{y} \gamma^{x} \to \phi \phi^{\dagger}) = \frac{ e^{4} }{ 8 \pi s } \, ,
\end{equation}
%
and its contribution to the dispersion relation can also be subtracted.  







